INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-143', 'planetariy-vladikavkaza', '{"ru": "Планетарий (Школа космонавтики им. Комаева)", "en": "Planetarium — Komaev Cosmonaut School"}'::jsonb, 'attractions'::poi_category, 'museum', NULL, '{"lat": 43.033701, "lng": 44.674972, "address": {"ru": "ул. Кирова, 14, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362040", "en": "11 Ognyeva St, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Небо над Осетией — в куполе диаметром 7 метров. Звёздные шоу, лазерные программы, детские сеансы.", "en": "The sky above Ossetia — in a 7-metre dome. Star shows, laser programs, children''s sessions."}, "medium": {"ru": "Владикавказский планетарий — небольшое учреждение с куполом-кинотеатром и звёздным проектором. Работает с советских времён, в последние годы обновлён. Проводятся астрономические лекции, лазерные шоу, специальные программы для детей. Хорошая точка для семейного визита — особенно осенью и зимой.", "en": "The Vladikavkaz Planetarium is a small institution with a dome theatre and star projector. Operating since Soviet times, updated in recent years. Astronomical lectures, laser shows, special programs for children. A good spot for a family visit — especially in autumn and winter."}, "full": {"ru": "Планетарий — одно из тех мест, которые существуют в каждом советском городе и при этом никогда не надоедают детям. Купол над головой, темнота, и вдруг — небо. Владикавказский планетарий небольшой: семь метров в диаметре, несколько десятков мест. Но это не мешает. Проектор показывает звёздное небо над Кавказом — летнее, зимнее, то, каким оно было сотни лет назад. Есть лазерные шоу под музыку и программы специально для дошкольников. Детям обычно нравится — особенно если потом выйти на улицу и попробовать найти те же созвездия в настоящем небе. Расположен в центре города, вход недорогой, сеансы короткие — 40–50 минут.", "en": "A planetarium is one of those places that exist in every Soviet city and yet never bore children. A dome overhead, darkness, and then — sky. The Vladikavkaz Planetarium is small: seven metres in diameter, a few dozen seats. But that doesn''t matter. The projector shows the star-filled sky above the Caucasus — summer, winter, the sky as it appeared hundreds of years ago. There are laser shows set to music and programs specifically for preschoolers. Children usually like it — especially if you go outside afterward and try to find the same constellations in the real sky. Located in the city center, admission is affordable, sessions run 40–50 minutes."}}'::jsonb, ARRAY['/images/pois/planetariy-vladikavkaza_gp.webp','/images/pois/planetariy-vladikavkaza_2.webp','/images/pois/planetariy-vladikavkaza_3.webp','/images/pois/planetariy-vladikavkaza_4.webp','/images/pois/planetariy-vladikavkaza_5.webp','/images/pois/planetariy-vladikavkaza_6.webp','/images/pois/planetariy-vladikavkaza_7.webp','/images/pois/planetariy-vladikavkaza_8.webp']::text[], 5, '{"sun": "10:00-18:00", "mon": "10:00-18:00", "tue": "10:00-18:00", "wed": "10:00-18:00", "thu": "10:00-18:00", "fri": "10:00-18:00", "sat": "10:00-18:00"}'::jsonb, '+7 (8672) 33-34-11', 'http://schoolcosmo.ru/', NULL, ARRAY['culture','family','science']::text[], false, false, false, 100, 3, 'free'::subscription_tier, 1420);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-144', 'severo-osetinskiy-teatr-im-thapsaeva', '{"ru": "Северо-Осетинский театр им. Тхапсаева", "en": "North Ossetian Tkhapsayev Theatre"}'::jsonb, 'attractions'::poi_category, 'theatre', NULL, '{"lat": 43.031918, "lng": 44.667694, "address": {"ru": "просп. Коста, 172, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362020", "en": "5 Svobody Square, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Осетинский язык на сцене с 1935 года. Театр имени Тхапсаева — живой голос осетинской культуры.", "en": "Ossetian language on stage since 1935. The Tkhapsayev Theatre — the living voice of Ossetian culture."}, "medium": {"ru": "Северо-Осетинский государственный академический театр основан в 1935 году. Носит имя Владимира Тхапсаева (1910–1981) — легендарного актёра, народного артиста СССР, игравшего здесь полвека. Спектакли идут на осетинском языке; часть постановок — с синхронным переводом. Репертуар включает национальную классику, нартовский эпос и мировую драматургию в осетинской интерпретации.", "en": "The North Ossetian State Academic Theatre was founded in 1935. It bears the name of Vladimir Tkhapsayev (1910–1981) — a legendary actor, People''s Artist of the USSR, who performed here for half a century. Performances are in Ossetian; some productions include simultaneous translation. The repertoire includes national classics, Nart epics, and world drama in Ossetian interpretation."}, "full": {"ru": "Есть вещи, которые невозможно перевести — и Осетинский театр об этом знает. Спектакли здесь идут на осетинском языке: том самом, который звучит в горных сёлах, в застольных тостах, в нартовских песнях. Не понять слов — не страшно. Актёрская игра здесь такая, что смысл доходит и без перевода. Театр основан в 1935 году, когда осетинский язык ещё только обретал письменность в современном виде. Имя своё он носит в честь Владимира Тхапсаева — человека, который играл на этой сцене полвека и стал народным артистом СССР, не выучив при этом ни одного лишнего слова по-русски. В репертуаре — нартовский эпос, осетинская классика, Шекспир и Чехов в осетинском прочтении. Зал не самый большой, но атмосфера живая. Если попадёте на вечерний спектакль — посмотрите на публику: это театр, который ходят смотреть, а не посещают для галочки.", "en": "Some things cannot be translated — and the Ossetian Theatre knows this. Performances here are in the Ossetian language: the one that sounds in mountain villages, in toasting speeches, in Nart songs. Not understanding the words is fine. The acting is such that meaning comes through without translation. The theatre was founded in 1935, when the Ossetian language was only just acquiring its modern written form. It takes its name from Vladimir Tkhapsayev — a man who performed on this stage for half a century and became a People''s Artist of the USSR without learning a single unnecessary word of Russian in the process. The repertoire includes the Nart epic, Ossetian classics, Shakespeare and Chekhov in Ossetian interpretation. The hall is not the largest, but the atmosphere is alive. If you catch an evening performance — watch the audience: this is a theatre people come to see, not visit for a checkmark."}}'::jsonb, ARRAY['/images/pois/severo-osetinskiy-teatr-im-thapsaeva_gp.webp','/images/pois/severo-osetinskiy-teatr-im-thapsaeva_facade.webp','/images/pois/severo-osetinskiy-teatr-im-thapsaeva_kosta.webp','/images/pois/severo-osetinskiy-teatr-im-thapsaeva_2.webp','/images/pois/severo-osetinskiy-teatr-im-thapsaeva_3.webp','/images/pois/severo-osetinskiy-teatr-im-thapsaeva_4.webp','/images/pois/severo-osetinskiy-teatr-im-thapsaeva_5.webp','/images/pois/severo-osetinskiy-teatr-im-thapsaeva_6.webp','/images/pois/severo-osetinskiy-teatr-im-thapsaeva_7.webp']::text[], 4.6, NULL, '+7 867 225-11-42', 'http://www.os-teatr.ru/', NULL, ARRAY['culture','theatre','ossetian']::text[], false, false, false, 100, 202, 'free'::subscription_tier, 2310);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-145', 'osetinskaya-tserkov-rozhdestvo-bogoroditskaya', '{"ru": "Осетинская церковь (Рождество-Богородицкая)", "en": "Ossetian Church (Nativity of the Virgin)"}'::jsonb, 'attractions'::poi_category, 'religion', NULL, '{"lat": 43.020244, "lng": 44.685991, "address": {"ru": "ул. Войкова, 20, Владикавказ", "en": "20 Voykova St, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Один из старейших храмов Владикавказа — сердце исторической Осетинской слободки.", "en": "One of the oldest churches in Vladikavkaz — the heart of the historic Ossetian Quarter."}, "medium": {"ru": "Рождество-Богородицкая церковь в Осетинской слободке — один из старейших сохранившихся храмов города, построена в конце XVIII — начале XIX в. Центр религиозной жизни осетинской православной общины Владикавказа на протяжении двух столетий. Небольшая, аскетичная, с характерным для кавказского христианства обликом.", "en": "The Church of the Nativity of the Virgin in the Ossetian Quarter is one of the oldest surviving churches in the city, built in the late XVIII — early XIX century. The center of religious life for Vladikavkaz''s Ossetian Orthodox community for two centuries. Small, austere, with an appearance characteristic of Caucasian Christianity."}, "full": {"ru": "Осетинская слободка — старейший квартал Владикавказа. Когда в 1784 году здесь заложили крепость, осетины уже жили на этом берегу Терека. Рождество-Богородицкая церковь строилась вместе с городом: небольшая, каменная, без лишних украшений — как и подобает храму народа, который принял христианство в горах. Осетинское православие — особенное: в нём живёт древний нартовский субстрат, образы Уастырджи и Уацилла соседствуют с Георгием Победоносцем и Ильёй Пророком. Эта церковь — один из узлов, в которых эти нити сплетались. Здесь крестили, венчали, отпевали — поколение за поколением. В советское время она закрывалась, была возвращена общине в конце 1980-х. Снаружи — скромная. Внутри — та тишина, которая бывает в местах с памятью.", "en": "The Ossetian Quarter is Vladikavkaz''s oldest neighborhood. When the fortress was laid here in 1784, Ossetians already lived on this bank of the Terek. The Church of the Nativity of the Virgin was built alongside the city: small, stone, without excess ornament — as befits a church of a people who accepted Christianity in the mountains. Ossetian Orthodoxy is distinctive: in it lives an ancient Nart substratum, the figures of Uastyrdzhi and Uatsilla stand alongside George the Victorious and Elijah the Prophet. This church is one of the knots where those threads intertwined. Baptisms, weddings, funerals — generation after generation. During Soviet times it was closed, returned to the community in the late 1980s. From the outside — modest. Inside — that silence that exists in places with memory."}}'::jsonb, ARRAY['/images/pois/osetinskaya-tserkov-rozhdestvo-bogoroditskaya_gp.webp','/images/pois/osetinskaya-tserkov_day.webp','/images/pois/osetinskaya-tserkov_night.webp','/images/pois/osetinskaya-tserkov-rozhdestvo-bogoroditskaya_2.webp','/images/pois/osetinskaya-tserkov-rozhdestvo-bogoroditskaya_3.webp','/images/pois/osetinskaya-tserkov-rozhdestvo-bogoroditskaya_4.webp','/images/pois/osetinskaya-tserkov-rozhdestvo-bogoroditskaya_5.webp','/images/pois/osetinskaya-tserkov-rozhdestvo-bogoroditskaya_6.webp','/images/pois/osetinskaya-tserkov-rozhdestvo-bogoroditskaya_7.webp']::text[], 4.6, '{"mon": "08:00-18:00", "tue": "08:00-18:00", "wed": "08:00-18:00", "thu": "08:00-18:00", "fri": "08:00-18:00", "sat": "08:00-19:00", "sun": "08:00-20:00"}'::jsonb, '+7 867 254-98-67', NULL, NULL, ARRAY['culture','religion','history']::text[], false, false, false, 100, 40, 'free'::subscription_tier, 1870);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-147', 'regakh-kafe', '{"ru": "Регах", "en": "Regakh"}'::jsonb, 'food'::poi_category, 'cafe', 'national'::cuisine_type, '{"lat": 43.062475, "lng": 44.633985, "address": {"ru": "Архонское шоссе, 7", "en": "Arkhonskoye shosse, 7"}}'::jsonb, '{"short": {"ru": "Кафе с осетинской и кавказской кухней. Популярное место у местных...", "en": "Cafe with Ossetian and Caucasian cuisine. Popular with locals..."}, "medium": {"ru": "Кафе Регах с осетинской и кавказской кухней в северной части Владикавказа. Домашняя кухня, приятная атмосфера, разумные цены.", "en": "Regakh cafe with Ossetian and Caucasian cuisine in the northern part of Vladikavkaz. Home-style cooking, pleasant atmosphere, reasonable prices."}, "full": {"ru": "Регах — кафе с акцентом на осетинскую и кавказскую кухню. Здесь можно попробовать традиционные пироги, мясные блюда и горячие напитки. Место популярно среди жителей северной части города — за честную еду и комфортную обстановку.", "en": "Regakh is a cafe with a focus on Ossetian and Caucasian cuisine. Here you can try traditional pies, meat dishes, and hot drinks. The place is popular with residents of the city''s northern district for its honest food and comfortable atmosphere."}}'::jsonb, ARRAY['/images/pois/regakh-kafe_8.webp','/images/pois/regakh-kafe_1.webp','/images/pois/regakh-kafe_2.webp','/images/pois/regakh-kafe_3.webp','/images/pois/regakh-kafe_4.webp','/images/pois/regakh-kafe_5.webp','/images/pois/regakh-kafe_6.webp','/images/pois/regakh-kafe_7.webp']::text[], 4.2, '{"sun": "12:00-00:00", "mon": "12:00-00:00", "tue": "12:00-00:00", "wed": "12:00-00:00", "thu": "12:00-00:00", "fri": "12:00-00:00", "sat": "12:00-00:00"}'::jsonb, '+7 919 424-55-29', NULL, 2, ARRAY['кавказская кухня','осетинские пироги','кафе']::text[], false, true, false, 50, 35, 'free'::subscription_tier, 240);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-148', 'l-pole', '{"ru": "L-поле", "en": "L-Pole"}'::jsonb, 'food'::poi_category, 'restaurant', 'european'::cuisine_type, '{"lat": 43.065274, "lng": 44.625022, "address": {"ru": "Архонское шоссе, 6", "en": "Arkhonskoye shosse, 6"}}'::jsonb, '{"short": {"ru": "Современный ресторан с авторской кухней. Широкое меню, атмосферный...", "en": "Modern restaurant with original cuisine. Wide menu, atmospheric..."}, "medium": {"ru": "L-поле — современный ресторан с авторской европейской кухней. Широкое меню, приятный интерьер. Работает с обеда до позднего вечера.", "en": "L-Pole is a modern restaurant with original European cuisine. Wide menu, pleasant interior. Open from lunch through late evening."}, "full": {"ru": "L-поле — ресторан с авторской кухней и современным подходом к подаче блюд. Меню охватывает широкий спектр европейской кулинарии с местными акцентами. Интерьер продуман, атмосфера располагает к долгому ужину. Хорошее место для встречи или семейного выхода.", "en": "L-Pole is a restaurant with original cuisine and a modern approach to food presentation. The menu covers a wide range of European cooking with local accents. The interior is thoughtfully designed and the atmosphere lends itself to a long dinner. A good spot for a gathering or family outing."}}'::jsonb, ARRAY['/images/pois/l-pole_13.webp','/images/pois/l-pole_1.webp','/images/pois/l-pole_2.webp','/images/pois/l-pole_3.webp','/images/pois/l-pole_4.webp','/images/pois/l-pole_5.webp','/images/pois/l-pole_6.webp','/images/pois/l-pole_7.webp','/images/pois/l-pole_8.webp','/images/pois/l-pole_9.webp','/images/pois/l-pole_10.webp','/images/pois/l-pole_11.webp','/images/pois/l-pole_12.webp']::text[], 4.4, '{"sun": "11:00-23:00", "mon": "11:00-23:00", "tue": "11:00-23:00", "wed": "11:00-23:00", "thu": "11:00-23:00", "fri": "11:00-23:00", "sat": "11:00-23:00"}'::jsonb, '+7 (867) 240-30-16', 'https://l-pole.ru', 2, ARRAY['ресторан','европейская кухня','авторская кухня']::text[], false, true, false, 50, 62, 'free'::subscription_tier, 380);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-149', 'magiya-kafe', '{"ru": "Магия", "en": "Magiya"}'::jsonb, 'food'::poi_category, 'cafe', 'european'::cuisine_type, '{"lat": 43.027999, "lng": 44.679466, "address": {"ru": "ул. Максима Горького, 9", "en": "ul. Maksima Gorkogo, 9"}}'::jsonb, '{"short": {"ru": "Кафе в центре города. Завтраки, кофе и домашняя кухня с утра...", "en": "Cafe in the city center. Breakfasts, coffee and home-style cooking..."}, "medium": {"ru": "Кафе «Магия» в центральном районе Владикавказа. Работает с раннего утра — хорошее место для завтрака, кофе или обеда.", "en": "Magiya cafe in the central district of Vladikavkaz. Open from early morning — a good place for breakfast, coffee, or lunch."}, "full": {"ru": "«Магия» открывается рано и закрывается поздно — с 8 утра до 11 вечера. Это делает её удобным местом на весь день: завтрак с кофе, деловой обед, вечерний десерт. Европейское меню, приятная атмосфера, доступные цены. Хорошо расположена в центре города.", "en": "Magiya opens early and closes late — from 8am to 11pm. This makes it a convenient all-day spot: breakfast with coffee, a business lunch, an evening dessert. European menu, pleasant atmosphere, affordable prices. Well located in the city center."}}'::jsonb, ARRAY['/images/pois/magia_1.webp','/images/pois/magia_2.webp','/images/pois/magia_3.webp','/images/pois/magia_4.webp','/images/pois/magia_5.webp','/images/pois/magia_6.webp','/images/pois/magia_7.webp']::text[], 4.2, '{"sun": "08:00-23:00", "mon": "08:00-23:00", "tue": "08:00-23:00", "wed": "08:00-23:00", "thu": "08:00-23:00", "fri": "08:00-23:00", "sat": "08:00-23:00"}'::jsonb, '+7 (8672) 54-06-48', NULL, 1, ARRAY['завтраки','кофе','кафе','центр']::text[], false, true, false, 50, 40, 'free'::subscription_tier, 290);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-150', 'vinograd-restoran', '{"ru": "Виноград", "en": "Vinograd"}'::jsonb, 'food'::poi_category, 'restaurant', 'european'::cuisine_type, '{"lat": 43.039244, "lng": 44.630525, "address": {"ru": "ул. Цоколаева, 15", "en": "ul. Tsokolaeva, 15"}}'::jsonb, '{"short": {"ru": "Ресторан с акцентом на вина и авторскую кухню. Работает до полуночи...", "en": "Restaurant with a focus on wines and original cuisine. Open until midnight..."}, "medium": {"ru": "Ресторан «Виноград» с хорошей винной картой и авторской кухней. Работает до полуночи — хорошее место для вечернего ужина.", "en": "Vinograd restaurant with a good wine list and original cuisine. Open until midnight — a good place for an evening dinner."}, "full": {"ru": "«Виноград» — ресторан, в котором вину уделяется должное внимание. Карта вин подобрана с пониманием, кухня — европейская с местными нотами. Работает с полудня до полуночи. Подходит для романтического ужина, встречи с друзьями или просто чтобы выпить хорошего вина в правильной обстановке.", "en": "Vinograd is a restaurant where wine gets the attention it deserves. The wine list is curated with knowledge, the cuisine is European with local notes. Open from noon to midnight. Suitable for a romantic dinner, meeting friends, or simply enjoying good wine in the right setting."}}'::jsonb, ARRAY['/images/pois/vinograd_8.webp','/images/pois/vinograd_1.webp','/images/pois/vinograd_2.webp','/images/pois/vinograd_3.webp','/images/pois/vinograd_4.webp','/images/pois/vinograd_5.webp','/images/pois/vinograd_6.webp','/images/pois/vinograd_7.webp','/images/pois/vinograd_9.webp']::text[], 4.4, '{"sun": "12:00-00:00", "mon": "12:00-00:00", "tue": "12:00-00:00", "wed": "12:00-00:00", "thu": "12:00-00:00", "fri": "12:00-00:00", "sat": "12:00-00:00"}'::jsonb, '+7 (8672) 70-03-07', NULL, 3, ARRAY['вина','ресторан','ужин','европейская кухня']::text[], false, true, false, 50, 55, 'free'::subscription_tier, 350);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-154', 'vershina-5033', '{"ru": "Вершина 5033", "en": "Vershina 5033"}'::jsonb, 'food'::poi_category, 'restaurant', 'national'::cuisine_type, '{"lat": 43.03, "lng": 44.671, "address": {"ru": "пр. Мира, 10, Владикавказ", "en": "10 Mira Ave, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Ресторан на пр. Мира. Осетинская и кавказская кухня, атмосферный...", "en": "Restaurant on Mira Ave. Ossetian and Caucasian cuisine, atmospheric..."}, "medium": {"ru": "Ресторан «Вершина 5033» на пр. Мира — осетинская и кавказская кухня в центре Владикавказа. Название отсылает к высоте Казбека. Работает с 9 утра до 11 вечера.", "en": "Vershina 5033 restaurant on Mira Ave — Ossetian and Caucasian cuisine in central Vladikavkaz. The name references the height of Kazbek. Open from 9am to 11pm."}, "full": {"ru": "«Вершина 5033» — название говорит само за себя: 5033 метра — высота Казбека, символа Владикавказа. Ресторан на проспекте Мира предлагает осетинскую и кавказскую кухню: пироги, шашлык, национальные блюда. Работает почти весь день — с 9 утра до 11 вечера. Хорошее место, чтобы погрузиться в местную гастрономию.", "en": "Vershina 5033 — the name speaks for itself: 5033 meters is the height of Kazbek, the symbol of Vladikavkaz. The restaurant on Mira Avenue offers Ossetian and Caucasian cuisine: pies, shashlik, traditional dishes. Open almost all day — from 9am to 11pm. A good place to immerse yourself in local gastronomy."}}'::jsonb, ARRAY['/images/pois/vershina-5033_15.webp','/images/pois/vershina-5033_1.webp','/images/pois/vershina-5033_2.webp','/images/pois/vershina-5033_3.webp','/images/pois/vershina-5033_4.webp','/images/pois/vershina-5033_5.webp','/images/pois/vershina-5033_6.webp','/images/pois/vershina-5033_7.webp','/images/pois/vershina-5033_8.webp','/images/pois/vershina-5033_9.webp','/images/pois/vershina-5033_10.webp','/images/pois/vershina-5033_11.webp','/images/pois/vershina-5033_12.webp','/images/pois/vershina-5033_13.webp','/images/pois/vershina-5033_14.webp']::text[], 4.4, '{"sun": "09:00-23:00", "mon": "09:00-23:00", "tue": "09:00-23:00", "wed": "09:00-23:00", "thu": "09:00-23:00", "fri": "09:00-23:00", "sat": "09:00-23:00"}'::jsonb, '+7 (8672) 46-50-40', 'https://vershina5033.ru', 2, ARRAY['осетинская кухня','кавказская кухня','ресторан','национальные блюда']::text[], false, true, false, 50, 85, 'free'::subscription_tier, 520);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-155', 'verdi-restoran', '{"ru": "Verdi", "en": "Verdi"}'::jsonb, 'food'::poi_category, 'restaurant', 'italian'::cuisine_type, '{"lat": 43.027, "lng": 44.673, "address": {"ru": "ул. Коцоева, 73А, Владикавказ", "en": "73A Kotsoyeva St, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Ресторан с итальянским настроением. Пиццы, пасты, вина — открыт круглосуточно...", "en": "Restaurant with an Italian mood. Pizzas, pastas, wines — open around the clock..."}, "medium": {"ru": "Verdi на ул. Коцоева — ресторан с итальянской и европейской кухней. Открыт практически круглосуточно: с 7 утра до полуночи. Широкий выбор блюд и напитков.", "en": "Verdi on Kotsoyeva St is a restaurant with Italian and European cuisine. Open nearly round the clock: from 7am to midnight. Wide selection of dishes and drinks."}, "full": {"ru": "Verdi — ресторан итальянской и европейской кухни на ул. Коцоева. Открывается в 7 утра и работает до полуночи — один из немногих вариантов для раннего завтрака в центре. Меню включает пиццы, пасты, горячие блюда и широкий выбор напитков. Атмосфера приятная, подходит как для завтрака, так и для позднего ужина.", "en": "Verdi is an Italian and European cuisine restaurant on Kotsoyeva Street. It opens at 7am and operates until midnight — one of the few options for an early breakfast in the center. The menu includes pizzas, pastas, hot dishes, and a wide selection of drinks. The atmosphere is pleasant, suitable for both breakfast and a late dinner."}}'::jsonb, ARRAY['/images/pois/verdi-restoran_5.webp','/images/pois/verdi-restoran_1.webp','/images/pois/verdi-restoran_2.webp','/images/pois/verdi-restoran_3.webp','/images/pois/verdi-restoran_4.webp','/images/pois/verdi-restoran_6.webp','/images/pois/verdi-restoran_7.webp','/images/pois/verdi-restoran_8.webp','/images/pois/verdi-restoran_9.webp','/images/pois/verdi-restoran_10.webp','/images/pois/verdi-restoran_11.webp','/images/pois/verdi-restoran_12.webp','/images/pois/verdi-restoran_13.webp','/images/pois/verdi-restoran_14.webp','/images/pois/verdi-restoran_15.webp','/images/pois/verdi-restoran_16.webp']::text[], 4.3, '{"sun": "07:00-00:00", "mon": "07:00-00:00", "tue": "07:00-00:00", "wed": "07:00-00:00", "thu": "07:00-00:00", "fri": "07:00-00:00", "sat": "07:00-00:00"}'::jsonb, '+7 962 270-00-04', 'https://verdi-restaurant.ru', 2, ARRAY['итальянская кухня','пицца','паста','завтраки','ресторан']::text[], false, true, false, 50, 60, 'free'::subscription_tier, 410);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-156', 'irbis-restoran', '{"ru": "Ирбис", "en": "Irbis"}'::jsonb, 'food'::poi_category, 'restaurant', 'national'::cuisine_type, '{"lat": 43.022, "lng": 44.681, "address": {"ru": "ул. Гадиева, 81В, Владикавказ", "en": "81V Gadiyeva St, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Ресторан на ул. Гадиева. Кавказская кухня, поздний режим работы...", "en": "Restaurant on Gadiyeva St. Caucasian cuisine, late opening hours..."}, "medium": {"ru": "Ресторан «Ирбис» на ул. Гадиева с кавказской кухней. Работает допоздна — подходит для позднего ужина и встреч в вечернее время.", "en": "Irbis restaurant on Gadiyeva Street with Caucasian cuisine. Open late — suitable for a late dinner and evening gatherings."}, "full": {"ru": "«Ирбис» — ресторан на ул. Гадиева, названный в честь снежного барса — символа горных регионов Кавказа. Кавказская кухня, позднее время работы. Хороший выбор для ужина, когда другие заведения уже закрыты.", "en": "Irbis is a restaurant on Gadiyeva Street, named after the snow leopard — a symbol of the mountain regions of the Caucasus. Caucasian cuisine, late hours. A good choice for dinner when other establishments are already closed."}}'::jsonb, ARRAY['/images/pois/irbis-restoran_5.webp','/images/pois/irbis-restoran_1.webp','/images/pois/irbis-restoran_2.webp','/images/pois/irbis-restoran_3.webp','/images/pois/irbis-restoran_4.webp','/images/pois/irbis-restoran_6.webp','/images/pois/irbis-restoran_7.webp','/images/pois/irbis-restoran_8.webp','/images/pois/irbis-restoran_9.webp','/images/pois/irbis-restoran_10.webp','/images/pois/irbis-restoran_11.webp','/images/pois/irbis-restoran_12.webp','/images/pois/irbis-restoran_13.webp','/images/pois/irbis-restoran_14.webp','/images/pois/irbis-restoran_15.webp','/images/pois/irbis-restoran_16.webp','/images/pois/irbis-restoran_17.webp']::text[], 4.2, '{"sun": "12:00-00:00", "mon": "12:00-00:00", "tue": "12:00-00:00", "wed": "12:00-00:00", "thu": "12:00-00:00", "fri": "12:00-00:00", "sat": "12:00-00:00"}'::jsonb, '+7 (8672) 52-21-00', NULL, 2, ARRAY['кавказская кухня','ресторан','поздний ужин']::text[], false, true, false, 50, 42, 'free'::subscription_tier, 280);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-164', 'memorial-slavy', '{"ru": "Мемориал Славы", "en": "Memorial of Glory"}'::jsonb, 'attractions'::poi_category, 'monument', NULL, '{"lat": 43.000882, "lng": 44.677758, "address": {"ru": "ул. Красногвардейская, Владикавказ", "en": "Krasnovardeiskaya St, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Мемориальный комплекс в честь победы в Великой Отечественной войне — триумфальная арка, Аллея Славы и вечный огонь.", "en": "Memorial complex honoring WWII victory — a triumphal arch, Alley of Glory and eternal flame."}, "medium": {"ru": "Мемориал Славы открыт в 2005 году на юге Владикавказа. Центральный вход — триумфальная арка с бронзовыми скульптурами двух солдат. За аркой — Аллея Славы с именами погибших уроженцев Осетии. Один из главных мемориальных комплексов республики.", "en": "The Memorial of Glory was opened in 2005 in southern Vladikavkaz. The triumphal arch entrance features bronze sculptures of two soldiers. Behind it — the Alley of Glory with the names of fallen Ossetians."}, "full": {"ru": "Мемориал Славы — главный военный мемориал Северной Осетии, открытый в 2005 году. Комплекс занимает большую территорию на улице Красногвардейской. Триумфальная арка при входе увенчана двумя бронзовыми солдатами. Аллея Славы ведёт мимо плит с именами более пяти тысяч уроженцев республики, павших в Великой Отечественной. В глубине комплекса горит вечный огонь. Место, где Владикавказ помнит.", "en": "The Memorial of Glory is the main military memorial of North Ossetia, opened in 2005. The triumphal arch is crowned with two bronze soldiers. The Alley of Glory leads past plaques bearing the names of over five thousand natives of the republic who fell in WWII. At the far end burns an eternal flame."}}'::jsonb, ARRAY['/images/pois/memorial-slavy.webp','/images/pois/memorial-slavy_gp.webp','/images/pois/memorial-slavy_2.webp','/images/pois/memorial-slavy_3.webp','/images/pois/memorial-slavy_4.webp','/images/pois/memorial-slavy_5.webp','/images/pois/memorial-slavy_6.webp','/images/pois/memorial-slavy_7.webp']::text[], 4.7, NULL, NULL, NULL, NULL, ARRAY['мемориал','история','ВОВ','обязательно к посещению']::text[], false, false, false, 100, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-165', 'pliev-monument', '{"ru": "Памятник генералу Исса Плиеву", "en": "Monument to General Issa Pliev"}'::jsonb, 'attractions'::poi_category, 'monument', NULL, '{"lat": 43.019819, "lng": 44.680087, "address": {"ru": "площадь Генерала Плиева, Владикавказ", "en": "General Pliev Square, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Конный памятник прославленному осетинскому генералу — одна из самых узнаваемых скульптур города.", "en": "Equestrian monument to the legendary Ossetian general — one of the city''s most recognizable sculptures."}, "medium": {"ru": "Исса Плиев — генерал армии, дважды Герой Советского Союза, уроженец Осетии. Конный памятник установлен на площади его имени. Скульптура изображает Плиева в полном военном облачении верхом на коне.", "en": "Issa Pliev — Army General, twice Hero of the Soviet Union, native of Ossetia. The equestrian monument stands on the square bearing his name."}, "full": {"ru": "Исса Александрович Плиев родился в 1903 году в Осетии. Выдающийся советский военачальник, командовавший конно-механизированными группами в годы Великой Отечественной. Дважды Герой Советского Союза, Герой МНР. В 1962 году командовал советскими войсками на Кубе. Конный памятник на площади его имени — один из самых выразительных монументов Владикавказа, работа скульптора Юрия Чернова.", "en": "Issa Pliev was born in 1903 in Ossetia. An outstanding Soviet military commander, he led cavalry-mechanized groups during WWII. Twice Hero of the Soviet Union. In 1962 he commanded Soviet forces in Cuba. The equestrian monument on the square bearing his name is one of the most expressive monuments in Vladikavkaz."}}'::jsonb, ARRAY['/images/pois/pliev-monument.webp','/images/pois/pliev-monument_gp.webp','/images/pois/pliev-monument_2.webp','/images/pois/pliev-monument_3.webp','/images/pois/pliev-monument_4.webp']::text[], 4.5, NULL, NULL, NULL, NULL, ARRAY['памятник','история','конная скульптура']::text[], false, false, false, 100, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-166', 'vladikavkaz-history-museum', '{"ru": "Музей истории Владикавказа", "en": "Vladikavkaz History Museum"}'::jsonb, 'museums'::poi_category, 'museum', NULL, '{"lat": 43.034926, "lng": 44.682355, "address": {"ru": "ул. Революции, 61, Владикавказ", "en": "Revolyutsii St, 61, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Музей в историческом здании с экспозицией об истории города от крепости XIX века до наших дней.", "en": "Museum in a historic building with an exhibition on the city''s history from the 19th-century fortress to today."}, "medium": {"ru": "Музей истории Владикавказа расположен в историческом центре города. Экспозиция охватывает период от основания крепости в 1784 году до современности. Документы, фотографии, предметы быта, военные артефакты — всё о превращении пограничной крепости в столицу Северной Осетии.", "en": "The museum covers the period from the founding of the fortress in 1784 to the present. Documents, photographs, everyday objects, military artifacts tell the story of this border fortress becoming the capital of North Ossetia."}, "full": {"ru": "Музей истории Владикавказа — хранилище городской памяти. Здесь можно увидеть как выглядел Владикавказ в разные эпохи: планы крепости 1784 года, фотографии дореволюционного «Кавказского Петербурга», документы советского времени. Отдельные залы посвящены Великой Отечественной войне, обороне Кавказа и послевоенному восстановлению. Экспонаты помогают понять, как небольшая военная крепость стала крупным городом с богатой историей.", "en": "The museum is a repository of urban memory. You can see how Vladikavkaz looked in different eras: fortress plans from 1784, photos of pre-revolutionary \"Caucasian Petersburg\", Soviet-era documents. Separate halls cover WWII and the defense of the Caucasus."}}'::jsonb, ARRAY['/images/pois/vladikavkaz-history-museum.webp','/images/pois/vladikavkaz-history-museum_gp.webp','/images/pois/vladikavkaz-history-museum_2.webp','/images/pois/vladikavkaz-history-museum_3.webp','/images/pois/vladikavkaz-history-museum_4.webp','/images/pois/vladikavkaz-history-museum_5.webp','/images/pois/vladikavkaz-history-museum_6.webp','/images/pois/vladikavkaz-history-museum_7.webp','/images/pois/vladikavkaz-history-museum_8.webp']::text[], 4.3, '{"tue": "10:00-18:00", "wed": "10:00-18:00", "thu": "10:00-18:00", "fri": "10:00-18:00", "sat": "10:00-18:00", "sun": "10:00-18:00"}'::jsonb, NULL, NULL, NULL, ARRAY['музей','история','Владикавказ']::text[], false, false, false, 100, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-167', 'pliev-house-museum', '{"ru": "Дом-музей генерала Плиева", "en": "General Pliev House-Museum"}'::jsonb, 'museums'::poi_category, 'museum', NULL, '{"lat": 43.030397, "lng": 44.687801, "address": {"ru": "ул. Бородинская, 7, Владикавказ", "en": "Borodinskaya St, 7, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Мемориальная квартира дважды Героя Советского Союза генерала Исса Плиева с личными вещами и наградами.", "en": "Memorial apartment of twice Hero of the Soviet Union General Issa Pliev, with personal belongings and awards."}, "medium": {"ru": "Дом-музей Исса Плиева открыт в квартире, где жил прославленный генерал. Личные вещи, два ордена Золотой Звезды, военное снаряжение, документы и фотографии с маршалами Жуковым, Коневым и Рокоссовским.", "en": "The Pliev House-Museum is open in the apartment where the legendary general lived. Personal belongings, two Orders of the Gold Star, military equipment, photos with Marshals Zhukov, Konev and Rokossovsky."}, "full": {"ru": "Дом-музей Исса Плиева — камерное и трогательное место. Квартира сохранена почти в том виде, в каком её оставил генерал: личный кабинет с картами и книгами, коллекция наград, фотографии со Сталиным, Жуковым и другими маршалами. Здесь чувствуется масштаб человека, чьё имя носит одна из центральных площадей Владикавказа. Музей небольшой, но посещение занимает около часа.", "en": "The Pliev House-Museum is an intimate place. The apartment is preserved almost as the general left it: his personal study with maps and books, award collection, photographs with Stalin, Zhukov and other marshals. A place to feel the scale of the man whose name graces one of the central squares of Vladikavkaz."}}'::jsonb, ARRAY['/images/pois/pliev-house-museum.webp','/images/pois/pliev-house-museum_gp.webp','/images/pois/pliev-house-museum_2.webp','/images/pois/pliev-house-museum_3.webp','/images/pois/pliev-house-museum_4.webp','/images/pois/pliev-house-museum_5.webp']::text[], 4.4, '{"tue": "10:00-17:00", "wed": "10:00-17:00", "thu": "10:00-17:00", "fri": "10:00-17:00", "sat": "10:00-17:00"}'::jsonb, NULL, NULL, NULL, ARRAY['музей','история','военная история']::text[], false, false, false, 100, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-168', 'vladikavkaz-zoo', '{"ru": "Зоопарк Владикавказа", "en": "Vladikavkaz Zoo"}'::jsonb, 'attractions'::poi_category, 'park', NULL, '{"lat": 42.995925, "lng": 44.676758, "address": {"ru": "просп. Коста, 24, Владикавказ", "en": "Kosta Ave, 24, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Городской зоопарк с более чем 200 видами животных, в том числе кавказскими — горными козлами, турами и леопардами.", "en": "City zoo with over 200 animal species including Caucasian mountain goats, tur and leopards."}, "medium": {"ru": "Зоопарк Владикавказа — один из немногих зоопарков Северного Кавказа. На территории около 10 гектаров содержится более 200 видов животных: кавказские туры, серны, леопарды, а также жирафы, слоны, зебры. Популярное место для семейного отдыха. Рядом — Детская железная дорога.", "en": "One of the few zoos in the North Caucasus. Its 10 hectares house over 200 species including Caucasian tur, chamois, leopards, as well as giraffes, elephants and zebras. Adjacent to the Children''s Railway."}, "full": {"ru": "Зоопарк Владикавказа расположен на проспекте Коста. Коллекция включает кавказские эндемики — виды, которых большинство горожан никогда не видело в дикой природе: туры, серны, кавказские леопарды. Есть и африканская экзотика. Зоопарк постепенно модернизируется. Хорошее место для семейного дня, особенно если совместить с поездкой на Детской железной дороге — она в 200 метрах.", "en": "The Vladikavkaz Zoo is located on Kosta Avenue. The collection includes Caucasian endemics: tur, chamois, Caucasian leopards — animals most city residents have never seen in the wild. There is also African wildlife. A good place for a family day, especially combined with a ride on the Children''s Railway 200m away."}}'::jsonb, ARRAY['/images/pois/vladikavkaz-zoo.webp','/images/pois/vladikavkaz-zoo_gp.webp','/images/pois/vladikavkaz-zoo_2.webp','/images/pois/vladikavkaz-zoo_3.webp','/images/pois/vladikavkaz-zoo_4.webp']::text[], 4.1, '{"mon": "10:00-18:00", "tue": "10:00-18:00", "wed": "10:00-18:00", "thu": "10:00-18:00", "fri": "10:00-18:00", "sat": "10:00-18:00", "sun": "10:00-18:00"}'::jsonb, '+7 (867) 253-36-36', NULL, 1, ARRAY['зоопарк','семья','природа','дети']::text[], false, false, false, 100, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-169', 'childrens-railway', '{"ru": "Детская железная дорога", "en": "Children''s Railway"}'::jsonb, 'attractions'::poi_category, 'park', NULL, '{"lat": 42.996498, "lng": 44.676422, "address": {"ru": "просп. Коста, 30, Владикавказ", "en": "Kosta Ave, 30, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Миниатюрная железная дорога 4,5 км — один из старейших детских аттракционов Кавказа, работает с 1940-х годов.", "en": "A 4.5 km miniature railway — one of the oldest children''s attractions in the Caucasus, operating since the 1940s."}, "medium": {"ru": "Детская железная дорога Владикавказа работает с 1940-х годов. Маршрут 4,5 км проходит через живописный парк, поездка занимает около 20 минут. Летом здесь многолюдно — горожане приходят целыми семьями. Работает только в тёплый сезон, с мая по октябрь.", "en": "The Children''s Railway has been operating since the 1940s. The 4.5 km route runs through a picturesque park. The ride takes about 20 minutes. Open May–October only."}, "full": {"ru": "Детская железная дорога Владикавказа — один из немногих сохранившихся детских железнодорожных маршрутов на Кавказе. Небольшие тепловозы тянут состав из разноцветных вагонов по кольцу через парк. Узкоколейка 750 мм, настоящая тяга — это не просто аттракцион, а уменьшенная копия настоящей железной дороги. Дорога работает только в тёплое время года, с мая по октябрь. Рядом — зоопарк и городской парк.", "en": "The Children''s Railway of Vladikavkaz is one of the few remaining children''s railways in the Caucasus. Small diesel locomotives pull colorful carriages around a loop through the park. Operating May to October only. Adjacent to the city zoo."}}'::jsonb, ARRAY['/images/pois/childrens-railway.webp','/images/pois/childrens-railway_gp.webp','/images/pois/childrens-railway_2.webp','/images/pois/childrens-railway_3.webp']::text[], 4.4, NULL, NULL, NULL, 1, ARRAY['дети','парк','аттракцион','семья']::text[], false, false, false, 100, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-170', 'kosta-khetagurov-monument', '{"ru": "Памятник Коста Хетагурову", "en": "Kosta Khetagurov Monument"}'::jsonb, 'attractions'::poi_category, 'monument', NULL, '{"lat": 43.032336, "lng": 44.66901, "address": {"ru": "ул. Карла Маркса, 70, Владикавказ", "en": "Karl Marx St, 70, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Памятник основоположнику осетинской литературы и национальному поэту Коста Хетагурову.", "en": "Monument to the founder of Ossetian literature and national poet Kosta Khetagurov."}, "medium": {"ru": "Коста Хетагуров (1859–1906) — осетинский поэт, художник, публицист, основоположник осетинской литературы. Его имя носят парк, улицы, проспект и театр во Владикавказе. Памятник установлен на улице Карла Маркса.", "en": "Kosta Khetagurov (1859–1906) was an Ossetian poet, artist, publicist, and the founder of Ossetian literature. The monument stands on Karl Marx Street."}, "full": {"ru": "Коста Хетагуров — фигура, без которой невозможно понять Осетию. Поэт, писавший на осетинском и русском языках, художник и общественный деятель. Его сборник «Осетинская лира» (Ирон фандыр) стал первым литературным произведением на осетинском языке. Именем Коста названы главный парк Владикавказа, проспект и государственный театр. Памятник на улице Карла Маркса стоит среди старых домов дореволюционной застройки, в которой поэт и провёл большую часть жизни.", "en": "Kosta Khetagurov is a figure without whom Ossetia cannot be understood. A poet writing in Ossetian and Russian, his collection \"Ossetian Lyre\" (Iron Fandyr) was the first literary work in the Ossetian language. The city''s main park, avenue and state theatre all bear his name. The monument stands among the pre-revolutionary buildings where the poet spent much of his life."}}'::jsonb, ARRAY['/images/pois/kosta-khetagurov-monument.webp','/images/pois/kosta-khetagurov-monument_gp.webp','/images/pois/kosta-khetagurov-monument_2.webp','/images/pois/kosta-khetagurov-monument_3.webp']::text[], 4.5, NULL, NULL, NULL, NULL, ARRAY['памятник','Коста Хетагуров','история','литература']::text[], false, false, false, 100, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-171', 'north-ossetian-philharmonic', '{"ru": "Северо-Осетинская государственная филармония", "en": "North Ossetian State Philharmonic"}'::jsonb, 'attractions'::poi_category, 'concert_hall', NULL, '{"lat": 43.03671, "lng": 44.67784, "address": {"ru": "ул. Миллера, 34, Владикавказ", "en": "Millera St, 34, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Главная концертная площадка республики в здании бывшей лютеранской церкви 1824 года постройки.", "en": "The republic''s main concert venue, housed in a former Lutheran church built in 1824."}, "medium": {"ru": "Северо-Осетинская филармония расположена в здании бывшей лютеранской церкви Святого Архангела Михаила (1824) — памятнике архитектуры. В концертном зале проходят симфонические концерты, выступления ансамбля «Алан» и других коллективов.", "en": "The Philharmonic is housed in the former Lutheran Church of St. Michael (1824), an architectural landmark. The concert hall hosts symphonic performances and the Alan ensemble."}, "full": {"ru": "Это здание — один из парадоксов Владикавказа. Лютеранская кирха 1824 года постройки сегодня служит главным концертным залом республики. Строгий немецкий неоклассицизм неожиданно красиво смотрится на фоне кавказского пейзажа. Внутри хорошая акустика, программы от классики до народной осетинской музыки. Государственный ансамбль «Алан», ансамбли традиционного пения, симфонические концерты — стоит проверить афишу. И в любом случае заглянуть ради здания снаружи — оно выглядит как привет из другой эпохи.", "en": "This building is one of the paradoxes of Vladikavkaz. A Lutheran church built in 1824 serves as the republic''s main concert hall. Strict German neo-classicism looks unexpectedly beautiful against a Caucasian backdrop. Good acoustics inside, programs ranging from classical to traditional Ossetian music. Worth checking the schedule — and worth stopping by just to see the building from outside."}}'::jsonb, ARRAY['/images/pois/north-ossetian-philharmonic.webp','/images/pois/north-ossetian-philharmonic_gp.webp','/images/pois/north-ossetian-philharmonic_2.webp','/images/pois/north-ossetian-philharmonic_3.webp','/images/pois/north-ossetian-philharmonic_4.webp','/images/pois/north-ossetian-philharmonic_5.webp','/images/pois/north-ossetian-philharmonic_6.webp']::text[], 4.5, NULL, '+7 (867) 253-04-09', 'http://filarmoniya-vladikavkaz.ru/', NULL, ARRAY['концерт','музыка','архитектура','культура']::text[], false, false, false, 100, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-172', 'steinghel-mansion', '{"ru": "Особняк барона Штейнгеля", "en": "Baron Steinghel Mansion"}'::jsonb, 'attractions'::poi_category, 'architecture', NULL, '{"lat": 43.027351, "lng": 44.678987, "address": {"ru": "ул. Максима Горького, 6, Владикавказ", "en": "Maxima Gorkogo St, 6, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Один из красивейших дореволюционных особняков Владикавказа — памятник архитектуры федерального значения, конец XIX века.", "en": "One of the most beautiful pre-revolutionary mansions in Vladikavkaz, a federally protected architectural monument from the late 19th century."}, "medium": {"ru": "Особняк барона Штейнгеля — памятник архитектуры федерального значения. Построен в конце XIX века в стиле эклектики с элементами ренессанса. Богатый лепной декор, арочные окна, угловая башня делают особняк одним из самых красивых исторических зданий Владикавказа.", "en": "The Steinghel Mansion is a federally protected architectural monument. Built in the late 19th century in eclectic style with Renaissance elements. Rich stucco decor, arched windows and a corner tower make it one of the most beautiful historic buildings in Vladikavkaz."}, "full": {"ru": "Владикавказ конца XIX века часто называли «Кавказским Петербургом» — и особняк Штейнгеля объясняет почему. Богатые купцы и чиновники строили здесь дома не хуже столичных. Этот особняк с его роскошным лепным фасадом, арочными окнами и угловой башенкой — один из лучших примеров той эпохи. Сегодня здание используется как административное. Стоит пройти мимо, особенно если идти по Проспекту Мира — особняк в полутора кварталах от него.", "en": "Late 19th-century Vladikavkaz was often called the \"Caucasian Petersburg\" — the Steinghel Mansion explains why. This mansion with its ornate facade, arched windows and corner tower is one of the finest examples of that era. Today used as an office building. Worth a stop if walking near Prospekt Mira — it''s a block and a half away."}}'::jsonb, ARRAY['/images/pois/steinghel-mansion.webp','/images/pois/steinghel-mansion_gp.webp','/images/pois/steinghel-mansion_2.webp']::text[], 4.3, NULL, NULL, NULL, NULL, ARRAY['архитектура','XIX век','исторический центр']::text[], false, false, false, 100, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-173', 'ilyinskaya-church', '{"ru": "Ильинская церковь", "en": "Church of St. Elijah"}'::jsonb, 'attractions'::poi_category, 'church', NULL, '{"lat": 43.019673, "lng": 44.664538, "address": {"ru": "ул. Дзержинского, 70, Владикавказ", "en": "Dzerzhinskogo St, 70, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Одна из старейших православных церквей Владикавказа, основанная в 1796 году — первый приход города.", "en": "One of the oldest Orthodox churches in Vladikavkaz, established in 1796 — the city''s first parish."}, "medium": {"ru": "Ильинская церковь — первая православная церковь Владикавказа. Первоначальное здание возведено в 1796 году. Освящена в честь пророка Илии. Скромный по размерам, но значимый по истории храм — он старше большинства городских кварталов.", "en": "The Church of St. Elijah is the first Orthodox church of Vladikavkaz. The original building was erected in 1796, dedicated to the Prophet Elijah. Modest in size but historically significant — older than most city blocks."}, "full": {"ru": "Ильинская церковь стоит здесь с 1796 года — она старше многих кварталов современного Владикавказа. Первоначально деревянная, позже перестроенная в камне, церковь сохранила значение православного прихода Осетинской слободы. Внешне неприметная, она важна как памятник первых лет существования города. Вокруг — тихие улочки старого Владикавказа, в которых ещё чувствуется дух XIX века.", "en": "The Church of St. Elijah has stood here since 1796 — older than many blocks of modern Vladikavkaz. Originally wooden, later rebuilt in stone, the church retained its significance as a parish of the Ossetian settlement. Externally understated, it is an important monument to the city''s earliest years."}}'::jsonb, ARRAY['/images/pois/ilyinskaya-church.webp','/images/pois/ilyinskaya-church_gp.webp','/images/pois/ilyinskaya-church_2.webp','/images/pois/ilyinskaya-church_3.webp','/images/pois/ilyinskaya-church_4.webp','/images/pois/ilyinskaya-church_5.webp']::text[], 4.3, NULL, NULL, NULL, NULL, ARRAY['церковь','православие','история','XIX век']::text[], false, false, false, 100, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-174', 'hotel-bumerang', '{"ru": "Гостиница «Бумеранг»", "en": "Boomerang Hotel"}'::jsonb, 'accommodation'::poi_category, 'Гостиница', NULL, '{"lat": 43.0142, "lng": 44.6543, "address": {"ru": "ул. Васо Абаева, 69Б, Владикавказ, Респ. Северная Осетия — Алания", "en": "69B Vaso Abaev St, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Яркий двухэтажный отель 3★ в черно-красных тонах вблизи зоопарка Владикавказа.", "en": "A bright 3★ hotel in black and red near Vladikavkaz Zoo."}, "medium": {"ru": "Гостиница «Бумеранг» — современный двухэтажный отель 3★ с запоминающимся черно-красным фасадом. Расположена вблизи зоопарка, 15 уютных номеров. Цены от 3 205 ₽/ночь.", "en": "Boomerang Hotel is a modern 3★ two-story hotel with a memorable black-and-red facade, located near the zoo. 15 cozy rooms from 3,205 RUB/night."}, "full": {"ru": "Гостиница «Бумеранг» — современный отель категории 3 звезды с оригинальным черно-красным фасадом. Расположена в тихом районе Владикавказа вблизи зоопарка, в окружении зелени. 15 номеров различных категорий оснащены кондиционером, телевизором и всем необходимым для комфортного проживания. Территория отеля включает собственную парковку и аккуратно обустроенный двор. Цены от 3 205 ₽ в сутки.", "en": "Boomerang Hotel is a 3-star property with a distinctive black-and-red facade, situated in a quiet residential area near Vladikavkaz Zoo. 15 rooms of various categories are equipped with air conditioning, TV, and all the essentials for a comfortable stay. The property features on-site parking and a well-maintained courtyard. Rates from 3,205 RUB per night."}}'::jsonb, ARRAY['/images/pois/hotel-bumerang_facade.webp','/images/pois/hotel-bumerang_1.webp','/images/pois/hotel-bumerang_2.webp','/images/pois/hotel-bumerang_3.webp','/images/pois/hotel-bumerang_4.webp','/images/pois/hotel-bumerang_5.webp','/images/pois/hotel-bumerang_6.webp','/images/pois/hotel-bumerang_7.webp']::text[], 4.6, '{"mon": "00:00-23:59"}'::jsonb, '+7 (8672) 53-40-00', 'http://boomerang-hotel.ru/', 2, ARRAY['уютный отель','рядом с зоопарком','парковка','3 звезды']::text[], false, false, false, 80, 314, 'free'::subscription_tier, 3200);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-175', 'hotel-kameliya-v', '{"ru": "Гостиница «Камелия-В»", "en": "Kameliya-V Hotel"}'::jsonb, 'accommodation'::poi_category, 'Гостиница', NULL, '{"lat": 43.0247, "lng": 44.6752, "address": {"ru": "ул. Калинина, 1, Владикавказ, Респ. Северная Осетия — Алания", "en": "1 Kalinina St, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Уютная 3★ гостиница в центре Владикавказа с рестораном и кофейней.", "en": "A cozy 3★ hotel in central Vladikavkaz with restaurant and café."}, "medium": {"ru": "Гостиница «Камелия-В» — 3★ отель в самом центре Владикавказа. 26 номеров, ресторан европейской кухни, кофейня, бесплатный Wi-Fi. Цены от 3 200 ₽/ночь.", "en": "Kameliya-V Hotel is a 3★ property in the very center of Vladikavkaz. 26 rooms, European restaurant, café, free Wi-Fi. Rates from 3,200 RUB/night."}, "full": {"ru": "Гостиница «Камелия-В» расположена в историческом центре Владикавказа на улице Калинина. Отель категории 3 звезды предлагает 26 хорошо оснащённых номеров с кондиционером и бесплатным Wi-Fi. На территории работает ресторан европейской кухни и кофейня. К услугам гостей — прачечная, конференц-зал, собственная парковка и круглосуточная стойка регистрации. Рейтинг отеля — 4.5/5 на основе более 370 отзывов. Цены от 3 200 ₽ в сутки.", "en": "Kameliya-V Hotel is located in the historic center of Vladikavkaz on Kalinina Street. This 3-star property offers 26 well-equipped rooms with air conditioning and free Wi-Fi. The hotel features a European restaurant and café. Amenities include a laundry service, conference hall, private parking, and 24-hour front desk. Hotel rating is 4.5/5 based on over 370 reviews. Rates from 3,200 RUB per night."}}'::jsonb, ARRAY['/images/pois/hotel-kameliya-v_facade.webp','/images/pois/hotel-kameliya-v_1.webp','/images/pois/hotel-kameliya-v_2.webp','/images/pois/hotel-kameliya-v_3.webp','/images/pois/hotel-kameliya-v_4.webp','/images/pois/hotel-kameliya-v_5.webp','/images/pois/hotel-kameliya-v_6.webp','/images/pois/hotel-kameliya-v_7.webp','/images/pois/hotel-kameliya-v_8.webp']::text[], 4.5, '{"mon": "00:00-23:59"}'::jsonb, '+7 (867) 251-86-00', 'https://kameliya-v-mini-hotel.rhotel.site/', 2, ARRAY['центр города','ресторан','кофейня','3 звезды']::text[], false, false, false, 80, 376, 'free'::subscription_tier, 4100);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-176', 'roots-park-otel', '{"ru": "ROOTS Парк-отель", "en": "ROOTS Park Hotel"}'::jsonb, 'accommodation'::poi_category, 'Парк-отель', NULL, '{"lat": 42.8165, "lng": 43.8835, "address": {"ru": "Цейское ущелье, Верхний Цей, Северная Осетия — Алания", "en": "Tsey Gorge, Verkhniy Tsey, North Ossetia–Alania"}}'::jsonb, '{"short": {"ru": "Бутик-отель в горах Цейского ущелья на высоте 1 900 м с панорамными коттеджами.", "en": "A boutique mountain hotel at 1,900m in Tsey Gorge with panoramic cottages."}, "medium": {"ru": "ROOTS — концептуальный парк-отель в Цейском ущелье на высоте 1 900 м над уровнем моря. Уединённые коттеджи с панорамными окнами, вид на горные вершины. 90 минут от Владикавказа. Коттеджи от 14 100 ₽/ночь.", "en": "ROOTS is a boutique park hotel in Tsey Gorge at 1,900m altitude. Secluded cottages with panoramic windows and mountain views. 90 minutes from Vladikavkaz. Cottages from 14,100 RUB/night."}, "full": {"ru": "ROOTS Парк-отель — бутик-отель в Цейском ущелье Северной Осетии на высоте 1 900 м над уровнем моря. Концепция: сочетание комфорта городского бутик-отеля с дикой горной природой. Уединённые коттеджи площадью 28 м² с панорамными окнами открывают вид на ущелье и вершины Большого Кавказа. Гостям доступны банный комплекс с горячей купелью, зоны барбекю, костровые площадки, конные маршруты и экологические тропы. Вблизи — подъёмник и святилище Реком. Расстояние от Владикавказа — 90 минут. Стоимость коттеджей от 14 100 ₽/ночь.", "en": "ROOTS Park Hotel is a boutique mountain retreat in the Tsey Gorge of North Ossetia at 1,900m above sea level. The concept blends city-boutique comfort with raw mountain nature. Standalone 28 m² cottages with panoramic windows frame views of the gorge and Greater Caucasus peaks. Guests enjoy a bath house with a hot tub, BBQ zones, fire pit areas, horse trekking routes, and eco-trails. The Recom Sanctuary and a ski lift are nearby. Distance from Vladikavkaz: 90 minutes. Cottages from 14,100 RUB/night."}}'::jsonb, ARRAY['/images/pois/hotel-roots_facade.webp','/images/pois/hotel-roots_1.webp','/images/pois/hotel-roots_2.webp','/images/pois/hotel-roots_3.webp','/images/pois/hotel-roots_4.webp','/images/pois/hotel-roots_5.webp','/images/pois/hotel-roots_6.webp','/images/pois/hotel-roots_7.webp','/images/pois/hotel-roots_8.webp','/images/pois/hotel-roots_9.webp','/images/pois/hotel-roots_10.webp']::text[], 4.9, '{"mon": "00:00-23:59"}'::jsonb, '+7 928 928-63-28', 'https://rootshotel.ru/', 3, ARRAY['горный отель','Цейское ущелье','коттеджи','панорамные виды','эко-отдых']::text[], false, false, false, 80, 89, 'free'::subscription_tier, 2800);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-179', 'ozero-kozskoe', '{"ru": "Озеро Козское", "en": "Koz Lake"}'::jsonb, 'nature'::poi_category, 'nature', NULL, '{"lat": 42.745, "lng": 43.892, "address": {"ru": "Цейское ущелье, Алагирский р-н, Северная Осетия", "en": "Tsey Gorge, North Ossetia"}}'::jsonb, '{"short": {"ru": "Ледниковое озеро на высоте почти 2800 м. Кристально чистая вода и абсолютная тишина вокруг.", "en": "A glacial lake at nearly 2800 m elevation. Crystal-clear water and absolute silence all around."}, "medium": {"ru": "Козское озеро образовалось в 1975–1984 годах за мореной отступавшего ледника. Расположено на высоте 2792 м в Цейском районе. Размеры — 284 × 163 м, глубина около 20 м. Вода ледниковая, прозрачная. Добраться можно пешим маршрутом из Цейского ущелья.", "en": "Koz Lake formed between 1975 and 1984 behind the moraine of a retreating glacier. Located at 2792 m in the Tsey area. Dimensions: 284 × 163 m, depth around 20 m. The water is glacial and clear. Accessible by a hiking trail from the Tsey Gorge."}, "full": {"ru": "Козское озеро — молодое ледниковое озеро, появившееся несколько десятилетий назад, когда отступающий ледник оставил за собой морену. Высота — 2792 м: здесь прохладно даже в разгар лета. Вода прозрачная, на дне видны камни. Берега суровые — крупный курумник и сырой горный воздух. Никаких кафе и парковок. Сюда идут те, кто хочет настоящей горной тишины. Лучшее время — июль–август.", "en": "Koz Lake is a young glacial lake that appeared a few decades ago when a retreating glacier left behind a natural moraine dam. Elevation: 2792 m — cool even in midsummer. The water is crystal-clear, stones visible on the bottom. The shores are austere — boulder fields and damp mountain air. No cafes, no parking. This is for those who want real mountain silence. Best time: July–August."}}'::jsonb, ARRAY['/images/pois/ozero-kozskoe_gp.webp','/images/pois/ozero-kozskoe_2.webp','/images/pois/ozero-kozskoe_3.webp','/images/pois/ozero-kozskoe_4.webp']::text[], 4.7, NULL, NULL, NULL, NULL, ARRAY['nature','lake','hiking']::text[], false, false, false, 800, 54, 'free'::subscription_tier, 890);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-180', 'ozero-tamisk', '{"ru": "Озеро Тамиск", "en": "Tamisk Lake"}'::jsonb, 'nature'::poi_category, 'nature', NULL, '{"lat": 43.052, "lng": 44.065, "address": {"ru": "с. Тамиск, Алагирский р-н, Северная Осетия", "en": "Tamisk village, Alagir district, North Ossetia"}}'::jsonb, '{"short": {"ru": "Бирюзовое минеральное озеро с необычным цветом воды — прямо у дороги на Цей, в 45 км от Владикавказа.", "en": "A turquoise mineral lake with striking water color — right along the road to Tsey, 45 km from Vladikavkaz."}, "medium": {"ru": "Тамиск — небольшое озеро с ярко-бирюзовой водой в Ардонском ущелье. Необычный цвет объясняется высокой минерализацией: вода богата сульфатами и ��арбонатами. Высота — около 730 м. Легкодоступно — прямо с трассы Владикавказ–Цей.", "en": "Tamisk is a small lake with vivid turquoise water in the Ardon Gorge. The unusual color is due to high mineralization: the water is rich in sulfates and carbonates. Elevation: about 730 m. Easily accessible right off the Vladikavkaz–Tsey road."}, "full": {"ru": "Озеро Тамиск притягивает взгляд своим неправдоподобным цветом: вода здесь ярко-бирюзовая. Секрет — в геохимии: озеро питается минеральными источниками, богатыми сульфатами и карбонатами кальция, которые рассеивают свет особым образом. Купаться здесь не принято — вода холодная и сильноминерализованная. Зато это одна из лучших фотолокаций Осетии. Добраться просто: дорога на Цейское ущелье проходит прямо мимо.", "en": "Lake Tamisk catches the eye with its improbable color: vivid turquoise. The secret is geochemical — fed by mineral springs rich in sulfates and calcium carbonates, which scatter light in a special way. Swimming is not common here — the water is cold and heavily mineralized. But it is one of the best photo locations in Ossetia. Easy to reach — the road to Tsey Gorge passes right by."}}'::jsonb, ARRAY['/images/pois/ozero-tamisk_gp.webp','/images/pois/ozero-tamisk_2.webp','/images/pois/ozero-tamisk_3.webp','/images/pois/ozero-tamisk_4.webp','/images/pois/ozero-tamisk_5.webp','/images/pois/ozero-tamisk_6.webp','/images/pois/ozero-tamisk_7.webp']::text[], 4.6, NULL, NULL, NULL, NULL, ARRAY['nature','lake']::text[], false, false, false, 800, 143, 'free'::subscription_tier, 2100);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-181', 'gizeldonskoye-ushchele', '{"ru": "Гизельдонское ущелье", "en": "Gizeldon Gorge"}'::jsonb, 'nature'::poi_category, 'nature', NULL, '{"lat": 42.905, "lng": 44.44, "address": {"ru": "Пригородный р-н, Северная Осетия", "en": "Prigorodny district, North Ossetia"}}'::jsonb, '{"short": {"ru": "Ущелье реки Гизельдон — путь из Мидаграбинской долины к Даргавсу и «Городу мёртвых».", "en": "The Gizeldon river gorge — the route from the Midagrabin Valley to Dargavs and the City of the Dead."}, "medium": {"ru": "Гизельдонское ущелье образовано рекой Гизельдон, берущей начало в ледниках Главного Кавказского хребта. Ущелье соединяет Мидаграбинскую долину с Даргавским котлованом. По дороге — отвесные скальные стены, узкие каньоны и смотровые точки. Один из маршрутов к пещере Ласок.", "en": "The Gizeldon Gorge is carved by the Gizeldon River, originating in the glaciers of the Main Caucasian Ridge. It connects the Midagrabin Valley to the Dargavs basin. Along the way: sheer rock walls, narrow canyons, and viewpoints. One of the routes to Lasok Cave."}, "full": {"ru": "Гизельдонское ущелье — коридор между несколькими мирами. С одной стороны — Мидаграбинская долина с водопадами и ледниками. С другой — Даргавский котлован, где стоит «Город мёртвых», один из крупнейших некрополей Кавказа. Река Гизельдон прорезала в скальном массиве узкие теснины. Маршруты здесь разной сложности: от прогулочных до серьёзных скальных троп. В ущелье также находится вход в пещеру Ласок — одну из крупнейших пещер Северной Осетии.", "en": "The Gizeldon Gorge is a corridor between several worlds. On one side — the Midagrabin Valley with its waterfalls and glaciers. On the other — the Dargavs basin, home of the City of the Dead, one of the largest necropolises in the Caucasus. The Gizeldon River has cut narrow passages through the rock. Routes range from easy walks to serious rock trails. The gorge also contains the entrance to Lasok Cave — one of the largest caves in North Ossetia."}}'::jsonb, ARRAY['/images/pois/gizeldonskoye-ushchele_gp.webp','/images/pois/gizeldonskoye-ushchele_2.webp','/images/pois/gizeldonskoye-ushchele_3.webp','/images/pois/gizeldonskoye-ushchele_4.webp','/images/pois/gizeldonskoye-ushchele_5.webp']::text[], 4.5, NULL, NULL, NULL, NULL, ARRAY['nature','gorge','hiking']::text[], false, false, false, 800, 76, 'free'::subscription_tier, 1200);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-182', 'vorota-karmadona', '{"ru": "Ворота Кармадона", "en": "Gates of Karmadon"}'::jsonb, 'nature'::poi_category, 'nature', NULL, '{"lat": 42.695, "lng": 44.415, "address": {"ru": "Геналдонское ущелье, Северная Осетия", "en": "Genaldon Gorge, North Ossetia"}}'::jsonb, '{"short": {"ru": "Самое узкое место Геналдонского каньона — скалы сходятся на 30 метров. Место силы и памяти одновременно.", "en": "The narrowest point of the Genaldon Canyon — rock walls close to just 30 meters. A place of both power and memory."}, "medium": {"ru": "Ворота Кармадона — теснина в Геналдонском ущелье, где скальные стены сближаются до 30 метров. Именно здесь в 2002 году сход ледника Колка остановился, погребя под обломками съёмочную группу Сергея Бодрова-младшего. Сегодня это и природная достопримечательность, и место памяти.", "en": "The Gates of Karmadon is a narrow pass in the Genaldon Gorge where rock walls close to just 30 meters. This is where in 2002 the Kolka glacier surge stopped, burying the film crew of Sergei Bodrov Jr. Today it is both a natural attraction and a place of remembrance."}, "full": {"ru": "Геналдонское ущелье — одно из самых напряжённых мест Северной Осетии, где всё построено на контрастах: красота и опасность, жизнь и смерть. Ворота Кармадона — самая узкая часть, где скалы сжимают реку Геналдон до 30-метрового коридора. Осетины называют это место Комынараг — «узкие ворота». В 2002 году здесь остановилась масса льда с ледника Колка: 20 миллионов тонн льда и скальных обломков, унёсших жизни более ста человек, в том числе съёмочной группы Сергея Бодрова-младшего. Скалы здесь почти вертикальные, вода бурлит внизу, воздух пронизан горной влажностью.", "en": "The Genaldon Gorge is one of the most charged places in North Ossetia — everything built on contrasts: beauty and danger, life and death. The Gates of Karmadon are the narrowest part, where the rock walls squeeze the Genaldon River into a 30-meter corridor. Ossetians call it Komynarag — narrow gate. In 2002, the mass of ice from the Kolka glacier stopped here: 20 million tons of ice and rock debris that took over a hundred lives, including the film crew of Sergei Bodrov Jr. The cliffs are nearly vertical, the water churns below, the air is heavy with mountain moisture."}}'::jsonb, ARRAY['/images/pois/vorota-karmadona_gp.webp','/images/pois/vorota-karmadona_2.webp','/images/pois/vorota-karmadona_3.webp','/images/pois/vorota-karmadona_4.webp','/images/pois/vorota-karmadona_5.webp']::text[], 4.7, NULL, NULL, NULL, NULL, ARRAY['nature','canyon','history']::text[], false, false, false, 800, 112, 'free'::subscription_tier, 1860);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-184', 'ozero-zrugskoe', '{"ru": "Зругское озеро", "en": "Zrug Lake"}'::jsonb, 'nature'::poi_category, 'nature', NULL, '{"lat": 42.573488, "lng": 43.920602, "address": {"ru": "Зругское ущелье, Алагирский р-н, Северная Осетия", "en": "Zrug Gorge, Alagir district, North Ossetia"}}'::jsonb, '{"short": {"ru": "Высокогорное ледниковое озеро на высоте 2997 м с ярко-бирюзовой водой в Зругском ущелье.", "en": "High-altitude glacial lake at 2997 m with vivid turquoise water in the Zrug Gorge."}, "medium": {"ru": "Зругское озеро расположено на высоте 2997 м в Зругском ущелье. Бирюзовый цвет воды объясняется ледниковым происхождением и минеральным составом. Один из самых труднодоступных и живописных водоёмов республики.", "en": "Zrug Lake sits at 2997 m in the Zrug Gorge. Its turquoise color comes from glacial origin and mineral composition. One of the most remote and scenic bodies of water in the republic."}, "full": {"ru": "Зругское озеро расположено на высоте 2997 м в Зругском ущелье. Бирюзовый цвет воды объясняется ледниковым происхождением и минеральным составом. Один из самых труднодоступных и живописных водоёмов республики.", "en": "Zrug Lake sits at 2997 m in the Zrug Gorge. Its turquoise color comes from glacial origin and mineral composition. One of the most remote and scenic bodies of water in the republic."}}'::jsonb, ARRAY['/images/pois/ozero-zrugskoe_gp.webp','/images/pois/ozero-zrugskoe_2.webp','/images/pois/ozero-zrugskoe_3.webp','/images/pois/ozero-zrugskoe_4.webp','/images/pois/ozero-zrugskoe_5.webp','/images/pois/ozero-zrugskoe_6.webp']::text[], 4.8, NULL, NULL, NULL, NULL, ARRAY['nature','lake','hiking']::text[], false, false, false, 800, 43, 'free'::subscription_tier, 720);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-185', 'ledник-karaugom', '{"ru": "Ледник Караугом", "en": "Karaugom Glacier"}'::jsonb, 'nature'::poi_category, 'nature', NULL, '{"lat": 42.799238, "lng": 43.732749, "address": {"ru": "Дигорское ущелье, Ирафский р-н, Северная Осетия", "en": "Digor Gorge, Iraf district, North Ossetia"}}'::jsonb, '{"short": {"ru": "Крупнейший ледник Северной Осетии — 12,27 км длиной, площадь 26 км². Настоящий гигант Дигории.", "en": "The largest glacier in North Ossetia — 12.27 km long, area 26 km². A true giant of Digoria."}, "medium": {"ru": "Ледник Караугом — крупнейший ледник Северной Осетии. Длина — 12,27 км, площадь — около 26 км². Расположен в Дигорском ущелье среди высоких вершин, питает реку Урух. Маршрут к языку ледника рассчитан на опытных горных туристов.", "en": "Karaugom is the largest glacier in North Ossetia: 12.27 km long, about 26 km² in area. Located in the Digor Gorge surrounded by high peaks. It feeds the Urukh River. The route to the glacier terminus is suitable for experienced mountain hikers."}, "full": {"ru": "Ледник Караугом — крупнейший ледник Северной Осетии. Длина — 12,27 км, площадь — около 26 км². Расположен в Дигорском ущелье среди высоких вершин, питает реку Урух. Маршрут к языку ледника рассчитан на опытных горных туристов.", "en": "Karaugom is the largest glacier in North Ossetia: 12.27 km long, about 26 km² in area. Located in the Digor Gorge surrounded by high peaks. It feeds the Urukh River. The route to the glacier terminus is suitable for experienced mountain hikers."}}'::jsonb, ARRAY['/images/pois/karaugom-glacier_gp.webp','/images/pois/ledник-karaugom_2.webp','/images/pois/ledник-karaugom_3.webp','/images/pois/ledник-karaugom_4.webp','/images/pois/ledник-karaugom_5.webp','/images/pois/ledник-karaugom_6.webp','/images/pois/ledник-karaugom_7.webp']::text[], 4.9, NULL, NULL, NULL, NULL, ARRAY['nature','glacier','hiking']::text[], false, false, false, 800, 67, 'free'::subscription_tier, 980);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-186', 'elkhotovskie-vorota', '{"ru": "Эльхотовские ворота", "en": "Elkhotovo Gates"}'::jsonb, 'culture'::poi_category, 'nature', NULL, '{"lat": 43.354, "lng": 44.19, "address": {"ru": "Эльхотово, Кировский р-н, Северная Осетия", "en": "Elkhotovo, Kirovsky district, North Ossetia"}}'::jsonb, '{"short": {"ru": "Узкий горный проход реки Терек через Сунженский хребет — природные ворота Северного Кавказа.", "en": "A narrow mountain pass of the Terek River through the Sunzhensky ridge — the natural gateway to the North Caucasus."}, "medium": {"ru": "Эльхотовские ворота — теснина реки Терек в Сунженском хребте. Осенью 1942 года советские войска остановили здесь наступление немецких дивизий, стремившихся к нефтяным месторождениям юга. 8 мая 1975 года на месте боёв открыт мемориал в честь защитников. Сегодня место привлекает историков и любителей природы.", "en": "The Elkhotovo Gates are a gorge where the Terek River cuts through the Sunzhensky ridge. In autumn 1942 Soviet forces halted the German advance here, blocking access to the southern oilfields. A memorial to the defenders was unveiled on 8 May 1975. Today the site attracts historians and nature lovers."}, "full": {"ru": "Эльхотовские ворота — теснина реки Терек в Сунженском хребте. Осенью 1942 года советские войска остановили здесь наступление немецких дивизий, стремившихся к нефтяным месторождениям юга. 8 мая 1975 года на месте боёв открыт мемориал в честь защитников. Сегодня место привлекает историков и любителей природы.", "en": "The Elkhotovo Gates are a gorge where the Terek River cuts through the Sunzhensky ridge. In autumn 1942 Soviet forces halted the German advance here, blocking access to the southern oilfields. A memorial to the defenders was unveiled on 8 May 1975. Today the site attracts historians and nature lovers."}}'::jsonb, ARRAY['/images/pois/elkhotovskie-vorota_gp.webp','/images/pois/elkhotovskie-vorota_2.webp','/images/pois/elkhotovskie-vorota_3.webp','/images/pois/elkhotovskie-vorota_4.webp']::text[], 4.5, NULL, NULL, NULL, NULL, ARRAY['nature','gorge','history']::text[], false, false, false, 80, 88, 'free'::subscription_tier, 1450);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-188', 'verkhniy-zgid', '{"ru": "Верхний Згид", "en": "Upper Zgid"}'::jsonb, 'nature'::poi_category, 'nature', NULL, '{"lat": 42.874647, "lng": 43.960423, "address": {"ru": "Куртатинское ущелье, Алагирский р-н, Северная Осетия", "en": "Kurtatinsky Gorge, Alagir district, North Ossetia"}}'::jsonb, '{"short": {"ru": "Высокогорное село на высоте 2047 м с панорамными видами на горы Куртатинского ущелья.", "en": "A high-altitude village at 2047 m with panoramic views of the Kurtatinsky Gorge mountains."}, "medium": {"ru": "Верхний Згид расположен на высоте 2047 м в Куртатинском ущелье. В советский период добыча свинцово-цинковой руды превратила его в рабочий посёлок Садонского горно-обогатительного комбината. После закрытия рудника посёлок практически опустел. Сохранились средневековые родовые башни и живописные виды на хребты.", "en": "Upper Zgid sits at 2047 m in the Kurtatinsky Gorge. During the Soviet era, lead-zinc ore mining made it a workers settlement of the Sadon Mining Combine. After the mine closed the village was largely abandoned. Medieval clan towers and panoramic mountain views remain."}, "full": {"ru": "Верхний Згид расположен на высоте 2047 м в Куртатинском ущелье. В советский период добыча свинцово-цинковой руды превратила его в рабочий посёлок Садонского горно-обогатительного комбината. После закрытия рудника посёлок практически опустел. Сохранились средневековые родовые башни и живописные виды на хребты.", "en": "Upper Zgid sits at 2047 m in the Kurtatinsky Gorge. During the Soviet era, lead-zinc ore mining made it a workers settlement of the Sadon Mining Combine. After the mine closed the village was largely abandoned. Medieval clan towers and panoramic mountain views remain."}}'::jsonb, ARRAY['/images/pois/verkhniy-zgid_gp.webp','/images/pois/verkhniy-zgid_2.webp','/images/pois/verkhniy-zgid_3.webp','/images/pois/verkhniy-zgid_4.webp','/images/pois/verkhniy-zgid_5.webp']::text[], 4.6, NULL, NULL, NULL, NULL, ARRAY['nature','village','hiking']::text[], false, false, false, 800, 38, 'free'::subscription_tier, 610);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-189', 'teatr-opery-i-baleta', '{"ru": "Театр оперы и балета", "en": "Opera and Ballet Theatre"}'::jsonb, 'culture'::poi_category, 'culture', NULL, '{"lat": 43.034, "lng": 44.663, "address": {"ru": "ул. Владимира Тхапсаева, 18, Владикавказ", "en": "18 Vladimir Tkhapsaev St, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Филиал Мариинского театра — опера и балет мирового уровня в самом сердце Владикавказа.", "en": "A branch of the Mariinsky Theatre — world-class opera and ballet in the heart of Vladikavkaz."}, "medium": {"ru": "Северо-Осетинский театр оперы и балета открылся 18 апреля 1972 года. С 2017 года — филиал Государственного академического Мариинского театра. Зал на 627 мест, на набережной Терека. Художественный руководитель — народная артистка РФ Лариса Гергиева.", "en": "The North Ossetian Opera and Ballet Theatre opened on 18 April 1972. Since 2017 it has been a branch of the Mariinsky State Academic Theatre. The 627-seat auditorium stands on the Terek embankment, led by artistic director Larisa Gergieva."}, "full": {"ru": "Северо-Осетинский театр оперы и балета открылся 18 апреля 1972 года — первый оперный театр в истории Северной Осетии. С 2017 года является филиалом Государственного академического Мариинского театра в Санкт-Петербурге: это открыло республике доступ к мировому репертуару. Зрительный зал на 627 мест расположен на набережной реки Терека. Художественный руководитель — народная артистка РФ Лариса Гергиева, возглавляющая труппу с 1995 года. В репертуаре — классические оперы и балеты, а также совместные постановки с Мариинским театром.", "en": "The North Ossetian Opera and Ballet Theatre opened on 18 April 1972, the first opera house in North Ossetia. In 2017 the theatre became a branch of the Mariinsky State Academic Theatre in St Petersburg, bringing world-class productions to the region. The 627-seat auditorium stands on the Terek embankment. Artistic director Larisa Gergieva has led the company since 1995. The repertoire spans classical operas and ballets, with regular performances by leading Mariinsky soloists."}}'::jsonb, ARRAY['/images/pois/opera-and-ballet-theatre_gp.webp','/images/pois/teatr-opery-i-baleta_2.webp','/images/pois/teatr-opery-i-baleta_3.webp','/images/pois/teatr-opery-i-baleta_4.webp','/images/pois/teatr-opery-i-baleta_5.webp']::text[], 4.9, NULL, NULL, NULL, NULL, ARRAY['culture','theatre','music']::text[], false, false, false, 80, 312, 'free'::subscription_tier, 4200);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-191', 'teatr-sabi', '{"ru": "Театр юного зрителя «Саби»", "en": "Sabi Youth Theatre"}'::jsonb, 'culture'::poi_category, 'culture', NULL, '{"lat": 43.041, "lng": 44.678, "address": {"ru": "Владикавказ", "en": "Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Театр для детей и молодёжи: здание 1914 года, театр основан в 1938-м, имя «Саби» с 1960-го.", "en": "Theatre for children and youth: the 1914 building, founded 1938, named Sabi since 1960."}, "medium": {"ru": "Здание театра построено в 1914 году по проекту архитектора Ивана Рябикина. Северо-Осетинский государственный театр юного зрителя основан в 1938 году, с 1960 года носит имя «Саби» (осет. — «дитя»). Специализируется на постановках для детей и молодёжи: сказки, классика и современные пьесы.", "en": "The theatre building was constructed in 1914 to a design by architect Ivan Ryabikov. The North Ossetian State Youth Theatre was founded in 1938 and since 1960 has borne the name Sabi, meaning Child in Ossetian. It specialises in productions for children and young audiences: fairy tales, classics, and contemporary plays."}, "full": {"ru": "Здание театра построено в 1914 году по проекту архитектора Ивана Рябикина. Северо-Осетинский государственный театр юного зрителя основан в 1938 году, с 1960 года носит имя «Саби» (осет. — «дитя»). Специализируется на постановках для детей и молодёжи: сказки, классика и современные пьесы.", "en": "The theatre building was constructed in 1914 to a design by architect Ivan Ryabikov. The North Ossetian State Youth Theatre was founded in 1938 and since 1960 has borne the name Sabi, meaning Child in Ossetian. It specialises in productions for children and young audiences: fairy tales, classics, and contemporary plays."}}'::jsonb, ARRAY['/images/pois/sabi-youth-theatre_gp.webp','/images/pois/teatr-sabi_2.webp','/images/pois/teatr-sabi_3.webp','/images/pois/teatr-sabi_4.webp','/images/pois/teatr-sabi_5.webp','/images/pois/teatr-sabi_6.webp','/images/pois/teatr-sabi_7.webp']::text[], 4.5, NULL, NULL, NULL, NULL, ARRAY['culture','theatre']::text[], false, false, false, 80, 134, 'free'::subscription_tier, 1600);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-193', 'muzey-teatra-tkhapsaeva', '{"ru": "Музей театрального искусства им. Тхапсаева", "en": "Tkhapsaev Theatre Art Museum"}'::jsonb, 'museums'::poi_category, 'culture', NULL, '{"lat": 43.03, "lng": 44.677, "address": {"ru": "ул. Максима Горького, 30, Владикавказ", "en": "30 Maxim Gorky St, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Единственный музей театрального искусства на Северном Кавказе в историческом особняке.", "en": "The only theatre art museum in the North Caucasus, housed in a historic mansion."}, "medium": {"ru": "Музей театрального искусства имени Васо Тхапсаева открыт в январе 1994 года в доме, где народный артист СССР прожил с 1937 по 1977 год. Фонд насчитывает более 16 300 экспонатов: костюмы, декорации, афиши, рукописи и личные вещи деятелей осетинского театра.", "en": "The Vaso Tkhapsaev Theatre Art Museum opened in January 1994 in the house where the USSR People''s Artist lived from 1937 to 1977. The collection numbers more than 16,300 items: costumes, scenery, posters, manuscripts, and personal belongings of Ossetian theatre figures."}, "full": {"ru": "Музей театрального искусства имени Васо Тхапсаева открыт в январе 1994 года в доме, где народный артист СССР прожил с 1937 по 1977 год. Фонд насчитывает более 16 300 экспонатов: костюмы, декорации, афиши, рукописи и личные вещи деятелей осетинского театра.", "en": "The Vaso Tkhapsaev Theatre Art Museum opened in January 1994 in the house where the USSR People''s Artist lived from 1937 to 1977. The collection numbers more than 16,300 items: costumes, scenery, posters, manuscripts, and personal belongings of Ossetian theatre figures."}}'::jsonb, ARRAY['/images/pois/tkhapsaev-theatre-art-museum_gp.webp','/images/pois/muzey-teatra-tkhapsaeva_2.webp','/images/pois/muzey-teatra-tkhapsaeva_3.webp','/images/pois/muzey-teatra-tkhapsaeva_4.webp','/images/pois/muzey-teatra-tkhapsaeva_5.webp','/images/pois/muzey-teatra-tkhapsaeva_6.webp']::text[], 4.4, NULL, NULL, NULL, NULL, ARRAY['culture','museum']::text[], false, false, false, 80, 89, 'free'::subscription_tier, 980);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-197', 'kontsertny-zal-mariinsky-kirkha', '{"ru": "Концертный зал Мариинского (бывшая кирха)", "en": "Mariinsky Concert Hall (former Kirche)"}'::jsonb, 'culture'::poi_category, 'culture', NULL, '{"lat": 43.032, "lng": 44.676, "address": {"ru": "Владикавказ", "en": "Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Редкий памятник архитектуры в стиле поздней готики (1911 г.) — ныне концертный зал филармонии.", "en": "A rare late Gothic architectural landmark (1911) — now a concert hall of the philharmonic."}, "medium": {"ru": "Бывшая лютеранская кирха 1911 года постройки — один из немногих образцов готической архитектуры на Северном Кавказе. После советских преобразований здание передано Северо-Осетинской государственной филармонии. Сегодня здесь проходят камерные концерты и выступления.", "en": "The former Lutheran Kirche of 1911 is one of the few examples of Gothic architecture in the North Caucasus. After Soviet transformations, the building was transferred to the North Ossetian State Philharmonic. Today it hosts chamber concerts and performances."}, "full": {"ru": "Бывшая лютеранская кирха 1911 года постройки — один из немногих образцов готической архитектуры на Северном Кавказе. После советских преобразований здание передано Северо-Осетинской государственной филармонии. Сегодня здесь проходят камерные концерты и выступления.", "en": "The former Lutheran Kirche of 1911 is one of the few examples of Gothic architecture in the North Caucasus. After Soviet transformations, the building was transferred to the North Ossetian State Philharmonic. Today it hosts chamber concerts and performances."}}'::jsonb, ARRAY['/images/pois/mariinsky-concert-hall-kirkha_gp.webp']::text[], 4.8, NULL, NULL, NULL, NULL, ARRAY['culture','architecture','music']::text[], false, false, false, 80, 167, 'free'::subscription_tier, 2300);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-198', 'dom-muzey-khеtagurova', '{"ru": "Дом-музей Коста Хетагурова", "en": "Kosta Khetagurov House Museum"}'::jsonb, 'museums'::poi_category, 'culture', NULL, '{"lat": 43.028, "lng": 44.673, "address": {"ru": "ул. Бутырина, 19, Владикавказ", "en": "19 Butyrina St, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Мемориальный музей основателя осетинской литературы в его родном доме.", "en": "Memorial museum of the founder of Ossetian literature in his family home."}, "medium": {"ru": "Коста Хетагуров �� основоположник осетинской литературы, поэт и художник. Дом-музей открыт в 1979 году в здании 1864 года постройки, где жил поэт. Восемь залов хранят 133 экспоната: рукописи, картины, личные вещи и документы эпохи.", "en": "Kosta Khetagurov is the founder of Ossetian literature, a poet and artist. The house museum opened in 1979 in a building from 1864 where the poet lived. Eight exhibition halls hold 133 items: manuscripts, paintings, personal belongings, and documents of the era."}, "full": {"ru": "Коста Хетагуров — основоположник осетинской литературы, поэт и художник. Дом-музей открыт в 1979 году в здании 1864 года постройки, где жил поэт. Восемь залов хранят 133 экспоната: рукописи, картины, личные вещи и документы эпохи.", "en": "Kosta Khetagurov is the founder of Ossetian literature, a poet and artist. The house museum opened in 1979 in a building from 1864 where the poet lived. Eight exhibition halls hold 133 items: manuscripts, paintings, personal belongings, and documents of the era."}}'::jsonb, ARRAY['/images/pois/kosta-khetagurov-house-museum_gp.webp','/images/pois/dom-muzey-khеtagurova_2.webp','/images/pois/dom-muzey-khеtagurova_3.webp','/images/pois/dom-muzey-khеtagurova_4.webp','/images/pois/dom-muzey-khеtagurova_5.webp','/images/pois/dom-muzey-khеtagurova_6.webp']::text[], 4.6, NULL, NULL, NULL, NULL, ARRAY['culture','museum','history']::text[], false, false, false, 80, 154, 'free'::subscription_tier, 1800);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-205', 'zoopark-vladikavkaz', '{"ru": "Владикавказский зоопарк", "en": "Vladikavkaz Zoo"}'::jsonb, 'activities'::poi_category, 'activities', NULL, '{"lat": 42.9963, "lng": 44.6773, "address": {"ru": "Владикавказ", "en": "Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Уютный городской зоопарк с животными со всего света и образовательными программами.", "en": "A cozy city zoo with animals from around the world and educational programs."}, "medium": {"ru": "Владикавказский зоопарк — небольшой, но ухоженный. Здесь живут хищники, копытные, птицы и рептилии. Работают образовательные программы для детей и возможность кормить некоторых животных. Хорошее место для семейного отдыха.", "en": "Vladikavkaz Zoo is small but well-maintained. Home to predators, ungulates, birds, and reptiles. Educational programs for children and opportunities to feed some animals. A good place for family recreation."}, "full": {"ru": "Владикавказский зоопарк — небольшой, но ухоженный. Здесь живут хищники, копытные, птицы и рептилии. Работают образовательные программы для детей и возможность кормить некоторых животных. Хорошее место для семейного отдыха.", "en": "Vladikavkaz Zoo is small but well-maintained. Home to predators, ungulates, birds, and reptiles. Educational programs for children and opportunities to feed some animals. A good place for family recreation."}}'::jsonb, ARRAY['/images/pois/zoopark-vladikavkaz_gp.webp']::text[], 4.2, NULL, NULL, NULL, NULL, ARRAY['activities','family','animals']::text[], false, false, false, 200, 423, 'free'::subscription_tier, 7800);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-206', 'akvapark-akva-pati', '{"ru": "Аквапарк «Аква Пати»", "en": "Aqua Party Waterpark"}'::jsonb, 'activities'::poi_category, 'activities', NULL, '{"lat": 43.0046, "lng": 44.6727, "address": {"ru": "пр-т Коста, 15, Владикавказ", "en": "15 Kosta Ave, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Современный аквапарк с горками, аквааэробикой и кафе в центре города.", "en": "Modern waterpark with slides, aqua aerobics, and a café in the city center."}, "medium": {"ru": "Аква Пати — городской аквапарк с несколькими водными горками, бассейнами разной глубины и зоной для малышей. Проводятся занятия по аквааэробике. При аквапарке есть кафе и раздевалки.", "en": "Aqua Party is a city waterpark with several water slides, pools of varying depths, and a toddler zone. Aqua aerobics classes are held here. The park has a café and changing rooms."}, "full": {"ru": "Аква Пати — городской аквапарк с несколькими водными горками, бассейнами разной глубины и зоной для малышей. Проводятся занятия по аквааэробике. При аквапарке есть кафе и раздевалки.", "en": "Aqua Party is a city waterpark with several water slides, pools of varying depths, and a toddler zone. Aqua aerobics classes are held here. The park has a café and changing rooms."}}'::jsonb, ARRAY['/images/pois/akvapark-akva-pati_gp.webp']::text[], 4.1, NULL, NULL, NULL, NULL, ARRAY['activities','family','water']::text[], false, false, false, 200, 356, 'free'::subscription_tier, 6200);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-207', 'ferrari-karting', '{"ru": "Ferrari Karting Club", "en": "Ferrari Karting Club"}'::jsonb, 'activities'::poi_category, 'activities', NULL, '{"lat": 43.0442, "lng": 44.6603, "address": {"ru": "Владикавказ", "en": "Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Картинг-клуб с адреналиновыми заездами на взрослых и детских картах.", "en": "Karting club with adrenaline races on adult and junior karts."}, "medium": {"ru": "Ferrari Karting Club предлагает заезды на профессиональных картах для взрослых и детей. Трасса оборудована системой хронометража. Работает ежедневно с 12:00 до 24:00. Подходит как для новичков, так и для опытных гонщиков.", "en": "Ferrari Karting Club offers races on professional karts for adults and children. The track is equipped with a timing system. Open daily from 12:00 to midnight. Suitable for both beginners and experienced racers."}, "full": {"ru": "Ferrari Karting Club предлагает заезды на профессиональных картах для взрослых и детей. Трасса оборудована системой хронометража. Работает ежедневно с 12:00 до 24:00. Подходит как для новичков, так и для опытных гонщиков.", "en": "Ferrari Karting Club offers races on professional karts for adults and children. The track is equipped with a timing system. Open daily from 12:00 to midnight. Suitable for both beginners and experienced racers."}}'::jsonb, ARRAY['/images/pois/ferrari-karting_gp.webp']::text[], 4.4, NULL, NULL, NULL, NULL, ARRAY['activities','sport','family']::text[], false, false, false, 200, 287, 'free'::subscription_tier, 4900);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-208', 'bouling-daryal', '{"ru": "Боулинг-клуб «Дарьял»", "en": "Daryal Bowling Club"}'::jsonb, 'activities'::poi_category, 'activities', NULL, '{"lat": 43.0198, "lng": 44.6754, "address": {"ru": "пр-т Коста, 274, Владикавказ", "en": "274 Kosta Ave, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Развлекательный комплекс с 6 дорожками Brunswick, рестораном и парковкой.", "en": "Entertainment complex with 6 Brunswick lanes, restaurant, and parking."}, "medium": {"ru": "Боулинг-клуб «Дарьял» — 6 профессиональных дорожек Brunswick, автоматическая система учёта очков. При клубе работает ресторан с кавказской кухней. Удобная парковка. Популярное место для корпоративных мероприятий и дружеских встреч.", "en": "Daryal Bowling Club has 6 professional Brunswick lanes with an automatic scoring system. The attached restaurant serves Caucasian cuisine. Convenient parking. A popular venue for corporate events and friendly gatherings."}, "full": {"ru": "Боулинг-клуб «Дарьял» — 6 профессиональных дорожек Brunswick, автоматическая система учёта очков. При клубе работает ресторан с кавказской кухней. Удобная парковка. Популярное место для корпоративных мероприятий и дружеских встреч.", "en": "Daryal Bowling Club has 6 professional Brunswick lanes with an automatic scoring system. The attached restaurant serves Caucasian cuisine. Convenient parking. A popular venue for corporate events and friendly gatherings."}}'::jsonb, ARRAY['/images/pois/bouling-daryal_gp.webp']::text[], 4.3, NULL, NULL, NULL, NULL, ARRAY['activities','entertainment']::text[], false, false, false, 200, 312, 'free'::subscription_tier, 5100);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-209', 'dendrary-vladikavkaz', '{"ru": "Владикавказский дендрарий", "en": "Vladikavkaz Arboretum"}'::jsonb, 'activities'::poi_category, 'activities', NULL, '{"lat": 42.9763, "lng": 44.6603, "address": {"ru": "Владикавказ", "en": "Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Ботанический памятник природы с более чем 200 видами растений, включая редкие реликтовые.", "en": "A botanical nature monument with over 200 plant species, including rare relics."}, "medium": {"ru": "Владикавказский дендрарий основан в 1982 году. На площади нескольких гектаров собрано более 200 видов деревьев и кустарников, в том числе редкие реликтовые растения. Хорошее место для тихих прогулок и наблюдения за природой.", "en": "The Vladikavkaz Arboretum was founded in 1982. On several hectares, over 200 species of trees and shrubs have been collected, including rare relic plants. A good place for quiet walks and nature observation."}, "full": {"ru": "Владикавказский дендрарий основан в 1982 году. На площади нескольких гектаров собрано более 200 видов деревьев и кустарников, в том числе редкие реликтовые растения. Хорошее место для тихих прогулок и наблюдения за природой.", "en": "The Vladikavkaz Arboretum was founded in 1982. On several hectares, over 200 species of trees and shrubs have been collected, including rare relic plants. A good place for quiet walks and nature observation."}}'::jsonb, ARRAY['/images/pois/dendrary-vladikavkaz_gp.webp']::text[], 4.5, NULL, NULL, NULL, NULL, ARRAY['activities','nature','family']::text[], false, false, false, 200, 198, 'free'::subscription_tier, 3400);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-210', 'lazertag-strayk', '{"ru": "Лазертаг «Страйк»", "en": "Strike Lasertag"}'::jsonb, 'activities'::poi_category, 'activities', NULL, '{"lat": 43.0371, "lng": 44.6884, "address": {"ru": "ТРЦ «Карусель», Владикавказ", "en": "Karusel Mall, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Центр лазертага в ТРЦ Карусель с современным оборудованием.", "en": "Lasertag center in Karusel Mall with modern equipment."}, "medium": {"ru": "Лазер-клуб «Страйк» располагается в ТРЦ «Карусель». Современное оборудование, несколько игровых сценариев, подходит для детей и взрослых. Работает ежедневно с 11:00 до 22:00.", "en": "Strike Lasertag is located in Karusel Mall. Modern equipment, several game scenarios, suitable for children and adults. Open daily from 11:00 to 22:00."}, "full": {"ru": "Лазер-клуб «Страйк» располагается в ТРЦ «Карусель». Современное оборудование, несколько игровых сценариев, подходит для детей и взрослых. Работает ежедневно с 11:00 до 22:00.", "en": "Strike Lasertag is located in Karusel Mall. Modern equipment, several game scenarios, suitable for children and adults. Open daily from 11:00 to 22:00."}}'::jsonb, ARRAY['/images/pois/lazertag-strayk_gp.webp']::text[], 4.2, NULL, NULL, NULL, NULL, ARRAY['activities','entertainment','family']::text[], false, false, false, 200, 176, 'free'::subscription_tier, 2800);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-211', 'kurort-mamison', '{"ru": "Горнолыжный курорт Мамисон", "en": "Mamison Ski Resort"}'::jsonb, 'activities'::poi_category, 'activities', NULL, '{"lat": 42.6621, "lng": 43.8398, "address": {"ru": "Мамисонское ущелье, Алагирский р-н, Северная Осетия", "en": "Mamison Gorge, Alagir district, North Ossetia"}}'::jsonb, '{"short": {"ru": "Новый всесезонный курорт на высоте 2950 м, открылся в 2025 году. 100 км от Владикавказа.", "en": "New all-season resort at 2950 m, opened in 2025. 100 km from Vladikavkaz."}, "medium": {"ru": "Горнолыжный курорт Мамисон открылся в марте 2025 года в Мамисонском ущелье. Высота — до 2950 м. Несколько трасс разной сложности, современные подъёмники. Летом работает как трекинговый курорт. Один из самых перспективных горнолыжных проектов Северного Кавказа.", "en": "Mamison Ski Resort opened in March 2025 in the Mamison Gorge. Elevation up to 2950 m. Several slopes of varying difficulty, modern lifts. In summer it operates as a trekking resort. One of the most promising ski projects in the North Caucasus."}, "full": {"ru": "Горнолыжный курорт Мамисон открылся в марте 2025 года в Мамисонском ущелье. Высота — до 2950 м. Несколько трасс разной сложности, современные подъёмники. Летом работает как трекинговый курорт. Один из самых перспективных горнолыжных проектов Северного Кавказа.", "en": "Mamison Ski Resort opened in March 2025 in the Mamison Gorge. Elevation up to 2950 m. Several slopes of varying difficulty, modern lifts. In summer it operates as a trekking resort. One of the most promising ski projects in the North Caucasus."}}'::jsonb, ARRAY['/images/pois/kurort-mamison_gp.webp']::text[], 4.6, NULL, NULL, NULL, NULL, ARRAY['activities','skiing','mountains']::text[], false, false, false, 200, 89, 'free'::subscription_tier, 1200);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-212', 'mfc-moi-dokumenty', '{"ru": "МФЦ «Мои документы»", "en": "MFC My Documents"}'::jsonb, 'practical'::poi_category, 'practical', NULL, '{"lat": 43.011578, "lng": 44.690548, "address": {"ru": "ул. Кутузова, 104А, Владикавказ", "en": "104A Kutuzov St, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Многофункциональный центр для оформления госуслуг, документов и справок.", "en": "Multifunctional center for government services, documents, and certificates."}, "medium": {"ru": "МФЦ «Мои документы» — удобное место для оформления любых государственных услуг: паспорта, регистрация, справки, лицензии. Электронная очередь, вежливый персонал. Для иностранных туристов — консультации по регистрации.", "en": "MFC My Documents is a convenient place for any government services: passport, registration, certificates, licenses. Electronic queue, friendly staff. For foreign tourists — consultation on registration."}, "full": {"ru": "МФЦ «Мои документы» — удобное место для оформления любых государственных услуг: паспорта, регистрация, справки, лицензии. Электронная очередь, вежливый персонал. Для иностранных туристов — консультации по регистрации.", "en": "MFC My Documents is a convenient place for any government services: passport, registration, certificates, licenses. Electronic queue, friendly staff. For foreign tourists — consultation on registration."}}'::jsonb, ARRAY['/images/pois/mfc-my-documents_gp.webp']::text[], 3.8, NULL, NULL, NULL, NULL, ARRAY['practical','services']::text[], false, false, false, 50, 234, 'free'::subscription_tier, 4500);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-213', 'azs-lukoyl', '{"ru": "АЗС ЛУКОЙЛ", "en": "Lukoil Gas Station"}'::jsonb, 'practical'::poi_category, 'practical', NULL, '{"lat": 43.056989, "lng": 44.641401, "address": {"ru": "ул. Московская, 16Б, Владикавказ", "en": "16B Moskovskaya St, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Круглосуточная заправка с АИ-92, АИ-95, дизелем и магазином при АЗС.", "en": "24-hour gas station with 92, 95 octane, diesel, and a convenience store."}, "medium": {"ru": "ЛУКОЙЛ на Московской — удобная заправка рядом с выездом из центра города. Работает 24/7. Топливо АИ-92, АИ-95, АИ-98, дизель. При АЗС магазин с напитками, снеками и автотоварами.", "en": "Lukoil on Moskovskaya is a convenient gas station near the exit from the city center. Open 24/7. Fuel grades 92, 95, 98 octane, diesel. Attached shop with drinks, snacks, and auto supplies."}, "full": {"ru": "ЛУКОЙЛ на Московской — удобная заправка рядом с выездом из центра города. Работает 24/7. Топливо АИ-92, АИ-95, АИ-98, дизель. При АЗС магазин с напитками, снеками и автотоварами.", "en": "Lukoil on Moskovskaya is a convenient gas station near the exit from the city center. Open 24/7. Fuel grades 92, 95, 98 octane, diesel. Attached shop with drinks, snacks, and auto supplies."}}'::jsonb, ARRAY['/images/pois/lukoil-gas-station_gp.webp']::text[], 4.1, NULL, NULL, NULL, NULL, ARRAY['practical','transport']::text[], false, false, false, 50, 156, 'free'::subscription_tier, 8900);
