INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-216', 'apteka-36-6', '{"ru": "Аптека «36,6»", "en": "36.6 Pharmacy"}'::jsonb, 'practical'::poi_category, 'practical', NULL, '{"lat": 43.0382, "lng": 44.6348, "address": {"ru": "ул. Леваневского, 270, Владикавказ", "en": "270 Levanevsky St, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Круглосуточная аптека с полным ассортиментом лекарств и товаров для здоровья.", "en": "24-hour pharmacy with a full range of medicines and health products."}, "medium": {"ru": "Аптека «36,6» работает круглосуточно. Полный ассортимент лекарств, витаминов, медицинских товаров и косметики. Удобно для туристов — есть базовые препараты без рецепта и средства первой помощи.", "en": "36.6 Pharmacy is open 24 hours. Full range of medicines, vitamins, medical goods, and cosmetics. Convenient for tourists — basic over-the-counter medicines and first aid supplies available."}, "full": {"ru": "Аптека «36,6» работает круглосуточно. Полный ассортимент лекарств, витаминов, медицинских товаров и косметики. Удобно для туристов — есть базовые препараты без рецепта и средства первой помощи.", "en": "36.6 Pharmacy is open 24 hours. Full range of medicines, vitamins, medical goods, and cosmetics. Convenient for tourists — basic over-the-counter medicines and first aid supplies available."}}'::jsonb, ARRAY['/images/pois/pharmacy-36-6_gp.webp']::text[], 4.1, NULL, NULL, NULL, NULL, ARRAY['practical','health','24h']::text[], true, false, false, 50, 187, 'free'::subscription_tier, 5600);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-217', 'salon-mts', '{"ru": "Салон МТС", "en": "MTS Store"}'::jsonb, 'practical'::poi_category, 'practical', NULL, '{"lat": 43.0355, "lng": 44.687, "address": {"ru": "ул. Максима Горького, 11, Владикавказ", "en": "11 Maxim Gorky St, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Салон МТС — SIM-карты, тарифы, смартфоны и подключение услуг оператора.", "en": "MTS store — SIM cards, plans, smartphones, and operator services."}, "medium": {"ru": "Официальный салон МТС в центре Владикавказа. Туристам удобно купить российскую SIM-карту с интернетом. Подключение занимает около 15 минут при наличии паспорта. Также продаются смартфоны, аксессуары и аксессуары.", "en": "Official MTS store in the center of Vladikavkaz. Convenient for tourists to buy a Russian SIM card with internet. Connection takes about 15 minutes with a passport. Smartphones and accessories also sold."}, "full": {"ru": "Официальный салон МТС в центре Владикавказа. Туристам удобно купить российскую SIM-карту с интернетом. Подключение занимает около 15 минут при наличии паспорта. Также продаются смартфоны, аксессуары и аксессуары.", "en": "Official MTS store in the center of Vladikavkaz. Convenient for tourists to buy a Russian SIM card with internet. Connection takes about 15 minutes with a passport. Smartphones and accessories also sold."}}'::jsonb, ARRAY['/images/pois/mts-store_gp.webp']::text[], 3.9, NULL, NULL, NULL, NULL, ARRAY['practical','telecom']::text[], true, false, false, 50, 112, 'free'::subscription_tier, 2800);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-218', 'salon-beeline', '{"ru": "Салон Билайн", "en": "Beeline Store"}'::jsonb, 'practical'::poi_category, 'practical', NULL, '{"lat": 43.0265, "lng": 44.6915, "address": {"ru": "ул. Чкалова, 10, Владикавказ", "en": "10 Chkalov St, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Официальный салон Билайн — SIM-карты, смартфоны и подключение тарифов.", "en": "Official Beeline store — SIM cards, smartphones, and plan activation."}, "medium": {"ru": "Центральный офис Билайн во Владикавказе. Оформление SIM-карт для туристов, подключение выгодных тарифов с интернетом, продажа телефонов и аксессуаров. Требуется паспорт.", "en": "Beeline central office in Vladikavkaz. SIM card registration for tourists, activation of internet plans, sale of phones and accessories. Passport required."}, "full": {"ru": "Центральный офис Билайн во Владикавказе. Оформление SIM-карт для туристов, подключение выгодных тарифов с интернетом, продажа телефонов и аксессуаров. Требуется паспорт.", "en": "Beeline central office in Vladikavkaz. SIM card registration for tourists, activation of internet plans, sale of phones and accessories. Passport required."}}'::jsonb, ARRAY['/images/pois/beeline-store_gp.webp']::text[], 3.8, NULL, NULL, NULL, NULL, ARRAY['practical','telecom']::text[], true, false, false, 50, 98, 'free'::subscription_tier, 2400);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-219', 'ediny-vizovy-tsentr', '{"ru": "Единый визовый центр", "en": "Unified Visa Center"}'::jsonb, 'practical'::poi_category, 'practical', NULL, '{"lat": 43.02, "lng": 44.6827, "address": {"ru": "ул. Гаппо Баева, 20, Владикавказ", "en": "20 Gappo Baev St, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Центр оформления виз и консульских документов для поездок за рубеж.", "en": "Visa and consular document processing center for international travel."}, "medium": {"ru": "Единый визовый центр во Владикавказе занимается оформлением виз в различные страны, консультирует по пакету документов и срокам. Приём по предварительной записи. Полезен для туристов, планирующих продолжить путешествие за рубеж.", "en": "The Unified Visa Center in Vladikavkaz handles visa applications for various countries, advises on document requirements and processing times. Appointment-based. Useful for tourists planning to continue their journey abroad."}, "full": {"ru": "Единый визовый центр во Владикавказе занимается оформлением виз в различные страны, консультирует по пакету документов и срокам. Приём по предварительной записи. Полезен для туристов, планирующих продолжить путешествие за рубеж.", "en": "The Unified Visa Center in Vladikavkaz handles visa applications for various countries, advises on document requirements and processing times. Appointment-based. Useful for tourists planning to continue their journey abroad."}}'::jsonb, ARRAY['/images/pois/ediny-vizovy-tsentr_gp.webp','/images/pois/ediny-vizovy-tsentr_2.webp']::text[], 4, NULL, NULL, NULL, NULL, ARRAY['practical','services']::text[], false, false, false, 50, 76, 'free'::subscription_tier, 1200);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-221', 'cosmos-la-vallee', '{"ru": "Cosmos Vladikavkaz La Vallée", "en": "Cosmos Vladikavkaz La Vallée"}'::jsonb, 'accommodation'::poi_category, '4-звёздочный отель', NULL, '{"lat": 42.829049, "lng": 44.439235, "address": {"ru": "ул. Тагаурская, 21, Даргавс, Северная Осетия — Алания", "en": "21 Tagaurskaya St, Dargavs, North Ossetia–Alania"}}'::jsonb, '{"short": {"ru": "4-звёздочный спа-отель в Дагавском ущелье с панорамными видами на Кавказ.", "en": "A 4-star spa hotel in the Dargavs Gorge with panoramic views of the Caucasus."}, "medium": {"ru": "Cosmos Vladikavkaz La Vallée — современный 4-звёздочный спа-отель в Даргавском ущелье, в 45 км от Владикавказа. 70 номеров, закрытый 25-метровый бассейн, хаммам, сауна, два ресторана с кавказской и европейской кухней. Рейтинг 5.0 на Яндекс.Картах.", "en": "Cosmos Vladikavkaz La Vallée is a modern 4-star spa hotel in the Dargavs Gorge, 45 km from Vladikavkaz. 70 rooms, an indoor 25-metre pool, hammam, sauna, and two restaurants with Caucasian and European cuisine. Rated 5.0 on Yandex Maps."}, "full": {"ru": "Cosmos Vladikavkaz La Vallée — 4-звёздочный спа-отель группы Cosmos Hotels в Даргавском ущелье Северной Осетии, в 45 км от Владикавказа. 70 номеров категорий Standard, Deluxe и Junior Suite с видом на Кавказские горы. Инфраструктура: закрытый 25-метровый бассейн, сауна, хаммам, массажный кабинет, фитнес-центр, два ресторана, конференц-залы на 200 мест, вертолётная площадка, бесплатная парковка. Рейтинг 5.0 на Яндекс.Картах (214 отзывов), 9.7/10 на Ostrovok.ru.", "en": "Cosmos Vladikavkaz La Vallée is a 4-star spa hotel by Cosmos Hotels Group in the Dargavs Gorge of North Ossetia, 45 km from Vladikavkaz. 70 rooms including Standard, Deluxe and Junior Suite, all with Caucasus mountain views. Facilities include an indoor 25-metre pool, sauna, hammam, massage room, fitness centre, two restaurants, conference halls for 200, a helipad, and free parking. Rated 5.0 on Yandex Maps (214 reviews), 9.7/10 on Ostrovok.ru."}}'::jsonb, ARRAY['/images/pois/cosmos-la-vallee_8.webp','/images/pois/cosmos-la-vallee_10.webp','/images/pois/cosmos-la-vallee_11.webp','/images/pois/cosmos-la-vallee_1.webp','/images/pois/cosmos-la-vallee_2.webp','/images/pois/cosmos-la-vallee_3.webp','/images/pois/cosmos-la-vallee_4.webp','/images/pois/cosmos-la-vallee_5.webp','/images/pois/cosmos-la-vallee_6.webp','/images/pois/cosmos-la-vallee_7.webp','/images/pois/cosmos-la-vallee_9.webp']::text[], 5, '{"mon": "00:00-23:59", "tue": "00:00-23:59", "wed": "00:00-23:59", "thu": "00:00-23:59", "fri": "00:00-23:59", "sat": "00:00-23:59", "sun": "00:00-23:59"}'::jsonb, '+7 (800) 100-56-10', 'https://vladikavkaz.cosmosgroup.ru/', 4, ARRAY['спа-отель','горы','Даргавс','бассейн','4 звезды']::text[], true, false, false, 80, 214, 'free'::subscription_tier, 3200);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-222', 'forrest-terrace-hotel', '{"ru": "Forrest Terrace Hotel", "en": "Forrest Terrace Hotel"}'::jsonb, 'accommodation'::poi_category, '4-звёздочный отель', NULL, '{"lat": 42.885816, "lng": 44.334483, "address": {"ru": "п. Верхний Фиагдон, 16с, Алагирский район, Северная Осетия — Алания", "en": "16c, Verkhniy Fiagdon, Alagirsky District, North Ossetia-Alania"}}'::jsonb, '{"short": {"ru": "Горный отель-шале в Куртатинском ущелье с панорамными видами на Кавказ.", "en": "Mountain chalet hotel in the Kurtatinskoe gorge with panoramic views of the Caucasus."}, "medium": {"ru": "Forrest Terrace Hotel — 4-звёздочный горный отель в Куртатинском ущелье, в 40 км от Владикавказа. 48 номеров, крытый бассейн с джакузи, СПА-центр, ресторан с кавказской кухней. Рейтинг 9.7 на Booking.com.", "en": "Forrest Terrace Hotel is a 4-star mountain hotel in the Kurtatinskoe gorge, 40 km from Vladikavkaz. 48 rooms, indoor heated pool with jacuzzi, spa centre, restaurant with Caucasian cuisine. Rated 9.7 on Booking.com."}, "full": {"ru": "Forrest Terrace Hotel — горный отель-шале в Куртатинском ущелье Северной Осетии, 40 км от Владикавказа. 48 номеров: стандарт, люкс и апартаменты — все с видом на горы. Инфраструктура: крытый отапливаемый бассейн, джакузи, хаммам, сауна, массажный кабинет, фитнес-центр с панорамным видом, ресторан с кавказской и европейской кухней, бильярд, терренкур. Рейтинг 9.7 на Booking.com (988 отзывов), 9.5 на Ostrovok.ru, 5.0 на 2GIS.", "en": "Forrest Terrace Hotel is a mountain chalet in the Kurtatinskoe gorge of North Ossetia, 40 km from Vladikavkaz. 48 rooms — standard, suites and apartments — all with mountain views. Facilities: indoor heated pool, jacuzzi, hammam, sauna, massage room, panoramic fitness centre, restaurant with Caucasian and European cuisine, billiards, and walking trails. Rated 9.7 on Booking.com (988 reviews), 9.5 on Ostrovok.ru, 5.0 on 2GIS."}}'::jsonb, ARRAY['/images/pois/forrest-terrace-hotel_1.webp','/images/pois/forrest-terrace-hotel_2.webp','/images/pois/forrest-terrace-hotel_3.webp','/images/pois/forrest-terrace-hotel_4.webp','/images/pois/forrest-terrace-hotel_5.webp','/images/pois/forrest-terrace-hotel_6.webp','/images/pois/forrest-terrace-hotel_7.webp','/images/pois/forrest-terrace-hotel_8.webp','/images/pois/forrest-terrace-hotel_9.webp','/images/pois/forrest-terrace-hotel_10.webp']::text[], 4.9, '{"mon": "00:00-23:59", "tue": "00:00-23:59", "wed": "00:00-23:59", "thu": "00:00-23:59", "fri": "00:00-23:59", "sat": "00:00-23:59", "sun": "00:00-23:59"}'::jsonb, '+7 (800) 201-64-22', 'https://forrest-hotel.ru/', 4, ARRAY['горный отель','шале','СПА','бассейн','Куртатинское ущелье','4 звезды']::text[], false, false, false, 80, 988, 'free'::subscription_tier, 2800);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-223', 'alania-4x4', '{"ru": "ALANIA 4X4", "en": "ALANIA 4X4"}'::jsonb, 'tours'::poi_category, 'Джип-туры', NULL, '{"lat": 43.0241, "lng": 44.6819, "address": {"ru": "ул. Гагарина, 4, Владикавказ", "en": "4 Gagarina St, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Джип-туры по горам Северной Осетии на Toyota и Lexus.", "en": "Jeep tours through the mountains of North Ossetia in Toyota and Lexus vehicles."}, "medium": {"ru": "ALANIA 4X4 — компания джип-туров по Северной Осетии с 2017 года. 45 маршрутов: Фиагдон, Кармадон, Цейское и Дигорское ущелья. Однодневные туры от 13 000 ₽, многодневные программы до 7 дней.", "en": "ALANIA 4X4 — jeep tour company in North Ossetia since 2017. 45 routes: Fiagdon, Karmadon, Tsei and Digoria gorges. Day tours from 13,000 ₽, multi-day programs up to 7 days."}, "full": {"ru": "ALANIA 4X4 — компания джип-туров по горам Северной Осетии, работает с 2017 года. Парк автомобилей: Toyota и Lexus повышенной проходимости. 45 готовых маршрутов — от однодневных экскурсий по Куртатинскому и Кармадонскому ущельям до 7-дневных экспедиций по всей горной Осетии. Также организуют треккинг, рафтинг, полёты на параплане и туры на квадроциклах. Цены: однодневные туры от 13 000 ₽, 3 дня от 39 900 ₽, 5–7 дней от 68 000 до 125 000 ₽.", "en": "ALANIA 4X4 is a jeep tour company operating in the mountains of North Ossetia since 2017. Fleet: Toyota and Lexus off-road vehicles. 45 ready-made routes — from day trips through the Kurtatinskoe and Karmadon gorges to 7-day expeditions across mountain Ossetia. Also organises trekking, rafting, paragliding and quad bike tours. Prices: day tours from 13,000 ₽, 3 days from 39,900 ₽, 5–7 days from 68,000 to 125,000 ₽."}}'::jsonb, ARRAY['/images/pois/alania-4x4_gp.webp']::text[], 5, '{"mon": "09:00-21:00", "tue": "09:00-21:00", "wed": "09:00-21:00", "thu": "09:00-21:00", "fri": "09:00-21:00", "sat": "09:00-21:00", "sun": "09:00-21:00"}'::jsonb, '+7 (918) 703-39-39', 'https://alania4x4.ru/', NULL, ARRAY['джип-туры','4x4','горы','ущелья','треккинг','рафтинг']::text[], false, false, false, 150, 0, 'free'::subscription_tier, 1200);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-224', 'rocktour-caucasus', '{"ru": "RockTour Caucasus", "en": "RockTour Caucasus"}'::jsonb, 'tours'::poi_category, 'Горные туры', NULL, '{"lat": 43.0289, "lng": 44.6712, "address": {"ru": "ул. Ушинского, 84, Владикавказ", "en": "84 Ushinskogo St, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Горные туры и активный отдых в Северной Осетии: треккинг, рафтинг, восхождения.", "en": "Mountain tours and outdoor activities in North Ossetia: trekking, rafting, climbing."}, "medium": {"ru": "RockTour Caucasus — владикавказская компания активного туризма. Организуют экскурсии по Цейскому, Дигорскому и Алагирскому ущельям, треккинг, восхождения на Казбек, рафтинг, скалолазание, конные туры и эндуро.", "en": "RockTour Caucasus is a Vladikavkaz outdoor tourism company. They organise excursions to Tsei, Digoria and Alagir gorges, trekking, ascents of Kazbek, rafting, rock climbing, horse riding and enduro tours."}, "full": {"ru": "RockTour Caucasus — местная владикавказская компания активного туризма. Полная линейка маршрутов: экскурсии по Цейскому, Дигорскому и Алагирскому ущельям, пешие треккинги, восхождения на Казбек, рафтинг, скалолазание, конные туры, эндуро-туры. Все программы из Владикавказа с местными гидами.", "en": "RockTour Caucasus is a local Vladikavkaz outdoor tourism company offering a full range of routes: excursions to Tsei, Digoria and Alagir gorges, trekking, Kazbek ascents, rafting, rock climbing, horse riding and enduro tours. All programmes depart from Vladikavkaz with local guides."}}'::jsonb, ARRAY['/images/pois/rocktour-caucasus_gp.webp']::text[], 5, '{"mon": "09:00-21:00", "tue": "09:00-21:00", "wed": "09:00-21:00", "thu": "09:00-21:00", "fri": "09:00-21:00", "sat": "09:00-21:00", "sun": "09:00-21:00"}'::jsonb, '+7 (928) 072-02-00', 'https://rocktour.ru/', NULL, ARRAY['горные туры','треккинг','рафтинг','восхождения','скалолазание','Казбек']::text[], false, false, false, 150, 0, 'free'::subscription_tier, 900);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-225', 'explore-ossetia', '{"ru": "Explore Ossetia", "en": "Explore Ossetia"}'::jsonb, 'tours'::poi_category, 'Горные туры', NULL, '{"lat": 43.0225, "lng": 44.6789, "address": {"ru": "Владикавказ, Северная Осетия — Алания", "en": "Vladikavkaz, North Ossetia-Alania"}}'::jsonb, '{"short": {"ru": "Индивидуальные и групповые туры по горам Осетии: джип-туры, треккинг, астро-туры.", "en": "Individual and group tours through the mountains of Ossetia: jeep tours, trekking, astro-tours."}, "medium": {"ru": "Explore Ossetia — авторские туры по Северной Осетии с душой. Индивидуальные, корпоративные и групповые программы: джип-туры по ущельям, пешие маршруты, астро-туры под звёздным небом Кавказа.", "en": "Explore Ossetia offers soulful tours through North Ossetia. Individual, corporate and group programmes: jeep tours through gorges, trekking routes, and astro-tours under the Caucasian night sky."}, "full": {"ru": "Explore Ossetia — туристическая компания с душой, специализирующаяся на авторских турах по горам Северной Осетии. 16 тысяч подписчиков в Instagram. Программы: индивидуальные и групповые джип-туры по ущельям, корпоративные поездки, пешие маршруты по Кавказскому хребту, астро-туры для наблюдения за звёздами в горах.", "en": "Explore Ossetia is a tourism company specialising in authentic tours through the mountains of North Ossetia. 16,000 Instagram followers. Programmes: individual and group jeep tours through the gorges, corporate trips, trekking routes along the Caucasian ridge, and astro-tours for stargazing in the mountains."}}'::jsonb, ARRAY['/images/pois/explore-ossetia_gp.webp']::text[], 5, '{"mon": "09:00-21:00", "tue": "09:00-21:00", "wed": "09:00-21:00", "thu": "09:00-21:00", "fri": "09:00-21:00", "sat": "09:00-21:00", "sun": "09:00-21:00"}'::jsonb, NULL, 'https://vk.com/explore_ossetia', NULL, ARRAY['горные туры','джип-туры','треккинг','астро-туры','индивидуальные туры']::text[], false, false, false, 150, 0, 'free'::subscription_tier, 1600);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-226', 'ossetia-unikalnye-tury', '{"ru": "Осетия Уникальные туры", "en": "Ossetia Unique Tours"}'::jsonb, 'tours'::poi_category, 'Авторские туры', NULL, '{"lat": 43.0225, "lng": 44.6789, "address": {"ru": "Владикавказ, Северная Осетия — Алания", "en": "Vladikavkaz, North Ossetia-Alania"}}'::jsonb, '{"short": {"ru": "Авторские туры по горам Осетии от Шоты Гаглоева. 9 лет в горах.", "en": "Authentic mountain tours in Ossetia by Shota Gagloev. 9 years in the mountains."}, "medium": {"ru": "Осетия Уникальные туры — авторский проект Шоты Гаглоева, основателя Explore Ossetia. 9 лет показывает горы как искусство. Индивидуальные и групповые туры по Северной Осетии.", "en": "Ossetia Unique Tours is an author project by Shota Gagloev, founder of Explore Ossetia. 9 years of showing mountains as art. Individual and group tours across North Ossetia."}, "full": {"ru": "Осетия Уникальные туры — авторский проект Шоты Гаглоева. Более 26 тысяч подписчиков в Instagram (@sh0tik0). 9 лет опыта в горных турах по Северной Осетии. Основатель компании Explore Ossetia. Организует индивидуальные, групповые туры и восхождения.", "en": "Ossetia Unique Tours is the author project of Shota Gagloev. Over 26,000 Instagram followers (@sh0tik0). 9 years of experience in mountain tours across North Ossetia. Founder of Explore Ossetia. Organises individual, group tours and mountain ascents."}}'::jsonb, ARRAY['/images/pois/ossetia-unikalnye-tury_gp.webp']::text[], 5, '{"mon": "09:00-21:00", "tue": "09:00-21:00", "wed": "09:00-21:00", "thu": "09:00-21:00", "fri": "09:00-21:00", "sat": "09:00-21:00", "sun": "09:00-21:00"}'::jsonb, '+7 (999) 350-05-55', 'https://www.instagram.com/sh0tik0', NULL, ARRAY['авторские туры','горы','восхождения','индивидуальные туры']::text[], false, false, false, 150, 0, 'free'::subscription_tier, 1400);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-227', 'travel-osetia-011', '{"ru": "Travel Osetia 011", "en": "Travel Osetia 011"}'::jsonb, 'tours'::poi_category, 'VIP-туры и трансфер', NULL, '{"lat": 43.0225, "lng": 44.6789, "address": {"ru": "Владикавказ, Северная Осетия — Алания", "en": "Vladikavkaz, North Ossetia-Alania"}}'::jsonb, '{"short": {"ru": "VIP-коттеджи в Фиагдоне, аренда джипов, трансфер и кейтеринг по Осетии.", "en": "VIP cottages in Fiagdon, jeep hire, transfer and catering across Ossetia."}, "medium": {"ru": "Travel Osetia 011 — отдых под ключ в Северной Осетии. Более 150 VIP-коттеджей, поездки по горам на внедорожниках, кейтеринг, трансфер и организация мероприятий.", "en": "Travel Osetia 011 — turnkey holidays in North Ossetia. Over 150 VIP cottages, mountain trips in off-road vehicles, catering, transfer and event organisation."}, "full": {"ru": "Travel Osetia 011 — комплексный туристический сервис в Северной Осетии. 22 тысячи подписчиков в Instagram. Более 150 VIP-коттеджей в Фиагдоне и горных районах. Аренда внедорожников для поездок по ущельям, профессиональный трансфер, кейтеринг и организация корпоративных мероприятий и праздников.", "en": "Travel Osetia 011 is a comprehensive tourism service in North Ossetia. 22,000 Instagram followers. Over 150 VIP cottages in Fiagdon and mountain areas. Off-road vehicle hire for gorge trips, professional transfer, catering and corporate event organisation."}}'::jsonb, ARRAY['/images/pois/travel-osetia-011_gp.webp']::text[], 5, '{"mon": "09:00-21:00", "tue": "09:00-21:00", "wed": "09:00-21:00", "thu": "09:00-21:00", "fri": "09:00-21:00", "sat": "09:00-21:00", "sun": "09:00-21:00"}'::jsonb, '+7 (989) 035-10-11', 'https://t.me/TRAVEL_OSETIA', NULL, ARRAY['VIP коттеджи','Фиагдон','аренда джипа','трансфер','кейтеринг']::text[], false, false, false, 150, 0, 'free'::subscription_tier, 1600);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-228', 'ossetia-mechta', '{"ru": "Осетия как мечта", "en": "Ossetia as a Dream"}'::jsonb, 'tours'::poi_category, 'Туры и экскурсии', NULL, '{"lat": 43.0225, "lng": 44.6789, "address": {"ru": "Владикавказ, Северная Осетия — Алания", "en": "Vladikavkaz, North Ossetia-Alania"}}'::jsonb, '{"short": {"ru": "Бюро путешествий: туры и экскурсии по Осетии и Кавказу с молодыми гидами.", "en": "Travel bureau: tours and excursions across Ossetia and the Caucasus with young guides."}, "medium": {"ru": "Осетия как мечта — бюро путешествий с молодыми гидами. 45 тысяч подписчиков в Instagram. Туры и экскурсии по Северной Осетии и Кавказу с настоящими эмоциями.", "en": "Ossetia as a Dream is a travel bureau with young guides. 45,000 Instagram followers. Tours and excursions across North Ossetia and the Caucasus with real emotions."}, "full": {"ru": "Осетия как мечта — бюро путешествий в Северной Осетии. Более 45 тысяч подписчиков в Instagram (@ossetia.mechta). Молодые местные гиды, живая Осетия, настоящие эмоции. Организуют туры и экскурсии по всей Осетии и Кавказу. Афиша туров на сезон 2026 в актуальных сторис.", "en": "Ossetia as a Dream is a travel bureau in North Ossetia. Over 45,000 Instagram followers (@ossetia.mechta). Young local guides, living Ossetia, real emotions. Organise tours and excursions across Ossetia and the Caucasus. 2026 season tour schedule in their highlights."}}'::jsonb, ARRAY['/images/pois/ossetia-mechta_gp.webp']::text[], 5, '{"mon": "09:00-21:00", "tue": "09:00-21:00", "wed": "09:00-21:00", "thu": "09:00-21:00", "fri": "09:00-21:00", "sat": "09:00-21:00", "sun": "09:00-21:00"}'::jsonb, '+7 (928) 499-55-22', 'https://t.me/ossetiamechta', NULL, ARRAY['туры','экскурсии','молодые гиды','Кавказ','живая Осетия']::text[], false, false, false, 150, 0, 'free'::subscription_tier, 2100);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-229', 'vechny-ogon-vladikavkaz', '{"ru": "Вечный огонь", "en": "Eternal Flame"}'::jsonb, 'culture'::poi_category, 'memorial', NULL, '{"lat": 43.0185, "lng": 44.6812, "address": {"ru": "Проспект Коста, Владикавказ", "en": "Kosta Avenue, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Мемориальный огонь в честь защитников Владикавказа, павших в Великой Отечественной войне.", "en": "Memorial flame honoring the defenders of Vladikavkaz who fell in the Great Patriotic War."}, "medium": {"ru": "Вечный огонь во Владикавказе горит в память о защитниках города, остановивших немецкое наступление в ноябре 1942 года. Мемориальный комплекс открыт в 1967 году к 25-летию победы в Битве за Кавказ — одном из переломных сражений Второй мировой войны.", "en": "The Eternal Flame in Vladikavkaz burns in memory of the city defenders who stopped the German advance in November 1942. The memorial complex was opened in 1967 for the 25th anniversary of the victory in the Battle of the Caucasus — one of the turning points of World War II."}, "full": {"ru": "Вечный огонь во Владикавказе — сердце мемориального комплекса, посвящённого героям Великой Отечественной войны. В октябре–ноябре 1942 года у стен тогдашнего Орджоникидзе разгорелось одно из решающих сражений Битвы за Кавказ. Немецкие войска группы армий «А», рвавшиеся к бакинской нефти и через Кавказский хребет в Закавказье, были остановлены и отброшены именно здесь — в нескольких километрах от городских улиц. Эта победа стала прологом к Сталинградскому контрнаступлению и переломила ход войны на южном направлении.\n\nМемориальный комплекс с Вечным огнём был торжественно открыт в 1967 году — ровно через 25 лет после битвы. Огонь не гаснет круглый год: он горит как символ вечной памяти о тысячах солдат, офицеров и мирных жителей, отдавших жизнь за город. На мемориальных плитах высечены имена погибших защитников.\n\nСегодня это место глубокого почитания: сюда приносят цветы в дни государственных праздников, здесь проходят торжественные церемонии 9 Мая, а молодожёны по традиции приезжают возложить букеты. Рядом расположена одна из станций Детской железной дороги, которая так и называется — «Вечный огонь».", "en": "The Eternal Flame in Vladikavkaz is the heart of the memorial complex dedicated to the heroes of the Great Patriotic War. In October–November 1942, one of the decisive battles of the Battle of the Caucasus took place at the walls of then-Ordzhonikidze. German forces of Army Group A, racing toward the Baku oil fields and across the Caucasus range into Transcaucasia, were stopped and driven back right here — just a few kilometers from the city streets. This victory foreshadowed the Stalingrad counteroffensive and turned the tide of the war on the southern front.\n\nThe memorial complex with the Eternal Flame was solemnly opened in 1967, exactly 25 years after the battle. The flame burns year-round as a symbol of eternal remembrance for the thousands of soldiers, officers, and civilians who gave their lives for the city. The memorial slabs bear the names of fallen defenders.\n\nToday this is a place of deep reverence: flowers are brought here on national holidays, solemn ceremonies take place on Victory Day (May 9th), and newlyweds traditionally come to lay bouquets. The children''s railway station nearby is named \"Eternal Flame\" in its honor."}}'::jsonb, ARRAY['/images/pois/vechny-ogon_gp.webp','/images/pois/vechny-ogon-vladikavkaz_2.webp','/images/pois/vechny-ogon-vladikavkaz_3.webp','/images/pois/vechny-ogon-vladikavkaz_4.webp','/images/pois/vechny-ogon-vladikavkaz_5.webp']::text[], 4.8, NULL, NULL, NULL, NULL, ARRAY['мемориал','война','история','вечный огонь','ВОВ']::text[], false, false, false, 80, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-230', 'sword-in-stone', '{"ru": "Меч в камне", "en": "Sword in Stone"}'::jsonb, 'culture'::poi_category, 'art-object', NULL, '{"lat": 42.7933, "lng": 44.3735, "address": {"ru": "Мидаграбинская долина, Северная Осетия", "en": "Midagrabin Valley, North Ossetia"}}'::jsonb, '{"short": {"ru": "Арт-объект: металлический клинок, воткнутый в пятиметровый камень посреди горной долины.", "en": "Art object: a metal blade thrust into a five-meter boulder in the heart of a mountain valley."}, "medium": {"ru": "Гигантский металлический меч, пронзающий огромный камень — отсылка к нартскому эпосу и легенде о короле Артуре. Учёные считают, что история о мече в камне могла прийти в Европу именно от предков осетин — скифов и сарматов. Установлен в Мидаграбинской долине в 2021 году.", "en": "A giant metal sword piercing a massive boulder — a reference to the Nart epic and the Arthurian legend. Scholars believe the sword-in-stone tale may have reached Europe from the Scythians and Sarmatians, ancestors of the Ossetians. Installed in Midagrabin Valley in 2021."}, "full": {"ru": "Арт-объект «Меч в камне» установлен в Мидаграбинской долине — одном из красивейших мест Северной Осетии, где расположены одни из самых высоких водопадов Европы. Металлический клинок, вонзённый в пятиметровый гранитный валун, отсылает сразу к двум великим эпосам: осетинским нартским сказаниям и западноевропейской легенде о короле Артуре.\n\nСвязь неслучайна: ряд историков и фольклористов полагает, что сюжет о мече, который способен вытащить из камня лишь истинный герой, пришёл в Европу от скифов и сарматов — кочевых народов, которые являются предками современных осетин. Этот арт-объект превращает горный пейзаж в живую иллюстрацию того, как древние осетинские предания могли дать импульс мировой культуре.\n\nВокруг объекта открывается панорама Мидаграбинских водопадов — каскада из семи водопадов, среди которых Большой Зейгалан высотой 600 метров входит в число крупнейших в Европе.", "en": "The \"Sword in Stone\" art object stands in Midagrabin Valley — one of the most spectacular areas of North Ossetia, home to some of the tallest waterfalls in Europe. A metal blade thrust into a five-meter granite boulder references two great epics at once: the Ossetian Nart sagas and the Arthurian legend.\n\nThe connection is no coincidence. Many historians and folklorists believe the tale of the sword only a true hero can draw from stone traveled to Europe through the Scythians and Sarmatians — nomadic peoples who are ancestors of modern Ossetians. This art object turns a mountain landscape into a living illustration of how ancient Ossetian tales may have shaped world culture.\n\nAround the object, the panorama of the Midagrabin waterfalls unfolds — a cascade of seven falls, among which the Great Zeygalan at 600 meters is one of the tallest in Europe."}}'::jsonb, ARRAY['/images/pois/sword-in-stone_gp.webp','/images/pois/sword-in-stone_2.webp','/images/pois/sword-in-stone_3.webp','/images/pois/sword-in-stone_4.webp']::text[], 4.7, NULL, NULL, NULL, NULL, ARRAY['арт-объект','нарты','горы','история','скульптура']::text[], false, false, false, 80, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-231', 'mirror-snow-leopard', '{"ru": "Зеркальный барс", "en": "Mirror Snow Leopard"}'::jsonb, 'culture'::poi_category, 'art-object', NULL, '{"lat": 42.8827, "lng": 44.3268, "address": {"ru": "Кадаргаванский каньон, Северная Осетия", "en": "Kadargavan Canyon, North Ossetia"}}'::jsonb, '{"short": {"ru": "Скульптура барса, покрытая зеркальными элементами — символ исчезающего переднеазиатского леопарда, изображённого на гербе Осетии.", "en": "A leopard sculpture covered in mirror elements — symbol of the endangered Caucasian leopard depicted on the coat of arms of Ossetia."}, "medium": {"ru": "Барс будто крадётся по скале, его тело частично отражает окружающий горный пейзаж и становится почти невидимым. Так арт-объект напоминает: переднеазиатский леопард — символ республики на гербе — находится под угрозой исчезновения. Установлен у входа в Кадаргаванский каньон в 2021 году.", "en": "The leopard seems to stalk the cliff face, its mirrored body reflecting the surrounding mountain landscape, rendering it almost invisible. The art object reminds us that the Caucasian leopard — the republic''s heraldic symbol — is on the brink of extinction. Installed at the entrance to Kadargavan Canyon in 2021."}, "full": {"ru": "Зеркальный барс установлен у Кадаргаванского каньона — узкой теснины с отвесными скалами высотой до 100 метров, по дну которой стремительно несётся река Ардон. Скульптура выполнена из металла и покрыта зеркальными фрагментами: хищник будто растворяется в пейзаже, отражая небо, скалы и деревья.\n\nЭтот художественный приём несёт глубокий смысл. Переднеазиатский леопард — редчайший подвид, занесённый в Красную книгу России. Именно он изображён на гербе и флаге Северной Осетии — Алании как символ силы, красоты и независимости горного народа. Сегодня в дикой природе Кавказа сохранились лишь единицы этих животных.\n\nКадаргаванский каньон сам по себе — одна из главных природных достопримечательностей республики. Через него проходит Транскавказская магистраль, и многие путешественники, следующие в Южную Осетию или возвращающиеся оттуда, останавливаются здесь, чтобы осмотреть каньон и зеркального барса.", "en": "The Mirror Snow Leopard stands at Kadargavan Canyon — a narrow gorge with sheer cliffs up to 100 meters tall, through which the Ardon River rushes. The sculpture is crafted from metal and covered with mirror fragments: the predator seems to dissolve into the landscape, reflecting sky, rock, and trees.\n\nThis artistic device carries deep meaning. The Caucasian leopard is a critically endangered subspecies listed in Russia''s Red Book. It is depicted on the coat of arms and flag of North Ossetia-Alania as a symbol of the mountain people''s strength, beauty, and independence. Today, only a handful of these animals survive in the wild Caucasus.\n\nKadargavan Canyon is itself one of the republic''s premier natural attractions. The Trans-Caucasian Highway passes through it, and many travelers heading to or from South Ossetia stop here to take in the canyon and the mirrored leopard."}}'::jsonb, ARRAY['/images/pois/mirror-snow-leopard_gp.webp','/images/pois/mirror-snow-leopard_2.webp','/images/pois/mirror-snow-leopard_3.webp','/images/pois/mirror-snow-leopard_4.webp']::text[], 4.8, NULL, NULL, NULL, NULL, ARRAY['арт-объект','барс','каньон','скульптура','символ']::text[], false, false, false, 80, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-232', 'ossetian-alphabet-letter', '{"ru": "Буква Æ", "en": "Letter Æ"}'::jsonb, 'culture'::poi_category, 'art-object', NULL, '{"lat": 42.8345, "lng": 44.3689, "address": {"ru": "Между Даргавсом и Фиагдоном, Северная Осетия", "en": "Between Dargavs and Fiagdon, North Ossetia"}}'::jsonb, '{"short": {"ru": "Металлическая конструкция в виде уникальной буквы осетинского алфавита — одного из символов языка и идентичности осетинского народа.", "en": "A metal structure shaped as a unique letter of the Ossetian alphabet — a symbol of the language and identity of the Ossetian people."}, "medium": {"ru": "Буква «Æ» — одна из самобытных букв осетинского алфавита, сохранённых при переводе языка на кириллицу. Она не имеет аналогов в русском алфавите и является символом уникальности осетинского языка. Арт-объект установлен на живописном горном маршруте между Даргавсом и Фиагдоном.", "en": "The letter \"Æ\" is one of the distinctive letters of the Ossetian alphabet, preserved when the language was transferred to Cyrillic script. It has no equivalent in the Russian alphabet and symbolizes the uniqueness of the Ossetian language. The art object stands on a scenic mountain route between Dargavs and Fiagdon."}, "full": {"ru": "Арт-объект «Буква Æ» посвящён осетинскому языку — одному из немногих живых потомков скифо-сарматской языковой традиции, восходящей к иранской ветви индоевропейской семьи. Когда в XIX веке осетинский язык был переведён в письменную форму, а затем адаптирован под кириллицу, составители алфавита сохранили уникальный диграф «Æ/æ» — звук, не имеющий точного аналога ни в русском, ни в большинстве других кириллических алфавитов.\n\nМеталлическая конструкция выполнена в виде объёмной буквы, внутри которой можно сидеть и отдыхать. Расположена на высоте с панорамным видом на горные хребты. Маршрут от Даргавса — «города мёртвых» — до Фиагдона является одним из самых популярных в Куртатинском ущелье и проходит через несколько исторических осетинских сёл.\n\nЭтот арт-объект — не просто скульптура, но приглашение задуматься о том, как язык хранит идентичность народа на протяжении тысячелетий.", "en": "The \"Letter Æ\" art object is dedicated to the Ossetian language — one of the few living descendants of the Scythian-Sarmatian linguistic tradition, rooted in the Iranian branch of the Indo-European family. When the Ossetian language was committed to writing in the 19th century and later adapted to Cyrillic, alphabet creators preserved the unique digraph \"Æ/æ\" — a sound with no precise equivalent in Russian or most other Cyrillic-script languages.\n\nThe metal structure is shaped as a three-dimensional letter with space inside for resting. It sits at an elevation with panoramic views of mountain ridges. The route from Dargavs — the \"City of the Dead\" — to Fiagdon is one of the most popular in Kurtatinsky Gorge, passing through several historic Ossetian villages.\n\nThis art object is not just a sculpture, but an invitation to reflect on how language preserves a people''s identity across millennia."}}'::jsonb, ARRAY['/images/pois/ossetian-alphabet-letter_gp.webp','/images/pois/ossetian-alphabet-letter_2.webp','/images/pois/ossetian-alphabet-letter_3.webp','/images/pois/ossetian-alphabet-letter_4.webp']::text[], 4.6, NULL, NULL, NULL, NULL, ARRAY['арт-объект','язык','культура','алфавит','горы']::text[], false, false, false, 80, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-233', 'kosta-khetagurov-portrait', '{"ru": "Портрет Косты Хетагурова", "en": "Portrait of Kosta Khetagurov"}'::jsonb, 'culture'::poi_category, 'art-object', NULL, '{"lat": 42.6961, "lng": 43.9768, "address": {"ru": "Зарамагское водохранилище, Северная Осетия", "en": "Zaramag Reservoir, North Ossetia"}}'::jsonb, '{"short": {"ru": "Уникальная скульптура из вертикальных металлических брусьев, складывающихся в портрет великого осетинского поэта под определённым углом.", "en": "A unique sculpture of vertical metal rods that resolve into a portrait of the great Ossetian poet when viewed from the right angle."}, "medium": {"ru": "С одной точки — хаотичный лес металлических стержней. Под нужным углом — чёткий портрет Косты Хетагурова, основателя осетинской литературы. Оптическая иллюзия превращает встречу с арт-объектом в маленькое открытие. Установлен у живописного Зарамагского водохранилища.", "en": "From one point — a chaotic forest of metal rods. From the right angle — a clear portrait of Kosta Khetagurov, founder of Ossetian literature. The optical illusion turns the encounter into a small revelation. Installed beside the scenic Zaramag reservoir."}, "full": {"ru": "Арт-объект создан в честь Косты Левановича Хетагурова (1859–1906) — осетинского поэта, художника и просветителя, которого называют основателем осетинской литературы и осетинского литературного языка. Его сборник «Осетинская лира» (Ирон фандыр), написанный на осетинском языке, стал первой книгой осетинской художественной литературы.\n\nТехника арт-объекта — анаморфная скульптура: вертикальные металлические стержни разной высоты расставлены так, что при взгляде строго с одной точки складываются в узнаваемый образ. С любого другого угла — это просто лес прутьев. Такой приём метафорически говорит о том, что понять и увидеть поэта можно лишь с правильной, внимательной позиции.\n\nЗарамагское водохранилище, у которого стоит объект, образовано плотиной Зарамагской ГЭС и окружено высокогорными хребтами. Это один из самых труднодоступных и потому нетронутых уголков Северной Осетии.", "en": "The art object honors Kosta Levanovich Khetagurov (1859–1906) — Ossetian poet, artist, and enlightener, considered the founder of Ossetian literature and the Ossetian literary language. His collection \"Ossetian Lyre\" (Iron Fandir), written in Ossetian, was the first book of Ossetian belles-lettres.\n\nThe technique is anamorphic sculpture: vertical metal rods of varying heights are arranged so that from exactly one vantage point they resolve into a recognizable face. From any other angle — just a forest of rods. This approach metaphorically suggests that to truly see and understand a poet, one must find the right, attentive perspective.\n\nThe Zaramag reservoir beside which the object stands was formed by the Zaramag hydroelectric dam and is surrounded by high-mountain ridges — one of the most remote and therefore untouched corners of North Ossetia."}}'::jsonb, ARRAY['/images/pois/kosta-khetagurov-portrait_gp.webp','/images/pois/kosta-khetagurov-portrait_2.webp','/images/pois/kosta-khetagurov-portrait_3.webp','/images/pois/kosta-khetagurov-portrait_4.webp']::text[], 4.7, NULL, NULL, NULL, NULL, ARRAY['арт-объект','Коста Хетагуров','поэт','культура','скульптура']::text[], false, false, false, 80, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-234', 'balsag-wheel', '{"ru": "Колесо Балсага", "en": "Wheel of Balsag"}'::jsonb, 'culture'::poi_category, 'art-object', NULL, '{"lat": 42.785, "lng": 44.33, "address": {"ru": "Даргавское ущелье, Северная Осетия", "en": "Dargavs Gorge, North Ossetia"}}'::jsonb, '{"short": {"ru": "Скульптура огненного колеса из нартского эпоса — орудия пытки героя Сослана, ставшего символом испытания и воли.", "en": "Sculpture of the fiery wheel from the Nart epic — the instrument of Soslan''s trial that became a symbol of endurance and will."}, "medium": {"ru": "В нартском эпосе огненное колесо Балсага отрезало ноги непобедимому герою Сослану. Этот трагический образ стал одним из центральных в осетинской мифологии. Металлическая скульптура в горах Даргавского ущелья оживляет древнее предание, превращая легенду в ощутимый объект.", "en": "In the Nart epic, the fiery Wheel of Balsag severed the legs of the invincible hero Soslan. This tragic image became one of the central motifs in Ossetian mythology. The metal sculpture in the mountains of Dargavs Gorge brings the ancient tale to life, making the legend tangible."}, "full": {"ru": "Нартский эпос — грандиозный цикл мифов и сказаний, общий для многих народов Кавказа, но наиболее полно сохранившийся у осетин. Герой Сослан (Созрыко) — один из главных нартских богатырей, рождённый из камня, закалённый в волчьем молоке, непобедимый в битвах.\n\nОднако именно Колесо Балсага — мистическое огненное колесо, наделённое разумом и злобой, — сумело погубить Сослана. Согласно эпосу, оно отрезало ему ноги, нанеся смертельную рану. Этот эпизод трактуется исследователями по-разному: как символ неизбежности судьбы, как напоминание о том, что у каждого героя есть слабость, или как астрономическая метафора солнечного диска.\n\nАрт-объект установлен в Даргавском ущелье — вблизи знаменитого «города мёртвых» Даргавса, где расположен средневековый некрополь. Соседство скульптуры с историческими склеповыми башнями создаёт особую атмосферу, где миф и реальная история переплетаются неразрывно.", "en": "The Nart epic is a grand cycle of myths and tales shared by many Caucasian peoples but most completely preserved among the Ossetians. Soslan (Sozryko) is one of the chief Nart heroes — born of stone, tempered in wolf''s milk, invincible in battle.\n\nYet it was the Wheel of Balsag — a mystical fiery wheel endowed with intelligence and malice — that managed to destroy Soslan. According to the epic, it severed his legs, inflicting a mortal wound. Scholars interpret this episode variously: as a symbol of fate''s inevitability, as a reminder that every hero has a weakness, or as an astronomical metaphor for the solar disc.\n\nThe art object stands in Dargavs Gorge — near the famous \"City of the Dead\" at Dargavs, site of a medieval necropolis. The sculpture''s proximity to historic crypt towers creates a unique atmosphere where myth and real history intertwine inseparably."}}'::jsonb, ARRAY['/images/pois/balsag-wheel_gp.webp','/images/pois/balsag-wheel_2.webp','/images/pois/balsag-wheel_3.webp','/images/pois/balsag-wheel_4.webp','/images/pois/balsag-wheel_5.webp','/images/pois/balsag-wheel_6.webp']::text[], 4.6, NULL, NULL, NULL, NULL, ARRAY['арт-объект','нарты','Сослан','мифология','скульптура']::text[], false, false, false, 80, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-235', 'horn-of-abundance', '{"ru": "Рог изобилия", "en": "Horn of Abundance"}'::jsonb, 'culture'::poi_category, 'art-object', NULL, '{"lat": 42.7945, "lng": 44.0041, "address": {"ru": "Посёлок Бурон, Северная Осетия", "en": "Buron, North Ossetia"}}'::jsonb, '{"short": {"ru": "Огромный рог, закреплённый цепями на скале у посёлка Бурон — символ богатства, гостеприимства и щедрости осетинского народа.", "en": "A massive horn chained to a cliff near Buron — symbol of the wealth, hospitality, and generosity of the Ossetian people."}, "medium": {"ru": "Рог занимает особое место в осетинской культуре: на традиционном пиру старший поднимает рог с пивом или аракой и произносит тост. Арт-объект в виде исполинского рога на скале у посёлка Бурон превращает этот символ гостеприимства в монументальный образ, видимый с трассы А-164.", "en": "The drinking horn holds a special place in Ossetian culture: at a traditional feast, the elder raises a horn of beer or araka and offers a toast. The art object — a giant horn fastened to a cliff near Buron — turns this symbol of hospitality into a monumental image visible from highway A-164."}, "full": {"ru": "Рог изобилия у посёлка Бурон стоит на стратегически важной точке: именно здесь Транскавказская магистраль (А-164) уходит в сторону Рокского тоннеля и Южной Осетии. Каждый, кто едет в горы или возвращается оттуда, видит этот монументальный символ.\n\nВ осетинской традиции рог — не просто сосуд для напитков. Он неотъемлемая часть ритуала застолья — «куывда». Без рога нет настоящего осетинского пира: тот, кто поднимает его, берёт на себя ответственность старшего и произносит молитву-тост. Передать рог другому — значит передать честь и слово.\n\nАрт-объект выкован из металла и закреплён цепями прямо на скальной породе, создавая ощущение, что рог вырастает из самой горы. Бурон расположен у слияния рек Ардон и Закка, в окружении скал и лесов. Рядом — Нарское ущелье и Цейское ущелье, богатые альпийскими пейзажами.", "en": "The Horn of Abundance near Buron stands at a strategically important point: this is where the Trans-Caucasian Highway (A-164) branches toward the Roki Tunnel and South Ossetia. Everyone traveling into the mountains or returning passes this monumental symbol.\n\nIn Ossetian tradition, the horn is more than a vessel for drinks. It is an integral part of the \"kuvd\" feast ritual. Without a horn there is no true Ossetian banquet: whoever raises it takes on the responsibility of the elder and offers a prayer-toast. To pass the horn is to pass honor and one''s word.\n\nThe art object is forged from metal and fastened with chains directly into the rock face, creating the impression that the horn grows from the mountain itself. Buron lies at the confluence of the Ardon and Zakka rivers, surrounded by cliffs and forests, near the Nar and Tsey gorges with their alpine landscapes."}}'::jsonb, ARRAY['/images/pois/horn-of-abundance_gp.webp','/images/pois/horn-of-abundance_2.webp','/images/pois/horn-of-abundance_3.webp','/images/pois/horn-of-abundance_4.webp']::text[], 4.7, NULL, NULL, NULL, NULL, ARRAY['арт-объект','рог','традиции','скульптура','гостеприимство']::text[], false, false, false, 80, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-236', 'dagger-dance', '{"ru": "Танец с кинжалами", "en": "Dagger Dance"}'::jsonb, 'culture'::poi_category, 'art-object', NULL, '{"lat": 42.8712, "lng": 43.9577, "address": {"ru": "Селение Верхний Згид, Северная Осетия", "en": "Upper Zgid village, North Ossetia"}}'::jsonb, '{"short": {"ru": "Скульптура джигита, исполняющего традиционный осетинский танец с кинжалами — дань воинской культуре горного народа.", "en": "Sculpture of a horseman performing the traditional Ossetian dagger dance — a tribute to the warrior culture of the mountain people."}, "medium": {"ru": "Танец с кинжалами был распространён в Осетии до конца XIX века и отражал воинскую доблесть горца. Скульптура в селении Верхний Згид — в одном из самых отдалённых ущелий республики — воссоздаёт этот образ: фигура в динамике, кинжалы подняты, как на пике танца.", "en": "The dagger dance was practiced in Ossetia until the late 19th century, expressing the martial valor of mountain warriors. The sculpture in the remote village of Upper Zgid captures this image: a figure in motion, daggers raised at the peak of the dance."}, "full": {"ru": "Арт-объект «Танец с кинжалами» установлен в Садонском ущелье, у селения Верхний Згид — одного из наиболее труднодоступных населённых пунктов Северной Осетии. Добраться сюда непросто, что делает встречу со скульптурой особенно ценной для тех, кто преодолел дорогу.\n\nТанец с кинжалами — «карды кафт» — особый вид осетинского мужского танца, демонстрировавший ловкость, реакцию и бесстрашие воина. В отличие от парных танцев, этот исполнялся соло и нередко сопровождался реальными кинжалами. К концу XIX века традиция начала угасать, но в фольклорных коллективах её элементы сохранились до наших дней.\n\nМеталлическая фигура передаёт момент кульминации — когда тело и оружие слиты в единый порыв. На фоне суровых скал Садонского ущелья, где работали крупные свинцово-цинковые рудники, этот образ звучит особенно мощно: здесь жили люди, умевшие и трудиться, и воевать, и танцевать.", "en": "The \"Dagger Dance\" art object stands in Sadon Gorge, near the village of Upper Zgid — one of the most remote settlements in North Ossetia. The journey is not easy, which makes the encounter with the sculpture especially meaningful for those who make the trip.\n\nThe dagger dance — \"kardy kaft\" — was a special form of Ossetian men''s dance demonstrating a warrior''s agility, reflexes, and fearlessness. Unlike paired dances, it was performed solo and often with real daggers. By the late 19th century the tradition began fading, but elements were preserved in folk ensembles to this day.\n\nThe metal figure captures the climactic moment — when body and weapon merge in a single impulse. Against the severe cliffs of Sadon Gorge, where major lead-zinc mines once operated, this image resonates with particular power: here lived people who knew how to labor, fight, and dance."}}'::jsonb, ARRAY['/images/pois/dagger-dance_gp.webp','/images/pois/dagger-dance_2.webp','/images/pois/dagger-dance_3.webp','/images/pois/dagger-dance_4.webp','/images/pois/dagger-dance_5.webp','/images/pois/dagger-dance_6.webp']::text[], 4.6, NULL, NULL, NULL, NULL, ARRAY['арт-объект','танец','традиции','воинская культура','скульптура']::text[], false, false, false, 80, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-237', 'soslan-arrows', '{"ru": "Стрелы Сослана", "en": "Arrows of Soslan"}'::jsonb, 'culture'::poi_category, 'art-object', NULL, '{"lat": 42.9807, "lng": 43.7767, "address": {"ru": "Село Мацута, Дигорское ущелье, Северная Осетия", "en": "Matsuta village, Digor Gorge, North Ossetia"}}'::jsonb, '{"short": {"ru": "Три исполинские металлические стрелы в горах Дигории — памятник нартскому герою Сослану и его неиссякаемой силе.", "en": "Three giant metal arrows in the mountains of Digoria — a monument to the Nart hero Soslan and his inexhaustible strength."}, "medium": {"ru": "Сослан — непобедимый герой нартского эпоса, чьи стрелы разили любого врага. Три металлические стрелы исполинского размера у села Мацута стоят как напоминание о мощи нартов — легендарных предков осетин. Дигорское ущелье — одно из красивейших в республике с живописными водопадами и средневековыми башнями.", "en": "Soslan is the invincible hero of the Nart epic, whose arrows struck down any foe. Three giant metal arrows near Matsuta village stand as a reminder of the power of the Narts — the legendary ancestors of the Ossetians. Digor Gorge is one of the most scenic in the republic, with picturesque waterfalls and medieval towers."}, "full": {"ru": "Арт-объект «Стрелы Сослана» находится в Дигорском ущелье — одном из самых живописных и относительно малоизвестных мест Северной Осетии. Три огромные металлические стрелы, вонзённые в землю рядом с селом Мацута, отсылают к нартскому герою Сослану.\n\nВ осетинском эпосе Сослан обладал оружием, перед которым не устоять ни смертному, ни существу иного мира. Его стрелы летели туда, куда он посылал их мысленно, и никогда не возвращались без добычи. Образ трёх стрел — это и мощь, и точность, и неотвратимость.\n\nДигорское ущелье, где стоит объект, — особый мир: здесь живут дигорцы, говорящие на дигорском диалекте осетинского языка, и сохранились уникальные средневековые родовые башни. Рядом — Задалеск, Ханаз, Дунта. Природа ущелья поражает: альпийские луга, бурные реки, водопады и хребты, уходящие за 3000 метров.", "en": "The \"Arrows of Soslan\" art object stands in Digor Gorge — one of the most scenic and relatively little-known places in North Ossetia. Three massive metal arrows thrust into the earth near Matsuta village reference the Nart hero Soslan.\n\nIn the Ossetian epic, Soslan possessed weapons that no mortal or otherworldly creature could withstand. His arrows flew wherever he directed them in thought and never returned without prey. The image of three arrows conveys power, precision, and inevitability.\n\nDigor Gorge, where the object stands, is a world apart: here live the Digorians, speakers of the Digor dialect of Ossetian, and unique medieval clan towers have survived. Nearby are Zadaleskh, Khanaz, and Dunta. The gorge''s nature is extraordinary: alpine meadows, rushing rivers, waterfalls, and ridges reaching beyond 3,000 meters."}}'::jsonb, ARRAY['/images/pois/soslan-arrows_gp.webp','/images/pois/soslan-arrows_2.webp','/images/pois/soslan-arrows_3.webp','/images/pois/soslan-arrows_4.webp']::text[], 4.7, NULL, NULL, NULL, NULL, ARRAY['арт-объект','нарты','Сослан','Дигория','скульптура']::text[], false, false, false, 80, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-239', 'khsisin-fandir', '{"ru": "Хъисын фандыр", "en": "Khsisin Fandir"}'::jsonb, 'culture'::poi_category, 'art-object', NULL, '{"lat": 42.9225, "lng": 43.8367, "address": {"ru": "У Галиатского водопада, Дигорское ущелье, Северная Осетия", "en": "Near Galiat Waterfall, Digor Gorge, North Ossetia"}}'::jsonb, '{"short": {"ru": "Пятиметровая скульптура хъисын фандыра — традиционного осетинского смычкового инструмента, предка скрипки и балалайки.", "en": "A five-meter sculpture of the khsisin fandir — the traditional Ossetian bowed instrument, ancestor of the violin and balalaika."}, "medium": {"ru": "Хъисын фандыр — старинный осетинский струнный инструмент со смычком, на котором пели нартские сказания. Одни исследователи считают его предком скрипки, другие — балалайки. Пятиметровая металлическая скульптура стоит у Галиатского водопада в Дигорском ущелье, воспевая музыкальное наследие осетинского народа.", "en": "The khsisin fandir is an ancient Ossetian bowed string instrument used to sing the Nart sagas. Some scholars consider it an ancestor of the violin, others of the balalaika. The five-meter metal sculpture stands near Galiat Waterfall in Digor Gorge, celebrating the musical heritage of the Ossetian people."}, "full": {"ru": "Арт-объект «Хъисын фандыр» посвящён одному из старейших музыкальных инструментов Кавказа. Хъисын фандыр — смычковый инструмент с двумя-тремя струнами из конского волоса — использовался осетинскими сказителями для исполнения нартских эпических песен. Историки музыки прослеживают его родство с европейскими смычковыми и центральноазиатскими инструментами, что говорит о древних культурных связях осетин.\n\nПятиметровая скульптура установлена рядом с Галиатским водопадом — живописным многоступенчатым каскадом в Дигорском ущелье. Шум воды создаёт естественный акустический фон для немого инструмента, зафиксированного в металле. В тёплое время года здесь устраивают музыкальные перформансы и этнофестивали.\n\nГалиат — старинное осетинское село, сохранившее средневековые башни и склепы. Вместе с арт-объектом это место превращается в точку пересечения прошлого и настоящего: древние камни, живая вода водопада и современная скульптура говорят об одном — о неразрывной связи осетинской культуры с этой землёй.", "en": "The \"Khsisin Fandir\" art object is dedicated to one of the oldest musical instruments of the Caucasus. The khsisin fandir — a bowed instrument with two or three horsehair strings — was used by Ossetian storytellers to perform Nart epic songs. Music historians trace its kinship with European bowed instruments and Central Asian instruments, pointing to the Ossetians'' ancient cultural connections.\n\nThe five-meter sculpture stands beside Galiat Waterfall — a picturesque multi-tiered cascade in Digor Gorge. The sound of water creates a natural acoustic backdrop for the silent instrument frozen in metal. In warm months, musical performances and ethnofestivals are held here.\n\nGaliat is an ancient Ossetian village that has preserved medieval towers and crypts. Together with the art object, this place becomes a crossing point of past and present: ancient stones, living waterfall water, and a modern sculpture all speak of one thing — the unbreakable bond of Ossetian culture with this land."}}'::jsonb, ARRAY['/images/pois/khsisin-fandir_gp.webp','/images/pois/khsisin-fandir_2.webp','/images/pois/khsisin-fandir_3.webp','/images/pois/khsisin-fandir_4.webp','/images/pois/khsisin-fandir_5.webp','/images/pois/khsisin-fandir_6.webp']::text[], 4.8, NULL, NULL, NULL, NULL, ARRAY['арт-объект','музыка','нарты','инструмент','Дигория']::text[], false, false, false, 80, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-240', 'park-narton', '{"ru": "Парк Нартон", "en": "Narton Park"}'::jsonb, 'attractions'::poi_category, 'park', NULL, '{"lat": 43.028, "lng": 44.685, "address": {"ru": "Промышленный район, Владикавказ", "en": "Promyshlenny district, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Городской парк с аллеей нартских скульптур — персонажей осетинского героического эпоса.", "en": "City park featuring an alley of Nart sculptures — characters from the Ossetian heroic epic."}, "medium": {"ru": "Парк Нартон — тихое зелёное место в Промышленном районе Владикавказа. Главная достопримечательность — аллея с фигурами нартских героев: Сосланом, Батрадзом, Сырдоном и другими персонажами осетинского эпоса. Нарты — мифические богатыри, чьи подвиги тысячелетиями передавались в песнях и сказаниях.", "en": "Narton Park is a quiet green space in the Promyshlenny district of Vladikavkaz. Its main attraction is an alley of Nart hero figures: Soslan, Batradz, Syrdon and other characters from the Ossetian epic. The Narts are mythical warriors whose feats have been passed down in songs and tales for millennia."}, "full": {"ru": "Парк Нартон назван в честь нартов — мифических героев кавказского эпоса, широко распространённого у осетин, чеченцев, абхазов и других народов. Центральный элемент парка — аллея скульптур, изображающих нартских богатырей. Среди них — Сослан Железнорождённый, закалённый в волчьем молоке; Батрадз, выкованный из стали; мудрый и хитрый Сырдон. Скульптуры сочетают монументальность советского искусства с образами древней мифологии.\n\nПарк — популярное место для прогулок жителей Промышленного района. Аллея нартов превращает обычный городской сквер в открытый музей под открытым небом, где мифология буквально стоит вдоль тропинки. Дети любят рассматривать каменных великанов, взрослые — фотографироваться рядом.\n\nДля туриста это место интересно как живое воплощение осетинской идентичности: нартский эпос здесь не книжное явление, а часть городского пространства. Приходить лучше в утреннее время или вечером — тогда скульптуры особенно красиво смотрятся в свете солнца.", "en": "Narton Park is named after the Narts — mythical heroes of the Caucasian epic, widely spread among Ossetians, Chechens, Abkhazians and other peoples. The park''s centerpiece is an alley of sculptures depicting Nart warriors. Among them: Soslan the Iron-born, tempered in wolf''s milk; Batradz, forged from steel; and the wise, cunning Syrdon. The sculptures combine the monumentality of Soviet art with images from ancient mythology.\n\nThe park is a popular walking spot for residents of the Promyshlenny district. The Nart alley turns an ordinary city square into an open-air museum where mythology literally lines the footpath. Children love to study the stone giants; adults come to photograph them.\n\nFor tourists, this place is interesting as a living embodiment of Ossetian identity: the Nart epic here is not a literary phenomenon but part of urban space. Best visited in the morning or evening, when the sculptures look especially striking in the sun''s light."}}'::jsonb, ARRAY['/images/pois/park-narton_gp.webp','/images/pois/park-narton_2.webp','/images/pois/park-narton_3.webp','/images/pois/park-narton_4.webp','/images/pois/park-narton_5.webp','/images/pois/park-narton_6.webp','/images/pois/park-narton_7.webp','/images/pois/park-narton_8.webp','/images/pois/park-narton_9.webp','/images/pois/park-narton_10.webp']::text[], 4.4, '{"mon": "08:00-22:00", "tue": "08:00-22:00", "wed": "08:00-22:00", "thu": "08:00-22:00", "fri": "08:00-22:00", "sat": "08:00-22:00", "sun": "08:00-22:00"}'::jsonb, NULL, NULL, NULL, ARRAY['парк','нарты','скульптуры','прогулка','культура']::text[], false, false, false, 100, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-315', 'karmadonskie-termalnye-vanny-verhnie', '{"ru": "Кармадонские термальные ванны верхние", "en": "Karmadon Upper Hot Pools"}'::jsonb, 'nature'::poi_category, 'springs', NULL, '{"lat": 42.7519, "lng": 44.4801, "address": {"ru": "Кармадонское ущелье, Респ. Северная Осетия — Алания", "en": "Karmadon Gorge, North Ossetia, Russia"}}'::jsonb, '{"short": {"ru": "Верхние горячие термальные бассейны в Кармадонском ущелье с температурой воды +42°C.", "en": "Upper hot thermal pools in Karmadon Gorge, water temperature +42°C year-round."}, "medium": {"ru": "Верхние горячие термальные бассейны в Кармадонском (Геналдонском) ущелье. Расположены выше по ущелью, в более диком и уединённом месте. Температура воды +42°C круглый год. Окружены горными скалами и нетронутой природой Северной Осетии.", "en": "Upper hot thermal pools in Karmadon (Genaldon) Gorge, set higher up in a wilder, more secluded location. Water temperature stays at +42°C year-round amid mountain cliffs and pristine North Ossetian nature."}, "full": {"ru": "Верхние горячие термальные бассейны в Кармадонском (Геналдонском) ущелье. Расположены выше по ущелью, в более диком и уединённом месте — меньше туристов, больше тишины. Температура воды +42°C круглый год. Окружены вертикальными горными скалами и нетронутой природой Северной Осетии. После трагедии 2002 года, когда сошёл ледник Колка, ущелье было закрыто на долгие годы, но сейчас снова открыто и становится всё популярнее.", "en": "Upper hot thermal pools in Karmadon (Genaldon) Gorge, set higher up in a wilder, more secluded location with fewer visitors. Water temperature stays at +42°C year-round, surrounded by vertical mountain cliffs and pristine Ossetian wilderness. The gorge was closed for years after the 2002 Kolka glacier disaster but has since reopened and is gaining popularity."}}'::jsonb, ARRAY['/images/pois/karmadonskie-termalnye-vanny-verhnie_gp.webp','/images/pois/karmadonskie-termalnye-vanny-verhnie_2.webp','/images/pois/karmadonskie-termalnye-vanny-verhnie_3.webp','/images/pois/karmadonskie-termalnye-vanny-verhnie_4.webp']::text[], 4.8, NULL, NULL, NULL, NULL, ARRAY['nature']::text[], false, false, false, 400, 0, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-316', 'karmadonskie-termalnye-vanny-nizhnie', '{"ru": "Кармадонские термальные ванны нижние", "en": "Karmadon Lower Hot Pools"}'::jsonb, 'nature'::poi_category, 'springs', NULL, '{"lat": 42.7547, "lng": 44.4813, "address": {"ru": "Кармадонское ущелье, Респ. Северная Осетия — Алания", "en": "Karmadon Gorge, North Ossetia, Russia"}}'::jsonb, '{"short": {"ru": "Нижние горячие термальные бассейны в Кармадонском ущелье с температурой воды +42°C.", "en": "Lower hot thermal pools in Karmadon Gorge, water temperature +42°C year-round."}, "medium": {"ru": "Нижние горячие термальные бассейны в Кармадонском (Геналдонском) ущелье. Ближайшие к входу в ущелье и наиболее популярные среди туристов. Температура воды +42°C круглый год. Название «Кармадон» в переводе с осетинского означает «горячая вода».", "en": "Lower hot thermal pools in Karmadon (Genaldon) Gorge, closest to the gorge entrance and most popular with visitors. Water temperature stays at +42°C year-round. ''Karmadon'' translates from Ossetian as ''hot water''."}, "full": {"ru": "Нижние горячие термальные бассейны в Кармадонском (Геналдонском) ущелье. Ближайшие к входу и самые посещаемые. Температура воды +42°C круглый год — природный термальный источник без нагревателей. Название «Кармадон» в переводе с осетинского означает «горячая вода». Бассейны под открытым небом окружены горным пейзажем. После трагедии 2002 года, когда сошёл ледник Колка, ущелье было закрыто, но сейчас снова открыто и набирает популярность.", "en": "Lower hot thermal pools in Karmadon (Genaldon) Gorge, closest to the gorge entrance and most visited. Water temperature stays at +42°C year-round thanks to natural thermal springs. ''Karmadon'' translates from Ossetian as ''hot water''. Open-air pools surrounded by mountain scenery. The gorge was closed after the 2002 Kolka glacier disaster but has since reopened and is gaining popularity."}}'::jsonb, ARRAY['/images/pois/karmadonskie-termalnye-vanny-nizhnie_gp.webp','/images/pois/karmadonskie-termalnye-vanny-nizhnie_2.webp']::text[], 4.8, NULL, NULL, NULL, NULL, ARRAY['nature']::text[], false, false, false, 400, 26, 'free'::subscription_tier, 316);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-317', 'bruges', '{"ru": "Bruges", "en": "Bruges"}'::jsonb, 'food'::poi_category, 'bar', 'european'::cuisine_type, '{"lat": 43.0465108, "lng": 44.6596538, "address": {"ru": "ул. Кесаева, 154, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362020", "en": "K. Kesaeva St. 154, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Бельгийский паб в настоящем каменном замке на холме. Живое пиво, медные трубы, кирпичные своды.", "en": "Belgian pub in a real stone castle on a hill. Live beer, copper pipes, brick vaults."}, "medium": {"ru": "Бельгийский паб в каменном замке с видом на город. Пивоварня прямо в зале, богатая карта крафтового и бельгийского пива. Кухня европейская: тартары, брускеты, мясо на гриле. Открылся в 2020 году, входит в Bavaria Group.", "en": "Belgian pub in a stone castle overlooking the city. In-house brewery right in the hall, wide selection of craft and Belgian beer. European menu: tartares, bruschetta, grilled meat. Opened in 2020, part of Bavaria Group."}, "full": {"ru": "«Bruges» — это тот самый каменный замок на холме, который видно из разных точек города. Внутри — настоящий бельгийский паб: кирпич, медные трубы, пивные краны, антиквариат на стенах и пивоварня прямо в зале. Открылся в 2020 году как часть Bavaria Group — тех же, кто варит пиво в «Баварии». Карта пива широкая: бельгийские сорта, крафт, собственное производство. Еда — европейские закуски и горячее: тартар из говядины, брускеты с разными начинками, мясо на гриле. Два этажа, несколько залов с разным настроением. Атмосфера нескучная — особенно вечером.", "en": "Bruges is that stone castle on the hill you can see from different parts of the city. Inside — a proper Belgian pub: brick, copper pipes, beer taps, antiques on the walls, and a brewery right in the main hall. Opened in 2020 as part of Bavaria Group — the same people behind the Bavaria brewery. Wide beer menu: Belgian varieties, craft, house-brewed. Food is European snacks and mains: beef tartare, bruschetta with various toppings, grilled meat. Two floors, several rooms with different moods. The atmosphere is anything but dull — especially in the evenings."}}'::jsonb, ARRAY['/images/pois/bruges_9.webp','/images/pois/bruges_1.webp','/images/pois/bruges_2.webp','/images/pois/bruges_4.webp','/images/pois/bruges_3.webp','/images/pois/bruges_5.webp','/images/pois/bruges_6.webp','/images/pois/bruges_7.webp','/images/pois/bruges_8.webp','/images/pois/bruges_13.webp','/images/pois/bruges_10.webp','/images/pois/bruges_11.webp','/images/pois/bruges_12.webp','/images/pois/bruges_14.webp']::text[], 3.7, '{"sun": "12:00-00:00", "mon": "12:00-00:00", "tue": "12:00-00:00", "wed": "12:00-00:00", "thu": "12:00-00:00", "fri": "12:00-00:00", "sat": "12:00-00:00"}'::jsonb, '+7 (867) 251-38-38', 'https://bavaria-group.ru/service/bruges', 2, ARRAY['пиво','бельгийская кухня','европейская кухня','крафт','замок']::text[], false, true, false, 50, 24, 'free'::subscription_tier, 0);
INSERT INTO pois (id, slug, name, category, subcategory, cuisine_type, location, description, photos, rating, hours, phone, website, price_level, tags, is_chain, has_menu, has_delivery, radius, review_count, subscription_tier, visit_count) VALUES ('poi-318', 'hostel-baltson', '{"ru": "Хостел Baltson", "en": "Baltson Hostel"}'::jsonb, 'accommodation'::poi_category, 'Хостел', NULL, '{"lat": 43.047639, "lng": 44.621277, "address": {"ru": "ул. Генерала Дзусова, 42, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362045", "en": "9 Zarya Lane, Vladikavkaz"}}'::jsonb, '{"short": {"ru": "Капсульный хостел в центре Владикавказа — чисто, безопасно, от 600 ₽ за капсулу.", "en": "A capsule hostel in central Vladikavkaz — clean, secure, from 600 RUB per capsule."}, "medium": {"ru": "Baltson — современный капсульный хостел в центре Владикавказа. Личные локеры, стирка, Wi-Fi, круглосуточная стойка. Капсулы от 600 ₽ в сутки.", "en": "Baltson is a modern capsule hostel in central Vladikavkaz. Personal lockers, laundry, Wi-Fi, 24-hour front desk. Capsules from 600 RUB per night."}, "full": {"ru": "Хостел Baltson — капсульный хостел в центре Владикавказа на улице Генерала Дзусова. Вместительные капсулы, личные ящики для хранения вещей, Wi-Fi, стиральная машина, уютная лаундж-зона и круглосуточная стойка регистрации. Персонал помогает с организацией экскурсий и такси. Рейтинг 9.7 на Booking.com. Капсулы от 600 ₽ в сутки.", "en": "Baltson Hostel is a capsule hostel in the center of Vladikavkaz on Generala Dzusova Street. Roomy capsules, personal storage lockers, Wi-Fi, washing machine, a cozy lounge area, and 24-hour reception. Staff assist with excursions and taxi. Rated 9.7 on Booking.com. Capsules from 600 RUB per night."}}'::jsonb, ARRAY['/images/pois/hostel-baltson_facade.webp','/images/pois/hostel-baltson_1.webp','/images/pois/hostel-baltson_2.webp','/images/pois/hostel-baltson_3.webp','/images/pois/hostel-baltson_4.webp','/images/pois/hostel-baltson_5.webp','/images/pois/hostel-baltson_6.webp','/images/pois/hostel-baltson_7.webp','/images/pois/hostel-baltson_8.webp']::text[], 4.9, '{"mon": "00:00-23:59", "tue": "00:00-23:59", "wed": "00:00-23:59", "thu": "00:00-23:59", "fri": "00:00-23:59", "sat": "00:00-23:59", "sun": "00:00-23:59"}'::jsonb, '+7 989 743-67-36', 'https://www.hostel-baltson.ru/', 1, ARRAY['хостел','капсульный','центр','локеры','бюджетно']::text[], false, false, false, 80, 52, 'free'::subscription_tier, 2800);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-851', 'poi'::review_target_type, 'poi-070', 'Вобла', 5.0, 'Кафе с уютным интерьером и наивкуснейшей кухней. Осетинские пироги просто отличные, порции большие, персонал приветливый. Живая музыка создаёт атмосферу, хотя немного громковато.', '2023-11-15'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-852', 'poi'::review_target_type, 'poi-070', 'Путешественник из Москвы', 4.0, 'Самый национальный ресторан во Владикавказе. Национальные костюмы для фото, живая музыка, вкуснейшая осетинская кухня. Рекомендую обязательно посетить — здесь чувствуется настоящая Осетия.', '2022-08-03'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-853', 'poi'::review_target_type, 'poi-071', 'Вобла', 5.0, 'Ещё с советских времён кафе известно своими невероятно вкусными осетинскими мини-пирогами с мясом. Долгие годы держат марку — место, где самые вкусные фыдджынта в Осетии.', '2023-12-08'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-854', 'poi'::review_target_type, 'poi-071', 'Алексей К.', 5.0, 'Первым делом, как приезжаю во Владикавказ — только сюда! Сытный обед на троих с напитками выходит около 500 рублей. Персонал приветливый и расторопный, атмосфера домашняя.', '2024-03-17'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-855', 'poi'::review_target_type, 'poi-072', 'Татьяна Мазаева', 5.0, 'Остались очень довольны, что сегодня пришли ещё раз. Вежливый персонал, быстрая подача и очень вкусная еда. Замечательный ресторан с замечательным обслуживанием.', '2022-06-10'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-856', 'poi'::review_target_type, 'poi-072', 'Александр Кириллов', 5.0, 'Осетинские пироги с сыром сочные, много сыра, тянется. Чанахи, шашлык из печени и баклажаны с пхали — всё на высоте. Подача — супер!', '2022-04-22'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-857', 'poi'::review_target_type, 'poi-072', 'Nadi Kremen', 5.0, 'Отличное место. Мы впервые во Владикавказе и пока это лучшее место. Разнообразное меню, всё очень вкусно приготовлено.', '2022-03-05'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-858', 'poi'::review_target_type, 'poi-073', 'Олеся Третьякова', 5.0, 'Очень вкусно! Обедали там два раза. Все блюда вкусные.', '2022-07-14'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-859', 'poi'::review_target_type, 'poi-073', 'Vladimir Kurbatov', 5.0, 'По вкусу это настоящие 5 баллов. Я давно не ел такой вкусный шашлык. Шашлык хорошо прожаренный, но сочный. Рекомендую шашлык и картофель.', '2022-05-30'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-860', 'poi'::review_target_type, 'poi-073', 'Настя Иванова', 5.0, 'Просто невероятно вкусно! Пироги с ботвой нереальные, а шурпа — самая вкусная, что я пробовала. Атмосфера уютная, персонал чудесный.', '2022-04-18'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-864', 'poi'::review_target_type, 'poi-076', 'Сергей Сергеев', 5.0, 'Отличная кухня! Лучший шашлык и пироги! Красивый и очень уютный ресторан со своей атмосферой, колоритом и настроением. Обязательно приду ещё.', '2023-07-22'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-865', 'poi'::review_target_type, 'poi-076', 'Ольга Корженко', 5.0, 'Божественно прекрасное место! Красиво и очень вкусно. Ресторан расположен в здании исторической мельницы — это добавляет особый шарм. Персонал вежливый.', '2023-04-05'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-866', 'poi'::review_target_type, 'poi-076', 'Алексей', 5.0, 'Всё очень понравилось. Персонал вежливый, кухня на высоте. Осетинский пирог с мясом очень вкусный и сочный, обслуживание на высоте.', '2022-11-30'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-867', 'poi'::review_target_type, 'poi-077', 'Ilya Karnaukhov', 5.0, 'Стильное оформление, большой выбор национальных блюд, вкусно, цены умеренные. Готовят одни из самых вкусных осетинских пирогов, подают по осетинским обычаям.', '2022-08-19'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-868', 'poi'::review_target_type, 'poi-077', 'ZaurbeK', 5.0, 'Очень вкусно и хорошая атмосфера. Яблочный чай отличный — всем советую. Персонал расторопный и активный. Место красивое, интерьеры стильные.', '2022-06-12'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-869', 'poi'::review_target_type, 'poi-077', 'Ксения', 3.0, 'Место красивое, стильные интерьеры. Качество еды хорошее, но обслуживание стало очень плохое — долго ждать официантов.', '2022-07-04'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-870', 'poi'::review_target_type, 'poi-078', 'Дмитрий Кривошеев', 5.0, 'Вкусно, красиво, уютно, цены доступные. Лучшее место для отдыха и приятных встреч. Хинкали за 60 рублей — отлично для Владикавказа.', '2023-10-08'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-871', 'poi'::review_target_type, 'poi-078', 'Анастасия Бабурина', 5.0, 'Самые вкусные осетинские пироги во Владикавказе! Если хотите попробовать кавказскую кухню — только сюда. Каждый раз, когда приезжаем во Владикавказ, сразу идём в Lookoom.', '2024-02-14'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-872', 'poi'::review_target_type, 'poi-078', 'etonasya', 5.0, 'Если хотите попробовать кавказскую кухню во Владикавказе — только сюда! Отличный выбор блюд, демократичные цены, можно попробовать лучшую баранину в городе.', '2022-05-04'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-873', 'poi'::review_target_type, 'poi-079', 'Аслан Гудиев', 5.0, 'Шикарный персонал, уютная обстановка, сказочная кухня. Паста с морепродуктами — нежный соус, свежие хорошо приготовленные морепродукты. Пиво из собственной пивоварни отличное.', '2023-08-05'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-874', 'poi'::review_target_type, 'poi-079', 'Виктор Могилевский', 5.0, 'Всё очень вкусно, классная и негромкая музыка. Официанты приветливые. Интерьер интересный, есть живая музыка и спортивные трансляции.', '2023-03-21'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-875', 'poi'::review_target_type, 'poi-317', 'Лена Лен', 5.0, 'Уникальное место с отличной атмосферой, персоналом, блюдами и пивом. Особенно понравился говяжий карпаччо. Большой выбор пива, интересный интерьер, прекрасное расположение на набережной.', '2023-11-02'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-876', 'poi'::review_target_type, 'poi-317', 'Рустам Макаев', 5.0, 'Ходим специально за пивом и закусками. Огромный ассортимент пива, интересный интерьер. Ребрышки, колбаски и бельгийские вафли — отличный выбор.', '2023-09-15'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-877', 'poi'::review_target_type, 'poi-317', 'Екатерина Софорова', 5.0, 'Завтраки очень вкусные и сытные. Хорошее обслуживание, приятная обстановка.', '2023-06-28'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-878', 'poi'::review_target_type, 'poi-081', 'Артем Перминов', 5.0, 'Самое вкусное пиво во Владикавказе и очень вкусная кухня. Пирог с сыром и листьями свёклы восхитителен! Цены доступные, принимают только наличные — имейте в виду.', '2022-09-14'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-879', 'poi'::review_target_type, 'poi-081', 'Roman Pozdny', 5.0, 'Классная пивоварня. Различные сорта пива. Отличное обслуживание. Атмосферно, шумно и весело. Рекомендую бронировать стол заранее — место популярное.', '2023-01-07'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-880', 'poi'::review_target_type, 'poi-081', 'Chester Be', 5.0, 'Отличная кухня, вкусное пиво и прекрасный отзывчивый персонал. Одни из лучших пивных впечатлений во Владикавказе.', '2023-05-22'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-881', 'poi'::review_target_type, 'poi-082', 'София Зинченко', 5.0, 'Место обязательное к посещению! Лучшая паста с морепродуктами — очень рекомендую. Приятный интерьер и приветливое обслуживание. Цены средние.', '2022-08-05'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-882', 'poi'::review_target_type, 'poi-082', 'Юрий С.', 5.0, 'Отличное заведение, вежливый персонал, отличная вкусная кухня. Ценник более чем демократичный. Приехали из Краснодара — весь отпуск питались в этом ресторане!', '2022-07-19'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-883', 'poi'::review_target_type, 'poi-082', 'Ольга Эграмир', 5.0, 'Очень понравилось данное заведение! Приятный, добросовестный персонал. Очень вкусные блюда. Обслуживание превзошло все ожидания — официанты были невероятно внимательны.', '2023-04-11'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-887', 'poi'::review_target_type, 'poi-084', 'Дмитрий Бугай', 5.0, 'Хачапури бомба! Шашлык просто космос! Моя оценка 10 из 10. Всегда вкусно, всегда свежо.', '2024-01-09'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-888', 'poi'::review_target_type, 'poi-084', 'Евгения Пантелеева', 5.0, 'Самый вкусный кебаб из говядины и шашлык из баранины. Вкусно, много, вежливо, красиво. Лучший шашлык в моей жизни! Жемчужина Владикавказа.', '2022-09-20'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-889', 'poi'::review_target_type, 'poi-084', 'Ксюша Г.', 5.0, 'Остались очень довольны. Вкусная еда, напитки. Хороший шашлык и пироги. Обслуживание на уровне, персонал внимательный.', '2023-06-14'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-890', 'poi'::review_target_type, 'poi-085', 'Why Not', 5.0, 'Безумно вкусно! Пирог фыджин превзошёл все ожидания. Пиво хорошее, атмосфера приятная. Лучшее место во Владикавказе — справедливые цены.', '2023-12-03'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-891', 'poi'::review_target_type, 'poi-085', 'Евгения Аксёнова', 5.0, 'Очень вкусные пироги, супы и пиво. Большие порции, быстрое обслуживание. Ресторан со своей пивоварней — пиво свежее и ароматное.', '2023-08-17'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-892', 'poi'::review_target_type, 'poi-085', 'Сослан Козаев', 5.0, 'Одно из любимых мест. Вкусная еда, хорошие цены, уютная обстановка. Национальная кухня и хорошее местное пиво — сочетание отличное.', '2023-05-08'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-919', 'poi'::review_target_type, 'poi-087', 'Сергей Дмитриевич Мармоленко', 5.0, 'Лучший ресторан осетинской кухни во Владикавказе. Максимально идеальные пироги.', '2023-11-19'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-920', 'poi'::review_target_type, 'poi-087', 'Валентина Галдобина', 5.0, 'Кухня как всегда на высоте, очень понравились цыплята тапака.', '2022-09-10'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-921', 'poi'::review_target_type, 'poi-087', 'Ирина Бутова', 5.0, 'Быстрое обслуживание, вкусные блюда, свежие продукты, приветливый персонал.', '2023-06-15'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-927', 'poi'::review_target_type, 'poi-090', 'Мариям', 5.0, 'Это безумно атмосферное и вкусное место!', '2025-06-29'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-928', 'poi'::review_target_type, 'poi-090', 'Зарина', 5.0, 'Люблю кофе в этой кофейне, причём разные вкусы! Мне подходит.', '2024-12-03'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-929', 'poi'::review_target_type, 'poi-090', 'Сергей', 5.0, 'Лучший кофе в городе!!!', '2024-11-30'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-930', 'poi'::review_target_type, 'poi-091', 'Кристина Цховребова', 5.0, 'Самый вкусный кофе — не только во Владикавказе, но и вкуснее многих московских кофеен. Раф с малиной — очень, очень вкусный, просто отличный! Цены приятно удивляют.', '2023-12-10'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-931', 'poi'::review_target_type, 'poi-092', 'Анна Р.', 5.0, 'Каждый раз, посещая Владикавказ, иду выпить кофе в Горку. Раф Бэлла с малиной — отдельная любовь. Мороженое в креманках — фирменное блюдо заведения.', '2024-07-15'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-932', 'poi'::review_target_type, 'poi-092', 'Михаил Т.', 4.0, 'Красивый расписанный потолок, живая музыка, цветы в вазочках. Снаружи уютно сидеть с фонариками. Персонал радушный и улыбчивый.', '2024-05-20'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-938', 'poi'::review_target_type, 'poi-095', 'МВ Виктория', 4.0, 'Как же тут красиво! Домики стоят вдоль горной речки. Обедаете под шум воды и наслаждаетесь прекрасным видом гор. Вкусная уха, пироги, шашлык и компот из кизила — просто отлично!', '2023-10-06'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-939', 'poi'::review_target_type, 'poi-095', 'Ирина П.', 5.0, 'Отличный шашлык! Пироги — самые вкусные! Обслуживание на высшем уровне, вид на горную реку завораживает.', '2023-07-14'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-940', 'poi'::review_target_type, 'poi-096', 'Анастасия Д.', 4.0, 'Уютный интерьер, гостеприимный персонал. Все блюда, которые мы заказали, были вкусными и красиво оформлены. Порции большие, цены ниже, чем в других местах.', '2024-03-18'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-941', 'poi'::review_target_type, 'poi-098', 'Роман М.', 5.0, 'Любимое заведение. Мне там уютно и комфортно, хоть и фастфуд-формат. Атмосфера особенная.', '2023-09-05'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-942', 'poi'::review_target_type, 'poi-098', 'Вадим К.', 5.0, 'Вкусный бургер, шаурма тоже достойная. Рекомендую!', '2023-11-12'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-943', 'poi'::review_target_type, 'poi-098', 'Тотрбек С.', 5.0, 'Один из лучших бургеров в городе, картошечка замечательная. Цены не кусаются, обслуживание быстрое.', '2023-08-30'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-946', 'poi'::review_target_type, 'poi-123', 'Марина Т.', 3.0, 'Место работает до позднего. Заведение на любителя — тусовочная атмосфера, громкая музыка. Для весёлой компании подойдёт.', '2024-01-20'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-948', 'poi'::review_target_type, 'poi-125', 'Алексей В.', 2.0, 'Меню заявлено, но по факту почти ничего нет. Цены высокие. Видно, что посетителей мало.', '2023-11-08'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-987', 'poi'::review_target_type, 'poi-126', 'Неля', 5.0, 'Пришли по отзывам посетителей. Всё очень вкусно, обслуживание прекрасное, вид ещё лучше.', '2024-08-15'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-988', 'poi'::review_target_type, 'poi-126', 'Alan Kesaev', 5.0, 'Отличный ресторан, всё вкусно. Пироги очень вкусные. Официанты тоже порадовали.', '2024-06-20'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-989', 'poi'::review_target_type, 'poi-126', 'Влад Кудинов', 4.0, 'Очень приятное первое впечатление, вкусный чай и сибас. Чистый туалет, обслуживание гостеприимное.', '2024-05-10'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-990', 'poi'::review_target_type, 'poi-147', 'Yury Ars', 4.0, 'Всё здорово, красиво, весело, много места, интересное оформление! Кухню можно подтянуть!', '2022-09-14'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-991', 'poi'::review_target_type, 'poi-147', 'Залина Гиоева', 5.0, 'Вкусно. Хорошая весёлая программа. Живая музыка. Приятная атмосфера.', '2022-07-03'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-992', 'poi'::review_target_type, 'poi-147', 'Alex Borz', 5.0, 'Приятное место отдыха. Внимательный доброжелательный персонал. Хороший повар.', '2022-05-22'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-993', 'poi'::review_target_type, 'poi-148', 'Жанна Салбиева', 4.0, 'Хорошее оформление ресторана. Кухня выше всяких похвал. Официанты молодцы.', '2022-11-08'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-994', 'poi'::review_target_type, 'poi-148', 'Gayane Sakeyan', 5.0, 'Замечательно, нам очень понравилось. Персонал вежливый, еда вкусная, живая музыка, певец классный.', '2021-08-30'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-995', 'poi'::review_target_type, 'poi-149', 'Казбек Газданов', 5.0, 'Быстрое обслуживание, вкусные блюда, свежие продукты, приветливый персонал, отличный кофе.', '2024-03-12'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-996', 'poi'::review_target_type, 'poi-149', 'Алина Нестеренко', 5.0, 'Самые вкусные блины во Владикавказе! Большой выбор начинок, достаточно большие порции.', '2024-01-25'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-997', 'poi'::review_target_type, 'poi-149', 'Андрей Морган', 5.0, 'Всегда есть народ. Уютно, вкусно, недорого! Открываются рано с 08 утра.', '2023-11-05'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-998', 'poi'::review_target_type, 'poi-150', 'Светлана Дудаева', 5.0, 'Мне понравился дизайн ресторана. Так же хотела бы отметить персонал — все приветливые и очень милые.', '2024-04-18'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-999', 'poi'::review_target_type, 'poi-150', 'Ника Нука', 5.0, 'Остались в восторге от качества приготовленных блюд! Грибной суп — просто объедение!', '2024-02-09'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1000', 'poi'::review_target_type, 'poi-150', 'Марат Туаев', 4.0, 'Отдыхали компанией в ресторане в зоне караоке. Хочется поблагодарить и отметить кухню и обслуживание.', '2023-12-14'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1010', 'poi'::review_target_type, 'poi-154', 'Anon Anon', 4.0, 'Осетинская кухня на достойном уровне. Пироги хорошие, порции большие.', '2024-05-14'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1011', 'poi'::review_target_type, 'poi-155', 'Лидия Жамукова', 5.0, 'Вкусно готовят, есть халяль блюда. Приятный персонал, качественное обслуживание.', '2024-10-08'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1012', 'poi'::review_target_type, 'poi-155', 'Jully Apple', 5.0, 'Абсолютно прекрасным этот завтрак сделала официантка Ксения — очень чуткая, приятная, добрая.', '2024-08-03'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1013', 'poi'::review_target_type, 'poi-155', 'Татьяна Александрова', 4.0, 'Блины вкусные, но блины с сёмгой были холодные — хотелось бы, чтобы их приносили горячими.', '2024-04-19'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1017', 'poi'::review_target_type, 'poi-100', 'Елена Любимова', 5.0, 'Отдых был чудесный! Спасибо всем сотрудникам отеля! И за завтраки и за отдых в номере. Особая благодарность водителю Владимиру за трансфер.', '2026-04-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1018', 'poi'::review_target_type, 'poi-100', 'Майя Н.', 5.0, 'Атмосферно. Самый центр, на улице с трамвайчиками, идеальная локация. Администраторы приветливые, знают что такое сервис и нормы гостеприимства, всё чётко.', '2026-04-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1019', 'poi'::review_target_type, 'poi-100', 'Ксения Барышева', 5.0, 'Отличная гостиница со своим интерьерным шармом. Администратор была очень дружелюбная и даже подарила бутылку местного сидра.', '2025-10-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1020', 'poi'::review_target_type, 'poi-100', 'Поджог Сараев', 3.0, 'Заселили в номер, но здесь не было горячей воды. Всё перепробовали, не помогло — переселили в другой. Под окнами заведение с громкой музыкой, но выключают в 23:00. Завтраки не супер, но покушать можно. Расположение — супер.', '2025-01-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1021', 'poi'::review_target_type, 'poi-102', 'Andrey', 5.0, 'Понравилось всё! Чистота, отношение, ненавязчивая роскошь, шикарная косметика, завтраки, самый центр города, парковка!', '2023-07-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1022', 'poi'::review_target_type, 'poi-102', 'Sergey', 5.0, 'Самый центр! При этом не было проблем с парковкой. Завтрак разнообразный и вкусный. Хороший номер, удобная кровать.', '2023-05-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1023', 'poi'::review_target_type, 'poi-102', 'Elena', 5.0, 'Прекрасное расположение, заселили раньше времени. Отличный номер, рекомендую!', '2023-09-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1024', 'poi'::review_target_type, 'poi-102', 'Aitalina', 5.0, 'Отель расположен на пешеходной улице в центре города. Рядом много магазинов. Хороший завтрак, удобная кровать и отличное обслуживание.', '2023-02-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1025', 'poi'::review_target_type, 'poi-102', 'Екатерина', 5.0, 'Номер был стандарт с панорамным видом на центральную улицу и горы. Фото на сайте полностью соответствуют действительности.', '2023-01-09'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1026', 'poi'::review_target_type, 'poi-103', 'Evgenii', 5.0, 'Отель в 200 метрах от ж/д вокзала с кафе и съедобными завтраками. До места сбора экскурсий можно вполне комфортно доехать на единственном в городе трамвае.', '2024-09-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1027', 'poi'::review_target_type, 'poi-103', 'Galina', 5.0, 'Персонал очень приветливый и готов оказать помощь по любым возникающим вопросам. Из недостатков — шум от транспорта при окнах на улицу.', '2026-04-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1028', 'poi'::review_target_type, 'poi-103', 'Inesa', 5.0, 'Чисто, уютно, очень доброжелательно. Дали много рекомендаций по городу и окрестностям.', '2024-05-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1029', 'poi'::review_target_type, 'poi-103', 'Elena', 5.0, 'Отель очень чистый, сотрудники все хорошие.', '2023-09-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1030', 'poi'::review_target_type, 'poi-105', 'Vladislav', 5.0, 'Очень удобное расположение, приличное здание, приветливый персонал. Рядом с вокзалом, удобно для транзита.', '2024-05-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1031', 'poi'::review_target_type, 'poi-221', 'Андрей Белоусов', 5.0, 'Отель находится в отличном месте, где открываются шикарные виды и оттуда можно никуда не выезжать. Персонал на высшем уровне. Спа-зона с бассейном, сауной и хамамом выше всяких похвал. Осетинские пироги в ресторане — просто огонь.', '2026-05-07'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1032', 'poi'::review_target_type, 'poi-221', 'Анна', 5.0, 'Идеальная чистота везде, очень хороший текстиль и фурнитура не только в номерах, но и в зоне СПА. Быстро отреагировали на замечания — сервис живой и внимательный.', '2026-05-09'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1033', 'poi'::review_target_type, 'poi-221', 'Alla', 5.0, 'Всё отлично. Были в межсезонье, людей мало. Завтрак супер.', '2025-10-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1034', 'poi'::review_target_type, 'poi-221', 'Регина', 5.0, 'Вид из окна открывался на живописные горы, что создавало особое настроение с самого утра. Персонал ресторана — просто отдельная благодарность, всё вкусно и душевно.', '2025-09-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1035', 'poi'::review_target_type, 'poi-222', 'Полина Тимофеева', 5.0, 'Супер отель! Виды потрясающие из любой точки в отеле. Высокий уровень сервиса, отзывчивый и очень внимательный персонал.', '2024-08-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1036', 'poi'::review_target_type, 'poi-222', 'Андрей Мошков', 5.0, 'Это один из лучших отелей на всём Северном Кавказе. Персонал ресторана — это не про работу «на чай», а работа с душой и забота о гостях.', '2024-07-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1037', 'poi'::review_target_type, 'poi-222', 'Татьяна Григорьева', 5.0, 'Провели невероятные выходные. Приветливые и дружелюбные сотрудники, чувствовали себя как дома. Спа-зона и бассейн с джакузи очень достойные.', '2024-06-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1038', 'poi'::review_target_type, 'poi-222', 'Маг Гад', 5.0, 'Ездим уже не первый год. Вкусная кухня! Персонал очень вежливый и заботливый! Терренкур сзади отеля — целый парк!', '2024-09-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1039', 'poi'::review_target_type, 'poi-222', 'Юлия Юркова', 5.0, 'Просто восторг! Шикарные виды, вкусная еда, приветливый персонал. Хорошие гели для душа и шампуни. И приятный запах во всём отеле.', '2024-05-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1040', 'poi'::review_target_type, 'poi-176', 'Иван Шумеев', 5.0, 'Всё очень на достойном уровне! Мне понравилось всё — кухня, обслуживание, обстановка! Отлично!', '2026-03-22'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1041', 'poi'::review_target_type, 'poi-176', 'Дмитрий Гуськов', 5.0, 'Отель прекрасный в своей категории, один из лучших четвёрок. Два хороших ресторана, завтрак — отличный.', '2026-03-22'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1042', 'poi'::review_target_type, 'poi-176', 'Sergey Lis', 5.0, 'Очень вкусные завтраки, отличный сервис и свежие номера. Всё стильно, гостиница находится прямо в центре Владикавказа.', '2026-03-22'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1069', 'poi'::review_target_type, 'poi-070', 'Никита Заможных', 5.0, 'Добрый отзывчивый персонал. Вкусно и не дорого.', '2024-01-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1070', 'poi'::review_target_type, 'poi-071', 'Пётр Саркисов', 5.0, 'Замечательное место. Еда вкусная, ну и конечно божественные фыдджыны.', '2024-01-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1074', 'poi'::review_target_type, 'poi-079', 'Аслан Гудиев', 5.0, 'Шикарный персонал! Уютная обстановка!', '2024-01-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1076', 'poi'::review_target_type, 'poi-091', 'Кристина Цховребова', 5.0, 'Самый вкусный кофе.', '2024-01-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1077', 'poi'::review_target_type, 'poi-091', 'Максим Гречишников', 5.0, 'Сметанник топ!', '2024-01-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1121', 'poi'::review_target_type, 'poi-092', 'Виктория Бережнева', 5.0, 'Очень вкусный кофе и десерты, очень уютное место, персонал вежливый', '2025-11-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1122', 'poi'::review_target_type, 'poi-095', 'Lena_Shapochka', 4.0, 'Кафе у бурлящей реки посреди леса и гор. Это одно из самых потрясающих мест! Вся территория — небольшие домики-беседки вдоль горной реки вместо традиционных столиков. Потрясающие виды на горы, уха из семги и осетинские пироги — очень вкусно. Цены за три года заметно выросли, но место стоит посещения.', '2020-08-12'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1123', 'poi'::review_target_type, 'poi-095', 'МВ Виктория', 4.0, 'Как же тут красиво!!! Домики стоят вдоль горной речки, один даже расположен на сваях над водой. Меню не очень большое, но нам понравилось всё — и как готовят, и как обслуживают. Уха, пироги, шашлык и компот из кизила — всё на уровне.', '2023-10-06'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1127', 'poi'::review_target_type, 'poi-123', 'Милана Мирная', 1.0, 'Хуже заведения в жизни не видела, даже по России. Пили пиво — кислое. Пицца и салаты — невкусные. Микрофон плохой, персонал не справляется. Цены высокие при таком качестве.', '2023-09-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1128', 'poi'::review_target_type, 'poi-123', 'Артем Зайцев', 2.0, 'Старая мебель, отсутствуют чеки, одна девушка отвечает и за караоке, и за обязанности официанта — поэтому всё очень долго.', '2023-10-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1175', 'poi'::review_target_type, 'poi-148', 'Жанна Салбиева', 4.0, 'Хорошее оформление ресторана. Кухня выше всяких похвал. Официанты молодцы. Обслуживание столов на свадьбе было своевременное. Так держать. Буду рекомендовать вас всем.', '2022-07-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1176', 'poi'::review_target_type, 'poi-156', 'Мария', 5.0, 'В этом ресторане просто бомба как вкусно готовят грузинскую еду! Особенно бараний шашлык — говорят, один из лучших на Кавказе, и это правда. Порции огромные, цены приятные. Обслуживание быстрое и вежливое. Есть отдельные кабинки, чтобы посидеть с друзьями наедине. В общем, место топ!', '2025-04-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1253', 'poi'::review_target_type, 'poi-179', 'Юлия', 5.0, 'Спасибо огромное! Всем советую побывать! В компании друзей отдыхали. Часто вспоминаем это время. Многокилометровые походы на горы и ледники, потрясающие виды, разнообразие природы — и при этом комфортные условия базы.', '2015-05-04'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1254', 'poi'::review_target_type, 'poi-179', 'Сергей', 4.0, 'Красивая местность — это необходимое, но недостаточное условие для хорошего отдыха. Здесь, к счастью, есть и то и другое. Остановился в Дзинаге и ни разу не пожалел: уютное проживание, номера хорошие, самое главное — чистые и просторные.', '2019-11-09'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1255', 'poi'::review_target_type, 'poi-179', 'treya', 4.0, 'Для базы на краю земли — а дальше, между прочим, только маленькое село, погранзастава, высоченные ледники и граница с Грузией — очень и очень хорошо. Свежий воздух, прогулки по ущелью, можно насладиться красотой природы. Кому не нужен сервис 5+ — рекомендую.', '2021-09-04'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1256', 'poi'::review_target_type, 'poi-180', 'Zhanna', 5.0, 'Все домики с панорамными окнами, и вид из них открывается великолепный. Это что-то нереальное — чистейший воздух, вид как на картинке. Ферма с животными, сауна с панорамными окнами — отдых для всей семьи.', '2026-05-03'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1257', 'poi'::review_target_type, 'poi-180', 'Aleksandra', 5.0, 'Потрясающие виды, большая территория, доброжелательный персонал. Очень понравились мастер-классы по приготовлению осетинских пирогов. Уютно, чисто, с потрясающим видом на горы. Лучшее место на Кавказе для семейного отдыха!', '2025-07-18'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1258', 'poi'::review_target_type, 'poi-181', 'Надежда', 5.0, 'В альплагере нас кормили на убой. Еда была ооочень много и ооочень вкусно. Персонал организовал сытный обед даже когда мы пришли позже расписания. Из кранов в номерах течёт минеральная вода — вот это приятный сюрприз!', '2017-08-31'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1259', 'poi'::review_target_type, 'poi-181', 'Роман', 5.0, 'Прекрасное место! Отдохнули великолепно! Сам альплагерь шикарен, администрация очень приятная. Цены просто смешные — на четыре тысячи рублей можно провести полноценный отдых. Вокруг горы, грибы, река. Обязательно вернёмся!', '2017-08-16'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1260', 'poi'::review_target_type, 'poi-181', 'Лейла', 5.0, 'Питание отличное, порции огромные. Весь персонал лагеря очень приятен. Природа, горы, реки, звёздное небо — всё это не передать словами. Обязательно вернусь снова, уже с друзьями.', '2016-08-01'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1261', 'poi'::review_target_type, 'poi-182', 'Екатерина Медведева', 5.0, 'Всё прекрасно. Уютный и чистый отель, достаточно бюджетно. Завтраки вкусные! Рекомендую всем, кто приезжает во Владикавказ.', '2024-09-12'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1262', 'poi'::review_target_type, 'poi-182', 'Ingwar Helgardson', 5.0, 'Очень понравилось: чисто, уютно, небольшие номера, но удобные. Персонал на рецепшене очень отзывчивый, всегда готов подсказать и помочь. Вид на гору Столовую из окна — отдельный бонус.', '2024-11-20'::timestamptz, false);
INSERT INTO reviews (id, target_type, target_id, author_name, rating, text, date, is_generated) VALUES ('rev-1263', 'poi'::review_target_type, 'poi-182', 'ANNA', 5.0, 'Чистый, современный, уютный номер с видом на гору Столовая. В номере чашки, чай, тарелки, столовые приборы, холодильник, чайник — всё новое. Завтраки на выбор: каша, блины, яичница или сырники. Отличный отель за свои деньги.', '2023-11-05'::timestamptz, false);
