ALTER TABLE pois ADD COLUMN IF NOT EXISTS radius numeric;

-- === 1. Content update of 78 overlapping POIs (slug/slug_legacy/owner_id/subscription_tier/visit_count kept from DB) ===
UPDATE pois SET name = '{"ru": "Мидаграбинские водопады", "en": "Midagrabin Waterfalls"}'::jsonb, category = 'nature'::poi_category, subcategory = 'nature', cuisine_type = NULL, location = '{"lat": 42.767546, "lng": 44.362126, "address": {"ru": "Респ. Северная Осетия — Алания, Россия, 363203", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "50+ водопадов в одном ущелье — и один из них падает с высоты 750 метров. Это не преувеличение.", "en": "50+ waterfalls in one gorge — and one of them drops 750 meters. That''s not an exaggeration."}, "medium": {"ru": "Место, где горы буквально плачут от красоты. Больше пятидесяти водопадов рассыпаны по склонам Гизельдонского ущелья, а главный — Большой Зейгалан — в сезон обрушивается с высоты 750 метров. Это один из самых высоких водопадов в Европе, и увидеть его вживую — совсем другое ощущение, чем на фото.", "en": "A place where the mountains seem to weep with beauty. Over fifty waterfalls scatter across the slopes of Gizeldon Gorge, and the main one — Bolshoy Zeygalan — plunges 750 meters in season. One of the tallest waterfalls in Europe, and seeing it in person is nothing like a photo."}, "full": {"ru": "Место, где горы буквально плачут от красоты. Больше пятидесяти водопадов рассыпаны по склонам Гизельдонского ущелья — одни едва слышны за туманом, другие грохочут так, что не слышно собственных мыслей. Главный — Большой Зейгалан — в сезон обрушивается с высоты 750 метров, делая его одним из самых высоких водопадов в Европе. Добраться сюда непросто: дорога потребует времени и желания. Но когда стоишь у подножия и чувствуешь холодные брызги на лице — понимаешь, что это именно то место, ради которого стоило ехать.", "en": "A place where the mountains seem to weep with beauty. Over fifty waterfalls scatter across the slopes of Gizeldon Gorge — some barely audible through the mist, others roaring loud enough to drown your thoughts. The main one, Bolshoy Zeygalan, plunges 750 meters in season, making it one of the tallest waterfalls in Europe. Getting here takes effort. But when you''re standing at the base, feeling cold spray on your face, you''ll understand why it was worth every kilometer."}}'::jsonb, photos = ARRAY['/images/pois/midagrabin-waterfalls_gp.webp','/images/pois/midagrabinskie-vodopady_2.webp','/images/pois/midagrabinskie-vodopady_3.webp','/images/pois/midagrabinskie-vodopady_4.webp','/images/pois/midagrabinskie-vodopady_5.webp','/images/pois/midagrabinskie-vodopady_6.webp']::text[], rating = 4.9, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['nature']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 800, review_count = 133, updated_at = now() WHERE id = 'poi-001';
UPDATE pois SET name = '{"ru": "Цейское ущелье", "en": "Tsey Gorge"}'::jsonb, category = 'nature'::poi_category, subcategory = 'nature', cuisine_type = NULL, location = '{"lat": 42.784145, "lng": 43.904147, "address": {"ru": "Респ. Северная Осетия — Алания, Россия, 363221", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "23 километра дикой красоты — ледники, альпийские луга и горнолыжный курорт в одном ущелье.", "en": "23 kilometers of wild beauty — glaciers, alpine meadows and a ski resort all in one gorge."}, "medium": {"ru": "Цейское ущелье — это когда природа решила не мелочиться. На высоте 1300 метров вас ждут ледники, альпийские луга, горнолыжные трассы и древнее святилище Реком. Зимой сюда едут кататься на лыжах, летом — дышать воздухом, от которого кружится голова в хорошем смысле.", "en": "Tsey Gorge is what happens when nature goes all in. At 1300 meters you''ll find glaciers, alpine meadows, ski slopes, and the ancient Rekom sanctuary. In winter people come to ski; in summer — to breathe air that makes your head spin in the best possible way."}, "full": {"ru": "Цейское ущелье — это когда природа решила не мелочиться. На высоте 1300 метров и протяжённостью 23 километра оно вмещает в себя всё: ледники с бирюзовыми трещинами, альпийские луга в июле, горнолыжные трассы зимой и древнее святилище Реком, которому больше тысячи лет. Летом здесь можно подняться по канатной дороге прямо к леднику и смотреть на горы так, будто ты один на всём свете. Зимой — мчаться по склонам и греться у огня в одном из кафе. Цейское умеет быть разным — и каждый раз настоящим.", "en": "Tsey Gorge is what happens when nature goes all in. Stretching 23 kilometers at 1300 meters altitude, it holds everything: glaciers with turquoise crevasses, alpine meadows in July, ski slopes in winter, and the ancient Rekom sanctuary — over a thousand years old. In summer you can take the cable car straight up to the glacier and stare at the mountains like you''re the last person on earth. In winter — race down the slopes and warm up by the fire. Tsey knows how to be different every time — and always real."}}'::jsonb, photos = ARRAY['/images/pois/tsey-gorge_gp.webp','/images/pois/tseyskoe-uschele_2.webp','/images/pois/tseyskoe-uschele_3.webp','/images/pois/tseyskoe-uschele_4.webp','/images/pois/tseyskoe-uschele_5.webp','/images/pois/tseyskoe-uschele_6.webp','/images/pois/tseyskoe-uschele_7.webp','/images/pois/tseyskoe-uschele_8.webp']::text[], rating = 4.5, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['nature']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 800, review_count = 1168, updated_at = now() WHERE id = 'poi-002';
UPDATE pois SET name = '{"ru": "Цейский ледник", "en": "Tsey Glacier"}'::jsonb, category = 'nature'::poi_category, subcategory = 'nature', cuisine_type = NULL, location = '{"lat": 42.768889, "lng": 43.8525, "address": {"ru": "Цейский ледник, Респ. Северная Осетия — Алания, Россия, 363225", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Один из крупнейших ледников Кавказа — живая река льда прямо в Цейском ущелье.", "en": "One of the largest glaciers in the Caucasus — a living river of ice right in Tsey Gorge."}, "medium": {"ru": "Цейский ледник — это не просто лёд. Это живая река, которая медленно сползает с Кавказского хребта уже тысячелетия. Добраться до него можно пешком по тропе вдоль ущелья — и чем ближе, тем больше понимаешь, что такое настоящая мощь природы. Ледник отступает, но пока он здесь — впечатление незабываемое.", "en": "Tsey Glacier isn''t just ice. It''s a living river that has been slowly descending from the Caucasus ridge for millennia. You can reach it on foot along the gorge trail — and the closer you get, the more you understand what raw natural power really looks like. The glacier is retreating, but while it''s here, the impression is unforgettable."}, "full": {"ru": "Цейский ледник — это живая река льда, которая медленно сползает с северных склонов Кавказского хребта уже тысячелетия. Длина его около 8 километров, а поверхность покрыта глубокими трещинами и моренными грядами — следами многовековой работы льда. Добраться можно пешком по тропе вдоль ущелья: чем ближе подходишь, тем сильнее ощущение, что стоишь перед чем-то живым и огромным. Летом с поверхности ледника стекают ручьи, воздух резкий и холодный, а тишину нарушает только треск льда. Ледник постепенно отступает под влиянием климата — каждое десятилетие он становится короче. Именно поэтому видеть его стоит сейчас, пока он ещё здесь.", "en": "Tsey Glacier is a living river of ice that has been slowly descending from the northern slopes of the Caucasus ridge for millennia. It stretches about 8 kilometers, its surface carved by deep crevasses and moraine ridges — marks of centuries of glacial work. You reach it on foot along the gorge trail, and the closer you get, the stronger the feeling that you''re standing before something alive and immense. In summer, streams trickle off the surface, the air is sharp and cold, and the only sound is the crack of ice. The glacier is gradually retreating with the changing climate — shrinking a little each decade. That''s why you should see it now, while it''s still here."}}'::jsonb, photos = ARRAY['/images/pois/tsey-glacier_gp.webp','/images/pois/tseyskiy-lednik_2.webp','/images/pois/tseyskiy-lednik_3.webp','/images/pois/tseyskiy-lednik_4.webp','/images/pois/tseyskiy-lednik_5.webp','/images/pois/tseyskiy-lednik_6.webp','/images/pois/tseyskiy-lednik_7.webp','/images/pois/tseyskiy-lednik_8.webp']::text[], rating = 4.9, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['nature']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 800, review_count = 28, updated_at = now() WHERE id = 'poi-003';
UPDATE pois SET name = '{"ru": "Сказский ледник", "en": "Skaz Glacier"}'::jsonb, category = 'nature'::poi_category, subcategory = 'nature', cuisine_type = NULL, location = '{"lat": 42.765654, "lng": 43.852638, "address": {"ru": "Респ. Северная Осетия — Алания, Россия, 363225", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Голубой ледник на склоне горы Адай-Хох — ближайший к Владикавказу и самый доступный: канатная дорога доставляет почти к его краю.", "en": "The blue glacier on Aday-Khokh''s slopes — closest to Vladikavkaz and the most accessible: a cable car brings you nearly to its edge."}, "medium": {"ru": "Сказский ледник лежит на высоте от 2900 м на северном склоне Адай-Хоха (4408 м). В отличие от Цейского, сюда можно добраться по канатной дороге и увидеть живой лёд совсем близко — с трещинами, голубоватыми гротами и потоком талой воды внизу. Лучшее время — июнь–сентябрь.", "en": "The Skaz Glacier sits at 2,900 m and above on Aday-Khokh''s northern slopes. Unlike the Tsey Glacier, a cable car delivers you almost to its edge — close enough to see crevasses, pale-blue ice grottoes, and the meltwater stream below. Best visited June–September."}, "full": {"ru": "Среди ледников Осетии Сказский — самый доступный. Канатная дорога Цейского горнолыжного курорта поднимает вас с 1850 до 2700 м, и оттуда ледяное тело почти в пределах досягаемости руки. В ясный день здесь ощущается вся мощь горного мира: острые гребни Адай-Хоха (4408 м), хруст наста под ногами, запах холодного камня. Ледник отступает — за последние десятилетия потерял заметную часть своей длины. Смотреть на это одновременно красиво и немного тревожно. Приезжайте летом: зимой канатка работает для лыжников, а ледник прячется под снегом.", "en": "Among Ossetia''s glaciers, Skaz is the most accessible. The Tsey ski resort cable car lifts you from 1,850 to 2,700 m, and from there the ice is almost within arm''s reach. On a clear day the full weight of the mountain world bears down on you: the jagged ridges of Aday-Khokh (4,408 m), the crunch of firn underfoot, the smell of cold stone. The glacier is retreating — it has lost a noticeable portion of its length in recent decades. Watching it is beautiful and faintly unsettling at the same time. Come in summer: in winter the cable car serves skiers, and the glacier hides under snow."}}'::jsonb, photos = ARRAY['/images/pois/skaz-glacier_gp.webp','/images/pois/skazskiy-lednik_2.webp','/images/pois/skazskiy-lednik_3.webp','/images/pois/skazskiy-lednik_4.webp']::text[], rating = 5, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['nature']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 800, review_count = 22, updated_at = now() WHERE id = 'poi-004';
UPDATE pois SET name = '{"ru": "Кармадонское ущелье", "en": "Karmadon Gorge"}'::jsonb, category = 'nature'::poi_category, subcategory = 'nature', cuisine_type = NULL, location = '{"lat": 42.871243, "lng": 44.52022, "address": {"ru": "Р299, Респ. Северная Осетия — Алания, Россия, 363125", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Ущелье, которое изменило историю: здесь в 2002 году сошёл ледник Колка, похоронив съёмочную группу Бодрова. Сегодня — место памяти и дикой красоты.", "en": "The gorge that changed history: in 2002 the Kolka glacier collapsed here, burying Bodrov''s film crew. Today — a place of remembrance and raw beauty."}, "medium": {"ru": "Кармадонское ущелье (17 км, р. Геналдон) красиво само по себе: минеральные источники, теснины, старые башни. Но 20 сентября 2002 года ледник Колка сошёл со скоростью 200 км/ч, уничтожив всё на 18 км вниз. Погибли 125 человек, в том числе Сергей Бодров-младший и вся его съёмочная группа. Часть тел не найдена до сих пор.", "en": "The Karmadon gorge (17 km, Genaldon river) is beautiful in its own right: mineral springs, narrow passes, old towers. But on September 20, 2002, the Kolka glacier surged at 200 km/h, destroying everything for 18 km downstream. 125 people died, including Sergei Bodrov Jr. and his entire film crew. Some remains have never been found."}, "full": {"ru": "Кармадонское ущелье — одно из тех мест, где красота и трагедия существуют в одном пространстве. Река Геналдон прорезала здесь теснины с отвесными стенами, горячие и холодные источники выходят прямо у дороги, а средневековые башни смотрят с хребтов. Всё это существовало спокойно — пока 20 сентября 2002 года ледник Колка не сорвался со своего ложа. Ледово-каменная лавина объёмом в десятки миллионов кубометров прошла 18 км за несколько минут. 125 человек погибли или пропали без вести — среди них актёр Сергей Бодров-младший, снимавший здесь свой фильм «Связной». Тела большинства до сих пор не найдены. Сегодня в ущелье стоит мемориал, а ледяная пробка в конце тоннеля медленно тает. Приходить сюда — значит помнить.", "en": "The Karmadon gorge is one of those places where beauty and tragedy inhabit the same space. The Genaldon river has cut narrow canyons with sheer walls here; hot and cold mineral springs emerge right beside the road; medieval towers watch from the ridgelines. All of this existed quietly — until September 20, 2002, when the Kolka glacier tore from its bed. A rock-and-ice avalanche tens of millions of cubic meters in volume covered 18 km in minutes. 125 people died or vanished, among them the actor Sergei Bodrov Jr., who was filming his movie here. Most bodies were never recovered. Today a memorial stands in the gorge, and the ice plug at the tunnel''s end slowly melts. To come here is to remember."}}'::jsonb, photos = ARRAY['/images/pois/karmadon-gorge_gp.webp','/images/pois/karmadonskoe-uschele_2.webp','/images/pois/karmadonskoe-uschele_3.webp','/images/pois/karmadonskoe-uschele_4.webp','/images/pois/karmadonskoe-uschele_5.webp','/images/pois/karmadonskoe-uschele_6.webp']::text[], rating = 4.9, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['nature']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 800, review_count = 196, updated_at = now() WHERE id = 'poi-005';
UPDATE pois SET name = '{"ru": "Водопад Галдоридон (Жемчужный)", "en": "Galdoridon (Pearl) Waterfall"}'::jsonb, category = 'nature'::poi_category, subcategory = 'nature', cuisine_type = NULL, location = '{"lat": 42.911267, "lng": 43.552214, "address": {"ru": "Стур-Дигора, Респ. Северная Осетия — Алания, Россия, 363517", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Тридцать метров падающей воды в пяти каскадах — и никакой толпы. Галдоридон в Дигории ждёт тех, кто готов ехать.", "en": "Thirty meters of falling water in five cascades — and no crowds. Galoridon in Digoria is waiting for those willing to make the trip."}, "medium": {"ru": "Галдоридон — пятикаскадный водопад в Ирафском районе, высота падения около 30 м. Имя переводится как «жемчужный» — за водяную пыль, которая в солнечный день переливается радугой. Дорога ведёт через дигорские сёла; сам водопад в получасе пешком от ближайшей парковки. Идеален для однодневного похода по Дигории.", "en": "Galoridon is a five-cascade waterfall in the Iraf district, dropping about 30 m. The name means ''pearly'' — for the spray that shimmers like a rainbow on sunny days. The road passes through Digor villages; the waterfall itself is a 30-minute walk from the nearest parking. Ideal for a day hike through Digoria."}, "full": {"ru": "Дигория — малоизвестная западная часть Осетии, куда туристы добираются реже, чем в Цейское или Куртатинское ущелья. И именно здесь прячется Галдоридон — один из красивейших водопадов республики. Пять каскадов суммарной высотой около 30 метров падают в узкое ущелье, и в солнечную погоду водяная взвесь над ними светится как жемчуг — откуда и название. Тропа к водопаду идёт через альпийские луга и перелески. Вокруг — тишина, изредка разбавленная пастушьим звоном колокольчиков. Здесь нет сувенирных палаток и очередей у смотровых площадок. Есть только вода, камень и небо. Лучший сезон — июнь и первая половина июля, когда снеготаяние обеспечивает максимальный поток.", "en": "Digoria is the little-known western part of Ossetia, visited far less than the Tsey or Kurtatinsky gorges. And this is exactly where Galoridon hides — one of the most beautiful waterfalls in the republic. Five cascades dropping a total of about 30 meters pour into a narrow canyon, and in sunny weather the spray above them shines like pearls — hence the name. The trail to the waterfall passes through alpine meadows and small groves. Around you: silence, occasionally broken by the distant bell of a shepherd''s flock. No souvenir stalls, no queues at viewpoints. Just water, stone, and sky. Best season is June and early July, when snowmelt delivers maximum flow."}}'::jsonb, photos = ARRAY['/images/pois/galdoridon-(pearl)-waterfall_gp.webp','/images/pois/vodopad-galdoridon-zhemchuzhnyy_2.webp','/images/pois/vodopad-galdoridon-zhemchuzhnyy_3.webp','/images/pois/vodopad-galdoridon-zhemchuzhnyy_4.webp','/images/pois/vodopad-galdoridon-zhemchuzhnyy_5.webp','/images/pois/vodopad-galdoridon-zhemchuzhnyy_6.webp','/images/pois/vodopad-galdoridon-zhemchuzhnyy_7.webp']::text[], rating = 4.8, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['nature']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 800, review_count = 98, updated_at = now() WHERE id = 'poi-006';
UPDATE pois SET name = '{"ru": "Столовая гора (Мадыхох)", "en": "Table Mountain (Madykhokh)"}'::jsonb, category = 'nature'::poi_category, subcategory = 'nature', cuisine_type = NULL, location = '{"lat": 42.853359, "lng": 44.716373, "address": {"ru": "Респ. Ингушетия, Россия, 386430", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Столовая гора — Мадыхох, «гора-мать» по-осетински — плоская вершина высотой 3003 м, которую видно с любой точки Владикавказа. Священная для осетин и ингушей, она веками служила ориентиром и местом поклонения.", "en": "Table Mountain — Madykhokh, meaning ''Mother Mountain'' in Ossetian — a flat-topped peak at 3,003 m visible from anywhere in Vladikavkaz. Sacred to both Ossetians and Ingush for centuries."}, "medium": {"ru": "Мадыхох (Столовая гора, 3003 м) — один из главных символов Северной Осетии. Осетинское имя Мадыхох означает «гора-мать» — за её покровительственный облик над городом. Плоский силуэт виден с проспекта Мира и набережной Терека. На вершине сохранились карстовые пещеры и остатки средневековых укреплений. Маршрут протяжённостью около 14 км стартует из сёл Чми или Балта и занимает полный день.", "en": "Madykhokh (Table Mountain, 3,003 m) is one of North Ossetia''s defining landmarks. Its Ossetian name means ''Mother Mountain'' — for its protective silhouette above the city. The flat summit is visible from Prospekt Mira and the Terek embankment. Karst caves and medieval fortifications survive on the plateau. The ~14 km route starts from the villages of Chmi or Balta and takes a full day."}, "full": {"ru": "Утром, когда над Владикавказом ещё стоит дымка, Столовая гора уже освещена солнцем — её плоская вершина на 3003 метрах парит над городом как декорация к эпическому фильму. Ингуши зовут её Мят-Лоам, «камень, где сидит Бог», и смотришь на неё — понимаешь почему. Подняться на Столовую — полноценный трекинг. Маршрут от Чми или Балты около 14 км, набор высоты больше 1500 м. Наверху — карстовые пещеры, остатки средневековых башен и вид на обе стороны: Владикавказ с севера, и — в ясный день — хребты в сторону Грузии с юга. Физическая подготовка нужна, специального снаряжения — нет. Берите воду: наверху её нет.", "en": "In the morning, when haze still hangs over Vladikavkaz, Table Mountain is already lit by the sun — its flat summit at 3,003 m floats above the city like a set piece from an epic film. The Ingush call it Myat-Loam, ''the stone where God sits,'' and looking at it you understand why. Climbing Table Mountain is a real trek. The route from Chmi or Balta is about 14 km with 1,500 m of elevation gain. At the top: karst caves, remains of medieval towers, and views in both directions — Vladikavkaz to the north, and on a clear day ridges toward Georgia to the south. Physical fitness required; no special equipment needed. Bring water: there''s none on top."}}'::jsonb, photos = ARRAY['/images/pois/table-mountain-(myat-loam)_gp.webp','/images/pois/stolovaya-gora-myat-loam_2.webp','/images/pois/stolovaya-gora-myat-loam_3.webp','/images/pois/stolovaya-gora-myat-loam_4.webp','/images/pois/stolovaya-gora-myat-loam_5.webp','/images/pois/stolovaya-gora-myat-loam_6.webp','/images/pois/stolovaya-gora-myat-loam_7.webp','/images/pois/stolovaya-gora-myat-loam_8.webp','/images/pois/stolovaya-gora-myat-loam_9.webp','/images/pois/stolovaya-gora-myat-loam_10.webp']::text[], rating = 5, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['nature']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 800, review_count = 39, updated_at = now() WHERE id = 'poi-007';
UPDATE pois SET name = '{"ru": "Национальный парк «Алания»", "en": "Alania National Park"}'::jsonb, category = 'nature'::poi_category, subcategory = 'nature', cuisine_type = NULL, location = '{"lat": 42.979405, "lng": 43.772391, "address": {"ru": "Мацута, Респ. Северная Осетия — Алания, Россия, 363518", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "55 000 гектаров нетронутых гор, где снежные барсы — не легенда, а задокументированная реальность.", "en": "55,000 hectares of untouched mountains where snow leopards are documented reality, not legend."}, "medium": {"ru": "Парк «Алания» (основан 1998) охватывает западную часть горной Осетии: ледники, альпийские луга, вековые леса. Здесь живут туры, серны, бурые медведи и, по данным камер-ловушек учёных, снежные барсы. Шесть ледников, десятки водопадов. Инфраструктура минимальна — для тех, кто ищет настоящую дикую природу.", "en": "Alania National Park (est. 1998) covers western highland Ossetia: glaciers, alpine meadows, ancient forests. Tur, chamois, brown bears, and — according to camera trap data — snow leopards live here. Six glaciers, dozens of waterfalls. Infrastructure is minimal — for those seeking true wilderness."}, "full": {"ru": "Большинство туристов в Осетии едут в Цей или Дигорию — и проезжают мимо «Алании», которая их окружает. Парк занимает 55 000 га горного запада республики и почти не тронут цивилизацией. Шесть ледников. Водопады, которым не дали имена. Альпийские луга, где цветы стоят по колено. Леса из кавказского граба и дуба. И животные: туры, серны, бурые медведи. И, по данным камер-ловушек, снежный барс — один из самых неуловимых хищников планеты. Парк не для однодневной прогулки. Сюда приходят с палатками на несколько дней, с маршрутом и запасом еды. Ближайшая база — в Стур-Дигоре. Пропуска оформляются на кордоне; лучше договориться заранее.", "en": "Most tourists in Ossetia head to Tsey or Digoria — and drive right past Alania, which surrounds them. The park covers 55,000 ha of the republic''s mountainous west and is almost untouched by civilization. Six glaciers. Waterfalls that haven''t been named. Alpine meadows where flowers stand knee-deep. Forests of Caucasian hornbeam and oak. And animals: tur, chamois, brown bears. And, according to camera trap data, the snow leopard — one of the most elusive predators on the planet. The park isn''t for a day trip. You come here with tents for several days, with a route and food supply. The nearest base is in Stur-Digora. Permits are issued at the ranger post; best to arrange in advance."}}'::jsonb, photos = ARRAY['/images/pois/alania-national-park_gp.webp','/images/pois/natsionalnyy-park-alaniya_2.webp','/images/pois/natsionalnyy-park-alaniya_3.webp','/images/pois/natsionalnyy-park-alaniya_4.webp','/images/pois/natsionalnyy-park-alaniya_5.webp','/images/pois/natsionalnyy-park-alaniya_6.webp','/images/pois/natsionalnyy-park-alaniya_7.webp','/images/pois/natsionalnyy-park-alaniya_8.webp','/images/pois/natsionalnyy-park-alaniya_9.webp']::text[], rating = 4.8, hours = '{"mon": "00:00-23:59"}'::jsonb, phone = '+7 867 313-10-58', website = 'http://npalania.ru/', price_level = NULL, tags = ARRAY['nature']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 800, review_count = 405, updated_at = now() WHERE id = 'poi-008';
UPDATE pois SET name = '{"ru": "Зарамагское водохранилище", "en": "Zaramag Reservoir"}'::jsonb, category = 'nature'::poi_category, subcategory = 'nature', cuisine_type = NULL, location = '{"lat": 42.696272, "lng": 43.976911, "address": {"ru": "Респ. Северная Осетия — Алания, Россия, 363227", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Бирюзовое озеро в горном обрамлении — и маленький островок посередине с башней затопленного осетинского села.", "en": "A turquoise lake framed by mountains — and a small island at its center with a tower from a flooded Ossetian village."}, "medium": {"ru": "Зарамагское водохранилище появилось в 2009 году после пуска Зарамагской ГЭС. Под водой оказались несколько древних осетинских сёл. На островке посреди водохранилища сохранилась сторожевая башня — немой памятник затопленному прошлому. Вода отливает бирюзой в окружении голых скал Кассарского ущелья.", "en": "The Zaramag Reservoir appeared in 2009 after the Zaramag hydroelectric plant launched. Several ancient Ossetian villages were submerged. On a small island at the reservoir''s center, a watch tower survived — a silent memorial to the flooded past. The water shimmers turquoise amid the bare cliffs of the Kassar gorge."}, "full": {"ru": "Когда Зарамагская ГЭС наполнила ущелье водой в 2009 году, несколько осетинских сёл исчезли под поверхностью навсегда. Теперь здесь водохранилище — и оно по-своему красиво. Вода цвета холодного неба, по берегам голые светло-серые скалы Кассарского ущелья, вдали белые пики. И посередине — маленький островок со старой сторожевой башней. Башня осталась от одного из затопленных сёл; теперь она стоит в одиночестве на воде как памятник, которого не планировали строить. Остановитесь здесь по дороге в Цей или Зарамаг — это пять минут от трассы, а впечатление остаётся надолго.", "en": "When the Zaramag hydroelectric plant filled the gorge with water in 2009, several Ossetian villages disappeared beneath the surface forever. Now there''s a reservoir here — and it''s beautiful in its own way. The water is the color of a cold sky; along the banks, bare pale-grey cliffs of the Kassar gorge; ahead, white peaks. And in the middle — a small island with an old watch tower. The tower survived from one of the flooded villages; now it stands alone on the water like a memorial no one planned to build. Stop here on your way to Tsey or Zaramag — it''s five minutes from the highway, and the impression lasts."}}'::jsonb, photos = ARRAY['/images/pois/zaramag-reservoir_gp.webp','/images/pois/zaramagskoe-vodohranilische_2.webp','/images/pois/zaramagskoe-vodohranilische_3.webp','/images/pois/zaramagskoe-vodohranilische_4.webp','/images/pois/zaramagskoe-vodohranilische_5.webp']::text[], rating = 4.9, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['nature']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 800, review_count = 47, updated_at = now() WHERE id = 'poi-009';
UPDATE pois SET name = '{"ru": "Куртатинское ущелье", "en": "Kurtatinsky Gorge"}'::jsonb, category = 'nature'::poi_category, subcategory = 'nature', cuisine_type = NULL, location = '{"lat": 42.783333, "lng": 44.233333, "address": {"ru": "Куртатинское Ущелье, Респ. Северная Осетия — Алания, Россия, 363203", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "«Музейное ущелье» Осетии: здесь на 30 км умещается Даргавс, Дзивгисская крепость, монастырь и каньон с тропой над пропастью.", "en": "Ossetia''s ''museum gorge'': in 30 km you get Dargavs, Dzivgis fortress, a monastery, and a canyon trail above the abyss."}, "medium": {"ru": "Куртатинское ущелье — самый насыщенный маршрут Осетии. На коротком участке сосредоточены: «Город мёртвых» Даргавс, Дзивгисская скальная крепость, Аланский монастырь, тропа над Кадаргаванским каньоном и десятки средневековых башен. Всё это можно объехать за один день — или остаться на два, если хочется не спешить.", "en": "The Kurtatinsky gorge is Ossetia''s most densely packed route. In a short stretch: Dargavs City of the Dead, Dzivgis rock fortress, the Alanian monastery, the Kadargavan canyon trail, and dozens of medieval towers. You can cover it all in one day — or stay for two if you''d rather not rush."}, "full": {"ru": "Если бы Осетия была музеем, Куртатинское ущелье стало бы её главным залом. На каких-то 30 км дороги, ведущей от Владикавказа на юг, умещается то, что в другой стране растянулось бы на сотни километров маршрутов. Некрополь XIV–XVIII веков у Даргавса. Средневековая крепость, встроенная в скальные ниши. Православный монастырь в горной долине. Тропа над пропастью каньона Кадаргаван. И всюду — башни, башни, башни: боевые и жилые, полуразрушенные и реставрированные. Ущелье удобно для машины: дорога асфальтированная, остановок много. Но лучший способ понять его масштаб — выйти из машины и пройти хотя бы один участок пешком.", "en": "If Ossetia were a museum, the Kurtatinsky gorge would be its main hall. In about 30 km of road leading south from Vladikavkaz, you find what in another country would be spread over hundreds of kilometers of routes. A XIV–XVIII century necropolis near Dargavs. A medieval fortress built into cliff niches. An Orthodox monastery in a mountain valley. A trail above the Kadargavan canyon abyss. And everywhere — towers, towers, towers: combat and residential, half-ruined and restored. The gorge is convenient by car: the road is paved, with plenty of stops. But the best way to grasp its scale is to get out and walk at least one stretch."}}'::jsonb, photos = ARRAY['/images/pois/kurtatinsky-gorge_gp.webp','/images/pois/kurtatinskoe-uschele_2.webp','/images/pois/kurtatinskoe-uschele_3.webp','/images/pois/kurtatinskoe-uschele_4.webp','/images/pois/kurtatinskoe-uschele_5.webp','/images/pois/kurtatinskoe-uschele_6.webp','/images/pois/kurtatinskoe-uschele_7.webp','/images/pois/kurtatinskoe-uschele_8.webp']::text[], rating = 4.9, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['nature']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 800, review_count = 27, updated_at = now() WHERE id = 'poi-010';
UPDATE pois SET name = '{"ru": "Даргавс — «Город мёртвых»", "en": "Dargavs — City of the Dead"}'::jsonb, category = 'culture'::poi_category, subcategory = 'history', cuisine_type = NULL, location = '{"lat": 42.841563, "lng": 44.445056, "address": {"ru": "Даргавс, Респ. Северная Осетия — Алания, Россия, 363128", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "97 средневековых склепов на склоне горы — жители Осетии приходили умирать сюда сами, чтобы не заражать близких.", "en": "97 medieval crypts on a mountainside — Ossetians came here to die on their own, so as not to infect their loved ones."}, "medium": {"ru": "Даргавский некрополь XIV–XVIII вв. — один из крупнейших в России. По преданию, во время чумных эпидемий семьи уходили сюда умирать добровольно, принося с собой еду и воду. В склепах сохранились останки и личные вещи. Место внесено в список исторических памятников федерального значения.", "en": "The Dargavs necropolis (XIV–XVIII c.) is one of the largest in Russia. According to tradition, during plague epidemics, families would come here voluntarily to die, bringing food and water with them. The crypts preserve remains and personal belongings. The site is on the federal list of historical landmarks."}, "full": {"ru": "На склоне над рекой стоят 97 каменных домов с остроконечными крышами. Издали похожи на маленькую деревню. Вблизи понимаешь: это склепы. И ни один из жителей этой «деревни» не ушёл отсюда живым. По местному преданию, когда в Осетию приходила чума, целые семьи приходили в Даргавс сами — с едой, водой, личными вещами. Залезали в склеп, закрывали вход изнутри и ждали. Они не хотели заражать живых. В некоторых камерах до сих пор лежат кости и одежда XIV–XVIII веков. Сюда приходят не за развлечением. Сюда приходят, чтобы почувствовать масштаб чужого выбора — и помолчать.", "en": "On the slope above the river stand 97 stone houses with pointed roofs. From a distance they look like a small village. Up close you realize: these are crypts. And none of the residents of this ''village'' left alive. According to local tradition, when plague came to Ossetia, entire families would come to Dargavs themselves — with food, water, personal belongings. They would climb into a crypt, close the entrance from inside, and wait. They didn''t want to infect the living. In some chambers, bones and clothing from the XIV–XVIII centuries still lie undisturbed. You don''t come here for entertainment. You come to feel the weight of someone else''s choice — and to be quiet."}}'::jsonb, photos = ARRAY['/images/pois/dargavs--city-of-the-dead_gp.webp','/images/pois/dargavs-gorod-myortvyh_2.webp','/images/pois/dargavs-gorod-myortvyh_3.webp','/images/pois/dargavs-gorod-myortvyh_4.webp','/images/pois/dargavs-gorod-myortvyh_5.webp','/images/pois/dargavs-gorod-myortvyh_6.webp']::text[], rating = 4.8, hours = '{"sun": "10:00-17:00", "mon": "10:00-17:00", "tue": "10:00-17:00", "wed": "10:00-17:00", "thu": "10:00-17:00", "fri": "10:00-17:00", "sat": "10:00-17:00"}'::jsonb, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['culture','history']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 80, review_count = 1648, updated_at = now() WHERE id = 'poi-011';
UPDATE pois SET name = '{"ru": "Башенный комплекс Цимити", "en": "Tsimiti Tower Complex"}'::jsonb, category = 'culture'::poi_category, subcategory = 'history', cuisine_type = NULL, location = '{"lat": 42.837947, "lng": 44.291006, "address": {"ru": "Цимити, Респ. Северная Осетия — Алания, Россия, 363203", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Тридцать средневековых башен среди тишины — без автобусных туров и сувенирных лавок. Осетия до туризма.", "en": "Thirty medieval towers amid silence — no bus tours, no souvenir stalls. Ossetia before tourism."}, "medium": {"ru": "Цимити — один из крупнейших башенных комплексов Осетии с более чем 30 строениями XIV–XVII вв.: боевые башни, жилые башни, склепы. В отличие от Даргавса, здесь почти нет туристической инфраструктуры — сюда едут те, кто хочет видеть подлинное, а не отреставрированное.", "en": "Tsimiti is one of Ossetia''s largest tower complexes, with more than 30 structures from the XIV–XVII c.: combat towers, residential towers, crypts. Unlike Dargavs, this place has almost no tourist infrastructure — visited by those who want the authentic, not the restored."}, "full": {"ru": "На Даргавс привозят экскурсии. О Цимити знают немногие. А ведь это один из крупнейших башенных комплексов во всей Осетии: более 30 средневековых строений — боевые башни с бойницами, жилые башни с несколькими этажами, склепы, ограды. Всё это XIV–XVII века. Всё это стоит на склонах, как и сотни лет назад. Никакой реставрации ради туриста. Никаких касс и очередей. Зайти, обойти, потрогать камень — и попытаться представить, как здесь жили люди, для которых эти башни были домом, убежищем и символом статуса одновременно. Дорога сюда грунтовая; нужна машина с хорошим клиренсом или готовность пройти несколько километров пешком.", "en": "Dargavs gets the tour buses. Few people know about Tsimiti. Yet it''s one of the largest tower complexes in all of Ossetia: more than 30 medieval structures — combat towers with arrow slits, multi-story residential towers, crypts, boundary walls. All XIV–XVII century. All standing on the slopes as they have for hundreds of years. No restoration for tourists. No ticket booths or queues. Walk in, look around, touch the stone — and try to imagine the people for whom these towers were home, refuge, and status symbol all at once. The road here is dirt; you need a high-clearance vehicle or the willingness to walk several kilometers."}}'::jsonb, photos = ARRAY['/images/pois/tsimiti-tower-complex_gp.webp','/images/pois/bashennyy-kompleks-tsimiti_2.webp','/images/pois/bashennyy-kompleks-tsimiti_3.webp','/images/pois/bashennyy-kompleks-tsimiti_4.webp','/images/pois/bashennyy-kompleks-tsimiti_5.webp']::text[], rating = 4.3, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['culture','history']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 80, review_count = 99, updated_at = now() WHERE id = 'poi-013';
UPDATE pois SET name = '{"ru": "Нузальская часовня", "en": "Nuzal Chapel"}'::jsonb, category = 'culture'::poi_category, subcategory = 'history', cuisine_type = NULL, location = '{"lat": 42.830212, "lng": 44.025952, "address": {"ru": "Нузал, Респ. Северная Осетия — Алания, Россия, 363205", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Маленькая часовня XII–XIV вв. с фресками, которым нет аналогов на Кавказе — Христос рядом с нартскими героями.", "en": "A small XII–XIV century chapel with frescoes unlike anything else in the Caucasus — Christ alongside Nart heroes."}, "medium": {"ru": "Нузальская часовня в Алагирском ущелье — один из самых загадочных христианских памятников Кавказа. Фрески XII–XIV вв. изображают Иисуса Христа в окружении осетинских нартских героев — уникальный синтез христианства и языческой мифологии. По преданию, здесь похоронен Ос-Багатар, последний царь Алании.", "en": "Nuzal Chapel in the Alagir gorge is one of the most mysterious Christian monuments in the Caucasus. Frescoes from the XII–XIV c. depict Jesus Christ surrounded by Ossetian Nart heroes — a unique synthesis of Christianity and pagan mythology. According to tradition, Os-Bagatar, the last king of Alania, is buried here."}, "full": {"ru": "Снаружи Нузальская часовня выглядит скромно: небольшая каменная постройка XII–XIV веков в скале над рекой. Внутри — совсем другое. На стенах фрески, которые не вписываются ни в какой известный канон: рядом с образом Христа изображены герои осетинского нартского эпоса. Христианство и язычество встретились здесь и слились в нечто третье — уникальное и больше нигде не существующее. По преданию, в часовне похоронен Ос-Багатар — последний царь средневековой Алании, погибший в бою с войсками Тамерлана. Часовня небольшая, войти можно только по несколько человек. Стоять там в тишине и смотреть на эти лица на стенах — странный и очень сильный опыт.", "en": "From the outside, Nuzal Chapel looks modest: a small stone structure from the XII–XIV c. in the cliff above the river. Inside — something entirely different. The frescoes on the walls fit no known canon: alongside the image of Christ are heroes from the Ossetian Nart epic. Christianity and paganism met here and merged into something third — unique and existing nowhere else. According to tradition, Os-Bagatar is buried in the chapel — the last king of medieval Alania, who by one account died fighting Tamerlane''s armies. The chapel is small; only a few people can enter at a time. Standing there in silence and looking at those faces on the walls is a strange and very powerful experience."}}'::jsonb, photos = ARRAY['/images/pois/nuzalskaya-chasovnya_gp.webp','/images/pois/nuzalskaya-chasovnya_2.webp','/images/pois/nuzalskaya-chasovnya_3.webp','/images/pois/nuzalskaya-chasovnya_4.webp','/images/pois/nuzalskaya-chasovnya_5.webp','/images/pois/nuzalskaya-chasovnya_6.webp']::text[], rating = 4.2, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['culture','history']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 80, review_count = 236, updated_at = now() WHERE id = 'poi-014';
UPDATE pois SET name = '{"ru": "Галиат", "en": "Galiat Village"}'::jsonb, category = 'culture'::poi_category, subcategory = 'history', cuisine_type = NULL, location = '{"lat": 42.922063, "lng": 43.847581, "address": {"ru": "Галиат, Респ. Северная Осетия — Алания, Россия, 363515", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Средневековый город на высоте 2000+ м — жители ушли, башни остались. Дигорское Мачу-Пикчу.", "en": "A medieval city above 2,000 m — the people left, the towers remain. Digoria''s Machu Picchu."}, "medium": {"ru": "Галиат — архитектурный комплекс XIII–XVIII вв. на высоте более 2000 м в Дигорском ущелье. Когда-то здесь жило более 1000 человек. Боевые и жилые башни выстроились по крутому склону как ступени амфитеатра. Большинство жителей ушли в XIX–XX вв.; сейчас это почти нежилое место, сохранившее дух заброшенного города.", "en": "Galiat is an architectural complex from the XIII–XVIII c. at over 2,000 m in the Digor gorge. Once home to more than 1,000 people. Combat and residential towers line the steep slope like the steps of an amphitheater. Most residents left in the XIX–XX c.; today it''s nearly uninhabited, preserving the spirit of an abandoned city."}, "full": {"ru": "Представьте: крутой склон горы, покрытый каменными башнями сверху донизу, как гигантская лестница в небо. Это Галиат — средневековый город в Дигорском ущелье, который в лучшие времена принимал тысячу и больше жителей. XIII–XVIII века. Несколько видов башен: боевые — тонкие и высокие, жилые — с этажами и окнами, склепы на краях. Всё это держится на горе без ничего лишнего — только камень, только функция. Большинство жителей покинули Галиат в XIX–XX веках. Сейчас здесь живёт ноль или почти ноль человек. И тем не менее это не руины в обычном смысле. Это стоящий город, который просто опустел. Сравнение с Мачу-Пикчу не случайное: та же высота, та же монументальность, тот же вопрос — зачем люди жили именно здесь, в такой труднодоступности?", "en": "Imagine: a steep mountainside covered with stone towers from bottom to top, like a giant staircase to the sky. This is Galiat — a medieval city in the Digor gorge that in its prime housed a thousand or more residents. XIII–XVIII centuries. Several types of towers: combat ones — tall and narrow; residential ones — with floors and windows; crypts at the edges. All of it clinging to the mountain with nothing superfluous — only stone, only function. Most residents left Galiat in the XIX–XX centuries. Now zero or nearly zero people live here. And yet these aren''t ruins in the ordinary sense. It''s a city that simply emptied. The Machu Picchu comparison isn''t accidental: same altitude, same monumentality, same question — why did people live exactly here, in such inaccessibility?"}}'::jsonb, photos = ARRAY['/images/pois/galiat-village_gp.webp','/images/pois/galiat_2.webp','/images/pois/galiat_3.webp','/images/pois/galiat_4.webp','/images/pois/galiat_5.webp','/images/pois/galiat_6.webp','/images/pois/galiat_7.webp','/images/pois/galiat_8.webp','/images/pois/galiat_9.webp']::text[], rating = 4.3, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['culture','history']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 80, review_count = 260, updated_at = now() WHERE id = 'poi-015';
UPDATE pois SET name = '{"ru": "Тропа чудес в Кадаргаване", "en": "Kadargavan Trail of Wonders"}'::jsonb, category = 'culture'::poi_category, subcategory = 'history', cuisine_type = NULL, location = '{"lat": 42.880715, "lng": 44.325191, "address": {"ru": "каньон реки СО Алания 1 км от Дзивгисской крепости, Верхний Фиагдон, Респ. Северная Осетия — Алания, Россия, 363203", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Металлический мостик над 60-метровым каньоном — идёшь и смотришь вниз сквозь решётку под ногами.", "en": "A metal walkway above a 60-meter canyon — you walk and look straight down through the grating beneath your feet."}, "medium": {"ru": "Тропа чудес в Куртатинском ущелье — навесная конструкция над каньоном реки Фиагдон. Перила, сетчатый пол, 60 м обрыва под ногами. На выходе — скульптура «Зеркальный барс», символ Республики. Маршрут короткий (около 500 м), но впечатляющий даже для тех, кто не боится высоты.", "en": "The Trail of Wonders in the Kurtatinsky gorge is a suspended structure above the Fiagdon river canyon. Railings, mesh floor, 60 m drop below your feet. At the end — the Mirror Leopard sculpture, symbol of the Republic. The route is short (about 500 m) but impressive even for those with no fear of heights."}, "full": {"ru": "Тропа чудес — это несколько сотен метров металлической конструкции, прикреплённой к скале над каньоном реки Фиагдон. Пол — решётка, сквозь которую видно обрыв в 60 метров. Идёшь медленно, держишься за перила, смотришь вниз — и там, в узкой щели каньона, белая пена реки. Стены каньона почти смыкаются над головой. Для людей с акрофобией это будет испытанием. Для остальных — одно из самых необычных ощущений в Осетии. В конце тропы стоит «Зеркальный барс» — полированная скульптура, в которой отражается ущелье. Тропа короткая, но её не забываешь.", "en": "The Trail of Wonders is a few hundred meters of metal structure attached to the cliff above the Fiagdon river canyon. The floor is a grating through which you can see the 60-meter drop. You walk slowly, grip the railings, look down — and there, in the narrow canyon cleft, is the white foam of the river. The canyon walls almost close overhead. For people with acrophobia, this will be a challenge. For everyone else — one of the most unusual sensations in Ossetia. At the trail''s end stands the Mirror Leopard — a polished sculpture that reflects the gorge. The trail is short, but you don''t forget it."}}'::jsonb, photos = ARRAY['/images/pois/kadargavan-trail-of-wonders_gp.webp','/images/pois/tropa-chudes-v-kadargavane_2.webp','/images/pois/tropa-chudes-v-kadargavane_3.webp','/images/pois/tropa-chudes-v-kadargavane_4.webp','/images/pois/tropa-chudes-v-kadargavane_5.webp']::text[], rating = 4.5, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['culture','history']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 80, review_count = 722, updated_at = now() WHERE id = 'poi-016';
UPDATE pois SET name = '{"ru": "Памятник Уастырджи", "en": "Uastyrdzhi Monument"}'::jsonb, category = 'attractions'::poi_category, subcategory = 'monument', cuisine_type = NULL, location = '{"lat": 42.958886, "lng": 44.211809, "address": {"ru": "Респ. Северная Осетия — Алания, Россия, 363213", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "28-тонный всадник, вырывающийся из скалы на полном скаку — самая невероятная статуя, которую вы когда-либо видели с дороги.", "en": "A 28-ton rider bursting from the cliff at full gallop — the most astonishing roadside statue you''ll ever see."}, "medium": {"ru": "Памятник Уастырджи (1995, скульптор Дзантиев) — 28-тонная бронзовая фигура всадника на коне, будто вырывающегося из скалы на высоте 22 м. Уастырджи — осетинский небесный покровитель мужчин и путников, образ которого слился за века с образом Святого Георгия. Статуя стоит над Алагирским ущельем по дороге в горы.", "en": "The Uastyrdzhi Monument (1995, sculptor Dzantiev) is a 28-ton bronze rider on horseback, appearing to burst from the cliff at 22 m height. Uastyrdzhi is the Ossetian heavenly patron of men and travelers, whose image merged over centuries with that of Saint George. The statue stands above the Alagir gorge on the mountain road."}, "full": {"ru": "Едешь по Транскавказской магистрали в горы — и вдруг из скалы, буквально из камня, вырывается всадник. Огромный, бронзовый, 28 тонн. Конь в галопе, плащ за спиной, взгляд вперёд. Уастырджи — осетинский небесный покровитель мужчин, воинов и путников, образ которого слился за века с образом Святого Георгия. По преданию, именно он помогает людям в дороге и карает несправедливость. Монумент создал скульптор Николай Дзантиев в 1995 году. Конструкция крепится к скале единственной точкой опоры — задними ногами коня. Технически это чудо инженерии. Эстетически — просто чудо. Остановитесь и запрокиньте голову: на 22-метровой высоте этот всадник выглядит совсем иначе, чем с дороги.", "en": "You''re driving down the Trans-Caucasian Highway toward the mountains — and suddenly a horseman bursts from the cliff, literally from the stone. Enormous, bronze, 28 tons. Horse at full gallop, cloak streaming back, gaze fixed ahead. Uastyrdzhi is the Ossetian heavenly patron of men, warriors, and travelers, whose image merged over centuries with that of Saint George. According to tradition, he helps people on their journeys and punishes injustice. The monument was created by sculptor Nikolai Dzantiev in 1995. The entire structure is anchored to the cliff at a single point — the horse''s hind legs. Technically it''s an engineering marvel. Aesthetically — simply a marvel. Stop and tilt your head back: at 22 meters height this rider looks entirely different from the road."}}'::jsonb, photos = ARRAY['/images/pois/uastyrdzhi-monument_gp.webp','/images/pois/pamyatnik-uastyrdzhi_2.webp','/images/pois/pamyatnik-uastyrdzhi_3.webp','/images/pois/pamyatnik-uastyrdzhi_4.webp','/images/pois/pamyatnik-uastyrdzhi_5.webp','/images/pois/pamyatnik-uastyrdzhi_6.webp','/images/pois/pamyatnik-uastyrdzhi_7.webp']::text[], rating = 4.9, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['attractions','monument']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 100, review_count = 574, updated_at = now() WHERE id = 'poi-017';
UPDATE pois SET name = '{"ru": "«Город ангелов» (мемориал Беслана)", "en": "City of Angels (Beslan Memorial)"}'::jsonb, category = 'culture'::poi_category, subcategory = 'memorial', cuisine_type = NULL, location = '{"lat": 43.19367, "lng": 44.548436, "address": {"ru": "Беслан, Респ. Северная Осетия — Алания, Россия, 363023", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "266 могил детей и взрослых, погибших в теракте 2004 года. Самое тихое и самое тяжёлое место в Осетии.", "en": "266 graves of children and adults killed in the 2004 terror attack. The quietest and heaviest place in Ossetia."}, "medium": {"ru": "Мемориальное кладбище жертв захвата школы в Беслане (1–3 сентября 2004 г.) — 266 захоронений, из которых 186 детские. Рядом — руины спортзала школы № 1, превращённые в мемориал с фотографиями и игрушками. Это не туристическое место — это место памяти, куда приходят с уважением и тишиной.", "en": "The memorial cemetery for victims of the Beslan school siege (September 1–3, 2004) holds 266 graves, 186 of them children''s. Nearby — the ruins of School No. 1''s gymnasium, converted into a memorial with photographs and toys. This is not a tourist attraction — it''s a place of remembrance, approached with respect and silence."}, "full": {"ru": "1 сентября 2004 года в первый день учёбы террористы захватили школу № 1 в Беслане. Три дня. Более 1100 заложников, большинство — дети. 334 погибших, в том числе 186 детей. «Город ангелов» — так называют мемориальное кладбище, где они похоронены. Белые плиты с фотографиями, детские игрушки, живые цветы — люди приносят их постоянно, двадцать лет спустя. Рядом стоит руина спортзала, где всё и произошло: её не снесли, оставили как есть, только накрыли стеклянным куполом. Внутри — венки, иконы, бутылки с водой (заложники умирали от жажды). Идти сюда нужно медленно и молча. Фотографировать — только если чувствуете уважение в каждом кадре.", "en": "On September 1, 2004, the first day of school, terrorists seized School No. 1 in Beslan. Three days. More than 1,100 hostages, most of them children. 334 killed, including 186 children. ''City of Angels'' is what they call the memorial cemetery where they are buried. White stone markers with photographs, children''s toys, fresh flowers — people bring them constantly, twenty years later. Nearby stands the ruin of the gymnasium where it all happened: it wasn''t demolished, left as it was, only covered with a glass dome. Inside — wreaths, icons, bottles of water (the hostages were dying of thirst). Come here slowly and in silence. Photograph only if you feel respect in every frame."}}'::jsonb, photos = ARRAY['/images/pois/city-of-angels-(beslan-memorial)_gp.webp','/images/pois/gorod-angelov-memorial-beslana_2.webp','/images/pois/gorod-angelov-memorial-beslana_3.webp','/images/pois/gorod-angelov-memorial-beslana_4.webp']::text[], rating = 4.5, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['culture','memorial']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 80, review_count = 8, updated_at = now() WHERE id = 'poi-018';
UPDATE pois SET name = '{"ru": "Памятник Сергею Бодрову", "en": "Sergei Bodrov Memorial"}'::jsonb, category = 'culture'::poi_category, subcategory = 'memorial', cuisine_type = NULL, location = '{"lat": 42.871243, "lng": 44.52022, "address": {"ru": "Р299, Респ. Северная Осетия — Алания, Россия, 363125", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Скромный мемориал у Гизели — место, где Осетия прощается с теми, кого ледник Колка забрал в 2002 году.", "en": "A modest memorial near Gizel — the place where Ossetia says goodbye to those the Kolka glacier took in 2002."}, "medium": {"ru": "Мемориал у посёлка Гизель посвящён 125 жертвам схода ледника Колка 20 сентября 2002 года. Среди них — Сергей Бодров-младший, актёр и режиссёр, снимавший здесь фильм, и вся его съёмочная группа. Монумент стоит как напоминание о том, что горы непредсказуемы даже для тех, кто их знает.", "en": "The memorial near Gizel is dedicated to the 125 victims of the Kolka glacier collapse on September 20, 2002. Among them — Sergei Bodrov Jr., actor and director filming his movie here, and his entire crew. The monument stands as a reminder that mountains are unpredictable even for those who know them."}, "full": {"ru": "Сергей Бодров-младший был, пожалуй, самым любимым актёром своего поколения в России. «Брат», «Брат 2» — его лицо знала вся страна. 20 сентября 2002 года он снимал в Кармадонском ущелье. Ледник Колка сошёл внезапно. Бодров и вся его съёмочная группа — около 40 человек — погибли. Всего в катастрофе погибло 125 человек. Тела многих не нашли до сих пор. Мемориал у Гизели — небольшой, без помпы. Плита, имена, фотографии. Рядом всегда цветы. Сюда приходят разные люди: те, кто потерял близких в трагедии, и те, кто просто помнит Бодрова. Иногда это одни и те же люди.", "en": "Sergei Bodrov Jr. was perhaps the most beloved actor of his generation in Russia. «Brother», «Brother 2» — his face was known across the country. On September 20, 2002, he was filming in the Karmadon gorge. The Kolka glacier surged without warning. Bodrov and his entire film crew — around 40 people — died. In total, 125 people perished in the disaster. The bodies of many have never been found. The memorial near Gizel is modest, without ceremony. A plaque, names, photographs. There are always flowers nearby. Different people come here: those who lost loved ones in the tragedy, and those who simply remember Bodrov. Sometimes these are the same people."}}'::jsonb, photos = ARRAY['/images/pois/sergei-bodrov-memorial_gp.webp','/images/pois/pamyatnik-sergeyu-bodrovu_2.webp','/images/pois/pamyatnik-sergeyu-bodrovu_3.webp']::text[], rating = 4.9, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['culture','memorial']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 80, review_count = 196, updated_at = now() WHERE id = 'poi-019';
UPDATE pois SET name = '{"ru": "Фонтан «Нарт Сослан»", "en": "Nart Soslan Fountain"}'::jsonb, category = 'attractions'::poi_category, subcategory = 'monument', cuisine_type = NULL, location = '{"lat": 43.029934, "lng": 44.68009, "address": {"ru": "пр. Мира, 25, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362040", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Осетинский Геракл на главной площади Владикавказа — герой нартского эпоса верхом на солнечном колесе.", "en": "Ossetia''s Hercules in the center of Vladikavkaz — the Nart epic hero astride the wheel of the sun."}, "medium": {"ru": "Фонтан на центральной площади изображает Сослана — богатыря нартского эпоса, одного из главных героев осетинской мифологии. По легенде, его закалили в волчьем молоке. Фонтан служит традиционным местом встречи владикавказцев: «у Нарта» — привычная точка навигации в городе.", "en": "The fountain in the central square depicts Soslan — the champion of the Nart epic, one of the central heroes of Ossetian mythology. According to legend, he was tempered in wolf''s milk. The fountain serves as a traditional meeting point for Vladikavkaz residents: ''at the Nart'' is a common city navigation reference."}, "full": {"ru": "У осетин есть свой эпос — нартовский, древний, как горы вокруг. Сослан — один из его главных героев. Непобедимый воин, закалённый в волчьем молоке, герой невозможных подвигов. На центральной площади Владикавказа он стоит в виде фонтана: бронзовая фигура на чаше Уацамонга, которая в солнечный день отражает небо и проходящих людей. Местные давно присвоили ему просто «Нарт» — и теперь «встретимся у Нарта» означает «на площади». Так фонтан стал навигационной точкой города, личным мифом горожан и просто красивым местом для фото на фоне Столовой горы.", "en": "Ossetia has its own epic — the Nart cycle, ancient as the surrounding mountains. Soslan is one of its main heroes: an invincible warrior tempered in wolf''s milk, a champion of impossible feats. In the central square of Vladikavkaz he stands as a fountain — a bronze figure atop the Uatsamonga bowl that on sunny days reflects the sky and passing people. Locals long ago shortened it to just ''the Nart'' — so now ''meet me at the Nart'' means ''at the square.'' Thus the fountain became a city navigation point, a personal myth for the townspeople, and simply a beautiful place for photos with Table Mountain in the background."}}'::jsonb, photos = ARRAY['/images/pois/nart-soslan-fountain_gp.webp','/images/pois/fontan-nart-soslan_2.webp','/images/pois/fontan-nart-soslan_3.webp','/images/pois/fontan-nart-soslan_4.webp']::text[], rating = 4.5, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['attractions','monument']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 100, review_count = 8, updated_at = now() WHERE id = 'poi-020';
UPDATE pois SET name = '{"ru": "Аланский Свято-Успенский монастырь", "en": "Alansky Holy Dormition Monastery"}'::jsonb, category = 'culture'::poi_category, subcategory = 'religion', cuisine_type = NULL, location = '{"lat": 42.821863, "lng": 44.274735, "address": {"ru": "Хидикус, Респ. Северная Осетия — Алания, Россия, 363203", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Самый высокогорный православный монастырь России — и, говорят, самый южный. Открыт в 2000 году, уже стал намоленным местом.", "en": "Russia''s highest-altitude Orthodox monastery — and reportedly its southernmost. Founded in 2000, already a place of deep prayer."}, "medium": {"ru": "Аланский Свято-Успенский монастырь основан в 2000 году в Куртатинском ущелье на высоте около 1278 м. Считается самым высокогорным и самым южным православным монастырём в России. В кельях живут монахи, принимают паломников. Рядом — целебные источники и старинные башни. Открыт для посещения, службы проводятся.", "en": "The Alanian Holy Dormition Monastery was founded in 2000 in the Kurtatinsky gorge at about 1,278 m. It is considered Russia''s highest-altitude and southernmost Orthodox monastery. Monks live in the cells and receive pilgrims. Nearby — healing springs and ancient towers. Open to visitors, services held."}, "full": {"ru": "Монастырь новый — основан в 2000 году. Но место вокруг него древнее: горы Куртатины видели аланские племена, татаро-монгольские набеги, чуму, советскую власть. Белые стены монастыря на этом фоне выглядят одновременно хрупкими и непреклонными. Монастырь носит звание самого высокогорного православного в России и, по ряду данных, самого южного. Братия небольшая, принимают паломников. Рядом — источник, который местные считают целебным; к нему всегда стоят несколько машин. По дороге от монастыря видны башни, о которых никто не расскажет экскурсию — просто стоят и смотрят. Место для тишины и долгих мыслей.", "en": "The monastery is new — founded in 2000. But the surrounding place is ancient: the Kurtatinsky mountains have seen Alanian tribes, Mongol raids, plague, Soviet rule. The monastery''s white walls against this backdrop look simultaneously fragile and unyielding. The monastery holds the title of Russia''s highest-altitude Orthodox monastery and, by some accounts, its southernmost. The brotherhood is small; they receive pilgrims. Nearby — a spring the locals consider healing; there are always a few cars parked beside it. Along the road from the monastery, towers stand that no one will give you a guided talk about — they simply stand and watch. A place for silence and long thoughts."}}'::jsonb, photos = ARRAY['/images/pois/alansky-holy-dormition-monastery_gp.webp','/images/pois/alanskiy-svyato-uspenskiy-monastyr_2.webp','/images/pois/alanskiy-svyato-uspenskiy-monastyr_3.webp','/images/pois/alanskiy-svyato-uspenskiy-monastyr_4.webp','/images/pois/alanskiy-svyato-uspenskiy-monastyr_5.webp','/images/pois/alanskiy-svyato-uspenskiy-monastyr_6.webp']::text[], rating = 4.8, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['culture','religion']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 80, review_count = 333, updated_at = now() WHERE id = 'poi-022';
UPDATE pois SET name = '{"ru": "Суннитская мечеть Мухтарова", "en": "Mukhtarov Mosque"}'::jsonb, category = 'culture'::poi_category, subcategory = 'religion', cuisine_type = NULL, location = '{"lat": 43.025949, "lng": 44.675909, "address": {"ru": "ул. Коцоева, 62, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362008", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Мечеть 1908 года в египетском стиле — подарок бакинского нефтяного магната, красивейшее здание на берегу Терека.", "en": "A 1908 mosque in Egyptian style — a gift from a Baku oil magnate, the most beautiful building on the Terek''s bank."}, "medium": {"ru": "Суннитская мечеть Мухтарова построена в 1908 г. на средства бакинского миллионера Мурцы-Аги Мухтарова. Архитектор — польский инженер Иосиф Плошко. Стиль — египетский мамлюкский неоклассицизм. Два минарета высотой 28 м. Вмещает 600 молящихся. Расположена на проспекте Мира у берега Терека — одна из главных открыточных достопримечательностей Владикавказа.", "en": "The Mukhtarov Sunni Mosque was built in 1908 with funds from Baku millionaire Murtaza-Agha Mukhtarov. The architect was Polish engineer Jozef Ploshko. Style — Egyptian Mamluk neoclassicism. Two minarets 28 m high. Capacity 600 worshippers. Located on Prospekt Mira at the Terek bank — one of Vladikavkaz''s main postcard attractions."}, "full": {"ru": "В 1908 году бакинский нефтяной магнат Мурцы-Ага Мухтаров приехал во Владикавказ и увидел, что городской мусульманской общине негде молиться достойно. Он нанял польского архитектора Иосифа Плошко и выделил деньги без ограничений. Плошко спроектировал мечеть в египетском мамлюкском стиле — с двумя 28-метровыми минаретами, тонкой арабской вязью на фасадах, куполами цвета оливы. Результат стоит на берегу Терека уже больше ста лет и всё ещё останавливает взгляд. В советское время мечеть была закрыта и использовалась как склад. В 1990-х вернули верующим. Сейчас вмещает 600 молящихся; ежедневные службы. Немусульманам — вход с соблюдением дресс-кода.", "en": "In 1908, Baku oil magnate Murtaza-Agha Mukhtarov came to Vladikavkaz and saw that the city''s Muslim community had nowhere worthy to pray. He hired Polish architect Jozef Ploshko and provided funds without limit. Ploshko designed the mosque in Egyptian Mamluk style — with two 28-meter minarets, fine Arabic calligraphy on the facades, olive-colored domes. The result has stood on the Terek bank for more than a hundred years and still stops the eye. During Soviet times the mosque was closed and used as a warehouse. In the 1990s it was returned to worshippers. Now it holds 600 worshippers; daily services. Non-Muslims — entry permitted with dress code observed."}}'::jsonb, photos = ARRAY['/images/pois/mukhtarov-mosque_gp.webp','/images/pois/sunnitskaya-mechet-muhtarova_2.webp','/images/pois/sunnitskaya-mechet-muhtarova_3.webp','/images/pois/sunnitskaya-mechet-muhtarova_4.webp','/images/pois/sunnitskaya-mechet-muhtarova_5.webp']::text[], rating = 4.8, hours = NULL, phone = '+7 867 225-77-73', website = NULL, price_level = NULL, tags = ARRAY['culture','religion']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 80, review_count = 794, updated_at = now() WHERE id = 'poi-023';
UPDATE pois SET name = '{"ru": "Церковь Св. Григория Просветителя", "en": "Armenian Church of St. Gregory the Illuminator"}'::jsonb, category = 'attractions'::poi_category, subcategory = 'religion', cuisine_type = NULL, location = '{"lat": 43.022346, "lng": 44.681453, "address": {"ru": "Армянская ул., 1, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362007", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Армянская церковь 1868 года — маленький кусочек Армении на владикавказском берегу Терека.", "en": "An Armenian church from 1868 — a small piece of Armenia on the Vladikavkaz bank of the Terek."}, "medium": {"ru": "Армянская апостольская церковь Святого Григория Просветителя построена в 1868 году. Владикавказская армянская община — одна из старейших в городе; армяне жили здесь с основания крепости. Церковь с колокольней стоит на правом берегу Терека, неподалёку от мечети Мухтарова — два культовых здания разных конфессий смотрят почти друг на друга.", "en": "The Armenian Apostolic Church of Saint Gregory the Illuminator was built in 1868. The Vladikavkaz Armenian community is one of the city''s oldest; Armenians lived here from the fortress''s founding. The church with its bell tower stands on the right bank of the Terek, near the Mukhtarov Mosque — two places of worship of different faiths facing nearly each other."}, "full": {"ru": "Армяне во Владикавказе — с самого начала. Когда в 1784 году здесь заложили крепость, армянские купцы и ремесленники были среди первых гражданских жителей. К 1868 году община выросла настолько, что построила собственную церковь — Святого Григория Просветителя, крестителя Армении. Небольшая, строгая, с тёмным туфовым фасадом и звонницей, она стоит на берегу Терека в нескольких минутах ходьбы от мечети Мухтарова. Армянская церковь и суннитская мечеть смотрят почти друг на друга через улицу — и это не противоречие, это портрет Владикавказа: города, где много народов жили рядом веками.", "en": "Armenians have been in Vladikavkaz from the very beginning. When the fortress was laid down in 1784, Armenian merchants and craftsmen were among the first civilian residents. By 1868 the community had grown enough to build its own church — Saint Gregory the Illuminator, the baptizer of Armenia. Small, austere, with a dark tufa facade and bell tower, it stands on the Terek bank a few minutes'' walk from the Mukhtarov Mosque. An Armenian church and a Sunni mosque face nearly each other across the street — this isn''t a contradiction, it''s a portrait of Vladikavkaz: a city where many peoples have lived side by side for centuries."}}'::jsonb, photos = ARRAY['/images/pois/armenian-church-of-st.-gregory-the-illum_gp.webp','/images/pois/tserkov-sv-grigoriya-prosvetitelya_2.webp','/images/pois/tserkov-sv-grigoriya-prosvetitelya_3.webp','/images/pois/tserkov-sv-grigoriya-prosvetitelya_4.webp','/images/pois/tserkov-sv-grigoriya-prosvetitelya_5.webp','/images/pois/tserkov-sv-grigoriya-prosvetitelya_6.webp','/images/pois/tserkov-sv-grigoriya-prosvetitelya_7.webp']::text[], rating = 4.8, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['culture','religion']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 100, review_count = 89, updated_at = now() WHERE id = 'poi-024';
UPDATE pois SET name = '{"ru": "Свято-Георгиевский собор", "en": "St. George''s Cathedral"}'::jsonb, category = 'attractions'::poi_category, subcategory = 'religion', cuisine_type = NULL, location = '{"lat": 43.030018, "lng": 44.662067, "address": {"ru": "ул. Барбашова, 38, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362020", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Золотые купола над Владикавказом — новый кафедральный собор, ставший символом возрождения осетинского православия.", "en": "Golden domes over Vladikavkaz — the new cathedral that became a symbol of Ossetian Orthodox revival."}, "medium": {"ru": "Свято-Георгиевский собор открыт в 2010 году как главный православный храм Владикавказской епархии. Вмещает до 3000 человек. Пятиглавый, с золотыми куполами, построен в неовизантийском стиле. Расположен в центре города; в ясную погоду купола видны с многих точек Владикавказа.", "en": "Saint George''s Cathedral opened in 2010 as the main Orthodox church of the Vladikavkaz diocese. Capacity up to 3,000 people. Five-domed, with golden domes, built in neo-Byzantine style. Located in the city center; on clear days the domes are visible from many points in Vladikavkaz."}, "full": {"ru": "В советское время многие церкви Осетии были закрыты, снесены или перепрофилированы. Православие в республике восстанавливалось медленно и с трудом. Свято-Георгиевский собор, открытый в 2010 году, стал главным знаком этого восстановления: пятиглавый, золотой, вмещает три тысячи молящихся. Внутри — просторно и светло, иконостас новый, роспись ещё свежая. Снаружи купола видны с набережной, с проспекта Мира, с дороги на выезде из города. Собор посвящён Святому Георгию — покровителю Осетии, чей образ неотделим здесь от образа Уастырджи, небесного всадника осетинской мифологии. Это место для верующих, но и для всех, кому интересно понять, как православие переплелось в Осетии с местной традицией.", "en": "During Soviet times, many of Ossetia''s churches were closed, demolished, or repurposed. Orthodoxy in the republic recovered slowly and with difficulty. Saint George''s Cathedral, opened in 2010, became the main sign of that recovery: five-domed, golden, capacity three thousand worshippers. Inside — spacious and bright, the iconostasis is new, the frescoes are still fresh. Outside, the domes are visible from the embankment, from Prospekt Mira, from the road leaving the city. The cathedral is dedicated to Saint George — Ossetia''s patron, whose image here is inseparable from that of Uastyrdzhi, the celestial rider of Ossetian mythology. This is a place for believers, but also for anyone curious to understand how Orthodoxy intertwined with local tradition in Ossetia."}}'::jsonb, photos = ARRAY['/images/pois/st.-georges-cathedral_gp.webp','/images/pois/svyato-georgievskiy-sobor_2.webp','/images/pois/svyato-georgievskiy-sobor_3.webp','/images/pois/svyato-georgievskiy-sobor_4.webp']::text[], rating = 4.6, hours = '{"mon": "08:00-18:00", "tue": "08:00-18:00", "wed": "08:00-18:00", "thu": "08:00-18:00", "fri": "08:00-18:00", "sat": "08:00-19:00"}'::jsonb, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['culture','religion']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 100, review_count = 52, updated_at = now() WHERE id = 'poi-025';
UPDATE pois SET name = '{"ru": "Проспект Мира", "en": "Prospekt Mira (Peace Avenue)"}'::jsonb, category = 'attractions'::poi_category, subcategory = 'city', cuisine_type = NULL, location = '{"lat": 43.029756, "lng": 44.680462, "address": {"ru": "пр. Мира, Владикавказ, Респ. Северная Осетия — Алания, Россия", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Главная улица Владикавказа — исторические дома, горные виды в конце улицы и лучший осетинский пирог в радиусе ста метров.", "en": "Vladikavkaz''s main street — historic buildings, mountain views at the far end, and the best Ossetian pie within a hundred meters."}, "medium": {"ru": "Проспект Мира — пешеходный центр Владикавказа протяжённостью около 1 км. Историческая застройка XIX–XX вв., мечеть Мухтарова, Национальный и Художественный музеи, театр Вахтангова — всё в пешей доступности. Проспект заканчивается у парка им. Хетагурова. Особенно красив вечером, когда в конце улицы видны освещённые горы.", "en": "Prospekt Mira is the pedestrian center of Vladikavkaz, about 1 km long. Historic XIX–XX c. architecture, the Mukhtarov Mosque, the National and Art Museums, Vakhtangov Theatre — all within walking distance. The prospekt ends at Khetagurov Park. Especially beautiful in the evening, when the illuminated mountains are visible at the street''s far end."}, "full": {"ru": "Проспект Мира — это километр между горами и вечером. Начинается от площади с Нарт Сосланом, проходит мимо старых доходных домов, мечети Мухтарова, двух музеев и театра Вахтангова, заканчивается парком. Всё, что нужно знать о характере города, написано в этих фасадах: эклектика XIX века соседствует с советским конструктивизмом, а между ними — кафе с осетинскими пирогами и цветочный ларёк, который, кажется, стоит здесь сто лет. Вечером улица особенно хороша. Когда солнце садится за хребет, в конце проспекта золотеют горы — Столовая и её соседи. Это вид, который фотографируют все и который одинаково впечатляет каждый раз.", "en": "Prospekt Mira is one kilometer between mountains and evening. It begins at the square with the Nart Soslan, passes old apartment buildings, the Mukhtarov Mosque, two museums and the Vakhtangov Theatre, and ends at the park. Everything you need to know about this city''s character is written in these facades: XIX century eclecticism stands beside Soviet constructivism, and somewhere between them — a café serving Ossetian pies and a flower stall that seems to have stood here for a hundred years. In the evening the street is especially beautiful. When the sun sets behind the ridge, the mountains at the far end of the prospekt turn gold — Table Mountain and her neighbors. It''s a view everyone photographs, and it impresses every time."}}'::jsonb, photos = ARRAY['/images/pois/prospekt-mira-(peace-avenue)_gp.webp','/images/pois/prospekt-mira_2.webp','/images/pois/prospekt-mira_3.webp','/images/pois/prospekt-mira_4.webp','/images/pois/prospekt-mira_5.webp','/images/pois/prospekt-mira_6.webp','/images/pois/prospekt-mira_7.webp','/images/pois/prospekt-mira_8.webp','/images/pois/prospekt-mira_9.webp','/images/pois/prospekt-mira_10.webp','/images/pois/prospekt-mira_11.webp','/images/pois/prospekt-mira_12.webp','/images/pois/prospekt-mira_13.webp']::text[], rating = 4.3, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['attractions','city']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 100, review_count = 104, updated_at = now() WHERE id = 'poi-027';
UPDATE pois SET name = '{"ru": "Набережная реки Терек", "en": "Terek River Embankment"}'::jsonb, category = 'attractions'::poi_category, subcategory = 'city', cuisine_type = NULL, location = '{"lat": 43.04735, "lng": 44.660679, "address": {"ru": "ул. Кесаева, 154, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362020", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "1.6 км вдоль горной реки — с керамическими панно, видом на мечеть и Столовую гору, и Тереком, который шумит всегда.", "en": "1.6 km along a mountain river — ceramic murals, views of the mosque and Table Mountain, and the Terek that''s always roaring."}, "medium": {"ru": "Набережная Владикавказа (1.6 км) тянется вдоль Терека от пр. Коста до моста у Нартовской. Декорирована керамическими панно с мотивами осетинской культуры. Вдоль берега открываются виды на мечеть Мухтарова и Столовую гору. Вечером и в выходные — популярное место прогулок; много лавочек и фонарей.", "en": "Vladikavkaz''s embankment (1.6 km) runs along the Terek from Prospekt Kosta to the bridge near Nartovskaya. Decorated with ceramic murals featuring Ossetian cultural motifs. Along the bank, views open to the Mukhtarov Mosque and Table Mountain. In evenings and on weekends — a popular walking spot; many benches and lanterns."}, "full": {"ru": "Терек в Владикавказе не такой, как в Моздоке или Кизляре. Здесь он молодой — только что выбежал из ущелья, мутно-зелёный, быстрый, шумный. Набережная вдоль него — 1.6 км удовольствия. Под ногами — плитка, вдоль бортика — керамические панно с нартовскими сюжетами и осетинскими орнаментами. По правую руку — Мухтаровская мечеть с минаретами. По левую — Столовая гора, если повернуть голову. Вечером здесь гуляют парами и компаниями, кормят уток, едят мороженое. Это не аттракцион — это жизнь города, которую просто приятно наблюдать.", "en": "The Terek in Vladikavkaz isn''t the same river as in Mozdok or Kizlyar. Here it''s young — just emerged from the gorge, murky green, fast, noisy. The embankment along it is 1.6 km of pleasure. Underfoot — paving stones; along the railing — ceramic panels with Nart scenes and Ossetian patterns. To the right — the Mukhtarov Mosque with its minarets. To the left — Table Mountain, if you turn your head. In the evening people stroll here in pairs and groups, feed ducks, eat ice cream. It''s not an attraction — it''s the city''s life, which is simply pleasant to watch."}}'::jsonb, photos = ARRAY['/images/pois/terek-river-embankment_gp.webp','/images/pois/naberezhnaya-reki-terek_2.webp','/images/pois/naberezhnaya-reki-terek_3.webp','/images/pois/naberezhnaya-reki-terek_4.webp','/images/pois/naberezhnaya-reki-terek_5.webp','/images/pois/naberezhnaya-reki-terek_6.webp','/images/pois/naberezhnaya-reki-terek_7.webp','/images/pois/naberezhnaya-reki-terek_8.webp','/images/pois/naberezhnaya-reki-terek_9.webp']::text[], rating = 4.5, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['attractions','city']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 100, review_count = 1417, updated_at = now() WHERE id = 'poi-028';
UPDATE pois SET name = '{"ru": "Парк им. Коста Хетагурова", "en": "Kosta Khetagurov Park"}'::jsonb, category = 'attractions'::poi_category, subcategory = 'city', cuisine_type = NULL, location = '{"lat": 43.026118, "lng": 44.678954, "address": {"ru": "пр. Мира, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362040", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Главный парк Владикавказа: фонтаны, скульптуры, аттракционы — и памятник Коста, чьи стихи знает каждый осетин.", "en": "Vladikavkaz''s main park: fountains, sculptures, rides — and the monument to Kosta, whose poems every Ossetian knows."}, "medium": {"ru": "Парк им. Коста Хетагурова у конца проспекта Мира — многоуровневый, с фонтанами, скульптурами, летней эстрадой и детскими аттракционами. Назван в честь Коста Хетагурова (1859–1906) — основоположника осетинской литературы, поэта и художника. В центре парка — его памятник.", "en": "The Kosta Khetagurov Park at the end of Prospekt Mira is multi-level, with fountains, sculptures, a summer stage, and children''s rides. Named for Kosta Khetagurov (1859–1906) — the founder of Ossetian literature, a poet and artist. His monument stands in the park''s center."}, "full": {"ru": "Коста Хетагуров — для Осетии примерно то же, что Пушкин для России: поэт-основатель, создавший язык, на котором народ заговорил о себе самом. Его «Осетинская лира», его публицистика, его картины — это не школьная программа, это живая часть идентичности. В парке его имени хорошо в любое время дня. Утром — пустынно и тихо, только фонтаны. Днём — мамы с колясками и дедушки на лавочках. Вечером — гуляющие после проспекта. Парк спускается террасами к реке, и где-то на среднем уровне стоит сам Коста — в бронзе, с книгой, смотрит куда-то в сторону гор. Вероятно, пишет.", "en": "Kosta Khetagurov is to Ossetia roughly what Pushkin is to Russia: the founding poet who created the language through which a people spoke about themselves. His ''Ossetian Lyre,'' his journalism, his paintings — these aren''t a school curriculum, they''re a living part of identity. The park bearing his name is pleasant at any time of day. In the morning — deserted and quiet, only fountains. At midday — mothers with strollers and grandfathers on benches. In the evening — people walking after the prospekt. The park descends in terraces toward the river, and somewhere on the middle level stands Kosta himself — in bronze, with a book, looking somewhere toward the mountains. Probably writing."}}'::jsonb, photos = ARRAY['/images/pois/kosta-khetagurov-park_entrance.webp','/images/pois/kosta-khetagurov-park_swan.webp','/images/pois/kosta-khetagurov-park_statue.webp','/images/pois/kosta-khetagurov-park_view.webp','/images/pois/park-im-kosta-hetagurova_gp.webp','/images/pois/park-im-kosta-hetagurova_2.webp','/images/pois/park-im-kosta-hetagurova_3.webp','/images/pois/park-im-kosta-hetagurova_4.webp','/images/pois/park-im-kosta-hetagurova_5.webp','/images/pois/park-im-kosta-hetagurova_6.webp','/images/pois/park-im-kosta-hetagurova_7.webp','/images/pois/park-im-kosta-hetagurova_8.webp']::text[], rating = 4.6, hours = '{"sun": "07:00-21:00", "mon": "07:00-21:00", "tue": "07:00-21:00", "wed": "07:00-21:00", "thu": "07:00-21:00", "fri": "07:00-21:00", "sat": "07:00-21:00"}'::jsonb, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['attractions','city']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 100, review_count = 4516, updated_at = now() WHERE id = 'poi-029';
UPDATE pois SET name = '{"ru": "Национальный музей РСО-Алания", "en": "National Museum of North Ossetia-Alania"}'::jsonb, category = 'museums'::poi_category, subcategory = 'culture', cuisine_type = NULL, location = '{"lat": 43.027358, "lng": 44.68062, "address": {"ru": "пр. Мира, 11, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362040", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Старейший музей республики, основанный в 1893 году. Кобанская бронза, аланские мечи, скифо-сарматские украшения и осетинская этнография — всё под одной крышей.", "en": "The republic''s oldest museum, founded in 1893. Koban bronzes, Alanian swords, Scythian-Sarmatian jewellery and Ossetian ethnography — all under one roof."}, "medium": {"ru": "Национальный музей РСО-Алания (пр. Мира, 11) — главный краеведческий музей республики, основанный в 1893 году. После масштабной реконструкции открылся в 2020 году в историческом особняке купца Ходякова. Коллекции: кобанская культура, скифо-сарматские древности, история Алании, осетинская этнография. Более 5000 единиц хранения. Открыт вт–вс.", "en": "The National Museum of North Ossetia-Alania (11 Prospekt Mira) is the republic''s main regional museum. Permanent exhibitions: paleontology, zoology, history from the Stone Age to the XX c., Ossetian ethnography. The Scythian-Sarmatian collection is especially impressive. More than 4,000 holdings. Open Tue–Sun."}, "full": {"ru": "Если хотите понять Осетию глубже, чем позволяют горы и пироги, — идите в Национальный музей. Основанный в 1893 году, он хранит то, что нельзя объяснить на улице: украшения из кобанских курганов, аланские мечи, скифо-сарматские золотые изделия, осетинские национальные костюмы с тончайшей ручной вышивкой. Несколько залов, несколько эпох. Этнографический раздел особенно атмосферен — войлочные ковры, старинная одежда, подробная модель традиционного осетинского каменного дома. После масштабной реконструкции музей вновь открылся в 2020 году в историческом особняке купца Ходякова. Это музей не парадный — тихий и вдумчивый. Сюда можно прийти на час и остаться на три. Вход недорогой, экскурсоводы знают своё дело.", "en": "If you want to understand Ossetia more deeply than mountains and pies allow — go to the National Museum. Here is what can''t be explained on the street: jewelry from Koban burial mounds, Alanian swords, Christian icons from the pre-Christian era, Soviet posters in the Ossetian language. Four thousand objects, several floors. The paleontology hall with mammoths stands beside ethnography — felt carpets, traditional dress, a model of a traditional Ossetian house. This is not a grand museum — quiet and thoughtful. You can come for an hour and stay for three. Affordable entry; the guides know their material."}}'::jsonb, photos = ARRAY['/images/pois/natsionalnyy-muzey-rso-alaniya_gp.webp','/images/pois/natsionalnyy-muzey-rso-alaniya_2.webp','/images/pois/national-museum-of-north-ossetia-alania_gp.webp','/images/pois/natsionalnyy-muzey-rso-alaniya_3.webp','/images/pois/natsionalnyy-muzey-rso-alaniya_4.webp','/images/pois/natsionalnyy-muzey-rso-alaniya_5.webp','/images/pois/natsionalnyy-muzey-rso-alaniya_6.webp','/images/pois/natsionalnyy-muzey-rso-alaniya_7.webp','/images/pois/natsionalnyy-muzey-rso-alaniya_8.webp','/images/pois/natsionalnyy-muzey-rso-alaniya_9.webp','/images/pois/natsionalnyy-muzey-rso-alaniya_10.webp','/images/pois/natsionalnyy-muzey-rso-alaniya_11.webp']::text[], rating = 4.7, hours = '{"sun": "10:00-17:30", "tue": "10:00-17:30", "wed": "10:00-17:30", "thu": "10:00-17:30", "fri": "10:00-17:30", "sat": "10:00-17:30"}'::jsonb, phone = '+7 867 253-60-87', website = 'https://аланиянацмузей.рф/', price_level = NULL, tags = ARRAY['culture']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 80, review_count = 348, updated_at = now() WHERE id = 'poi-030';
UPDATE pois SET name = '{"ru": "Кадаргаванский каньон", "en": "Kadargavan Canyon"}'::jsonb, category = 'nature'::poi_category, subcategory = 'nature', cuisine_type = NULL, location = '{"lat": 42.881715, "lng": 44.326723, "address": {"ru": "Респ. Северная Осетия — Алания, Россия, 363203", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Узкий скальный каньон в Куртатинском ущелье с глубиной до 60 метров и шириной всего несколько...", "en": "A narrow rock canyon in Kurtatinsky Gorge, up to 60 meters deep and only a few meters wide. The..."}, "medium": {"ru": "Узкий скальный каньон в Куртатинском ущелье с глубиной до 60 метров и шириной всего несколько метров. Оборудована «Тропа чудес» — дорожка с перилами над обрывом, со смотровыми площадками. В каньоне установлен арт-объект «Зеркальный барс» — скульптура кавказского леопарда из зеркальной стали, парящая над пропастью.", "en": "A narrow rock canyon in Kurtatinsky Gorge, up to 60 meters deep and only a few meters wide. The ''Path of Wonders'' trail with railings runs along the cliff edge with viewing platforms. Inside the canyon stands the ''Mirror Leopard'' — a mirror-steel sculpture of a Caucasian leopard hovering above the abyss."}, "full": {"ru": "Узкий скальный каньон в Куртатинском ущелье с глубиной до 60 метров и шириной всего несколько метров. Оборудована «Тропа чудес» — дорожка с перилами над обрывом, со смотровыми площадками. В каньоне установлен арт-объект «Зеркальный барс» — скульптура кавказского леопарда из зеркальной стали, парящая над пропастью. Внизу видна река Фиагдон, пробившая себе путь сквозь скалы.", "en": "A narrow rock canyon in Kurtatinsky Gorge, up to 60 meters deep and only a few meters wide. The ''Path of Wonders'' trail with railings runs along the cliff edge with viewing platforms. Inside the canyon stands the ''Mirror Leopard'' — a mirror-steel sculpture of a Caucasian leopard hovering above the abyss. Below, the Fiagdon River has carved its way through the rocks."}}'::jsonb, photos = ARRAY['/images/pois/kadargavan-canyon_gp.webp','/images/pois/kadargavanskiy-kanon_2.webp','/images/pois/kadargavanskiy-kanon_3.webp','/images/pois/kadargavanskiy-kanon_4.webp','/images/pois/kadargavanskiy-kanon_5.webp','/images/pois/kadargavanskiy-kanon_6.webp']::text[], rating = 4.9, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['nature']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 800, review_count = 151, updated_at = now() WHERE id = 'poi-040';
UPDATE pois SET name = '{"ru": "Дзивгисская наскальная крепость", "en": "Dzivgis Rock Fortress"}'::jsonb, category = 'culture'::poi_category, subcategory = 'history', cuisine_type = NULL, location = '{"lat": 42.877364, "lng": 44.314714, "address": {"ru": "Дзивгис, Респ. Северная Осетия — Алания, Россия, 363203", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Крупнейшая пещерная крепость на Кавказе, построенная в XIII–XVI веках на склоне скального хребта у...", "en": "The largest cave fortress in the Caucasus, built in the 13th–16th centuries on the slopes of a..."}, "medium": {"ru": "Крупнейшая пещерная крепость на Кавказе, построенная в XIII–XVI веках на склоне скального хребта у села Дзивгис. Комплекс состоит из семи независимых оборонительных сооружений, встроенных в естественные пещерные проёмы. Рядом находится церковь Святого Георгия VII века — одна из древнейших в Осетии.", "en": "The largest cave fortress in the Caucasus, built in the 13th–16th centuries on the slopes of a rocky ridge behind Dzivgis village. The complex consists of seven independent defensive structures built into natural cave openings. Nearby stands the 7th-century Church of St. George — one of the oldest in Ossetia."}, "full": {"ru": "Крупнейшая пещерная крепость на Кавказе, построенная в XIII–XVI веках на склоне скального хребта у села Дзивгис. Комплекс состоит из семи независимых оборонительных сооружений, встроенных в естественные пещерные проёмы. Рядом находится церковь Святого Георгия VII века — одна из древнейших в Осетии. Село также имеет свой небольшой «город мёртвых» со средневековыми склепами.", "en": "The largest cave fortress in the Caucasus, built in the 13th–16th centuries on the slopes of a rocky ridge behind Dzivgis village. The complex consists of seven independent defensive structures built into natural cave openings. Nearby stands the 7th-century Church of St. George — one of the oldest in Ossetia. The village also has its own small ''City of the Dead'' with medieval crypts."}}'::jsonb, photos = ARRAY['/images/pois/dzivgis-rock-fortress_gp.webp','/images/pois/dzivgisskaya-naskalnaya-krepost_2.webp','/images/pois/dzivgisskaya-naskalnaya-krepost_3.webp','/images/pois/dzivgisskaya-naskalnaya-krepost_4.webp','/images/pois/dzivgisskaya-naskalnaya-krepost_5.webp']::text[], rating = 4.8, hours = '{"mon": "00:00-23:59"}'::jsonb, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['culture']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 80, review_count = 664, updated_at = now() WHERE id = 'poi-041';
UPDATE pois SET name = '{"ru": "Термальные источники Бирагзанг", "en": "Biragzang Thermal Springs"}'::jsonb, category = 'nature'::poi_category, subcategory = 'springs', cuisine_type = NULL, location = '{"lat": 42.99551, "lng": 44.229103, "address": {"ru": "Верхний Бирагзанг, Респ. Северная Осетия — Алания, Россия, 363210", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Горячие термальные источники у села Верхний Бирагзанг в Алагирском районе. Вода поднимается с...", "en": "Hot thermal springs near the village of Verkhny Biragzang in Alagir District. Water rises from a..."}, "medium": {"ru": "Горячие термальные источники у села Верхний Бирагзанг в Алагирском районе. Вода поднимается с глубины более 2000 метров, её температура не опускается ниже +40°C круглый год. Источники оборудованы для купания — есть бассейны под открытым небом с горячей минеральной водой на фоне горных пейзажей.", "en": "Hot thermal springs near the village of Verkhny Biragzang in Alagir District. Water rises from a depth of over 2,000 meters and maintains a temperature above 40°C year-round. The springs are equipped for bathing — open-air pools filled with hot mineral water against a backdrop of mountain scenery."}, "full": {"ru": "Горячие термальные источники у села Верхний Бирагзанг в Алагирском районе. Вода поднимается с глубины более 2000 метров, её температура не опускается ниже +40°C круглый год. Источники оборудованы для купания — есть бассейны под открытым небом с горячей минеральной водой на фоне горных пейзажей. Вода богата минералами и считается целебной.", "en": "Hot thermal springs near the village of Verkhny Biragzang in Alagir District. Water rises from a depth of over 2,000 meters and maintains a temperature above 40°C year-round. The springs are equipped for bathing — open-air pools filled with hot mineral water against a backdrop of mountain scenery. The water is mineral-rich and considered healing."}}'::jsonb, photos = ARRAY['/images/pois/biragzang-thermal-springs_gp.webp','/images/pois/termalnye-istochniki-biragzang_2.webp','/images/pois/termalnye-istochniki-biragzang_3.webp','/images/pois/termalnye-istochniki-biragzang_4.webp','/images/pois/termalnye-istochniki-biragzang_5.webp','/images/pois/termalnye-istochniki-biragzang_6.webp','/images/pois/termalnye-istochniki-biragzang_7.webp','/images/pois/termalnye-istochniki-biragzang_8.webp','/images/pois/termalnye-istochniki-biragzang_9.webp','/images/pois/termalnye-istochniki-biragzang_10.webp','/images/pois/termalnye-istochniki-biragzang_11.webp']::text[], rating = 4.5, hours = '{"sun": "06:00-22:00", "mon": "10:00-23:00", "tue": "06:00-23:00", "wed": "06:00-23:00", "thu": "06:00-22:00", "fri": "10:00-23:00", "sat": "06:00-23:00"}'::jsonb, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['nature']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 800, review_count = 1256, updated_at = now() WHERE id = 'poi-042';
UPDATE pois SET name = '{"ru": "Дигорское ущелье", "en": "Digora Gorge (Digorskoe Ushchelye)"}'::jsonb, category = 'nature'::poi_category, subcategory = 'nature', cuisine_type = NULL, location = '{"lat": 42.901761, "lng": 43.619606, "address": {"ru": "Стур-Дигора, Респ. Северная Осетия — Алания, Россия, 363517", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Одно из красивейших ущелий Кавказа, расположенное в 120 км от Владикавказа в бассейне реки Урух....", "en": "One of the most beautiful gorges in the Caucasus, located 120 km from Vladikavkaz in the Urukh..."}, "medium": {"ru": "Одно из красивейших ущелий Кавказа, расположенное в 120 км от Владикавказа в бассейне реки Урух. Ущелье ведёт в Национальный парк «Алания» и поражает разнообразием ландшафтов: альпийские луга, влажные леса, озёра, водопады и ледники. Здесь находятся древние сёла Галиат, Камунта, Задалеск, Стур-Дигора.", "en": "One of the most beautiful gorges in the Caucasus, located 120 km from Vladikavkaz in the Urukh River basin. The gorge leads to Alania National Park and stuns with landscape diversity: alpine meadows, humid forests, lakes, waterfalls, and glaciers. Here lie the ancient villages of Galiat, Kamunta, Zadalesk, and Stur-Digora."}, "full": {"ru": "Одно из красивейших ущелий Кавказа, расположенное в 120 км от Владикавказа в бассейне реки Урух. Ущелье ведёт в Национальный парк «Алания» и поражает разнообразием ландшафтов: альпийские луга, влажные леса, озёра, водопады и ледники. Здесь находятся древние сёла Галиат, Камунта, Задалеск, Стур-Дигора. Менее посещаемое, чем Куртатинское, оно сохраняет дикую красоту.", "en": "One of the most beautiful gorges in the Caucasus, located 120 km from Vladikavkaz in the Urukh River basin. The gorge leads to Alania National Park and stuns with landscape diversity: alpine meadows, humid forests, lakes, waterfalls, and glaciers. Here lie the ancient villages of Galiat, Kamunta, Zadalesk, and Stur-Digora. Less visited than Kurtatinsky Gorge, it preserves wild beauty."}}'::jsonb, photos = ARRAY['/images/pois/digora-gorge-(digorskoe-ushchelye)_gp.webp','/images/pois/digorskoe-uschele_2.webp','/images/pois/digorskoe-uschele_3.webp','/images/pois/digorskoe-uschele_4.webp','/images/pois/digorskoe-uschele_5.webp','/images/pois/digorskoe-uschele_6.webp','/images/pois/digorskoe-uschele_7.webp']::text[], rating = 4.9, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['nature']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 800, review_count = 82, updated_at = now() WHERE id = 'poi-047';
UPDATE pois SET name = '{"ru": "Водопады Три сестры (Таймази)", "en": "Three Sisters Waterfalls (Taimazi)"}'::jsonb, category = 'nature'::poi_category, subcategory = 'nature', cuisine_type = NULL, location = '{"lat": 42.883279, "lng": 43.59386, "address": {"ru": "Респ. Северная Осетия — Алания, Россия, 363517", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Три мощных водопада в южной части Дигорского ущелья, на правом берегу реки Танадон у подножия горы...", "en": "Three powerful waterfalls in the southern part of Digora Gorge, on the right bank of the Tanadon..."}, "medium": {"ru": "Три мощных водопада в южной части Дигорского ущелья, на правом берегу реки Танадон у подножия горы Таймази. Тающий ледник формирует три потока, которые серебристыми лентами спускаются с высоты почти 300 метров по горному склону. Особенно впечатляют в июле–августе, когда ледник тает интенсивнее.", "en": "Three powerful waterfalls in the southern part of Digora Gorge, on the right bank of the Tanadon River at the foot of Taimazi Mountain. A melting glacier forms three streams that descend like silver ribbons from nearly 300 meters down the mountainside. Most impressive in July–August when the glacier melts faster."}, "full": {"ru": "Три мощных водопада в южной части Дигорского ущелья, на правом берегу реки Танадон у подножия горы Таймази. Тающий ледник формирует три потока, которые серебристыми лентами спускаются с высоты почти 300 метров по горному склону. Особенно впечатляют в июле–августе, когда ледник тает интенсивнее. Зрелище напоминает три сверкающих косы, спущенных с небес.", "en": "Three powerful waterfalls in the southern part of Digora Gorge, on the right bank of the Tanadon River at the foot of Taimazi Mountain. A melting glacier forms three streams that descend like silver ribbons from nearly 300 meters down the mountainside. Most impressive in July–August when the glacier melts faster. The sight resembles three glittering braids let down from the heavens."}}'::jsonb, photos = ARRAY['/images/pois/three-sisters-waterfalls-(taimazi)_gp.webp','/images/pois/vodopady-tri-sestry-taymazi_2.webp','/images/pois/vodopady-tri-sestry-taymazi_3.webp','/images/pois/vodopady-tri-sestry-taymazi_4.webp','/images/pois/vodopady-tri-sestry-taymazi_5.webp']::text[], rating = 5, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['nature']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 800, review_count = 28, updated_at = now() WHERE id = 'poi-048';
UPDATE pois SET name = '{"ru": "Лисри", "en": "Lisri Village"}'::jsonb, category = 'nature'::poi_category, subcategory = 'village', cuisine_type = NULL, location = '{"lat": 42.668611, "lng": 43.857778, "address": {"ru": "Лисри, Респ. Северная Осетия — Алания, Россия, 363227", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Одно из крупнейших и древнейших поселений Северной Осетии, расположенное в Мамисонском ущелье на...", "en": "One of the largest and most ancient settlements in North Ossetia, located in Mamison Gorge at 2,000..."}, "medium": {"ru": "Одно из крупнейших и древнейших поселений Северной Осетии, расположенное в Мамисонском ущелье на высоте 2000 м над уровнем моря. Лисри — один из самых крупных комплексов каменных башен в Осетии: боевые, жилые и сторожевые башни выстроились вдоль долины. Рядом, в селе Тиб, находятся минеральные источники.", "en": "One of the largest and most ancient settlements in North Ossetia, located in Mamison Gorge at 2,000 m above sea level. Lisri has one of the biggest stone tower complexes in Ossetia: battle, residential, and watchtowers line the valley. Nearby, the village of Tib has mineral springs."}, "full": {"ru": "Одно из крупнейших и древнейших поселений Северной Осетии, расположенное в Мамисонском ущелье на высоте 2000 м над уровнем моря. Лисри — один из самых крупных комплексов каменных башен в Осетии: боевые, жилые и сторожевые башни выстроились вдоль долины. Рядом, в селе Тиб, находятся минеральные источники. Место поражает масштабом и ощущением затерянного мира.", "en": "One of the largest and most ancient settlements in North Ossetia, located in Mamison Gorge at 2,000 m above sea level. Lisri has one of the biggest stone tower complexes in Ossetia: battle, residential, and watchtowers line the valley. Nearby, the village of Tib has mineral springs. The place stuns with its scale and feeling of a lost world."}}'::jsonb, photos = ARRAY['/images/pois/lisri-village_gp.webp','/images/pois/lisri_2.webp','/images/pois/lisri_3.webp','/images/pois/lisri_4.webp','/images/pois/lisri_5.webp','/images/pois/lisri_6.webp']::text[], rating = 4.7, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['nature']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 800, review_count = 77, updated_at = now() WHERE id = 'poi-049';
UPDATE pois SET name = '{"ru": "Донифарс", "en": "Donifars"}'::jsonb, category = 'nature'::poi_category, subcategory = 'village', cuisine_type = NULL, location = '{"lat": 42.999589, "lng": 43.764871, "address": {"ru": "Донифарс, Респ. Северная Осетия — Алания, Россия, 363511", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Высокогорное село-некрополь в Дигории, называемое «город мёртвых Дигории». Здесь сохранились...", "en": "A high-altitude village-necropolis in Digoria, called the ''City of the Dead of Digoria''. Ancient..."}, "medium": {"ru": "Высокогорное село-некрополь в Дигории, называемое «город мёртвых Дигории». Здесь сохранились древнейшие надземные склепы (могильники), средневековые сторожевые башни, святилище-храм «Сатайи Обау» и родовые гнёзда именитых семей. Аланские катакомбные захоронения добавляют археологическую ценность.", "en": "A high-altitude village-necropolis in Digoria, called the ''City of the Dead of Digoria''. Ancient above-ground crypts (burial vaults), medieval watchtowers, the sanctuary-temple ''Satayi Obau'', and ancestral estates of notable families survive here. Alanian catacomb burials add archaeological value."}, "full": {"ru": "Высокогорное село-некрополь в Дигории, называемое «город мёртвых Дигории». Здесь сохранились древнейшие надземные склепы (могильники), средневековые сторожевые башни, святилище-храм «Сатайи Обау» и родовые гнёзда именитых семей. Аланские катакомбные захоронения добавляют археологическую ценность. В отличие от Даргавса, это место почти не посещается туристами.", "en": "A high-altitude village-necropolis in Digoria, called the ''City of the Dead of Digoria''. Ancient above-ground crypts (burial vaults), medieval watchtowers, the sanctuary-temple ''Satayi Obau'', and ancestral estates of notable families survive here. Alanian catacomb burials add archaeological value. Unlike Dargavs, this place sees almost no tourists."}}'::jsonb, photos = ARRAY['/images/pois/donifars_gp.webp','/images/pois/donifars_2.webp','/images/pois/donifars_3.webp','/images/pois/donifars_4.webp','/images/pois/donifars_5.webp','/images/pois/donifars_6.webp','/images/pois/donifars_7.webp','/images/pois/donifars_8.webp']::text[], rating = 4.7, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['nature']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 800, review_count = 121, updated_at = now() WHERE id = 'poi-050';
UPDATE pois SET name = '{"ru": "Верхний Фиагдон", "en": "Verkhny Fiagdon"}'::jsonb, category = 'nature'::poi_category, subcategory = 'village', cuisine_type = NULL, location = '{"lat": 42.834689, "lng": 44.307143, "address": {"ru": "Верхний Фиагдон, Респ. Северная Осетия — Алания, Россия, 363203", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Главная туристическая база Куртатинского ущелья на высоте около 1200 м. Село сочетает средневековые...", "en": "The main tourist base of Kurtatinsky Gorge at about 1,200 m elevation. The village combines..."}, "medium": {"ru": "Главная туристическая база Куртатинского ущелья на высоте около 1200 м. Село сочетает средневековые аланские сторожевые башни и современные гостевые дома. Здесь установлен один из первых памятников Ленину в мире (1924 год). Отсюда доступны Дзивгисская крепость, Кадаргаванский каньон, Аланский монастырь и «Лавочка любви» на Архонском перевале.", "en": "The main tourist base of Kurtatinsky Gorge at about 1,200 m elevation. The village combines medieval Alanian watchtowers with modern guesthouses. One of the world''s first Lenin monuments (1924) stands here. From this base, Dzivgis Fortress, Kadargavan Canyon, Alanian Monastery, and the ''Love Bench'' viewpoint on Arkhon Pass are all accessible."}, "full": {"ru": "Главная туристическая база Куртатинского ущелья на высоте около 1200 м. Село сочетает средневековые аланские сторожевые башни и современные гостевые дома. Здесь установлен один из первых памятников Ленину в мире (1924 год). Отсюда доступны Дзивгисская крепость, Кадаргаванский каньон, Аланский монастырь и «Лавочка любви» на Архонском перевале. Идеальная точка для радиальных вылазок.", "en": "The main tourist base of Kurtatinsky Gorge at about 1,200 m elevation. The village combines medieval Alanian watchtowers with modern guesthouses. One of the world''s first Lenin monuments (1924) stands here. From this base, Dzivgis Fortress, Kadargavan Canyon, Alanian Monastery, and the ''Love Bench'' viewpoint on Arkhon Pass are all accessible. An ideal hub for day trips."}}'::jsonb, photos = ARRAY['/images/pois/verkhny-fiagdon_gp.webp','/images/pois/verhniy-fiagdon_2.webp','/images/pois/verhniy-fiagdon_3.webp','/images/pois/verhniy-fiagdon_4.webp','/images/pois/verhniy-fiagdon_5.webp','/images/pois/verhniy-fiagdon_6.webp','/images/pois/verhniy-fiagdon_7.webp','/images/pois/verhniy-fiagdon_8.webp']::text[], rating = 4.5, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['nature']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 800, review_count = 13, updated_at = now() WHERE id = 'poi-051';
UPDATE pois SET name = '{"ru": "Цамад", "en": "Tsamad Village"}'::jsonb, category = 'nature'::poi_category, subcategory = 'village', cuisine_type = NULL, location = '{"lat": 42.855885, "lng": 44.164532, "address": {"ru": "Unnamed Road, Респ. Северная Осетия — Алания, Россия, 363214", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Одно из самых древних поселений Осетии на высоте 1450 м в Алагирском ущелье. В начале XX века здесь...", "en": "One of the most ancient settlements in Ossetia at 1,450 m elevation in Alagir Gorge. In the early..."}, "medium": {"ru": "Одно из самых древних поселений Осетии на высоте 1450 м в Алагирском ущелье. В начале XX века здесь жило около 700 человек, сейчас село заброшено. Осетины считают его особенным — по преданию, именно отсюда пришли их предки. Сохранились руины средневековой крепости и семиэтажная башня Черчесовых, построенная прямо на скале.", "en": "One of the most ancient settlements in Ossetia at 1,450 m elevation in Alagir Gorge. In the early 20th century about 700 people lived here; now the village is abandoned. Ossetians consider it special — according to tradition, this is where their ancestors originated."}, "full": {"ru": "Одно из самых древних поселений Осетии на высоте 1450 м в Алагирском ущелье. В начале XX века здесь жило около 700 человек, сейчас село заброшено. Осетины считают его особенным — по преданию, именно отсюда пришли их предки. Сохранились руины средневековой крепости и семиэтажная башня Черчесовых, построенная прямо на скале. Место овеяно легендами и тишиной заброшенного мира.", "en": "One of the most ancient settlements in Ossetia at 1,450 m elevation in Alagir Gorge. In the early 20th century about 700 people lived here; now the village is abandoned. Ossetians consider it special — according to tradition, this is where their ancestors originated. Ruins of a medieval fortress and the seven-story Cherchesov tower built directly on rock survive. The place is steeped in legends and the silence of an abandoned world."}}'::jsonb, photos = ARRAY['/images/pois/tsamad-village_gp.webp','/images/pois/tsamad_2.webp','/images/pois/tsamad_3.webp','/images/pois/tsamad_4.webp','/images/pois/tsamad_5.webp','/images/pois/tsamad_6.webp','/images/pois/tsamad_7.webp']::text[], rating = 5, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['nature']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 800, review_count = 22, updated_at = now() WHERE id = 'poi-053';
UPDATE pois SET name = '{"ru": "Музей «Задалески Нана»", "en": "Zadalesky Nana Museum"}'::jsonb, category = 'museums'::poi_category, subcategory = 'history', cuisine_type = NULL, location = '{"lat": 42.901761, "lng": 43.619606, "address": {"ru": "Стур-Дигора, Респ. Северная Осетия — Алания, Россия, 363517", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Музей в Нижнем Задалеске посвящён легендарной осетинской женщине Задалески Нана, которая спасла...", "en": "A museum in Nizhny Zadalesk dedicated to the legendary Ossetian woman Zadalesky Nana, who saved..."}, "medium": {"ru": "Музей в Нижнем Задалеске посвящён легендарной осетинской женщине Задалески Нана, которая спасла детей от нашествия Золотой Орды, укрыв их в горном ущелье. Музей размещён в старинном каменном доме и рассказывает историю спасения и жизни дигорцев.", "en": "A museum in Nizhny Zadalesk dedicated to the legendary Ossetian woman Zadalesky Nana, who saved children from the Golden Horde invasion by hiding them in a mountain gorge. The museum is housed in an old stone building and tells the story of the rescue and Digorian life."}, "full": {"ru": "Музей в Нижнем Задалеске посвящён легендарной осетинской женщине Задалески Нана, которая спасла детей от нашествия Золотой Орды, укрыв их в горном ущелье. Музей размещён в старинном каменном доме и рассказывает историю спасения и жизни дигорцев. Нана — символ материнского подвига и один из самых почитаемых образов в осетинской культуре.", "en": "A museum in Nizhny Zadalesk dedicated to the legendary Ossetian woman Zadalesky Nana, who saved children from the Golden Horde invasion by hiding them in a mountain gorge. The museum is housed in an old stone building and tells the story of the rescue and Digorian life. Nana is a symbol of maternal heroism and one of the most revered figures in Ossetian culture."}}'::jsonb, photos = ARRAY['/images/pois/zadalesky-nana-museum_gp.webp','/images/pois/muzey-zadaleski-nana_2.webp','/images/pois/muzey-zadaleski-nana_3.webp','/images/pois/muzey-zadaleski-nana_4.webp','/images/pois/muzey-zadaleski-nana_5.webp','/images/pois/muzey-zadaleski-nana_6.webp','/images/pois/muzey-zadaleski-nana_7.webp']::text[], rating = 4.9, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['culture']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 80, review_count = 82, updated_at = now() WHERE id = 'poi-054';
UPDATE pois SET name = '{"ru": "Касарское ущелье", "en": "Kasarskoe Gorge"}'::jsonb, category = 'nature'::poi_category, subcategory = 'nature', cuisine_type = NULL, location = '{"lat": 42.733333, "lng": 43.966667, "address": {"ru": "Кассарское Ущелье, Респ. Северная Осетия — Алания, Россия, 363227", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Узкое скалистое ущелье на подступах к Алагирскому ущелью, через которое река Ардон прорезала себе...", "en": "A narrow rocky gorge at the approaches to Alagir Gorge, where the Ardon River has carved its way..."}, "medium": {"ru": "Узкое скалистое ущелье на подступах к Алагирскому ущелью, через которое река Ардон прорезала себе путь в скалах. Стены каньона поднимаются на сотни метров, сужаясь местами до ширины дороги. Именно здесь стоит монумент Уастырджи.", "en": "A narrow rocky gorge at the approaches to Alagir Gorge, where the Ardon River has carved its way through the rocks. Canyon walls rise hundreds of meters, narrowing in places to road width. This is where the Uastyrdzhi monument stands."}, "full": {"ru": "Узкое скалистое ущелье на подступах к Алагирскому ущелью, через которое река Ардон прорезала себе путь в скалах. Стены каньона поднимаются на сотни метров, сужаясь местами до ширины дороги. Именно здесь стоит монумент Уастырджи. Касарское ущелье — природные ворота в горную Осетию; за ним начинается совершенно другой мир высокогорья.", "en": "A narrow rocky gorge at the approaches to Alagir Gorge, where the Ardon River has carved its way through the rocks. Canyon walls rise hundreds of meters, narrowing in places to road width. This is where the Uastyrdzhi monument stands. Kasarskoe Gorge is the natural gateway to mountainous Ossetia — beyond it begins an entirely different world of highlands."}}'::jsonb, photos = ARRAY['/images/pois/kasar-gorge.webp','/images/pois/kasarskoe-uschele_gp.webp','/images/pois/kasarskoe-uschele_2.webp','/images/pois/kasarskoe-uschele_3.webp']::text[], rating = 4, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['nature']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 800, review_count = 142, updated_at = now() WHERE id = 'poi-055';
UPDATE pois SET name = '{"ru": "Лавочка любви (Архонский перевал)", "en": "Love Bench (Arkhon Pass Viewpoint)"}'::jsonb, category = 'nature'::poi_category, subcategory = 'viewpoint', cuisine_type = NULL, location = '{"lat": 42.815747, "lng": 44.21017, "address": {"ru": "Unnamed Road, Респ. Северная Осетия — Алания, Россия, 363214", "en": "North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Смотровая площадка на Архонском перевале на высоте около 2600 м — одно из самых романтичных мест...", "en": "A viewpoint on Arkhon Pass at about 2,600 m — one of the most romantic spots in the Caucasus. A..."}, "medium": {"ru": "Смотровая площадка на Архонском перевале на высоте около 2600 м — одно из самых романтичных мест Кавказа. Простая лавочка на краю обрыва с захватывающим панорамным видом на горные вершины и долину реки Фиагдон. Популярное место для фото и предложений руки и сердца.", "en": "A viewpoint on Arkhon Pass at about 2,600 m — one of the most romantic spots in the Caucasus. A simple bench on the edge of a cliff with breathtaking panoramic views of mountain peaks and the Fiagdon River valley. A popular spot for photos and marriage proposals."}, "full": {"ru": "Смотровая площадка на Архонском перевале на высоте около 2600 м — одно из самых романтичных мест Кавказа. Простая лавочка на краю обрыва с захватывающим панорамным видом на горные вершины и долину реки Фиагдон. Популярное место для фото и предложений руки и сердца. Добраться можно по грунтовой дороге из Верхнего Фиагдона.", "en": "A viewpoint on Arkhon Pass at about 2,600 m — one of the most romantic spots in the Caucasus. A simple bench on the edge of a cliff with breathtaking panoramic views of mountain peaks and the Fiagdon River valley. A popular spot for photos and marriage proposals. Accessible via a dirt road from Verkhny Fiagdon."}}'::jsonb, photos = ARRAY['/images/pois/love-bench-(arkhon-pass-viewpoint)_gp.webp','/images/pois/lavochka-lyubvi-arhonskiy-pereval_2.webp','/images/pois/lavochka-lyubvi-arhonskiy-pereval_3.webp','/images/pois/lavochka-lyubvi-arhonskiy-pereval_4.webp','/images/pois/lavochka-lyubvi-arhonskiy-pereval_5.webp']::text[], rating = 5, hours = NULL, phone = NULL, website = NULL, price_level = NULL, tags = ARRAY['nature']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 800, review_count = 60, updated_at = now() WHERE id = 'poi-056';
UPDATE pois SET name = '{"ru": "Къона", "en": "Kona"}'::jsonb, category = 'food'::poi_category, subcategory = 'restaurant', cuisine_type = 'national'::cuisine_type, location = '{"lat": 43.045025, "lng": 44.65887, "address": {"ru": "просп. Коста, 258, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362020", "en": "Prospekt Kosta 258, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Ресторан-музей осетинской культуры с этнографической экспозицией, традиционной утварью и костюмами....", "en": "Museum-restaurant of Ossetian culture with ethnographic exhibits, traditional utensils and costumes."}, "medium": {"ru": "Ресторан-музей осетинской культуры с этнографической экспозицией, традиционной утварью и костюмами. Персонал встречает гостей на осетинском языке в национальных костюмах. Очаг с цепью — символ осетинского дома. Живая национальная музыка.", "en": "Museum-restaurant of Ossetian culture with ethnographic exhibits, traditional utensils and costumes. Staff greets guests in Ossetian language wearing national dress. Features a hearth with chain — symbol of the Ossetian home. Live national music."}, "full": {"ru": "Назвать «Кыону» просто рестораном — значит не договорить. Зал оформлен как осетинский дом: старинная утварь, войлочные ковры, деревянные скамьи — и всё это не декор, а подлинные вещи. Персонал встречает в национальных костюмах. Меню построено вокруг трёх пирогов — символа осетинского стола (три пирога = праздник, два = скорбь). Обязательно попробуйте дзыкка — сырную кашу на сметане, которую почти нигде больше не готовят. Порции большие, цены разумные. Это место понравится и тем, кто хочет поесть, и тем, кто хочет понять — что такое осетинская кухня на самом деле.", "en": "Calling Kyona simply a restaurant is an understatement. The hall is designed as an Ossetian home: old utensils, felt carpets, wooden benches — genuine objects, not reproductions. Staff greet you in national costume. The menu is built around the three pies that symbolize the Ossetian table (three pies = celebration; two = mourning). Don''t miss dzykka — a cheese porridge in sour cream almost no one else prepares. Portions are generous, prices are fair. This place works for those who want to eat, and for those who want to understand what Ossetian cuisine actually means."}}'::jsonb, photos = ARRAY['/images/pois/kona_7.webp','/images/pois/kona_1.webp','/images/pois/kona_2.webp','/images/pois/kona_3.webp','/images/pois/kona_4.webp','/images/pois/kona_5.webp','/images/pois/kona_6.webp','/images/pois/kona_8.webp','/images/pois/kona_9.webp']::text[], rating = 4.6, hours = '{"sun": "11:00-23:00", "mon": "11:00-23:00", "tue": "11:00-23:00", "wed": "11:00-23:00", "thu": "11:00-23:00", "fri": "11:00-23:00", "sat": "11:00-23:00"}'::jsonb, phone = '+7 918 825-88-08', website = 'https://www.instagram.com/kona_ir/', price_level = 2, tags = ARRAY['осетинская кухня','пироги','традиционная','мясо']::text[], is_chain = false, has_menu = true, has_delivery = false, radius = 50, review_count = 494, updated_at = now() WHERE id = 'poi-070';
UPDATE pois SET name = '{"ru": "Фыдджынтæ", "en": "Fydzhynta"}'::jsonb, category = 'food'::poi_category, subcategory = 'cafe', cuisine_type = 'national'::cuisine_type, location = '{"lat": 43.033813, "lng": 44.665918, "address": {"ru": "просп. Коста, 178, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362020", "en": "Prospekt Kosta 178, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Легендарное советское заведение, любимое местными. Маленькие порционные пироги фыджын (15 см)...", "en": "Legendary Soviet-era establishment beloved by locals. Small portioned meat pies fydzhyn (15cm)..."}, "medium": {"ru": "Легендарное советское заведение, любимое местными. Маленькие порционные пироги фыджын (15 см) подают с бульоном, сметаной и лимонадом. Средний чек — 500 руб. Культовое место, которое каждый гид рекомендует туристам.", "en": "Legendary Soviet-era establishment beloved by locals. Small portioned meat pies fydzhyn (15cm) served with broth, sour cream and lemonade. Average check ~500 RUB. Iconic spot that every guide recommends to tourists."}, "full": {"ru": "«Фыдджынтæ» — это место, где местные едят, а не то, где они показывают город гостям. Советская история, демократичные цены, небольшие порционные пироги диаметром сантиметров 15 — именно такими пироги подавали сто лет назад, до эпохи огромных праздничных кругов. Их несут с бульоном и сметаной; каждый пирог хрустит снизу и тянется сыром сверху. Обстановка простая до минимализма — и это не недостаток, это честность. Сюда идут не за атмосферой, а за пирогом, которому веришь.", "en": "Fyddzhyntae is where locals eat, not where they take guests to show off. Soviet history, democratic prices, small individual pies about 15 cm across — exactly how pies were served a century ago, before the era of the giant holiday wheel. They arrive with broth and sour cream; each pie is crisp underneath and stretches with cheese on top. The setting is minimal to the point of austerity — and that''s not a flaw, it''s honesty. People don''t come here for atmosphere. They come for a pie they can trust."}}'::jsonb, photos = ARRAY['/images/pois/fyddzhyntae_2.webp','/images/pois/fyddzhyntae_3.webp','/images/pois/fyddzhyntae_4.webp','/images/pois/fyddzhyntae_5.webp']::text[], rating = 4.7, hours = '{"sun": "09:00-21:00", "mon": "09:00-21:00", "tue": "09:00-21:00", "wed": "09:00-21:00", "thu": "09:00-21:00", "fri": "09:00-21:00", "sat": "09:00-21:00"}'::jsonb, phone = '+7 867 225-67-05', website = 'https://www.instagram.com/fiddjintae_vld_15rus/', price_level = 2, tags = ARRAY['осетинские пироги','фыдджын','национальная кухня','бюджетно']::text[], is_chain = false, has_menu = true, has_delivery = false, radius = 50, review_count = 1599, updated_at = now() WHERE id = 'poi-071';
UPDATE pois SET name = '{"ru": "Man&Гал", "en": "Man&Gal"}'::jsonb, category = 'food'::poi_category, subcategory = 'restaurant', cuisine_type = 'national'::cuisine_type, location = '{"lat": 43.027992, "lng": 44.690978, "address": {"ru": "ул. Ватутина, 50, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362002", "en": "Vatutina St. 50, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Ресторан с открытым мангалом для шашлыка и люля-кебаба. Четыре зала с кавказским декором и летняя...", "en": "Restaurant with open mangal grill for shashlik and lula kebab. Four halls with Caucasian decor and..."}, "medium": {"ru": "Ресторан с открытым мангалом для шашлыка и люля-кебаба. Четыре зала с кавказским декором и летняя веранда. Специализация — свежая местная баранина, говядина, свинина и птица. Шеф готовит фирменные блюда при гостях.", "en": "Restaurant with open mangal grill for shashlik and lula kebab. Four halls with Caucasian decor and a summer veranda. Specializes in fresh local lamb, beef, pork and poultry. Chef prepares signature dishes tableside."}, "full": {"ru": "«Man&Гал» живёт вокруг мангала — буквально. Открытый огонь, запах углей, мясо, которое поджаривается прямо в зале. Четыре пространства: несколько закрытых залов с кавказским декором и летняя веранда. Шашлык и люля-кебаб — основа меню, всё из свежего мяса по собственным рецептам маринада. Хорошее место для большой компании: шумно, просторно, порции рассчитаны на настоящий аппетит. Уровень цен средний по городу — за деньги дают много. По вечерам бывает живая музыка.", "en": "Man&Gal lives around the mangal — literally. Open fire, the smell of coals, meat grilling right in the hall. Four spaces: several indoor rooms with Caucasian decor and a summer terrace. Shashlik and lyulya-kebab form the core of the menu — all from fresh meat by their own marinade recipes. A good place for a large group: noisy, spacious, portions sized for real appetite. Pricing is average for the city — you get a lot for the money. Live music most evenings."}}'::jsonb, photos = ARRAY['/images/pois/man-gal_p19.webp','/images/pois/man-gal_p1.webp','/images/pois/man-gal_p11.webp','/images/pois/man-gal_p10.webp','/images/pois/man-gal_p12.webp','/images/pois/man-gal_p13.webp','/images/pois/man-gal_p14.webp','/images/pois/man-gal_p15.webp','/images/pois/man-gal_p16.webp','/images/pois/man-gal_p17.webp','/images/pois/man-gal_p18.webp','/images/pois/man-gal_p2.webp','/images/pois/man-gal_p3.webp','/images/pois/man-gal_p4.webp','/images/pois/man-gal_p5.webp','/images/pois/man-gal_p6.webp','/images/pois/man-gal_p7.webp','/images/pois/man-gal_p8.webp','/images/pois/man-gal_p9.webp']::text[], rating = 4.6, hours = '{"sun": "12:00-23:00", "mon": "12:00-23:00", "tue": "12:00-23:00", "wed": "12:00-23:00", "thu": "12:00-23:00", "fri": "12:00-23:00", "sat": "12:00-23:00"}'::jsonb, phone = '+7 867 240-34-24', website = 'https://premier-cru.ru/restaurant/restoran-mangal/', price_level = 2, tags = ARRAY['кавказская кухня','мясо','гриль','летняя веранда']::text[], is_chain = false, has_menu = true, has_delivery = false, radius = 50, review_count = 628, updated_at = now() WHERE id = 'poi-072';
UPDATE pois SET name = '{"ru": "Старый мостъ", "en": "Stary Most (Old Bridge)"}'::jsonb, category = 'food'::poi_category, subcategory = 'restaurant', cuisine_type = 'mixed'::cuisine_type, location = '{"lat": 43.031901, "lng": 44.672413, "address": {"ru": "ул. Пашковского, 2, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362040", "en": "Pashkovskogo St. 2/1, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Ресторан у исторического моста через Терек (1903 г.). Минималистичный подход — ограниченное меню,...", "en": "Restaurant by the historic Terek bridge (1903). Minimalist approach — limited menu focused on..."}, "medium": {"ru": "Ресторан у исторического моста через Терек (1903 г.). Минималистичный подход — ограниченное меню, упор на качество. Шесть видов мяса на мангале, четыре вида рыбы, осетинские пироги. Своё крафтовое пиво из чешского солода и австралийского хмеля. Вид на реку.", "en": "Restaurant by the historic Terek bridge (1903). Minimalist approach — limited menu focused on quality. Six types of meat on the grill, four types of fish, Ossetian pies. House-brewed craft beer from Czech malt and Australian hops. River views."}, "full": {"ru": "«Старый мостъ» стоит у одного из самых красивых мест Владикавказа — у исторического моста через Терек, построенного в 1903 году. Виды на реку и горы — из окон. Кухня намеренно сдержанная: небольшое меню, упор на качество каждого блюда. Шесть видов стейков, несколько рыбных позиций, фирменные закуски. Всё готовится медленно — это не то место, куда идут перехватить быстро. Идеально для ужина вдвоём или небольшой компании, которая хочет посидеть спокойно и поговорить.", "en": "Stary Most stands at one of Vladikavkaz''s most beautiful spots — the historic Terek bridge built in 1903. River and mountain views from the windows. The cuisine is deliberately restrained: a small menu focused on quality in every dish. Six steak cuts, several fish options, house appetizers. Everything is cooked slowly — this is not a place for a quick bite. Ideal for a dinner for two, or a small group that wants to sit quietly and actually talk."}}'::jsonb, photos = ARRAY['/images/pois/stary-most-(old-bridge)_gp.webp','/images/pois/staryy-most_2.webp','/images/pois/staryy-most_3.webp','/images/pois/staryy-most_6.webp','/images/pois/staryy-most_7.webp','/images/pois/staryy-most_in_15.webp','/images/pois/staryy-most_food_16.webp','/images/pois/staryy-most_food_17.webp','/images/pois/staryy-most_food_18.webp','/images/pois/staryy-most_p1.webp','/images/pois/staryy-most_p2.webp','/images/pois/staryy-most_p3.webp','/images/pois/staryy-most_p4.webp','/images/pois/staryy-most_p5.webp','/images/pois/staryy-most_p6.webp','/images/pois/staryy-most_p7.webp','/images/pois/staryy-most_p8.webp','/images/pois/staryy-most_p9.webp','/images/pois/staryy-most_p10.webp','/images/pois/staryy-most_p11.webp','/images/pois/staryy-most_p12.webp']::text[], rating = 4.4, hours = '{"sun": "12:00-23:59", "mon": "12:00-00:00", "tue": "12:00-00:00", "wed": "12:00-00:00", "thu": "12:00-00:00", "fri": "12:00-00:00", "sat": "12:00-00:00"}'::jsonb, phone = '+7 918 821-62-63', website = NULL, price_level = 2, tags = ARRAY['трактир','европейская кухня','кавказская кухня','стейки','банкеты']::text[], is_chain = false, has_menu = true, has_delivery = false, radius = 50, review_count = 319, updated_at = now() WHERE id = 'poi-073';
UPDATE pois SET name = '{"ru": "Куырой", "en": "Koyroi"}'::jsonb, category = 'food'::poi_category, subcategory = 'restaurant', cuisine_type = 'mixed'::cuisine_type, location = '{"lat": 43.02241, "lng": 44.678161, "address": {"ru": "ул. Коцоева, 26, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362008", "en": "Kotsoeva St. 26, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Ресторан в здании исторической мельницы на набережной Терека. Авторская кухня, живая музыка, летняя...", "en": "Restaurant in a historic mill building on the Terek embankment. Author''s cuisine, live music,..."}, "medium": {"ru": "Ресторан в здании исторической мельницы на набережной Терека. Авторская кухня, живая музыка, летняя веранда, караоке. Рецепты, сохранившиеся с XIX века. Итальянская, европейская, кавказская, японская кухня.", "en": "Restaurant in a historic mill building on the Terek embankment. Author''s cuisine, live music, summer terrace, karaoke. Recipes preserved since the 19th century. Italian, European, Caucasian, Japanese cuisine."}, "full": {"ru": "«Куырой» значит «мельница» — и ресторан действительно расположен в здании исторической мельницы на набережной Терека. Авторская кухня: сочетание кавказского и европейского без строгих рамок. Летом — открытая веранда над водой. По вечерам живая музыка, а в выходные бывает и полноценная клубная программа. Хорошее место, если нужно объединить ужин и вечеринку в одном выходе.", "en": "Kuyroi means ''mill'' — and the restaurant genuinely occupies a historic mill building on the Terek embankment. Signature cuisine blending Caucasian and European without rigid categories. In summer — an open terrace above the water. Evenings bring live music; weekends sometimes combine dinner with something close to a club program. Good if you want to combine dinner and a night out in a single outing."}}'::jsonb, photos = ARRAY['/images/pois/koyroi_gp.webp','/images/pois/kuyroy_int_1.webp','/images/pois/kuyroy_int_2.webp','/images/pois/kuyroy_int_3.webp','/images/pois/kuyroy_int_4.webp','/images/pois/kuyroy_int_5.webp','/images/pois/kuyroy_menu_1.webp','/images/pois/kuyroy_menu_3.webp']::text[], rating = 4.4, hours = '{"sun": "12:00-23:59", "mon": "12:00-01:00", "tue": "12:00-01:00", "wed": "12:00-01:00", "thu": "12:00-01:00", "fri": "12:00-01:00", "sat": "12:00-01:00"}'::jsonb, phone = '+7 867 270-03-00', website = 'https://koyroi.com/', price_level = 2, tags = ARRAY['авторская кухня','караоке','живая музыка','историческое здание','мельница']::text[], is_chain = false, has_menu = true, has_delivery = false, radius = 50, review_count = 503, updated_at = now() WHERE id = 'poi-076';
UPDATE pois SET name = '{"ru": "Дендрариум", "en": "Dendrarium"}'::jsonb, category = 'food'::poi_category, subcategory = 'restaurant', cuisine_type = 'mixed'::cuisine_type, location = '{"lat": 42.980004, "lng": 44.667592, "address": {"ru": "Московское ш., Владикавказ, Респ. Северная Осетия — Алания, Россия, 362026", "en": "Moskovskoe Shosse 14, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Ресторан в вековом дендропарке среди дубов и сосен. 550 мест, тихий зал и открытая терраса. 100+...", "en": "Restaurant in a century-old arboretum among oaks and pines. 550 seats, quiet hall and open terrace...."}, "medium": {"ru": "Ресторан в вековом дендропарке среди дубов и сосен. 550 мест, тихий зал и открытая терраса. 100+ сортов чая. Китайский шеф готовит аутентичные блюда, включая утку по-пекински. Осетинская, европейская, грузинская, японская, китайская кухня.", "en": "Restaurant in a century-old arboretum among oaks and pines. 550 seats, quiet hall and open terrace. 100+ tea varieties. Chinese chef prepares authentic dishes including Peking duck. Ossetian, European, Georgian, Japanese, Chinese cuisine."}, "full": {"ru": "«Дендрариум» — ресторан в самом буквальном смысле в лесу: столики стоят в вековом парке среди дубов и сосен, которые отгораживают от города лучше любых стен. 550 мест — один из самых вместительных залов Владикавказа. Меню эклектичное: китайский шеф, более 100 сортов чая, осетинские пироги и мангал — всё в одном. Атмосфера одинаково хороша для семейного воскресного обеда и большого корпоратива. Летом приходите днём — в тени деревьев прохладно даже в зной.", "en": "Dendarium is a restaurant in the most literal sense inside a forest: tables sit in a century-old park among oaks and pines that cut you off from the city better than any walls. 550 seats — one of the largest venues in Vladikavkaz. The menu is eclectic: a Chinese chef, more than 100 varieties of tea, Ossetian pies and mangal grill — all in one. The atmosphere works equally well for a family Sunday lunch and a large corporate event. In summer, come during the day — the tree shade stays cool even in the heat."}}'::jsonb, photos = ARRAY['/images/pois/dendrarium_7.webp','/images/pois/dendrarium_1.webp','/images/pois/dendrarium_2.webp','/images/pois/dendrarium_3.webp','/images/pois/dendrarium_4.webp','/images/pois/dendrarium_5.webp','/images/pois/dendrarium_6.webp']::text[], rating = 4.4, hours = '{"sun": "07:00-23:59", "mon": "07:00-23:00", "tue": "07:00-23:00", "wed": "07:00-23:00", "thu": "07:00-23:00", "fri": "07:00-23:00", "sat": "07:00-23:00"}'::jsonb, phone = '+7 867 228-28-08', website = 'https://www.mercadagroup.ru/restaurants/dendrarium/', price_level = 2, tags = ARRAY['европейская кухня','кавказская кухня','доставка','завтраки','банкеты']::text[], is_chain = false, has_menu = true, has_delivery = false, radius = 50, review_count = 1893, updated_at = now() WHERE id = 'poi-077';
UPDATE pois SET name = '{"ru": "Lookoom Чайхана", "en": "Lookoom Chaikhana"}'::jsonb, category = 'food'::poi_category, subcategory = 'restaurant', cuisine_type = 'mixed'::cuisine_type, location = '{"lat": 43.031323, "lng": 44.680076, "address": {"ru": "пр. Мира, 35, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362040", "en": "Prospekt Mira 35, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Первый ресторан узбекской кухни во Владикавказе. Современная европейская атмосфера с восточной...", "en": "First Uzbek cuisine restaurant in Vladikavkaz. Modern European atmosphere with Eastern luxury. BBQ..."}, "medium": {"ru": "Первый ресторан узбекской кухни во Владикавказе. Современная европейская атмосфера с восточной роскошью. Барбекю, европейская кухня. Расположен на главной пешеходной улице — проспекте Мира.", "en": "First Uzbek cuisine restaurant in Vladikavkaz. Modern European atmosphere with Eastern luxury. BBQ and European cuisine. Located on the main pedestrian street — Prospekt Mira."}, "full": {"ru": "«Лукум» — первый и пока единственный ресторан узбекской кухни в городе. Плов готовят в большом казане и подают горячим в чугунных порциях; самса с бараниной печётся в настоящем тандыре. Декор балансирует между Востоком и современностью — мозаика, восточные фонари, без китча. Большой зал, хорошо для семей. Цены ниже, чем в большинстве ресторанов города. Приходите голодными — порции узбекские, то есть щедрые.", "en": "Lookoom is the first and still only Uzbek cuisine restaurant in the city. Plov is cooked in a large kazan and served hot in cast iron portions; samsa with lamb bakes in a real tandoor. The decor balances East and modernity — mosaic, Eastern lanterns, without kitsch. Large hall, good for families. Prices are lower than most restaurants in the city. Come hungry — the portions are Uzbek, meaning generous."}}'::jsonb, photos = ARRAY['/images/pois/lookoom-chayhana_int_4.webp','/images/pois/lookoom-chaikhana_gp.webp','/images/pois/lookoom-chayhana_int_2.webp','/images/pois/lookoom-chayhana_int_5.webp','/images/pois/lookoom-chayhana_menu_4.webp']::text[], rating = 4.4, hours = '{"sun": "11:00-23:00", "mon": "11:00-23:00", "tue": "11:00-23:00", "wed": "11:00-23:00", "thu": "11:00-23:00", "fri": "11:00-23:00", "sat": "11:00-23:00"}'::jsonb, phone = '+7 867 240-57-52', website = 'https://premier-cru.ru/restaurant/restoran-lookoom/', price_level = 2, tags = ARRAY['узбекская кухня','восточная кухня','чайхана','плов','лагман']::text[], is_chain = false, has_menu = true, has_delivery = false, radius = 50, review_count = 1081, updated_at = now() WHERE id = 'poi-078';
UPDATE pois SET name = '{"ru": "Berdinberg", "en": "Berdinberg"}'::jsonb, category = 'food'::poi_category, subcategory = 'bar', cuisine_type = 'european'::cuisine_type, location = '{"lat": 43.028405, "lng": 44.6805, "address": {"ru": "пр. Мира, 17, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362040", "en": "Prospekt Mira 19, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Пивной ресторан в историческом здании на пешеходной улице. 30+ сортов пива из США, Германии, Чехии,...", "en": "Beer restaurant in a historic building on the pedestrian street. 30+ beer varieties from USA,..."}, "medium": {"ru": "Пивной ресторан в историческом здании на пешеходной улице. 30+ сортов пива из США, Германии, Чехии, Шотландии, Нидерландов и Бельгии. 5 собственных сортов Berdinberg. Живая музыка 3 раза в неделю. Стейки, колбаски, пицца, бургеры.", "en": "Beer restaurant in a historic building on the pedestrian street. 30+ beer varieties from USA, Germany, Czech Republic, Scotland, Netherlands and Belgium. 5 house Berdinberg brews. Live music 3 times a week. Steaks, sausages, pizza, burgers."}, "full": {"ru": "«Бердинберг» — пивной ресторан в историческом здании на проспекте Мира, и по ассортименту пива он выигрывает у большинства конкурентов в округе: 30+ сортов из Германии, Чехии, США, Шотландии. Тёмное и светлое, фильтрованное и нефильтрованное, кислое и нейтральное. К пиву — классические закуски и горячее. Формат паба: шумно, уютно, не слишком дорого. Хорошее место для неформального вечера с коллегами или друзьями.", "en": "Berdinberg is a beer restaurant in a historic building on Prospekt Mira, and on beer selection it beats most competitors in the area: 30+ varieties from Germany, Czech Republic, USA, Scotland. Dark and light, filtered and unfiltered, sour and neutral. With the beer — classic appetizers and hot dishes. Pub format: noisy, cozy, not too expensive. A good place for an informal evening with colleagues or friends."}}'::jsonb, photos = ARRAY['/images/pois/berdinberg_12.webp','/images/pois/berdinberg_1.webp','/images/pois/berdinberg_2.webp','/images/pois/berdinberg_3.webp','/images/pois/berdinberg_4.webp','/images/pois/berdinberg_5.webp','/images/pois/berdinberg_6.webp','/images/pois/berdinberg_7.webp','/images/pois/berdinberg_8.webp','/images/pois/berdinberg_9.webp','/images/pois/berdinberg_10.webp','/images/pois/berdinberg_11.webp']::text[], rating = 3.8, hours = '{"sun": "12:00-23:00", "mon": "12:00-23:00", "tue": "12:00-23:00", "wed": "12:00-23:00", "thu": "12:00-23:00", "fri": "12:00-23:00", "sat": "12:00-23:00"}'::jsonb, phone = '+7 (8672) 54-06-54', website = 'https://berdinberg.ru/', price_level = 2, tags = ARRAY['пивной ресторан','бургеры','европейская кухня','спортивные трансляции']::text[], is_chain = false, has_menu = true, has_delivery = true, radius = 50, review_count = 33, updated_at = now() WHERE id = 'poi-079';
UPDATE pois SET name = '{"ru": "Осетинская пивоварня", "en": "Ossetian Brewery"}'::jsonb, category = 'food'::poi_category, subcategory = 'bar', cuisine_type = 'european'::cuisine_type, location = '{"lat": 43.034572, "lng": 44.637833, "address": {"ru": "Весенняя ул., 1, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362047", "en": "Vesennyaya St. 1a, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Гастропаб с собственной пивоварней. Высочайший рейтинг на TripAdvisor (4.8). Кавказская кухня и...", "en": "Gastropub with its own brewery. Highest TripAdvisor rating (4.8). Caucasian cuisine and craft..."}, "medium": {"ru": "Гастропаб с собственной пивоварней. Высочайший рейтинг на TripAdvisor (4.8). Кавказская кухня и крафтовое осетинское пиво. Есть также филиал на просп. Мира, 52. Аутентичная атмосфера.", "en": "Gastropub with its own brewery. Highest TripAdvisor rating (4.8). Caucasian cuisine and craft Ossetian beer. Also has a branch at Prospekt Mira 52. Authentic atmosphere."}, "full": {"ru": "Гастропаб «Осетинская пивоварня» варит своё пиво прямо здесь — и это чувствуется в стакане. Светлое, тёмное, нефильтрованное: несколько собственных сортов плюс гостевые крафтовые позиции. Кухня — кавказские закуски, мясо, что-то посытнее для тех, кто пришёл поесть. Рейтинг 4.8 держится не случайно: здесь следят за качеством и того и другого. Формат демократичный, атмосфера дружелюбная.", "en": "The Ossetian Brewery gastropub brews its own beer right here — and you can taste it in the glass. Light, dark, unfiltered: several house varieties plus guest craft options. The food covers Caucasian appetizers, meat dishes, something substantial for those who came to eat rather than just drink. The 4.8 rating doesn''t maintain itself: they watch quality of both food and beer. Format is casual, atmosphere is friendly."}}'::jsonb, photos = ARRAY['/images/pois/osetinskaya-pivovarnya_int_5.webp','/images/pois/ossetian-brewery_gp.webp','/images/pois/osetinskaya-pivovarnya_int_2.webp','/images/pois/osetinskaya-pivovarnya_int_3.webp','/images/pois/osetinskaya-pivovarnya_int_4.webp','/images/pois/osetinskaya-pivovarnya_menu_4.webp']::text[], rating = 4.6, hours = '{"sun": "12:00-23:59", "mon": "12:00-00:00", "tue": "12:00-00:00", "wed": "12:00-00:00", "thu": "12:00-00:00", "fri": "12:00-00:00", "sat": "12:00-00:00"}'::jsonb, phone = '+7 928 861-00-86', website = 'https://www.instagram.com/beer_vladikavkaz/', price_level = 2, tags = ARRAY['крафтовое пиво','пивоварня','гастропаб','закуски','спортивные трансляции']::text[], is_chain = false, has_menu = true, has_delivery = false, radius = 50, review_count = 486, updated_at = now() WHERE id = 'poi-081';
UPDATE pois SET name = '{"ru": "Лимончелло", "en": "Limoncello"}'::jsonb, category = 'food'::poi_category, subcategory = 'restaurant', cuisine_type = 'european'::cuisine_type, location = '{"lat": 43.033155, "lng": 44.67979, "address": {"ru": "пр. Мира, 45, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362040", "en": "Prospekt Mira 45-47, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Итальянский ресторан в самом центре города на пешеходном проспекте Мира. Паста, пицца, гриль,...", "en": "Italian restaurant in the very heart of the city on pedestrian Prospekt Mira. Pasta, pizza, grill,..."}, "medium": {"ru": "Итальянский ресторан в самом центре города на пешеходном проспекте Мира. Паста, пицца, гриль, барбекю. Уютная атмосфера, популярен у местных и туристов. Входит в топ-10 ресторанов Владикавказа на TripAdvisor.", "en": "Italian restaurant in the very heart of the city on pedestrian Prospekt Mira. Pasta, pizza, grill, BBQ. Cozy atmosphere, popular with locals and tourists. Top-10 restaurant in Vladikavkaz on TripAdvisor."}, "full": {"ru": "Итальянская кухня в самом центре — на пешеходном проспекте Мира. «Лимончелло» делает пасту и пиццу так, как и должны: тесто собственного замеса, соусы без компромиссов. Интерьер тёплый — дерево, мягкий свет, небольшие столики. Хорошее место для обеда между музеями или для вечера, когда хочется чего-то лёгкого. Веранда в сезон. Цены умеренные для такого расположения.", "en": "Italian cuisine right in the center — on the pedestrian Prospekt Mira. Limonchello makes pasta and pizza the way they should be: house-made dough, sauces without compromise. The interior is warm — wood, soft light, small tables. Good for lunch between museums or an evening when you want something light. Terrace in season. Moderate prices for such a location."}}'::jsonb, photos = ARRAY['/images/pois/limoncello_gp.webp','/images/pois/limonchello_int_2.webp','/images/pois/limonchello_int_4.webp','/images/pois/limonchello_int_5.webp','/images/pois/limonchello_menu_2.webp']::text[], rating = 4.4, hours = '{"sun": "11:00-23:00", "mon": "11:00-23:00", "tue": "11:00-23:00", "wed": "11:00-23:00", "thu": "11:00-23:00", "fri": "11:00-23:00", "sat": "11:00-23:00"}'::jsonb, phone = '+7 867 240-36-60', website = 'https://premier-cru.ru/restaurant/restoran-limonchello/', price_level = 2, tags = ARRAY['итальянская кухня','пицца','суши','доставка']::text[], is_chain = false, has_menu = true, has_delivery = false, radius = 50, review_count = 882, updated_at = now() WHERE id = 'poi-082';
UPDATE pois SET name = '{"ru": "Минас", "en": "Minas"}'::jsonb, category = 'food'::poi_category, subcategory = 'cafe', cuisine_type = 'national'::cuisine_type, location = '{"lat": 43.025639, "lng": 44.638366, "address": {"ru": "ул. Барбашова, 76, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362020", "en": "Barbashova St. 76, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Популярное кафе с грузинской и кавказской кухней. Отличный шашлык по доступной цене (~465 руб/500г).", "en": "Popular cafe with Georgian and Caucasian cuisine. Excellent shashlik at affordable prices (~465..."}, "medium": {"ru": "Популярное кафе с грузинской и кавказской кухней. Отличный шашлык по доступной цене (~465 руб/500г). Летняя веранда, бесплатный Wi-Fi. Работает ежедневно 10:30–23:00.", "en": "Popular cafe with Georgian and Caucasian cuisine. Excellent shashlik at affordable prices (~465 RUB/500g). Summer terrace, free Wi-Fi. Open daily 10:30-23:00."}, "full": {"ru": "«Минас» ценят за конкретную вещь: шашлык. Тут его делают правильно — нежное мясо с угольным ароматом, хорошая маринация, не пережаренное. Цена около 465 рублей за 500 г — честно. Летняя веранда, бесплатная парковка, быстрое обслуживание. Формат кафе без претензий, зато надёжно. Если едете на один день и хотите хороший шашлык — это рабочий вариант.", "en": "Minas is valued for one specific thing: shashlik. They do it right — tender meat with coal aroma, good marinade, not overcooked. Price around 465 rubles per 500g — fair. Summer terrace, free parking, fast service. Café format without pretensions, but reliable. If you''re visiting for one day and want good shashlik — this is a solid choice."}}'::jsonb, photos = ARRAY['/images/pois/minas_10.webp','/images/pois/minas_1.webp','/images/pois/minas_2.webp','/images/pois/minas_3.webp','/images/pois/minas_4.webp','/images/pois/minas_5.webp','/images/pois/minas_6.webp','/images/pois/minas_7.webp','/images/pois/minas_8.webp','/images/pois/minas_9.webp']::text[], rating = 4.4, hours = '{"sun": "10:30-23:30", "mon": "10:30-23:00", "tue": "10:30-23:00", "wed": "10:30-23:00", "thu": "10:30-23:00", "fri": "10:30-23:00", "sat": "10:30-23:00"}'::jsonb, phone = '+7 867 252-17-27', website = 'http://cafeminas.ru/', price_level = 2, tags = ARRAY['армянская кухня','грузинская кухня','кавказская кухня','бизнес-ланч','доставка']::text[], is_chain = false, has_menu = true, has_delivery = false, radius = 50, review_count = 691, updated_at = now() WHERE id = 'poi-084';
UPDATE pois SET name = '{"ru": "Бавария", "en": "Bavaria"}'::jsonb, category = 'food'::poi_category, subcategory = 'bar', cuisine_type = 'european'::cuisine_type, location = '{"lat": 43.05344, "lng": 44.673313, "address": {"ru": "ул. Цаликова, 25, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362021", "en": "Tsalikova St. 25, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Пивной ресторан с собственной пивоварней, работает с 2001 года. Интерьер в немецком стиле с...", "en": "Beer restaurant with its own brewery, open since 2001. German-style interior with massive wooden..."}, "medium": {"ru": "Пивной ресторан с собственной пивоварней, работает с 2001 года. Интерьер в немецком стиле с массивными деревянными столами. Блюда на гриле, летняя веранда, доставка. Рейтинг 4.8 на Restaurant Guru.", "en": "Beer restaurant with its own brewery, open since 2001. German-style interior with massive wooden tables. Grilled dishes, summer terrace, delivery. Rated 4.8 on Restaurant Guru."}, "full": {"ru": "«Бавария» работает с 2001 года — и за это время стала частью городского пейзажа. Пивоварня при ресторане, немецкий стиль в интерьере (массивные столы, кружки по полтора литра, оленьи рога на стенах), живое пиво собственного производства. Это место, где отмечают дни рождения, провожают в армию, собираются на матчи. Шумно, демократично, вместительно. Закуски стандартные, пиво — главный аргумент.", "en": "Bavaria has been open since 2001 — and in that time has become part of the city landscape. In-house brewery, German-style interior (heavy tables, 1.5-liter mugs, antlers on the walls), live house-brewed beer. This is where people celebrate birthdays, send off draftees, gather for match screenings. Noisy, casual, spacious. The food is standard; the beer is the main argument."}}'::jsonb, photos = ARRAY['/images/pois/bavariya_15.webp','/images/pois/bavariya_1.webp','/images/pois/bavariya_2.webp','/images/pois/bavariya_3.webp','/images/pois/bavariya_4.webp','/images/pois/bavariya_5.webp','/images/pois/bavariya_6.webp','/images/pois/bavariya_7.webp','/images/pois/bavariya_8.webp','/images/pois/bavariya_9.webp','/images/pois/bavariya_10.webp','/images/pois/bavariya_11.webp','/images/pois/bavariya_12.webp','/images/pois/bavariya_13.webp','/images/pois/bavariya_14.webp']::text[], rating = 4.5, hours = '{"sun": "10:00-23:00", "mon": "10:00-23:00", "tue": "10:00-23:00", "wed": "10:00-23:00", "thu": "10:00-23:00", "fri": "10:00-23:00", "sat": "10:00-23:00"}'::jsonb, phone = '+7 867 276-78-26', website = 'http://bavaria-rest.ru/', price_level = 2, tags = ARRAY['немецкая кухня','пиво','пивоварня','гриль','банкеты']::text[], is_chain = false, has_menu = true, has_delivery = true, radius = 50, review_count = 836, updated_at = now() WHERE id = 'poi-085';
UPDATE pois SET name = '{"ru": "Жемчужина", "en": "Zhemchuzhina (Pearl)"}'::jsonb, category = 'food'::poi_category, subcategory = 'restaurant', cuisine_type = 'mixed'::cuisine_type, location = '{"lat": 42.997899, "lng": 44.674717, "address": {"ru": "просп. Коста, 11а, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362006", "en": "Prospekt Kosta 11a, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Историческое заведение в курортной зоне у мемориала славы и водной станции. Кавказская и...", "en": "Historic establishment in the resort zone near the glory memorial and water station. Caucasian and..."}, "medium": {"ru": "Историческое заведение в курортной зоне у мемориала славы и водной станции. Кавказская и европейская кухня. Павильон на открытом воздухе, живая музыка. Средний чек ~1500 руб. Работает с 8:30.", "en": "Historic establishment in the resort zone near the glory memorial and water station. Caucasian and European cuisine. Outdoor pavilion, live music. Average check ~1500 RUB. Opens at 8:30."}, "full": {"ru": "«Жемчужина» — историческое заведение в курортной части города, у мемориала Славы. Большой павильон, открытая терраса, кавказская и европейская кухня. Это место, которое помнят владикавказцы со стажем: здесь гуляли семьями ещё в советское время. Интерьер немного устарел, но этим и хорош — честное место без попыток быть модным. Порции большие, цены средние. Хорошо для большой группы.", "en": "Zhemchuzhina is a historic establishment in the resort part of the city, near the Memorial of Glory. A large pavilion, open terrace, Caucasian and European cuisine. This is a place that long-time Vladikavkaz residents remember: families came here in Soviet times too. The interior is somewhat dated, but that''s its charm — an honest place without any attempt to be trendy. Large portions, average prices. Good for a large group."}}'::jsonb, photos = ARRAY['/images/pois/zhemchuzhina_5.webp','/images/pois/zhemchuzhina_1.webp','/images/pois/zhemchuzhina_7.webp','/images/pois/zhemchuzhina_2.webp','/images/pois/zhemchuzhina_3.webp','/images/pois/zhemchuzhina_4.webp','/images/pois/zhemchuzhina_6.webp']::text[], rating = 4.5, hours = '{"sun": "09:00-23:59", "mon": "09:00-00:00", "tue": "09:00-00:00", "wed": "09:00-00:00", "thu": "09:00-00:00", "fri": "09:00-00:00", "sat": "09:00-00:00"}'::jsonb, phone = '+7 867 225-94-34', website = 'http://ресторан-жемчужина.рф/', price_level = 2, tags = ARRAY['европейская кухня','кавказская кухня','банкеты','доставка']::text[], is_chain = false, has_menu = true, has_delivery = false, radius = 50, review_count = 516, updated_at = now() WHERE id = 'poi-087';
UPDATE pois SET name = '{"ru": "Midov Coffee", "en": "Midov Coffee"}'::jsonb, category = 'food'::poi_category, subcategory = 'cafe', cuisine_type = 'european'::cuisine_type, location = '{"lat": 43.020335, "lng": 44.682765, "address": {"ru": "ул. Гаппо Баева, 29, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362007", "en": "Prospekt Mira 12, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Прогрессивная кофейня на главной пешеходной улице. Классика и авторские напитки: «Рафф Хазнидон» с...", "en": "Progressive coffeehouse on the main pedestrian street. Classics and signature drinks: ''Raff..."}, "medium": {"ru": "Прогрессивная кофейня на главной пешеходной улице. Классика и авторские напитки: «Рафф Хазнидон» с малиной, «23:41» — арабский латте с домашним пряным соусом. Несколько филиалов в городе.", "en": "Progressive coffeehouse on the main pedestrian street. Classics and signature drinks: ''Raff Haznidon'' with raspberry, ''23:41'' — Arabic latte with house-made spiced sauce. Several branches in the city."}, "full": {"ru": "«Мидов Кофе» на проспекте Мира — это прогрессивная кофейня в городе, где ещё несколько лет назад с кофе было скромно. Здесь знают, что такое эспрессо, умеют в альтернативные методы заварки и придумывают собственные напитки. «Рафф Хазнидон» с малиной, «23:41» — авторские позиции, которые стоит попробовать. Зерно свежее, оборудование правильное. Хорошее место, чтобы зайти утром перед прогулкой по проспекту.", "en": "Midov Coffee on Prospekt Mira is a progressive coffee shop in a city that not long ago had little to offer in that department. They understand espresso, work with alternative brewing methods, and create their own drinks. ''Raff Khaznidon'' with raspberry, ''23:41'' — house originals worth trying. Fresh beans, proper equipment. A good place to stop in the morning before walking the prospekt."}}'::jsonb, photos = ARRAY['/images/pois/midov-coffee_gp.webp','/images/pois/midov-coffee_int_1.webp','/images/pois/midov-coffee_int_2.webp','/images/pois/midov-coffee_int_3.webp','/images/pois/midov-coffee_int_4.webp','/images/pois/midov-coffee_int_5.webp','/images/pois/midov-coffee_menu_1.webp']::text[], rating = 3.7, hours = '{"sun": "10:00-22:00", "mon": "09:00-22:00", "tue": "09:00-22:00", "wed": "09:00-22:00", "thu": "09:00-22:00", "fri": "09:00-22:00", "sat": "10:00-22:00"}'::jsonb, phone = '+7 (918) 827-88-00', website = 'https://instagram.com/midov_coffee?utm_medium=copy_link', price_level = 1, tags = ARRAY['кофейня','кофе','десерты','завтраки']::text[], is_chain = false, has_menu = true, has_delivery = false, radius = 50, review_count = 9, updated_at = now() WHERE id = 'poi-090';
UPDATE pois SET name = '{"ru": "Coffenberg", "en": "Coffenberg"}'::jsonb, category = 'food'::poi_category, subcategory = 'cafe', cuisine_type = 'european'::cuisine_type, location = '{"lat": 43.041165, "lng": 44.636738, "address": {"ru": "ул. Морских пехотинцев, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362047", "en": "Prospekt Mira, Vladikavkaz (chain, multiple locations)"}}'::jsonb, description = '{"short": {"ru": "Крупнейшая сеть кофеен республики. «Осетиано» (американо по-местному) — 120 руб., другие напитки...", "en": "Largest coffee chain in the republic. ''Ossetiano'' (local Americano) — 120 RUB, other drinks 100-170..."}, "medium": {"ru": "Крупнейшая сеть кофеен республики. «Осетиано» (американо по-местному) — 120 руб., другие напитки 100–170 руб. Десерты и выпечка. Средний чек ~300 руб. Работает с 7:00.", "en": "Largest coffee chain in the republic. ''Ossetiano'' (local Americano) — 120 RUB, other drinks 100-170 RUB. Desserts and pastries. Average check ~300 RUB. Opens at 7:00."}, "full": {"ru": "«Коффенберг» — сеть, которая давно стала кофейным стандартом Владикавказа. «Осетиано» — это их версия американо, ставшая чем-то вроде локального мема: все знают, что это значит, и все его заказывают. Несколько точек в городе, предсказуемое качество, невысокие цены. Хорошие десерты. Место не для открытий, а для надёжного кофе в любой точке маршрута. Если нужна рабочая кофейня с Wi-Fi — это оно.", "en": "Coffenberg is the chain that long ago became Vladikavkaz''s coffee standard. ''Ossetiano'' — their version of an americano, which has become something of a local meme: everyone knows what it means and everyone orders it. Several locations across the city, predictable quality, low prices. Good pastries. Not a place for discoveries, but for reliable coffee at any point on your city route. If you need a working café with Wi-Fi — this is it."}}'::jsonb, photos = ARRAY['/images/pois/coffenberg_int_3.webp','/images/pois/coffenberg_int_4.webp','/images/pois/coffenberg_gp.webp','/images/pois/coffenberg_int_2.webp','/images/pois/coffenberg_int_5.webp','/images/pois/coffenberg_menu_3.webp']::text[], rating = 5, hours = '{"sun": "08:00-23:00", "mon": "08:00-23:00", "tue": "08:00-23:00", "wed": "08:00-23:00", "thu": "08:00-23:00", "fri": "08:00-23:00", "sat": "08:00-23:00"}'::jsonb, phone = '+7 918 701-66-77', website = 'https://www.instagram.com/coffenberg.ru/', price_level = 1, tags = ARRAY['кофейня','кофе','выпечка']::text[], is_chain = false, has_menu = true, has_delivery = true, radius = 50, review_count = 2, updated_at = now() WHERE id = 'poi-091';
UPDATE pois SET name = '{"ru": "Горка", "en": "Gorka"}'::jsonb, category = 'food'::poi_category, subcategory = 'cafe', cuisine_type = 'european'::cuisine_type, location = '{"lat": 43.018002, "lng": 44.679539, "address": {"ru": "ул. Гадиева, 2/1, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362000", "en": "Central Park (Khetagurov Park), Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Историческое кафе в центральном парке, рядом с национальным музеем. Кофе с десертами на террасе с...", "en": "Historic cafe in the central park, near the national museum. Coffee with desserts on a terrace..."}, "medium": {"ru": "Историческое кафе в центральном парке, рядом с национальным музеем. Кофе с десертами на террасе с видом на парк. Высочайший рейтинг на TripAdvisor. Уютная атмосфера для прогулки.", "en": "Historic cafe in the central park, near the national museum. Coffee with desserts on a terrace overlooking the park. Highest TripAdvisor rating. Cozy atmosphere for a stroll."}, "full": {"ru": "Кафе «Горка» стоит в центральном парке у Национального музея — и уже поэтому хорошее место для паузы. Терраса смотрит на деревья, кофе нормальный, десерты выше среднего по городу. Сюда заходят после музея, перед театром, в перерыве между делами. Высокий рейтинг держится на стабильности: всё предсказуемо хорошо, ничего не удивляет в плохом смысле. Место для спокойного часа.", "en": "Café Gorka stands in the central park next to the National Museum — and that alone makes it a good place to pause. The terrace looks out at trees, the coffee is solid, the desserts are above city average. People come here after the museum, before the theatre, between errands. The high rating is sustained by consistency: everything is reliably good, nothing surprises you badly. A place for a quiet hour."}}'::jsonb, photos = ARRAY['/images/pois/gorka_4.webp','/images/pois/gorka_1.webp','/images/pois/gorka_2.webp','/images/pois/gorka_3.webp','/images/pois/gorka_5.webp']::text[], rating = 3.9, hours = '{"sun": "11:00-23:00", "mon": "11:00-23:00", "tue": "11:00-23:00", "wed": "11:00-23:00", "thu": "11:00-23:00", "fri": "11:00-23:00", "sat": "11:00-23:00"}'::jsonb, phone = '+7 928 481-28-58', website = 'https://www.instagram.com/gorka_cafe/', price_level = 2, tags = ARRAY['кофейня','кондитерская','панорамный вид','парк','десерты']::text[], is_chain = false, has_menu = true, has_delivery = true, radius = 50, review_count = 69, updated_at = now() WHERE id = 'poi-092';
UPDATE pois SET name = '{"ru": "Отель «Империал»", "en": "Imperial Hotel"}'::jsonb, category = 'accommodation'::poi_category, subcategory = 'Отель', cuisine_type = NULL, location = '{"lat": 43.028453, "lng": 44.680383, "address": {"ru": "пр. Мира, 19, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362040", "en": "19 Mira Ave, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Гостиница «Империал» — памятник архитектуры 1896 года постройки, расположенный на проспекте Мира.", "en": "Imperial Hotel is an architectural monument built in 1896, located on Mira Avenue."}, "medium": {"ru": "Гостиница «Империал» — памятник архитектуры 1896 года постройки, расположенный на проспекте Мира. 25 комфортабельных номеров различных категорий. В отеле есть сауна, бассейн, салон красоты и зимний сад.", "en": "Imperial Hotel is an architectural monument built in 1896, located on Mira Avenue. It offers 25 comfortable rooms of various categories. The hotel features a sauna, pool, beauty salon, and winter garden."}, "full": {"ru": "Гостиница «Империал» — один из старейших отелей Владикавказа, построенный в 1896 году и являющийся памятником архитектуры и истории. Расположен в историческом центре города на главном проспекте Мира. Отель предлагает 25 номеров различных категорий — от стандарта до люкса. К услугам гостей — сейф, парковка с круглосуточной охраной, вызов такси, салон красоты, оздоровительный комплекс с сауной и бассейном, зимний сад. Идеальный выбор для тех, кто ценит историческую атмосферу и центральное расположение.", "en": "Imperial Hotel is one of the oldest hotels in Vladikavkaz, built in 1896 and recognized as an architectural and historical monument. Located in the historic city center on the main Mira Avenue, the hotel offers 25 rooms of various categories — from standard to suite. Guests can enjoy a safe, 24-hour guarded parking, taxi service, beauty salon, wellness complex with sauna and pool, and a winter garden. An ideal choice for those who appreciate historic atmosphere and central location."}}'::jsonb, photos = ARRAY['/images/pois/imperial-hotel_facade.webp','/images/pois/imperial-hotel_1.webp','/images/pois/imperial-hotel_2.webp','/images/pois/imperial-hotel_3.webp','/images/pois/imperial-hotel_4.webp','/images/pois/imperial-hotel_5.webp','/images/pois/imperial-hotel_6.webp']::text[], rating = 4.1, hours = '{"mon": "00:00-23:59"}'::jsonb, phone = '+7 867 254-74-74', website = 'http://intourist-ossetia.ru', price_level = 3, tags = ARRAY['исторический отель','центр города','бассейн','сауна','памятник архитектуры']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 80, review_count = 221, updated_at = now() WHERE id = 'poi-100';
UPDATE pois SET name = '{"ru": "Гостиница «Владикавказ»", "en": "Hotel Vladikavkaz"}'::jsonb, category = 'accommodation'::poi_category, subcategory = 'Гостиница', cuisine_type = NULL, location = '{"lat": 43.026899, "lng": 44.674293, "address": {"ru": "ул. Коцоева, 75, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362003", "en": "75 Kotsoyeva St, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Гостиница «Владикавказ» расположена в центре города с видом на реку Терек и горные хребты.", "en": "Hotel Vladikavkaz is located in the city center with views of the Terek River and mountain ranges."}, "medium": {"ru": "Гостиница «Владикавказ» расположена в центре города с видом на реку Терек и горные хребты. 203 номера со всем необходимым для полноценного отдыха. До аэропорта — 27 км, до ж/д вокзала — 3 км.", "en": "Hotel Vladikavkaz is located in the city center with views of the Terek River and mountain ranges. 203 rooms with everything needed for a comfortable stay. 27 km to the airport, 3 km to the railway station."}, "full": {"ru": "Гостиница «Владикавказ» — крупнейший отель города, входящий в группу «Интурист-Осетия». Расположена на набережной реки Терек в самом сердце Владикавказа. Из окон открываются великолепные виды на горные вершины и живописную набережную. 203 номера различных категорий обеспечивают комфортное размещение для деловых путешественников и туристов. На территории работают ресторан, конференц-зал, парковка. Удобное расположение позволяет пешком добраться до основных достопримечательностей города.", "en": "Hotel Vladikavkaz is the city''s largest hotel, part of the Intourist-Ossetia group. Located on the embankment of the Terek River in the very heart of Vladikavkaz, its windows offer magnificent views of mountain peaks and the picturesque waterfront. 203 rooms of various categories provide comfortable accommodation for business travelers and tourists. The property features a restaurant, conference hall, and parking. Its convenient location allows walking access to the city''s main attractions."}}'::jsonb, photos = ARRAY['/images/pois/hotel-vladikavkaz_facade.webp','/images/pois/hotel-vladikavkaz_1.webp','/images/pois/hotel-vladikavkaz_2.webp','/images/pois/hotel-vladikavkaz_3.webp','/images/pois/hotel-vladikavkaz_4.webp','/images/pois/hotel-vladikavkaz_5.webp','/images/pois/hotel-vladikavkaz_6.webp','/images/pois/hotel-vladikavkaz_7.webp','/images/pois/hotel-vladikavkaz_8.webp','/images/pois/hotel-vladikavkaz_9.webp']::text[], rating = 4.4, hours = '{"mon": "00:00-23:59"}'::jsonb, phone = '+7 800 222-93-55', website = 'https://vladikavkaz-hotel.ru/', price_level = 2, tags = ARRAY['набережная','вид на горы','конференц-зал','большой отель']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 80, review_count = 1101, updated_at = now() WHERE id = 'poi-101';
UPDATE pois SET name = '{"ru": "Гостиница «Планета Люкс» (бывш. «Кавказ»)", "en": "Hotel Planeta Lux (former Kavkaz)"}'::jsonb, category = 'accommodation'::poi_category, subcategory = 'Гостиница', cuisine_type = NULL, location = '{"lat": 43.02801, "lng": 44.691057, "address": {"ru": "ул. Ватутина, 50, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362025", "en": "50 Vatutina St, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Гостиница «Планета Люкс» (бывшая «Кавказ») — историческое здание-памятник культуры во Владикавказе.", "en": "Hotel Planeta Lux (former Kavkaz) is a historic cultural monument building in Vladikavkaz."}, "medium": {"ru": "Гостиница «Планета Люкс» (бывшая «Кавказ») — историческое здание-памятник культуры во Владикавказе. Обновлённые номера с современным комфортом сочетаются с архитектурным наследием. Расположена в спокойном районе города.", "en": "Hotel Planeta Lux (former Kavkaz) is a historic cultural monument building in Vladikavkaz. Renovated rooms with modern comfort are combined with architectural heritage. Located in a quiet district of the city."}, "full": {"ru": "Гостиница «Планета Люкс», ранее известная как «Кавказ», — одно из исторических зданий Владикавказа, находящееся под государственной охраной как памятник культуры. После реконструкции отель сочетает историческую архитектуру с современным комфортом. Номера оснащены всем необходимым для комфортного проживания. Расположена на улице Ватутина, в пешей доступности от центра города. Хороший выбор для путешественников, которые ищут спокойное размещение с историческим шармом и доступными ценами.", "en": "Hotel Planeta Lux, formerly known as Kavkaz, is one of Vladikavkaz''s historic buildings, protected by the state as a cultural monument. After reconstruction, the hotel combines historic architecture with modern comfort. Rooms are equipped with everything necessary for a comfortable stay. Located on Vatutina Street within walking distance of the city center. A good choice for travelers looking for quiet accommodation with historic charm and affordable prices."}}'::jsonb, photos = ARRAY['/images/pois/hotel-kavkaz-planeta-lux_facade.webp','/images/pois/hotel-kavkaz-planeta-lux_1.webp','/images/pois/hotel-kavkaz-planeta-lux_2.webp','/images/pois/hotel-kavkaz-planeta-lux_3.webp']::text[], rating = 4.4, hours = '{"mon": "00:00-23:59"}'::jsonb, phone = '+7 867 253-49-26', website = 'http://hotelplanetlux.ru/', price_level = 2, tags = ARRAY['памятник культуры','историческое здание','бюджетный']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 80, review_count = 516, updated_at = now() WHERE id = 'poi-104';
UPDATE pois SET name = '{"ru": "Отель «Амран»", "en": "Amran Hotel"}'::jsonb, category = 'accommodation'::poi_category, subcategory = 'Отель', cuisine_type = NULL, location = '{"lat": 43.039169, "lng": 44.686049, "address": {"ru": "ул. Маркова, 28, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362000", "en": "28 Markova St, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Отель «Амран» — комфортная 3-звёздочная гостиница в центре Владикавказа вблизи железнодорожного вокзала.", "en": "Amran Hotel is a comfortable 3-star hotel in the center of Vladikavkaz near the railway station."}, "medium": {"ru": "Отель «Амран» — комфортная 3-звёздочная гостиница в центре Владикавказа вблизи железнодорожного вокзала. 49 просторных номеров, сауна, бассейн 8 метров, конференц-зал, охраняемая парковка.", "en": "Amran Hotel is a comfortable 3-star hotel in the center of Vladikavkaz near the railway station. 49 spacious rooms, sauna, 8-meter pool, conference hall, and guarded parking."}, "full": {"ru": "Отель «Амран» — современная 3-звёздочная гостиница, расположенная в центральной части Владикавказа рядом с железнодорожным вокзалом. Предлагает 49 просторных и комфортабельных номеров с кондиционером. К услугам гостей — сауна, бассейн длиной 8 метров, конференц-зал, прачечная, охраняемая парковка, сейф и камера хранения. Благодаря близости к вокзалу, отель особенно удобен для путешественников, прибывающих поездом. Отличное соотношение цены и качества для делового и туристического размещения.", "en": "Amran Hotel is a modern 3-star hotel located in the central part of Vladikavkaz near the railway station. It offers 49 spacious and comfortable rooms with air conditioning. Guests can enjoy a sauna, 8-meter swimming pool, conference hall, laundry service, guarded parking, safe, and luggage storage. Due to its proximity to the station, the hotel is especially convenient for travelers arriving by train. Excellent value for money for both business and tourist accommodation."}}'::jsonb, photos = ARRAY['/images/pois/amran-hotel_facade.webp','/images/pois/amran-hotel_1.webp','/images/pois/amran-hotel_2.webp','/images/pois/amran-hotel_3.webp','/images/pois/amran-hotel_4.webp']::text[], rating = 4, hours = '{"sun": "08:00-23:00", "mon": "08:00-23:00", "tue": "08:00-23:00", "wed": "08:00-23:00", "thu": "08:00-23:00", "fri": "08:00-23:00", "sat": "08:00-23:00"}'::jsonb, phone = '+7 867 250-11-34', website = 'http://www.vladikavkaz-amran.ru/', price_level = 2, tags = ARRAY['3 звезды','бассейн','рядом с вокзалом','парковка']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 80, review_count = 229, updated_at = now() WHERE id = 'poi-105';
UPDATE pois SET name = '{"ru": "Гостевой дом «1950» в Цее", "en": "Guesthouse 1950 in Tsey"}'::jsonb, category = 'accommodation'::poi_category, subcategory = 'Гостевой дом', cuisine_type = NULL, location = '{"lat": 42.808169, "lng": 43.959547, "address": {"ru": "Абайтикау, Респ. Северная Осетия — Алания, Россия, 363225", "en": "Verkhny Tsey, Alagirsky District, North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Гостевой дом «1950» расположен в Цейском ущелье на высоте 1950 метров над уровнем моря, в 80 км от Владикавказа.", "en": "Guesthouse 1950 is located in Tsey Gorge at 1950 meters above sea level, 80 km from Vladikavkaz."}, "medium": {"ru": "Гостевой дом «1950» расположен в Цейском ущелье на высоте 1950 метров над уровнем моря, в 80 км от Владикавказа. 12 комфортных номеров с шумоизоляцией, камин, терраса, мангальная зона и потрясающие горные виды.", "en": "Guesthouse 1950 is located in Tsey Gorge at 1950 meters above sea level, 80 km from Vladikavkaz. 12 comfortable soundproofed rooms, fireplace, terrace, BBQ area, and stunning mountain views."}, "full": {"ru": "Гостевой дом «1950» — уединённое горное убежище в живописном Цейском ущелье на высоте 1950 метров. Расположен в 80 км от Владикавказа среди хвойных лесов и горных вершин. 12 номеров оборудованы удобной мебелью, рабочим столом и ванной комнатой с хорошей шумоизоляцией. В общих зонах — камин, гостиная, терраса с панорамным видом на горы, собственная мангальная зона. Идеальное место для уединённого ретрита, длительного проживания в горах или как база для треккинга к Цейскому и Сказскому ледникам.", "en": "Guesthouse 1950 is a secluded mountain retreat in the picturesque Tsey Gorge at 1950 meters altitude. Located 80 km from Vladikavkaz among coniferous forests and mountain peaks. 12 rooms are equipped with comfortable furniture, a desk, and a bathroom with good soundproofing. Common areas include a fireplace, living room, panoramic mountain-view terrace, and a private BBQ area. An ideal place for a secluded retreat, extended mountain stays, or as a base for trekking to the Tsey and Skazsky glaciers."}}'::jsonb, photos = ARRAY['/images/pois/guesthouse-1950-tsey_facade.webp','/images/pois/guesthouse-1950-tsey_1.webp','/images/pois/guesthouse-1950-tsey_2.webp','/images/pois/guesthouse-1950-tsey_3.webp','/images/pois/guesthouse-1950-tsey_4.webp','/images/pois/guesthouse-1950-tsey_5.webp','/images/pois/guesthouse-1950-tsey_6.webp','/images/pois/guesthouse-1950-tsey_7.webp','/images/pois/guesthouse-1950-tsey_8.webp','/images/pois/guesthouse-1950-tsey_9.webp']::text[], rating = 4.8, hours = '{"mon": "00:00-23:59", "tue": "00:00-23:59", "wed": "00:00-23:59", "thu": "00:00-23:59", "fri": "00:00-23:59", "sat": "00:00-23:59", "sun": "00:00-23:59"}'::jsonb, phone = '+7 928 070-19-50', website = 'https://alt1950.ru/', price_level = 3, tags = ARRAY['горы','Цейское ущелье','камин','треккинг','уединение']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 80, review_count = 42, updated_at = now() WHERE id = 'poi-107';
UPDATE pois SET name = '{"ru": "Турбаза «Дзинага»", "en": "Dzinaga Mountain Base"}'::jsonb, category = 'accommodation'::poi_category, subcategory = 'Турбаза', cuisine_type = NULL, location = '{"lat": 42.909512, "lng": 43.697201, "address": {"ru": "Дзинага, Респ. Северная Осетия — Алания, Россия, 363518", "en": "Dzinaga Village, Irafsky District, North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Турбаза «Дзинага» находится в Дигорском ущелье в 115 км от Владикавказа на высоте 1490 м. Вместимость — 250 человек.", "en": "Dzinaga Mountain Base is located in Digorsky Gorge, 115 km from Vladikavkaz at 1490 m altitude. Capacity — 250 guests."}, "medium": {"ru": "Турбаза «Дзинага» находится в Дигорском ущелье в 115 км от Владикавказа на высоте 1490 м. Вместимость — 250 человек. Номера стандарт и VIP, столовая на 100 мест, кафе, бассейн, сауна, парковка.", "en": "Dzinaga Mountain Base is located in Digorsky Gorge, 115 km from Vladikavkaz at 1490 m altitude. Capacity — 250 guests. Standard and VIP rooms, 100-seat dining hall, cafe, pool, sauna, parking."}, "full": {"ru": "Турбаза «Дзинага» — крупнейшая база отдыха в Дигорском ущелье, одном из самых живописных мест Северной Осетии. Расположена рядом с селением Дзинага в Ирафском районе на высоте 1490 метров, в 115 км от Владикавказа. Одновременно вмещает около 250 человек в номерах стандарт и VIP. На территории — столовая на 100 мест, кафе на 60 мест, бассейн, сауна, бильярд, настольный теннис, спортивный комплекс, танцплощадка, беседки с мангалами, медпункт и охраняемая парковка. В номерах — телевизоры и бесплатный Wi-Fi. Отправная точка для маршрутов к Таймази водопадам и ледникам Дигории.", "en": "Dzinaga Mountain Base is the largest recreation base in Digorsky Gorge, one of the most scenic places in North Ossetia. Located near Dzinaga village in Irafsky District at 1490 meters altitude, 115 km from Vladikavkaz. It accommodates about 250 guests in standard and VIP rooms. The territory features a 100-seat dining hall, 60-seat cafe, pool, sauna, billiards, table tennis, sports complex, dance floor, gazebos with BBQs, medical station, and guarded parking. Rooms have TVs and free Wi-Fi. A starting point for routes to Taymazi waterfalls and Digoria glaciers."}}'::jsonb, photos = ARRAY['/images/pois/turbaza-dzinaga_facade.webp','/images/pois/turbaza-dzinaga_1.webp','/images/pois/turbaza-dzinaga_2.webp','/images/pois/turbaza-dzinaga_3.webp','/images/pois/turbaza-dzinaga_4.webp','/images/pois/turbaza-dzinaga_5.webp','/images/pois/turbaza-dzinaga_6.webp','/images/pois/turbaza-dzinaga_7.webp']::text[], rating = 4.6, hours = '{"mon": "00:00-23:59"}'::jsonb, phone = '+7 988 878-77-22', website = 'http://turbaza-dzinaga.ru/', price_level = 2, tags = ARRAY['Дигория','турбаза','бассейн','горы','ледники']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 80, review_count = 89, updated_at = now() WHERE id = 'poi-109';
UPDATE pois SET name = '{"ru": "Эко-парк «Ирбис» в Даргавсе", "en": "Irbis Eco-Park in Dargavs"}'::jsonb, category = 'accommodation'::poi_category, subcategory = 'Гостевой дом', cuisine_type = NULL, location = '{"lat": 42.862319, "lng": 44.44174, "address": {"ru": "Центральная, 1, Даргавс, Респ. Северная Осетия — Алания, Россия, 363128", "en": "Dargavs Village, Prigorodny District, North Ossetia"}}'::jsonb, description = '{"short": {"ru": "«Ирбис» — стильный эко-парк в селе Даргавс рядом со знаменитым «Городом мёртвых».", "en": "Irbis is a stylish eco-park in Dargavs village near the famous City of the Dead."}, "medium": {"ru": "«Ирбис» — стильный эко-парк в селе Даргавс рядом со знаменитым «Городом мёртвых». Комфортные номера, ресторан кавказской и европейской кухни, сауна с панорамным остеклением, уличный бассейн с подогревом.", "en": "Irbis is a stylish eco-park in Dargavs village near the famous City of the Dead. Comfortable rooms, Caucasian and European cuisine restaurant, panoramic sauna, heated outdoor pool."}, "full": {"ru": "Эко-парк «Ирбис» — современный гостевой комплекс в горном селе Даргавс, известном своим уникальным средневековым некрополем — «Городом мёртвых». В номерах — удобные кровати, интернет, телевизор, санузел с полотенцами и косметикой. В ресторане подают блюда кавказской и европейской кухни. На территории — сауна с панорамным остеклением на горы и уличный бассейн с подогревом. Идеальная база для посещения Даргавского некрополя, башенных комплексов и живописных маршрутов по Гизельдонскому ущелью.", "en": "Irbis Eco-Park is a modern guest complex in the mountain village of Dargavs, known for its unique medieval necropolis — the City of the Dead. Rooms feature comfortable beds, internet, TV, and bathrooms with towels and toiletries. The restaurant serves Caucasian and European cuisine. The grounds include a panoramic mountain-view sauna and a heated outdoor pool. An ideal base for visiting the Dargavs necropolis, tower complexes, and scenic routes through Gizeldon Gorge."}}'::jsonb, photos = ARRAY['/images/pois/irbis-ecopark-dargavs_facade.webp','/images/pois/irbis-ecopark-dargavs_1.webp','/images/pois/irbis-ecopark-dargavs_2.webp','/images/pois/irbis-ecopark-dargavs_3.webp','/images/pois/irbis-ecopark-dargavs_4.webp','/images/pois/irbis-ecopark-dargavs_5.webp','/images/pois/irbis-ecopark-dargavs_6.webp','/images/pois/irbis-ecopark-dargavs_7.webp']::text[], rating = 4.5, hours = '{"mon": "00:00-23:59", "tue": "00:00-23:59", "wed": "00:00-23:59", "thu": "00:00-23:59", "fri": "00:00-23:59", "sat": "00:00-23:59", "sun": "00:00-23:59"}'::jsonb, phone = '+7 928 070-14-99', website = 'https://irbisecopark.ru/', price_level = 3, tags = ARRAY['эко-парк','Даргавс','город мёртвых','бассейн','сауна']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 80, review_count = 48, updated_at = now() WHERE id = 'poi-110';
UPDATE pois SET name = '{"ru": "Альплагерь «Цей»", "en": "Tsey Alpine Camp"}'::jsonb, category = 'accommodation'::poi_category, subcategory = 'Альплагерь', cuisine_type = NULL, location = '{"lat": 42.783559, "lng": 43.901716, "address": {"ru": "Unnamed Road, Алания, Респ. Северная Осетия — Алания, Россия, 363225", "en": "Tsey Gorge, Alagirsky District, North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Альплагерь «Цей» — легендарная база альпинистов, основанная в 1934 году на высоте 2000 м.", "en": "Tsey Alpine Camp is a legendary mountaineering base founded in 1934 at 2000 m altitude."}, "medium": {"ru": "Альплагерь «Цей» — легендарная база альпинистов, основанная в 1934 году на высоте 2000 м. Размещение в номерах основного здания, коттеджах «Приют Монаха» и «Айсхаус», а также в палаточном лагере.", "en": "Tsey Alpine Camp is a legendary mountaineering base founded in 1934 at 2000 m altitude. Accommodation in main building rooms, Priyut Monakha and Icehouse cottages, and a tent camp."}, "full": {"ru": "Альплагерь «Цей» — одна из старейших альпинистских баз Кавказа, основанная в 1934 году и расположенная на высоте 2000 метров в Цейском ущелье. Предлагает несколько видов размещения: номера на 2-8 человек в основном здании с санузлом на этаже, коттедж «Приют Монаха» с пятиэтажной башней и мансардой, коттедж «Айсхаус», а также бюджетный палаточный лагерь от 350 руб/сутки. При заселении обязателен паспорт и страховка от несчастного случая. База используется альпинистами, скалолазами и любителями горного треккинга как отправная точка для восхождений.", "en": "Tsey Alpine Camp is one of the oldest mountaineering bases in the Caucasus, founded in 1934 and located at 2000 meters in Tsey Gorge. It offers several accommodation types: 2-8 person rooms in the main building with shared bathroom, Priyut Monakha cottage with a five-story tower and attic, Icehouse cottage, and a budget tent camp from 350 rubles/night. Check-in requires a passport and accident insurance. The base is used by mountaineers, rock climbers, and hiking enthusiasts as a starting point for ascents."}}'::jsonb, photos = ARRAY['/images/pois/alplager-tsey_facade.webp','/images/pois/alplager-tsey_1.webp','/images/pois/alplager-tsey_2.webp','/images/pois/alplager-tsey_3.webp','/images/pois/alplager-tsey_4.webp','/images/pois/alplager-tsey_5.webp','/images/pois/alplager-tsey_6.webp','/images/pois/alplager-tsey_7.webp','/images/pois/alplager-tsey_8.webp']::text[], rating = 4.4, hours = '{"mon": "08:00-22:00", "tue": "08:00-22:00", "wed": "08:00-22:00", "thu": "08:00-22:00", "fri": "08:00-22:00", "sat": "08:00-22:00", "sun": "08:00-22:00"}'::jsonb, phone = '+7 918 822-69-00', website = 'http://www.альплагерьцей.рф/', price_level = 1, tags = ARRAY['альпинизм','Цейское ущелье','горы','палатки','восхождения']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 80, review_count = 215, updated_at = now() WHERE id = 'poi-111';
UPDATE pois SET name = '{"ru": "360 Restaurant & Karaoke", "en": "360 Restaurant & Karaoke"}'::jsonb, category = 'food'::poi_category, subcategory = 'Ресторан-караоке', cuisine_type = NULL, location = '{"lat": 43.0265, "lng": 44.6748, "address": {"ru": "ул. Коцоева, 75, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362001", "en": "73A Kotsoyeva St, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "360 — ресторан с панорамным видом и караоке-залом на верхнем этаже.", "en": "360 is a restaurant with panoramic views and a karaoke hall on the top floor."}, "medium": {"ru": "360 — ресторан с панорамным видом и караоке-залом на верхнем этаже. Авторская кухня, живая музыка по выходным, элегантный интерьер. Одно из лучших мест для особого вечера.", "en": "360 is a restaurant with panoramic views and a karaoke hall on the top floor. Signature cuisine, live music on weekends, elegant interior. One of the best places for a special evening."}, "full": {"ru": "360 Restaurant & Karaoke — премиальное заведение Владикавказа, расположенное на верхних этажах здания на улице Коцоева с панорамным видом на город, реку Терек и горы. Ресторан предлагает авторскую кухню с элементами кавказской и европейской гастрономии. Караоке-зал оснащён профессиональным оборудованием. По выходным — живая музыка и DJ-сеты. Элегантный интерьер с панорамными окнами создаёт атмосферу роскоши. Идеальное место для романтического ужина, торжества или вечеринки в кругу друзей. Рекомендуется бронирование.", "en": "360 Restaurant & Karaoke is a premium venue in Vladikavkaz, located on the upper floors of a building on Kotsoyeva Street with panoramic views of the city, Terek River, and mountains. The restaurant offers signature cuisine with Caucasian and European gastronomy elements. The karaoke hall features professional equipment. Live music and DJ sets on weekends. An elegant interior with panoramic windows creates a luxurious atmosphere. An ideal place for a romantic dinner, celebration, or party with friends. Reservations recommended."}}'::jsonb, photos = ARRAY['/images/pois/360-restaurant-karaoke_17.webp','/images/pois/360-restaurant-karaoke_1.webp','/images/pois/360-restaurant-karaoke_2.webp','/images/pois/360-restaurant-karaoke_3.webp','/images/pois/360-restaurant-karaoke_4.webp','/images/pois/360-restaurant-karaoke_5.webp','/images/pois/360-restaurant-karaoke_6.webp','/images/pois/360-restaurant-karaoke_7.webp','/images/pois/360-restaurant-karaoke_8.webp','/images/pois/360-restaurant-karaoke_9.webp','/images/pois/360-restaurant-karaoke_10.webp','/images/pois/360-restaurant-karaoke_11.webp','/images/pois/360-restaurant-karaoke_12.webp','/images/pois/360-restaurant-karaoke_13.webp','/images/pois/360-restaurant-karaoke_14.webp','/images/pois/360-restaurant-karaoke_15.webp','/images/pois/360-restaurant-karaoke_16.webp']::text[], rating = 4.5, hours = '{"sun": "07:30-23:59", "mon": "07:30-00:00", "tue": "07:30-00:00", "wed": "07:30-00:00", "thu": "07:30-00:00", "fri": "07:30-00:00", "sat": "07:30-00:00"}'::jsonb, phone = '+7 867 264-92-92', website = 'https://360restaurant.ru/', price_level = 4, tags = ARRAY['панорамный вид','караоке','ресторан','живая музыка','премиум']::text[], is_chain = false, has_menu = true, has_delivery = false, radius = 50, review_count = 196, updated_at = now() WHERE id = 'poi-126';
UPDATE pois SET name = '{"ru": "Рафтинг на Тереке", "en": "Terek River Rafting"}'::jsonb, category = 'activities'::poi_category, subcategory = 'Рафтинг', cuisine_type = NULL, location = '{"lat": 42.985, "lng": 44.665, "address": {"ru": "Владикавказ, набережная Терека", "en": "Vladikavkaz, Terek Embankment"}}'::jsonb, description = '{"short": {"ru": "Рафтинг на реке Терек — один из самых захватывающих видов активного отдыха в Северной Осетии.", "en": "Rafting on the Terek River is one of the most thrilling outdoor activities in North Ossetia."}, "medium": {"ru": "Рафтинг на реке Терек — один из самых захватывающих видов активного отдыха в Северной Осетии. Маршруты от простых до экстремальных проходят через живописное Дарьяльское ущелье с порогами 2-4 категории сложности.", "en": "Rafting on the Terek River is one of the most thrilling outdoor activities in North Ossetia. Routes from easy to extreme pass through the picturesque Daryal Gorge with grade 2-4 rapids."}, "full": {"ru": "Рафтинг на реке Терек — визитная карточка экстремального туризма Северной Осетии. Маршруты начинаются в Дарьяльском ущелье вдоль легендарной Военно-Грузинской дороги. Река предлагает пороги от 2 до 4 категории сложности, что позволяет участвовать как новичкам, так и опытным рафтерам. Продолжительность сплава — от 1 до 3 часов. Все участники обеспечиваются касками, спасжилетами и инструктажем. Сезон — с мая по сентябрь, наиболее полноводный период — июнь-июль. Организаторы забирают группы из Владикавказа. Незабываемый адреналиновый опыт на фоне величественных гор.", "en": "Terek River rafting is the hallmark of extreme tourism in North Ossetia. Routes begin in Daryal Gorge along the legendary Georgian Military Highway. The river offers grade 2 to 4 rapids, allowing both beginners and experienced rafters to participate. Rafting duration is 1 to 3 hours. All participants are provided with helmets, life jackets, and briefings. Season runs from May to September, with the highest water levels in June-July. Organizers pick up groups from Vladikavkaz. An unforgettable adrenaline experience against the backdrop of majestic mountains."}}'::jsonb, photos = ARRAY['/images/pois/terek-rafting_gp.webp']::text[], rating = 4.8, hours = '{"mon": "09:00-18:00", "tue": "09:00-18:00", "wed": "09:00-18:00", "thu": "09:00-18:00", "fri": "09:00-18:00", "sat": "09:00-18:00", "sun": "09:00-18:00"}'::jsonb, phone = '+7 (928) 069-00-00', website = NULL, price_level = 2, tags = ARRAY['рафтинг','экстрим','Терек','Дарьяльское ущелье','активный отдых']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 200, review_count = 76, updated_at = now() WHERE id = 'poi-127';
UPDATE pois SET name = '{"ru": "Параглайдинг над горами Осетии", "en": "Paragliding over Ossetian Mountains"}'::jsonb, category = 'activities'::poi_category, subcategory = 'Параглайдинг', cuisine_type = NULL, location = '{"lat": 42.82406, "lng": 44.411498, "address": {"ru": "Даргавс, Респ. Северная Осетия — Алания, Россия, 363128", "en": "Kurtatinsky Gorge, North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Параглайдинг в горах Северной Осетии — возможность увидеть Кавказский хребет с высоты птичьего полёта.", "en": "Paragliding in the mountains of North Ossetia — a chance to see the Caucasus Range from a bird''s-eye view."}, "medium": {"ru": "Параглайдинг в горах Северной Осетии — возможность увидеть Кавказский хребет с высоты птичьего полёта. Тандемные полёты с инструктором доступны без опыта. Старт с горных склонов Куртатинского ущелья.", "en": "Paragliding in the mountains of North Ossetia — a chance to see the Caucasus Range from a bird''s-eye view. Tandem flights with an instructor are available without experience. Launch from the mountain slopes of Kurtatinsky Gorge."}, "full": {"ru": "Параглайдинг в Северной Осетии — уникальная возможность увидеть горы Кавказа с высоты полёта параплана. Тандемные полёты с опытными инструкторами доступны для всех желающих без специальной подготовки. Старт осуществляется с горных склонов Куртатинского ущелья, откуда открываются потрясающие виды на заснеженные вершины, зелёные долины и средневековые башни. Продолжительность полёта — 15-30 минут в зависимости от погодных условий. Сезон — с мая по октябрь. В стоимость входит трансфер из Владикавказа, инструктаж и видеосъёмка полёта. Минимальный возраст участника — 14 лет.", "en": "Paragliding in North Ossetia is a unique opportunity to see the Caucasus mountains from a paraglider''s altitude. Tandem flights with experienced instructors are available to everyone without special training. Launch is from the mountain slopes of Kurtatinsky Gorge, offering stunning views of snow-capped peaks, green valleys, and medieval towers. Flight duration is 15-30 minutes depending on weather conditions. Season runs from May to October. The price includes transfer from Vladikavkaz, briefing, and flight video recording. Minimum participant age is 14."}}'::jsonb, photos = ARRAY['/images/pois/paragliding-vladikavkaz_gp.webp']::text[], rating = 5, hours = '{"sun": "11:00-17:00", "mon": "11:00-17:00", "tue": "11:00-17:00", "wed": "11:00-17:00", "thu": "11:00-17:00", "fri": "11:00-17:00", "sat": "11:00-17:00"}'::jsonb, phone = '+7 919 426-04-53', website = 'https://paraplan15.ru/', price_level = 3, tags = ARRAY['параглайдинг','полёт','горы','экстрим','виды']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 200, review_count = 2, updated_at = now() WHERE id = 'poi-128';
UPDATE pois SET name = '{"ru": "Конные прогулки по горам Осетии", "en": "Horse Riding Tours in Ossetian Mountains"}'::jsonb, category = 'activities'::poi_category, subcategory = 'Конные прогулки', cuisine_type = NULL, location = '{"lat": 42.835642, "lng": 44.429756, "address": {"ru": "Даргавс, Респ. Северная Осетия — Алания, Россия, 363128", "en": "Dargavs Village, Prigorodny District, North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Конные маршруты по горным ущельям с видом на «Город мёртвых»", "en": "Horse riding from Dargavs village along scenic mountain trails."}, "medium": {"ru": "Конные прогулки из села Даргавс по живописным горным тропам. Маршруты проходят через Даргавское и Мидаграбинское ущелья мимо средневековых башен и водопадов. Доступны для новичков. Цены от 1200 руб.", "en": "Horse riding from Dargavs village along scenic mountain trails. Routes pass through Dargavs and Midagrabin gorges past medieval towers and waterfalls. Suitable for beginners. Prices from 1200 RUB."}, "full": {"ru": "Конные прогулки в горах Северной Осетии организуются из конюшни в селе Даргавс — знаменитом месте с крупнейшим на Кавказе склеповым комплексом «Город мёртвых». Маршруты проходят по Даргавскому и Мидаграбинскому ущельям, вдоль горной реки Гизельдон, мимо средневековых башен и водопадов. Продолжительность — от 1 до 4 часов. Лошади спокойные и обученные, подходят для начинающих наездников. Инструкторы сопровождают группу на всём маршруте. Стоимость начинается от 1200 рублей. Необходимо бронирование. Сезон — с апреля по ноябрь. Одно из лучших впечатлений для любителей природы.", "en": "Horse riding tours in the mountains of North Ossetia are organized from a stable in Dargavs village — famous for the Caucasus''s largest burial vault complex, the City of the Dead. Routes pass through Dargavs and Midagrabin gorges, along the Gizeldon mountain river, past medieval towers and waterfalls. Duration is 1 to 4 hours. Horses are calm and trained, suitable for beginner riders. Instructors accompany the group throughout the route. Prices start from 1200 rubles. Booking required. Season from April to November. One of the best experiences for nature lovers."}}'::jsonb, photos = ARRAY['/images/pois/horse-riding-dargavs_gp.webp']::text[], rating = 4.4, hours = '{"sun": "09:00-18:00", "tue": "09:00-18:00", "wed": "09:00-18:00", "thu": "09:00-18:00", "fri": "09:00-18:00", "sat": "09:00-18:00"}'::jsonb, phone = '+7 989 038-28-61', website = 'https://alaniya-horses.ru/', price_level = 2, tags = ARRAY['конные прогулки','горы','Даргавс','природа','ущелья']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 200, review_count = 12, updated_at = now() WHERE id = 'poi-129';
UPDATE pois SET name = '{"ru": "Горнолыжный курорт «Цей»", "en": "Tsey Ski Resort"}'::jsonb, category = 'activities'::poi_category, subcategory = 'Горнолыжный курорт', cuisine_type = NULL, location = '{"lat": 42.784145, "lng": 43.904147, "address": {"ru": "Респ. Северная Осетия — Алания, Россия, 363221", "en": "Tsey Gorge, Alagirsky District, North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Горнолыжный курорт «Цей» — главное место зимнего отдыха в Северной Осетии.", "en": "Tsey Ski Resort is the main winter destination in North Ossetia."}, "medium": {"ru": "Горнолыжный курорт «Цей» — главное место зимнего отдыха в Северной Осетии. Трассы всех уровней сложности на высотах 1850-2870 м. Парнокресельная и однокресельная канатные дороги. Сезон — декабрь-апрель.", "en": "Tsey Ski Resort is the main winter destination in North Ossetia. Slopes of all difficulty levels at 1850-2870 m elevation. Double and single chairlifts. Season — December to April."}, "full": {"ru": "Горнолыжный курорт «Цей» расположен в Цейском ущелье у подножия гор Адайхох и Монах, в 90 км от Владикавказа. Трассы от «зелёных» до «чёрных» на высотах от 1850 до 2870 метров. Две канатные дороги — парнокресельная и однокресельная — поднимают лыжников на вершины. Высота снежного покрова в разгар сезона достигает двух метров. Ущелье входит в состав Северо-Осетинского заповедника, поэтому катание проходит на фоне первозданной природы. На курорте работают отели «Сказка» и «Вертикаль», гостиница «Осетия», прокат снаряжения. Сезон с декабря по апрель, но курорт работает круглый год как база для горного туризма.", "en": "Tsey Ski Resort is located in Tsey Gorge at the foot of Mount Adaykhokh and Mount Monakh, 90 km from Vladikavkaz. Slopes range from green to black at elevations from 1850 to 2870 meters. Two cable lifts — double and single chairlifts — take skiers to the peaks. Snow depth reaches two meters at the height of the season. The gorge is part of the North Ossetian Nature Reserve, so skiing takes place against pristine natural scenery. The resort features hotels Skazka and Vertikal, Ossetia hotel, and equipment rental. Season from December to April, but the resort operates year-round as a base for mountain tourism."}}'::jsonb, photos = ARRAY['/images/pois/tsey-ski-resort_gp.webp']::text[], rating = 4.5, hours = '{"sun": "10:00-15:30", "mon": "10:00-15:30", "tue": "10:00-15:30", "wed": "10:00-15:30", "thu": "10:00-15:30", "fri": "10:00-15:30", "sat": "10:00-15:30"}'::jsonb, phone = '+7 867 250-13-13', website = 'http://www.tseyski.ru/', price_level = 2, tags = ARRAY['горные лыжи','сноуборд','канатная дорога','Цей','зимний спорт']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 200, review_count = 1168, updated_at = now() WHERE id = 'poi-130';
UPDATE pois SET name = '{"ru": "Верёвочный парк", "en": "Rope Adventure Park"}'::jsonb, category = 'activities'::poi_category, subcategory = 'Верёвочный парк', cuisine_type = NULL, location = '{"lat": 42.99263, "lng": 44.573858, "address": {"ru": "Гизельское ш., Владикавказ, Респ. Северная Осетия — Алания, Россия, 363125", "en": "Olympic Park, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Верёвочный парк во Владикавказе — отличное развлечение для детей и взрослых.", "en": "The rope park in Vladikavkaz is great fun for children and adults."}, "medium": {"ru": "Верёвочный парк во Владикавказе — отличное развлечение для детей и взрослых. Несколько уровней сложности, зиплайн, подвесные мосты и платформы на деревьях. Инструкторы и страховка включены.", "en": "The rope park in Vladikavkaz is great fun for children and adults. Several difficulty levels, zipline, suspension bridges, and tree platforms. Instructors and safety gear included."}, "full": {"ru": "Верёвочный парк во Владикавказе предлагает активный отдых на свежем воздухе для всей семьи. Трассы разделены по уровням сложности: детские (от 5 лет), подростковые и взрослые. Маршруты включают подвесные мосты, канатные переправы, зиплайн, лазание по сеткам и переход по качающимся платформам среди деревьев. Все участники обеспечиваются страховочным снаряжением и проходят инструктаж перед стартом. Прохождение одной трассы занимает 30-60 минут. Работает в тёплый сезон с апреля по октябрь. Популярное место для семейного отдыха и корпоративных мероприятий.", "en": "The rope park in Vladikavkaz offers active outdoor recreation for the whole family. Courses are divided by difficulty: children''s (from age 5), teen, and adult. Routes include suspension bridges, rope crossings, ziplines, net climbing, and swaying platform traversals among trees. All participants are provided with safety equipment and receive a briefing before starting. Completing one course takes 30-60 minutes. Open in warm season from April to October. A popular spot for family recreation and corporate events."}}'::jsonb, photos = ARRAY['/images/pois/rope-park-vladikavkaz_gp.webp']::text[], rating = 4.9, hours = '{"sun": "11:00-18:30", "tue": "12:00-18:00", "wed": "12:00-18:00", "thu": "12:00-18:00", "fri": "12:00-18:00", "sat": "11:00-18:30"}'::jsonb, phone = '+7 918 838-87-81', website = NULL, price_level = 1, tags = ARRAY['верёвочный парк','зиплайн','семейный отдых','дети','активный отдых']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 200, review_count = 56, updated_at = now() WHERE id = 'poi-131';
UPDATE pois SET name = '{"ru": "Скалодром RockStar", "en": "RockStar Climbing Wall"}'::jsonb, category = 'activities'::poi_category, subcategory = 'Скалодром', cuisine_type = NULL, location = '{"lat": 43.061329, "lng": 44.648212, "address": {"ru": "Московская ул., 8, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362035", "en": "8 Moskovskaya St, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "RockStar — единственный скалодром во всей Северной Осетии, открытый в 2019 году.", "en": "RockStar is the only climbing wall in all of North Ossetia, opened in 2019."}, "medium": {"ru": "RockStar — единственный скалодром во всей Северной Осетии, открытый в 2019 году. 250 м² скалолазных стен, трассы от боулдеринга до лазания на трудность. Подходит для новичков и опытных скалолазов.", "en": "RockStar is the only climbing wall in all of North Ossetia, opened in 2019. 250 m² of climbing walls, routes from bouldering to lead climbing. Suitable for beginners and experienced climbers."}, "full": {"ru": "Скалодром RockStar — первая и единственная искусственная скалолазная площадка во всей Северной Осетии, открытая в 2019 году на Московской улице. Общая площадь скалолазных стен составляет около 250 квадратных метров. Накручены трассы разной сложности: невысокие боулдеринговые участки для лазания без верёвки и высокие стены для лазания на трудность со страховкой. Регулярно обновляются маршруты. Проводятся тренировки для детей и взрослых, индивидуальные занятия с инструктором. Отличная подготовка перед выходом на настоящие скалы Кавказа.", "en": "RockStar is the first and only artificial climbing wall in all of North Ossetia, opened in 2019 on Moskovskaya Street. The total climbing wall area is about 250 square meters. Routes of varying difficulty are set: low bouldering sections for ropeless climbing and tall walls for lead climbing with belaying. Routes are regularly updated. Training is available for children and adults, with individual instructor sessions. Excellent preparation before heading out to real Caucasus rock faces."}}'::jsonb, photos = ARRAY['/images/pois/rockstar-climbing_gp.webp']::text[], rating = 4.9, hours = '{"sun": "15:00-21:00", "tue": "15:00-21:00", "wed": "15:00-21:00", "thu": "15:00-21:00", "fri": "15:00-21:00", "sat": "15:00-21:00"}'::jsonb, phone = '+7 918 821-09-20', website = 'https://instagram.com/rockstar_team_vld', price_level = 2, tags = ARRAY['скалодром','скалолазание','боулдеринг','спорт','тренировки']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 200, review_count = 60, updated_at = now() WHERE id = 'poi-132';
UPDATE pois SET name = '{"ru": "Каньонинг Мидаграбин", "en": "Midagrabin Canyoning"}'::jsonb, category = 'activities'::poi_category, subcategory = 'Каньонинг', cuisine_type = NULL, location = '{"lat": 42.767546, "lng": 44.362126, "address": {"ru": "Респ. Северная Осетия — Алания, Россия, 363203", "en": "Midagrabin Gorge, North Ossetia"}}'::jsonb, description = '{"short": {"ru": "Каньонинг в Мидаграбинском ущелье — экстремальное приключение у подножия водопадов высотой до 750 м.", "en": "Canyoning in Midagrabin Gorge is an extreme adventure at the foot of waterfalls up to 750 m high."}, "medium": {"ru": "Каньонинг в Мидаграбинском ущелье — экстремальное приключение у подножия водопадов высотой до 750 м. Спуск по каньонам, переправы через горные потоки и купание в природных бассейнах.", "en": "Canyoning in Midagrabin Gorge is an extreme adventure at the foot of waterfalls up to 750 m high. Canyon descents, mountain stream crossings, and swimming in natural pools."}, "full": {"ru": "Каньонинг в Мидаграбинском ущелье — одно из самых ярких экстремальных приключений Северной Осетии. Мидаграбинские водопады (Большой Зейгалан достигает 750 метров) считаются высочайшими в Европе. Маршрут включает спуск по узким скальным каньонам, переправы через ледяные горные потоки, прыжки в природные бассейны и дюльфер по водопадным уступам. Продолжительность — 4-6 часов. Необходима хорошая физическая форма. Снаряжение (гидрокостюм, каска, обвязка) предоставляется. Группы сопровождают сертифицированные гиды. Сезон — июнь-сентябрь. Трансфер из Владикавказа включён.", "en": "Canyoning in Midagrabin Gorge is one of the most spectacular extreme adventures in North Ossetia. Midagrabin waterfalls (Big Zeygalan reaches 750 meters) are considered the highest in Europe. The route includes descending narrow rock canyons, crossing icy mountain streams, jumping into natural pools, and rappelling along waterfall ledges. Duration is 4-6 hours. Good physical fitness required. Equipment (wetsuit, helmet, harness) is provided. Groups are accompanied by certified guides. Season — June to September. Transfer from Vladikavkaz included."}}'::jsonb, photos = ARRAY['/images/pois/midagrabin-canyoning_gp.webp']::text[], rating = 4.9, hours = NULL, phone = '+7 (928) 073-20-00', website = NULL, price_level = 3, tags = ARRAY['каньонинг','Мидаграбин','водопады','экстрим','приключения']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 200, review_count = 133, updated_at = now() WHERE id = 'poi-134';
UPDATE pois SET name = '{"ru": "Железнодорожный вокзал Владикавказ", "en": "Vladikavkaz Railway Station"}'::jsonb, category = 'practical'::poi_category, subcategory = 'Вокзал', cuisine_type = NULL, location = '{"lat": 43.037825, "lng": 44.688198, "address": {"ru": "ул. Маркова, 24, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362000", "en": "24 Markova St, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Железнодорожный вокзал Владикавказа — главный транспортный узел города.", "en": "Vladikavkaz Railway Station is the city''s main transportation hub. Trains to Moscow, Rostov-on-Don, St."}, "medium": {"ru": "Железнодорожный вокзал Владикавказа — главный транспортный узел города. Поезда в Москву, Ростов-на-Дону, Санкт-Петербург и другие города. Зал ожидания, камеры хранения, билетные кассы.", "en": "Vladikavkaz Railway Station is the city''s main transportation hub. Trains to Moscow, Rostov-on-Don, St. Petersburg, and other cities. Waiting hall, luggage storage, ticket offices."}, "full": {"ru": "Железнодорожный вокзал Владикавказа расположен на улице Маркова в центральной части города. Это конечная станция Северо-Кавказской железной дороги. Отсюда отправляются поезда дальнего следования в Москву, Ростов-на-Дону, Санкт-Петербург, Адлер и другие города России. На вокзале работают билетные кассы, зал ожидания, камеры хранения, буфет. Единая справочная РЖД: 8-800-775-00-00. В пешей доступности — отель «Амран» и остановки городского транспорта. Рекомендуется приобретать билеты заранее, особенно в летний сезон.", "en": "Vladikavkaz Railway Station is located on Markova Street in the central part of the city. It is the terminal station of the North Caucasus Railway. Long-distance trains depart from here to Moscow, Rostov-on-Don, St. Petersburg, Adler, and other Russian cities. The station has ticket offices, a waiting hall, luggage storage, and a cafeteria. Russian Railways unified hotline: 8-800-775-00-00. Within walking distance are the Amran Hotel and public transport stops. Advance ticket purchase is recommended, especially during summer season."}}'::jsonb, photos = ARRAY['/images/pois/vladikavkaz-railway-station_gp.webp','/images/pois/zheleznodorozhnyy-vokzal-vladikavkaz_2.webp','/images/pois/zheleznodorozhnyy-vokzal-vladikavkaz_3.webp','/images/pois/zheleznodorozhnyy-vokzal-vladikavkaz_4.webp','/images/pois/zheleznodorozhnyy-vokzal-vladikavkaz_5.webp']::text[], rating = 4.2, hours = '{"sun": "06:30-20:00", "mon": "06:30-20:00", "tue": "06:30-20:00", "wed": "06:30-20:00", "thu": "06:30-20:00", "fri": "06:30-20:00", "sat": "06:30-20:00"}'::jsonb, phone = '+7 (800) 775-00-00', website = 'http://vladikavkaz.dzvr.ru/', price_level = NULL, tags = ARRAY['ж/д вокзал','поезда','транспорт','билеты']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 50, review_count = 170, updated_at = now() WHERE id = 'poi-135';
UPDATE pois SET name = '{"ru": "Автовокзал Владикавказ", "en": "Vladikavkaz Bus Station"}'::jsonb, category = 'practical'::poi_category, subcategory = 'Автовокзал', cuisine_type = NULL, location = '{"lat": 43.0584, "lng": 44.64328, "address": {"ru": "Владикавказ, Респ. Северная Осетия — Алания, Россия, 362035", "en": "1 Arkhonskoe Highway, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Автовокзал Владикавказа — отправная точка для автобусных маршрутов по Северной Осетии и соседним регионам Кавказа.", "en": "Vladikavkaz Bus Station is the departure point for bus routes across North Ossetia and neighboring Caucasus regions."}, "medium": {"ru": "Автовокзал Владикавказа — отправная точка для автобусных маршрутов по Северной Осетии и соседним регионам Кавказа. Рейсы в Нальчик, Грозный, Пятигорск, а также в горные посёлки республики.", "en": "Vladikavkaz Bus Station is the departure point for bus routes across North Ossetia and neighboring Caucasus regions. Services to Nalchik, Grozny, Pyatigorsk, and mountain villages of the republic."}, "full": {"ru": "Автовокзал Владикавказа расположен на Архонском шоссе и обслуживает междугородние и пригородные маршруты. Отсюда отправляются автобусы в соседние столицы республик СКФО — Нальчик, Грозный, Махачкалу, а также в города Кавказских Минеральных Вод — Пятигорск, Кисловодск, Минеральные Воды. Пригородные маршруты связывают Владикавказ с горными посёлками: Верхний Фиагдон, Алагир, Дигора. Зал ожидания, билетные кассы, справочная. Расписание может меняться в зависимости от сезона. Справочная: +7 (8672) 51-12-63.", "en": "Vladikavkaz Bus Station is located on Arkhonskoe Highway and serves intercity and suburban routes. Buses depart from here to neighboring republic capitals — Nalchik, Grozny, Makhachkala — as well as to Caucasus Mineral Waters cities — Pyatigorsk, Kislovodsk, Mineralnye Vody. Suburban routes connect Vladikavkaz with mountain villages: Upper Fiagdon, Alagir, Digora. Waiting hall, ticket offices, information desk available. Schedules may vary by season. Information: +7 (8672) 51-12-63."}}'::jsonb, photos = ARRAY['/images/pois/vladikavkaz-bus-station_gp.webp','/images/pois/avtovokzal-vladikavkaz_2.webp','/images/pois/avtovokzal-vladikavkaz_3.webp','/images/pois/avtovokzal-vladikavkaz_4.webp','/images/pois/avtovokzal-vladikavkaz_5.webp','/images/pois/avtovokzal-vladikavkaz_6.webp']::text[], rating = 2.2, hours = '{"mon": "06:00-19:30", "tue": "06:00-19:30", "wed": "06:00-19:30", "thu": "06:00-19:30", "fri": "06:00-19:30", "sat": "06:00-19:30", "sun": "06:00-19:30"}'::jsonb, phone = '+7 (8672) 51-12-63', website = 'https://avtovokzal15.ru/', price_level = NULL, tags = ARRAY['автовокзал','автобусы','транспорт','маршруты']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 50, review_count = 121, updated_at = now() WHERE id = 'poi-136';
UPDATE pois SET name = '{"ru": "Аэропорт Беслан (OGZ)", "en": "Beslan Airport (OGZ)"}'::jsonb, category = 'practical'::poi_category, subcategory = 'Аэропорт', cuisine_type = NULL, location = '{"lat": 43.201878, "lng": 44.604505, "address": {"ru": "РФ, РСО-Алания, г. Беслан, аэропорт «Владикавказ», Беслан, Респ. Северная Осетия — Алания, Россия, 363000", "en": "Beslan, Vladikavkaz Airport"}}'::jsonb, description = '{"short": {"ru": "Международный аэропорт в 26 км от Владикавказа (код OGZ)", "en": "International airport 26 km from Vladikavkaz (code OGZ)"}, "medium": {"ru": "Аэропорт «Владикавказ» (Беслан, OGZ) — единственный аэропорт Северной Осетии. Расположен в 26 км от Владикавказа. Рейсы в Москву, Санкт-Петербург, Сочи и другие города. Работает круглосуточно.", "en": "Vladikavkaz Airport (Beslan, OGZ) is the only airport in North Ossetia. Located 26 km from Vladikavkaz. Flights to Moscow, St. Petersburg, Sochi, and other cities. Open 24 hours."}, "full": {"ru": "Аэропорт «Владикавказ» (IATA: OGZ, ICAO: URMO) расположен вблизи города Беслан в 26 километрах от Владикавказа. Это единственный аэропорт Республики Северная Осетия-Алания, обслуживающий регулярные рейсы в Москву (Внуково, Домодедово, Шереметьево), Санкт-Петербург, Сочи, Сургут и другие города. Авиакомпании: «Победа», S7, «Россия», Utair и другие. В здании аэропорта — зал ожидания, кафе, магазин, пункт обмена валюты. Добраться из Владикавказа можно на такси (30-40 минут) или маршрутке. Справочная: +7 (8672) 33-36-53.", "en": "Vladikavkaz Airport (IATA: OGZ, ICAO: URMO) is located near the city of Beslan, 26 kilometers from Vladikavkaz. It is the only airport in the Republic of North Ossetia-Alania, serving regular flights to Moscow (Vnukovo, Domodedovo, Sheremetyevo), St. Petersburg, Sochi, Surgut, and other cities. Airlines: Pobeda, S7, Rossiya, Utair, and others. The airport building has a waiting hall, cafe, shop, and currency exchange. Reachable from Vladikavkaz by taxi (30-40 minutes) or minibus. Information: +7 (8672) 33-36-53."}}'::jsonb, photos = ARRAY['/images/pois/beslan-airport-ogz_gp.webp','/images/pois/aeroport-beslan-ogz_2.webp','/images/pois/aeroport-beslan-ogz_3.webp']::text[], rating = 3.7, hours = '{"sun": "08:30-20:30", "mon": "08:30-20:30", "tue": "08:30-20:30", "wed": "08:30-20:30", "thu": "08:30-20:30", "fri": "08:30-20:30", "sat": "08:30-20:30"}'::jsonb, phone = '+7 867 233-36-53', website = 'http://mav.aero/', price_level = NULL, tags = ARRAY['аэропорт','авиабилеты','OGZ','Беслан','транспорт']::text[], is_chain = false, has_menu = false, has_delivery = false, radius = 50, review_count = 1189, updated_at = now() WHERE id = 'poi-137';
UPDATE pois SET name = '{"ru": "Почта России (центральное отделение)", "en": "Russian Post (Central Office)"}'::jsonb, category = 'practical'::poi_category, subcategory = 'Почта', cuisine_type = NULL, location = '{"lat": 43.02408, "lng": 44.672016, "address": {"ru": "просп. Коста, 134, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362001", "en": "34 Mira Ave, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Центральное отделение Почты России во Владикавказе на проспекте Мира. Отправка писем, посылок, денежных переводов.", "en": "Central Russian Post office in Vladikavkaz on Mira Avenue. Sending letters, packages, money transfers."}, "medium": {"ru": "Центральное отделение Почты России во Владикавказе на проспекте Мира. Отправка писем, посылок, денежных переводов. EMS-доставка, подписка на периодику, оплата коммунальных услуг.", "en": "Central Russian Post office in Vladikavkaz on Mira Avenue. Sending letters, packages, money transfers. EMS delivery, periodical subscriptions, utility payments."}, "full": {"ru": "Центральное отделение Почты России во Владикавказе расположено на главном проспекте Мира. Предоставляет полный спектр почтовых услуг: отправка писем, бандеролей и посылок по России и за рубеж, EMS-доставка, денежные переводы, оплата коммунальных услуг, подписка на газеты и журналы. Для туристов полезна услуга отправки открыток и сувениров домой. Также работает пункт выдачи интернет-заказов. Индекс центрального отделения: 362040. Работает по будням с перерывом на обед, в субботу — сокращённый день.", "en": "The central Russian Post office in Vladikavkaz is located on the main Mira Avenue. It provides a full range of postal services: sending letters, parcels, and packages within Russia and abroad, EMS delivery, money transfers, utility payments, newspaper and magazine subscriptions. Tourists find it useful for mailing postcards and souvenirs home. An online order pickup point also operates here. Central office postal code: 362040. Open on weekdays with a lunch break, shortened hours on Saturday."}}'::jsonb, photos = ARRAY['/images/pois/post-office-vladikavkaz_gp.webp','/images/pois/pochta-rossii-tsentralnoe-otdelenie_2.webp']::text[], rating = 3, hours = '{"mon": "08:00-18:00", "tue": "08:00-18:00", "wed": "08:00-18:00", "thu": "08:00-18:00", "fri": "08:00-18:00", "sat": "08:00-17:00"}'::jsonb, phone = '+7 495 956-20-67', website = 'http://pochta.ru/', price_level = NULL, tags = ARRAY['почта','посылки','переводы','открытки']::text[], is_chain = true, has_menu = false, has_delivery = false, radius = 50, review_count = 71, updated_at = now() WHERE id = 'poi-138';
UPDATE pois SET name = '{"ru": "Сбербанк (центральный)", "en": "Sberbank (Central Branch)"}'::jsonb, category = 'practical'::poi_category, subcategory = 'Банк', cuisine_type = NULL, location = '{"lat": 43.036101, "lng": 44.686427, "address": {"ru": "ул. Кирова, 57, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362000", "en": "68 Kotsoyeva St, Vladikavkaz"}}'::jsonb, description = '{"short": {"ru": "Центральное отделение Сбербанка во Владикавказе на улице Коцоева.", "en": "Central Sberbank branch in Vladikavkaz on Kotsoyeva Street."}, "medium": {"ru": "Центральное отделение Сбербанка во Владикавказе на улице Коцоева. Обмен валюты, снятие наличных, переводы, кредиты, открытие счетов. Банкоматы работают круглосуточно.", "en": "Central Sberbank branch in Vladikavkaz on Kotsoyeva Street. Currency exchange, cash withdrawal, transfers, loans, account opening. ATMs operate 24/7."}, "full": {"ru": "Центральное отделение Сбербанка во Владикавказе расположено на улице Коцоева, в пешей доступности от набережной Терека и проспекта Мира. Предоставляет полный спектр банковских услуг: обмен валюты (доллары, евро), снятие наличных, международные переводы, оформление карт, кредиты, страхование. Для туристов наиболее актуальны обмен валюты и снятие наличных в банкоматах. Банкоматы Сбербанка принимают карты международных платёжных систем. В городе работают ещё более 15 отделений и множество банкоматов. Отделение оснащено электронной очередью.", "en": "The central Sberbank branch in Vladikavkaz is located on Kotsoyeva Street, within walking distance of the Terek embankment and Mira Avenue. It provides a full range of banking services: currency exchange (dollars, euros), cash withdrawal, international transfers, card issuance, loans, and insurance. For tourists, currency exchange and ATM cash withdrawal are most relevant. Sberbank ATMs accept international payment system cards. The city has over 15 more branches and numerous ATMs. The branch is equipped with an electronic queue system."}}'::jsonb, photos = ARRAY['/images/pois/sberbank-central-vladikavkaz_gp.webp']::text[], rating = 3.8, hours = '{"sun": "09:00-15:00", "mon": "08:30-17:00", "tue": "08:30-17:00", "wed": "08:30-17:00", "thu": "08:30-17:00", "fri": "08:30-17:00"}'::jsonb, phone = '+7 800 555-55-50', website = 'https://www.sberbank.ru/', price_level = NULL, tags = ARRAY['банк','обмен валюты','банкомат','переводы']::text[], is_chain = true, has_menu = false, has_delivery = false, radius = 50, review_count = 26, updated_at = now() WHERE id = 'poi-139';
UPDATE pois SET name = '{"ru": "Банкомат Тинькофф", "en": "Tinkoff ATM"}'::jsonb, category = 'practical'::poi_category, subcategory = 'Банкомат', cuisine_type = NULL, location = '{"lat": 43.032026, "lng": 44.688797, "address": {"ru": "Салон связи \"Билайн, ул. Куйбышева, 21, Владикавказ, Респ. Северная Осетия — Алания, Россия, 362025", "en": "29 Mira Ave, Vladikavkaz (Aleksandrovsky Grand Hotel)"}}'::jsonb, description = '{"short": {"ru": "Банкомат Тинькофф Банка расположен в вестибюле Гранд-отеля «Александровский» на проспекте Мира.", "en": "Tinkoff Bank ATM located in the lobby of the Aleksandrovsky Grand Hotel on Mira Avenue."}, "medium": {"ru": "Банкомат Тинькофф Банка расположен в вестибюле Гранд-отеля «Александровский» на проспекте Мира. Снятие наличных без комиссии для клиентов Тинькофф, пополнение счёта и переводы.", "en": "Tinkoff Bank ATM located in the lobby of the Aleksandrovsky Grand Hotel on Mira Avenue. Commission-free cash withdrawal for Tinkoff clients, account top-up, and transfers."}, "full": {"ru": "Банкомат Тинькофф Банка установлен в вестибюле Гранд-отеля «Александровский» на проспекте Мира — главной пешеходной улице Владикавказа. Для клиентов Тинькофф — снятие наличных без комиссии до установленных лимитов. Принимает карты Visa, Mastercard, МИР. Доступны операции: снятие и внесение наличных, переводы между счетами, оплата услуг. Работает круглосуточно. В городе есть ещё несколько банкоматов Тинькофф — их расположение можно найти в приложении банка. Ближайшие к центру — в торговых центрах и крупных магазинах.", "en": "The Tinkoff Bank ATM is installed in the lobby of the Aleksandrovsky Grand Hotel on Mira Avenue — Vladikavkaz''s main pedestrian street. For Tinkoff clients — commission-free cash withdrawal up to set limits. Accepts Visa, Mastercard, and MIR cards. Available operations: cash withdrawal and deposit, transfers between accounts, bill payments. Open 24/7. The city has several more Tinkoff ATMs — their locations can be found in the bank''s app. The closest to the center are in shopping malls and large stores."}}'::jsonb, photos = ARRAY['/images/pois/tinkoff-atm-vladikavkaz_gp.webp']::text[], rating = 2, hours = '{"sun": "09:00-20:00", "mon": "09:00-20:00", "tue": "09:00-20:00", "wed": "09:00-20:00", "thu": "09:00-20:00", "fri": "09:00-20:00", "sat": "09:00-20:00"}'::jsonb, phone = '+7 800 700-88-22', website = 'https://www.tinkoff.ru/', price_level = NULL, tags = ARRAY['банкомат','Тинькофф','наличные','Visa','Mastercard']::text[], is_chain = true, has_menu = false, has_delivery = false, radius = 50, review_count = 3, updated_at = now() WHERE id = 'poi-140';
